-- Holding a brainrot (game sets "Stealing" attribute on the player while carrying)
function _G.MoonIsHoldingBrainrot()
    local lp = game:GetService("Players").LocalPlayer
    if not lp then return false end
    if lp:GetAttribute("Stealing") == true then return true end
    local ch = lp.Character
    if ch and ch:GetAttribute("Stealing") == true then return true end
    return false
end

