-- Fast local cache check: avoid decoding/writing the embedded intro media
-- again on every script execution.
local function moonLocalFileExists(path)
    if type(isfile) == "function" then
        local ok, exists = pcall(isfile, path)
        if ok then return exists == true end
    end
    if type(readfile) == "function" then
        local ok, data = pcall(readfile, path)
        return ok and type(data) == "string" and #data > 0
    end
    return false
end

-- ============================================================
-- MOON HUB AUTO SAVE — REAL FILE SAVE (writefile / readfile)
-- Saves every switch, input box, selector, size, keybind, speed mode,
-- tab, menu open/closed and the position of the main menu, the steal
-- bar and every mobile button. Restores all of it on the next run.
-- ============================================================
do
    local HttpService = game:GetService("HttpService")
    local function executorApi(name)
        local envs = {}
        pcall(function() if type(getfenv) == "function" then table.insert(envs, getfenv(0)) end end)
        pcall(function() if type(getgenv) == "function" then table.insert(envs, getgenv()) end end)
        table.insert(envs, _G)
        pcall(function() if type(syn) == "table" then table.insert(envs, syn) end end)
        pcall(function() if type(getrenv) == "function" then table.insert(envs, getrenv()) end end)
        for _, env in ipairs(envs) do
            if type(env) == "table" then
                local value
                pcall(function() value = env[name] end)
                if type(value) == "function" then return value end
            end
        end
        return nil
    end
    local MS = {}
    MS._readfile = executorApi("readfile")
    MS._writefile = executorApi("writefile")
    MS._isfile = executorApi("isfile")
    MS._makefolder = executorApi("makefolder")
    MS._isfolder = executorApi("isfolder")
    MS._delfile = executorApi("delfile")
    _G.MoonSaveGen = (tonumber(_G.MoonSaveGen) or 0) + 1
    MS.gen = _G.MoonSaveGen
    MS.Folder = "MoonHub"
    MS.FileInFolder = "MoonHub/MoonHub_AutoSave.json"
    MS.FileRoot = "MoonHub_AutoSave.json"
    MS.items = {}
    MS.order = {}
    MS.data = nil
    MS.ready = false
    MS.restoring = false
    MS.lastSig = nil
    MS.canFile = type(MS._writefile) == "function" and type(MS._readfile) == "function"
    _G.MoonSave = MS
    _G.MoonSaveRefs = { hidePainters = {}, tabSelect = {} }

    -- Alias used across features (TP Ragdoll, Anti Lag, aimbot versions...)
    function scheduleRivalHubSave()
        if MS and MS.markDirty then
            MS.markDirty()
        elseif _G.MoonSave and _G.MoonSave.markDirty then
            _G.MoonSave.markDirty()
        end
    end
    _G.scheduleRivalHubSave = scheduleRivalHubSave


    local function isFiniteNumber(n)
        return type(n) == "number" and n == n and n ~= math.huge and n ~= -math.huge
    end

    local function clean(v, depth)
        depth = depth or 0
        local t = type(v)
        if t == "boolean" or t == "string" then return v end
        if t == "number" then return isFiniteNumber(v) and v or nil end
        if t == "table" and depth < 4 then
            local out = {}
            for k, val in pairs(v) do
                if type(k) == "string" or type(k) == "number" then
                    local c = clean(val, depth + 1)
                    if c ~= nil then out[tostring(k)] = c end
                end
            end
            return out
        end
        if typeof and typeof(v) == "UDim2" then
            return { xs = v.X.Scale, xo = v.X.Offset, ys = v.Y.Scale, yo = v.Y.Offset }
        end
        return nil
    end
    MS.clean = clean

    -- deterministic signature (so we only write when something really changed)
    local function sig(v)
        local t = type(v)
        if t ~= "table" then return t:sub(1, 1) .. tostring(v) end
        local keys = {}
        for k in pairs(v) do table.insert(keys, tostring(k)) end
        table.sort(keys)
        local parts = {}
        for _, k in ipairs(keys) do
            table.insert(parts, k .. "=" .. sig(v[k]))
        end
        return "{" .. table.concat(parts, ",") .. "}"
    end
    MS.sig = sig

    local function fileExists(path)
        if MS._isfile then
            local ok, r = pcall(MS._isfile, path)
            if ok then return r == true end
        end
        if not MS._readfile then return false end
        local ok, raw = pcall(MS._readfile, path)
        return ok and type(raw) == "string" and #raw > 0
    end

    local function ensureFolder()
        if not MS._makefolder then return false end
        local ok = pcall(function()
            if MS._isfolder then
                local exists, result = pcall(MS._isfolder, MS.Folder)
                if exists and result == true then return end
            end
            MS._makefolder(MS.Folder)
        end)
        if ok and MS._isfolder then
            local ok2, result = pcall(MS._isfolder, MS.Folder)
            if ok2 then return result == true end
        end
        return ok
    end

    function MS.readRaw()
        if MS.canFile then
            -- Compare both save locations by timestamp AND sequence. os.time() has
            -- one-second precision, so timestamp-only comparison could select an
            -- older file when two saves happened in the same second.
            local best, bestAt, bestSeq = nil, -1, -1
            for _, path in ipairs({ MS.FileInFolder, MS.FileRoot }) do
                if fileExists(path) then
                    local ok, raw = pcall(MS._readfile, path)
                    if ok and type(raw) == "string" and #raw > 2 then
                        local at = tonumber(raw:match('"savedAt"%s*:%s*(%d+)')) or 0
                        local seq = tonumber(raw:match('"saveSeq"%s*:%s*(%d+)')) or 0
                        if at > bestAt or (at == bestAt and seq > bestSeq) then
                            best, bestAt, bestSeq = raw, at, seq
                        end
                    end
                end
            end
            if best then return best end
        end
        if type(_G.MoonSaveMemory) == "string" then return _G.MoonSaveMemory end
        return nil
    end

    function MS.load()
        local raw = MS.readRaw()
        if not raw then MS.data = nil return nil end
        local ok, decoded = pcall(function() return HttpService:JSONDecode(raw) end)
        if ok and type(decoded) == "table" and type(decoded.values) == "table" then
            MS.data = decoded
            MS._saveSeq = tonumber(decoded.saveSeq) or 0
            return decoded
        end
        warn("[Moon Hub Save] save file is damaged, starting fresh")
        MS.data = nil
        return nil
    end

    function MS.get(key)
        return MS.data and MS.data.values and MS.data.values[key]
    end

    function MS.write(tbl)
        local ok, json = pcall(function() return HttpService:JSONEncode(tbl) end)
        if not ok or type(json) ~= "string" then return false end
        _G.MoonSaveMemory = json -- session backup (works even without writefile)
        if not MS.canFile then return true end

        -- Keep both supported locations synchronized. Previously only one path
        -- was written; if that write failed, an older copy with the same os.time()
        -- value could win on the next launch and silently roll settings backwards.
        local paths = {}
        if ensureFolder() then table.insert(paths, MS.FileInFolder) end
        table.insert(paths, MS.FileRoot)
        local wroteAtLeastOne = false
        local lastErr = nil
        for _, path in ipairs(paths) do
            local okW, err = pcall(MS._writefile, path, json)
            if okW then
                local verified = true
                if MS._readfile then
                    local okR, check = pcall(MS._readfile, path)
                    verified = okR and type(check) == "string" and check == json
                end
                if verified then
                    wroteAtLeastOne = true
                else
                    lastErr = "verification failed for " .. path
                end
            else
                lastErr = err
            end
        end
        if not wroteAtLeastOne then
            warn("[Moon Hub Save] writefile failed: " .. tostring(lastErr))
            return false
        end
        return true
    end

    function MS.register(key, getter, setter, prio)
        if type(key) ~= "string" or type(getter) ~= "function" then return end
        if MS.items[key] == nil then table.insert(MS.order, key) end
        local okD, def = pcall(getter)
        local defClean = nil
        if okD then defClean = clean(def) end
        MS.items[key] = { get = getter, set = setter, prio = prio or 50, default = defClean }
    end

    function MS.snapshot()
        local values = {}
        -- keep saved keys that were not registered this run (never lose data)
        if MS.data and type(MS.data.values) == "table" then
            for k, v in pairs(MS.data.values) do values[k] = v end
        end
        for _, key in ipairs(MS.order) do
            local it = MS.items[key]
            local ok, v = pcall(it.get)
            if ok then
                local c = clean(v)
                if c ~= nil then values[key] = c end
            end
        end
        return { version = 1, values = values }
    end

    function MS.saveNow(force)
        if not MS.ready or MS.restoring then return false end
        if _G.MoonSave ~= MS then return false end
        -- Skip heavy snapshot when nothing is marked dirty (Android FPS)
        if not force and MS._dirty ~= true and MS.lastSig ~= nil then
            return true
        end
        local snap = MS.snapshot()
        local s = sig(snap.values)
        if not force and s == MS.lastSig then
            MS._dirty = false
            return true
        end
        snap.savedAt = os.time()
        snap.saveSeq = (tonumber(MS._saveSeq) or 0) + 1
        if MS.write(snap) then
            MS._saveSeq = snap.saveSeq
            MS.lastSig = s
            MS.data = snap
            MS._dirty = false
            return true
        end
        return false
    end

    function MS.markDirty()
        if not MS.ready or MS.restoring then return end
        -- During a full reset, defer all intermediate writes. resetAll()
        -- performs one verified save after every factory default is applied.
        if MS._resettingAll then
            MS._dirty = true
            return
        end
        MS._dirty = true
        if MS._flushQueued then return end
        MS._flushQueued = true
        task.delay(0.25, function()
            MS._flushQueued = false
            if _G.MoonSave == MS and MS.ready and not MS.restoring and MS._dirty then
                local ok, saved = pcall(MS.saveNow)
                if not ok or saved ~= true then MS._dirty = true end
            end
        end)
    end

    function MS.restore()
        if not (MS.data and type(MS.data.values) == "table") then return 0 end
        MS.restoring = true
        local list = {}
        for _, key in ipairs(MS.order) do
            local it = MS.items[key]
            if it.set and MS.data.values[key] ~= nil then
                table.insert(list, { key = key, it = it })
            end
        end
        table.sort(list, function(a, b)
            if a.it.prio == b.it.prio then return a.key < b.key end
            return a.it.prio < b.it.prio
        end)
        local applied = 0
        -- Fast restore (old script style) with light frame breathing
        for i, e in ipairs(list) do
            local ok, err = pcall(e.it.set, MS.data.values[e.key])
            if ok then applied = applied + 1
            else warn("[Moon Hub Save] restore '" .. e.key .. "': " .. tostring(err)) end
            if i % 8 == 0 then
                task.wait()
            end
        end
        MS.restoring = false
        return applied
    end

    function MS.clear()
        MS.data = nil
        MS.lastSig = nil
        MS._saveSeq = 0
        _G.MoonSaveMemory = nil
        if MS.canFile and MS._delfile then
            pcall(MS._delfile, MS.FileInFolder)
            pcall(MS._delfile, MS.FileRoot)
        end
    end

    MS.load()
    -- Instant Reset is permanently V1 now; discard obsolete V2 selection from old saves.
    if MS.data and type(MS.data.values) == "table" and MS.data.values["V:Instant Reset Method"] ~= nil then
        MS.data.values["V:Instant Reset Method"] = nil
        MS._dirty = true
    end
    _G.AmbitiousInstantResetVersion = 1
    if not MS.canFile then
        warn("[Moon Hub Save] this executor has no writefile/readfile: settings are kept only until you leave the game")
    end

    -- things that must be known before the GUI is built
    -- (Skip Intro is read below from its own small file, see MoonSkipIntro)
    _G._MoonHubPendingConfig = _G._MoonHubPendingConfig or {}
    _G._MoonHubPendingConfig.Loaded = nil
    _G._MoonHubPendingConfig.Toggles = _G._MoonHubPendingConfig.Toggles or {}
    _G._MoonHubPendingConfig.Toggles["Anti Lag"] = MS.get("T:Anti Lag") == true
    local _alMode = MS.get("V:Anti Lag Mode")
    if type(_alMode) == "string" and _alMode ~= "" then
        _G._MoonHubPendingConfig.AntiLagMode = _alMode
        _G.MoonHubAntiLagMode = _alMode
    end
end

-- Skip Intro (default OFF; the original intro plays unless the user enables Skip Intro).
-- OFF = play the complete 6-second intro. ON = skip the intro and start the script immediately.
-- The user's choice is saved separately and respected on future runs.
MoonSkipIntro = {
    files = { "MoonHub/MoonHub_SkipIntro.txt", "MoonHub_SkipIntro.txt" },
}
function MoonSkipIntro.read()
    if type(readfile) ~= "function" then return nil end
    for _, path in ipairs(MoonSkipIntro.files) do
        local okE, exists = true, true
        if type(isfile) == "function" then okE, exists = pcall(isfile, path) end
        if okE and exists then
            local ok, raw = pcall(readfile, path)
            if ok and type(raw) == "string" then
                raw = raw:lower():gsub("%s", "")
                if raw == "1" or raw == "true" or raw == "on" then return true end
                if raw == "0" or raw == "false" or raw == "off" then return false end
            end
        end
    end
    return nil
end
function MoonSkipIntro.write(on)
    if type(writefile) ~= "function" then return end
    pcall(function()
        if type(isfolder) == "function" and type(makefolder) == "function" and not isfolder("MoonHub") then
            makefolder("MoonHub")
        end
    end)
    for _, path in ipairs(MoonSkipIntro.files) do
        pcall(writefile, path, on and "1" or "0")
    end
end

local _moonSkipIntroFromFile = MoonSkipIntro.read()
if _moonSkipIntroFromFile ~= nil then
    _G.RivalHubSkipIntro = _moonSkipIntroFromFile
else
    local _moonLegacySkip = _G.MoonSave and _G.MoonSave.get and _G.MoonSave.get("T:Skip Intro")
    _G.RivalHubSkipIntro = (_moonLegacySkip == true)
end

-- One-time restoration after the temporary fast-start build:
-- clear its forced-ON value, restore the original intro as the default,
-- and then leave the toggle fully user-controlled on later runs.
local _moonIntroRestoreDone = false
if type(readfile) == "function" then
    local _ok, _value = pcall(readfile, "MoonHub_IntroRestore_v214.txt")
    _moonIntroRestoreDone = _ok and tostring(_value):gsub("%s", "") == "1"
end
if not _moonIntroRestoreDone then
    _G.RivalHubSkipIntro = false
    pcall(function() MoonSkipIntro.write(false) end)

    -- Also clear the old saved toggle so it cannot turn Skip Intro back ON.
    local _save = _G.MoonSave
    if _save and _save.data and type(_save.data.values) == "table" then
        _save.data.values["T:Skip Intro"] = false
        _save.data.savedAt = os.time()
        if type(_save.write) == "function" then
            pcall(_save.write, _save.data)
        end
    end

    if type(writefile) == "function" then
        pcall(writefile, "MoonHub_IntroRestore_v214.txt", "1")
    end
end

_G.RivalHubSkipIntro = (_G.RivalHubSkipIntro == true)
skipIntroEnabled = (_G.RivalHubSkipIntro == true)

