end
local gui = _introParentGui
if skipIntroEnabled == true then _G.MoonNoTopIntroDone = true end

-- ============================================================
-- MOON NO TOP INTRO: embedded 6-second audio and Delta-friendly loader
-- ============================================================
do
    local skipIntro = (skipIntroEnabled == true) or (_G.RivalHubSkipIntro == true)
    _G.MoonHubFinishIntro = nil
    if skipIntro then
        _G.MoonNoTopIntroDone = true
        -- Skip Intro is ON: do not create intro GUI / audio, the script starts right away
    else
        _G.MoonNoTopIntroDone = false
    local MOON_NO_TOP_DURATION = 6.000
    local MOON_NO_TOP_AUDIO_B64 = [==[]==]
    local introDone = false
    _G.MoonNoTopIntroDone = false
    local introStarted = 0

    local function decodeMoonAudio(data)
        local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local map, out, buf, bits = {}, {}, 0, 0
        for i = 1, #chars do map[string.byte(chars, i)] = i - 1 end
        for i = 1, #data do
            local v = map[string.byte(data, i)]
            if v ~= nil then
                buf = buf * 64 + v
                bits = bits + 6
                if bits >= 8 then
                    bits = bits - 8
                    out[#out + 1] = string.char(math.floor(buf / 2 ^ bits) % 256)
                    buf = buf % 2 ^ bits
                end
            end
        end
        return table.concat(out)
    end

    local introGui = Instance.new("ScreenGui")
    introGui.Name = "MoonNoTopIntro"
    introGui.ResetOnSpawn = false
    introGui.IgnoreGuiInset = true
    introGui.DisplayOrder = 1000000
    introGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
    introGui.Parent = gui.Parent

    local overlay = Instance.new("Frame")
    overlay.Name = "PureBlackIntro"
    overlay.Size = UDim2.fromScale(1, 1)
    overlay.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    overlay.BorderSizePixel = 0
    overlay.ZIndex = 1
    overlay.Parent = introGui

    local title = Instance.new("TextLabel")
    title.Name = "RainbowMoonNoTop"
    title.AnchorPoint = Vector2.new(0.5, 0.5)
    title.Position = UDim2.fromScale(0.5, 0.5)
    title.Size = UDim2.fromScale(0.94, 0.20)
    title.BackgroundTransparency = 1
    title.Text = "MOON NO TOP"
    title.TextColor3 = Color3.fromRGB(255, 255, 255)
    title.TextScaled = true
    title.Font = Enum.Font.GothamBlack
    title.TextStrokeColor3 = Color3.fromRGB(255, 255, 255)
    title.TextStrokeTransparency = 0.72
    title.ZIndex = 5
    title.Parent = introGui
    local rainbow = Instance.new("UIGradient", title)
    rainbow.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 0, 0)),
        ColorSequenceKeypoint.new(0.16, Color3.fromRGB(255, 150, 0)),
