    lyricLabel.Name = "AboutMe"
    lyricLabel.AnchorPoint = Vector2.new(0.5, 0)
    lyricLabel.Position = UDim2.fromScale(0.5, 0.62)
    lyricLabel.Size = UDim2.fromScale(0.85, 0.20)
