    lyricLabel.TextYAlignment = Enum.TextYAlignment.Top
    lyricLabel.Font = Enum.Font.GothamMedium
    lyricLabel.ZIndex = 5
    lyricLabel.Parent = introGui
    task.spawn(function()
        local full = table.concat(lyricsLines, "\n")
        local per = (MOON_NO_TOP_DURATION - 0.8) / #full
        for i = 1, #full do
            if not lyricLabel.Parent then break end
            lyricLabel.Text = full:sub(1, i)
            task.wait(per)
        end
    end)

    local skip = Instance.new("TextButton")
    skip.Name = "Skip"
    skip.AnchorPoint = Vector2.new(1, 0)
    skip.Position = UDim2.new(1, -20, 0, 20)
    skip.Size = UDim2.fromOffset(104, 40)
    skip.BackgroundColor3 = Color3.fromRGB(12, 12, 12)
    skip.BorderSizePixel = 0
    skip.Text = "SKIP  ›"
    skip.TextColor3 = Color3.fromRGB(255, 255, 255)
    skip.TextScaled = true
    skip.Font = Enum.Font.GothamBold
    skip.ZIndex = 8
    skip.Parent = introGui
    Instance.new("UICorner", skip).CornerRadius = UDim.new(0, 8)
    local skipStroke = Instance.new("UIStroke", skip)
    skipStroke.Color = Color3.fromRGB(255, 255, 255)
    skipStroke.Thickness = 1

    TweenService:Create(rainbow, TweenInfo.new(2.0, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1), {Offset = Vector2.new(1, 0)}):Play()
    local music
    -- Start the intro clock immediately; prepare its sound in the background.
    -- Once the local MP3 exists, later runs reuse it instead of decoding and
    -- writing the same 6-second audio on every activation.
    introStarted = os.clock()
    task.spawn(function()
        pcall(function()
            local writer = type(writefile) == "function" and writefile or nil
            local assetLoader = type(getcustomasset) == "function" and getcustomasset
                or (type(getsynasset) == "function" and getsynasset or nil)
            if not assetLoader or introDone or not introGui.Parent then return end

            local audioFile = "MoonNoTop_Intro_6s_v214.mp3"
            if not moonLocalFileExists(audioFile) then
                if not writer then return end
                writer(audioFile, decodeMoonAudio(MOON_NO_TOP_AUDIO_B64))
            end
            if introDone or not introGui.Parent then return end

            local soundId = assetLoader(audioFile)
            if introDone or not introGui.Parent then return end
            local newMusic = Instance.new("Sound")
            newMusic.Name = "MoonNoTopIntroMusic"
            newMusic.SoundId = soundId
            newMusic.Volume = 1
            newMusic.Looped = false
            newMusic.Parent = introGui
            if introDone or not introGui.Parent then
                newMusic:Destroy()
                return
            end
            music = newMusic
            newMusic:Play()
        end)
    end)

    local function finishMoonIntro()
        if introDone then return end
        introDone = true
        _G.MoonNoTopIntroDone = true
        if music then pcall(function() music:Stop() end) end
        pcall(function() introGui:Destroy() end)
        task.defer(function()
            if type(_G.MoonHubFirstShow) == "function" then
                pcall(_G.MoonHubFirstShow)
            end
        end)
    end
    _G.MoonHubFinishIntro = finishMoonIntro
    skip.Activated:Connect(finishMoonIntro)
    UserInputService.InputBegan:Connect(function(input, processed)
        if not processed and input.KeyCode == Enum.KeyCode.Escape then finishMoonIntro() end
    end)
    TweenService:Create(title, TweenInfo.new(0.75, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {TextTransparency = 0}):Play()

    task.spawn(function()
        while not introDone do
            local elapsed = os.clock() - introStarted
            if elapsed >= MOON_NO_TOP_DURATION or skipIntroEnabled == true or _G.RivalHubSkipIntro == true then finishMoonIntro() break end
            RunService.Heartbeat:Wait()
        end
    end)
    end
end

