local TAG = "LocalOutfit_"

local function loadObjects(id)
    local ok, res = pcall(function()
        return game:GetObjects("rbxassetid://" .. tostring(id))
    end)
    if ok and typeof(res) == "table" and #res > 0 then return res end
    ok, res = pcall(function()
        return game:GetService("InsertService"):LoadAsset(id)
    end)
    if ok and res then return { res } end
    return nil
end

local function collectParts(objs)
    local out = {}
    for _, o in ipairs(objs) do
        if o:IsA("BasePart") then out[#out + 1] = o end
        for _, d in ipairs(o:GetDescendants()) do
            if d:IsA("BasePart") then out[#out + 1] = d end
        end
    end
    return out
end

local function findAtt(char, name)
    for _, p in ipairs(char:GetDescendants()) do
        if p:IsA("Attachment") and p.Name == name and p.Parent:IsA("BasePart") then
            return p
        end
    end
end

local function applyBody(char)
    local total = 0
    for _, id in ipairs(HOMERO_CFG.body) do
        local objs = loadObjects(id)
        if objs then
            for _, mp in ipairs(collectParts(objs)) do
                local orig = char:FindFirstChild(mp.Name)
                if orig and orig:IsA("BasePart") then
                    local c = mp:Clone()
                    c.Name = TAG .. "body_" .. mp.Name
                    c.CanCollide = false
                    c.Anchored = false
                    c.Massless = true
                    c.Size = orig.Size
                    c.CFrame = orig.CFrame
                    c.Parent = char
                    local w = Instance.new("WeldConstraint")
                    w.Part0 = orig
                    w.Part1 = c
                    w.Parent = c
                    if orig:GetAttribute("RivalHubOutfitOriginalTransparency") == nil then
                        orig:SetAttribute("RivalHubOutfitOriginalTransparency", orig.Transparency)
                    end
                    orig.Transparency = 1
                    total = total + 1
                end
            end
            for _, o in ipairs(objs) do pcall(function() o:Destroy() end) end
        end
    end
    return total
end

local function attachItem(char, entry)
    local objs = loadObjects(entry.id)
    if not objs then return false end

    local handle
    for _, p in ipairs(collectParts(objs)) do
        if p.Name == "Handle" then handle = p; break end
        if not handle then handle = p end
    end
    if not handle then
        for _, o in ipairs(objs) do pcall(function() o:Destroy() end) end
        return false
    end

    local H = handle:Clone()
    for _, o in ipairs(objs) do pcall(function() o:Destroy() end) end

    H.Name = TAG .. "item_" .. tostring(entry.id)
    H.CanCollide = false
    H.Anchored = false
    H.Massless = true

    local wrap = H:FindFirstChildWhichIsA("WrapLayer")
    local target, c0, c1

    if wrap then
        target = char:FindFirstChild("UpperTorso")
              or char:FindFirstChild("Torso")
              or char:FindFirstChild("HumanoidRootPart")
        c0 = entry.offset or _CFnew()
        c1 = _CFnew()
    else
        local hAtt = H:FindFirstChildOfClass("Attachment")
        local bAtt = hAtt and findAtt(char, hAtt.Name)
        if bAtt then
            target = bAtt.Parent
            c0 = bAtt.CFrame * (entry.offset or _CFnew())
            c1 = hAtt.CFrame
        else
            target = char:FindFirstChild("Head")
            c0 = entry.offset or _CFnew(0, 1.4, 0)
            c1 = _CFnew()
        end
    end

    if not target then H:Destroy(); return false end

    H.CFrame = target.CFrame * c0 * c1:Inverse()
    H.Parent = char

    local w = Instance.new("Weld")
    w.Part0 = target
    w.Part1 = H
    w.C0 = c0
    w.C1 = c1
    w.Parent = H
    return true
end

function applyHomeroOutfit(char)
    if not char then char = LP.Character end
    if not char then return end
    char:WaitForChild("Humanoid", 10)
    char:WaitForChild("Head", 10)
    task.wait(0.4)

    for _, d in ipairs(char:GetChildren()) do
        if d.Name:sub(1, #TAG) == TAG then pcall(function() d:Destroy() end) end
    end

    if HOMERO_CFG.skinColor then
        local bc = char:FindFirstChildWhichIsA("BodyColors") or Instance.new("BodyColors")
        bc.HeadColor3 = HOMERO_CFG.headColor or HOMERO_CFG.skinColor
        bc.TorsoColor3 = HOMERO_CFG.skinColor
        bc.LeftArmColor3, bc.RightArmColor3 = HOMERO_CFG.skinColor, HOMERO_CFG.skinColor
        bc.LeftLegColor3, bc.RightLegColor3 = HOMERO_CFG.skinColor, HOMERO_CFG.skinColor
        bc.Parent = char
    end

    for _, a in ipairs(char:GetChildren()) do
        if a:IsA("Accessory") then
            local h = a:FindFirstChild("Handle")
            if h then h.Transparency = 1 end
        end
    end

    if HOMERO_CFG.shirt then
        local s = char:FindFirstChildWhichIsA("Shirt") or Instance.new("Shirt")
        s.Name = "Shirt"
        s.ShirtTemplate = HOMERO_CFG.shirt
        s.Parent = char
    end
    if HOMERO_CFG.pants then
        local p = char:FindFirstChildWhichIsA("Pants") or Instance.new("Pants")
        p.Name = "Pants"
        p.PantsTemplate = HOMERO_CFG.pants
        p.Parent = char
    end
    if HOMERO_CFG.aplicarCuerpo then applyBody(char) end
    for _, e in ipairs(HOMERO_CFG.items) do attachItem(char, e) end
end

local _originalAppearance = _G.__MoonOriginalAppearance

local function captureOriginalAppearance(char)
    if not char or _originalAppearance then return end
    local data = {
        bodyColors = nil,
        shirt = nil,
        pants = nil,
        headMesh = nil,
        headTexture = nil,
    }
    local bc = char:FindFirstChildWhichIsA("BodyColors")
    if bc then
        data.bodyColors = {
            head = bc.HeadColor3,
            torso = bc.TorsoColor3,
            leftArm = bc.LeftArmColor3,
            rightArm = bc.RightArmColor3,
            leftLeg = bc.LeftLegColor3,
            rightLeg = bc.RightLegColor3,
        }
    end
    local sh = char:FindFirstChildWhichIsA("Shirt")
    if sh then data.shirt = sh.ShirtTemplate end
    local pa = char:FindFirstChildWhichIsA("Pants")
    if pa then data.pants = pa.PantsTemplate end
    local head = char:FindFirstChild("Head")
    if head then
        local sm = head:FindFirstChildWhichIsA("SpecialMesh")
        if sm and sm.MeshType == Enum.MeshType.FileMesh then
            data.headMesh = sm.MeshId
            data.headTexture = sm.TextureId
        end
    end
    _originalAppearance = data
    _G.__MoonOriginalAppearance = data
end

local function clearPreviousOutfitAssets(char)
    if not char then return end
    do
        local headForFace = char:FindFirstChild("Head")
        local f = headForFace and headForFace:FindFirstChild("face")
        if f then
            local otr = f:GetAttribute("RivalHubOriginalFaceTransparency")
            if otr ~= nil then
                pcall(function() f.Transparency = otr end)
                f:SetAttribute("RivalHubOriginalFaceTransparency", nil)
            end
        end
    end
    for _, child in ipairs(char:GetChildren()) do
        if child.Name:sub(1, #TAG) == TAG
        or child.Name == "AuFfitAccessory"
        or child.Name == "BubbleSkinChanger_Hair"
        or child.Name == "BubbleSkinChanger_Hat"
        or child.Name == "Korblox_RightLeg" then
            pcall(function() child:Destroy() end)
        elseif child:IsA("CharacterMesh") and child.BodyPart == Enum.BodyPart.Head then
            pcall(function() child:Destroy() end)
        end
    end
    for _, part in ipairs(char:GetDescendants()) do
        if part:IsA("BasePart") then
            local originalTransparency = part:GetAttribute("RivalHubOutfitOriginalTransparency")
            if originalTransparency ~= nil then
                part.Transparency = originalTransparency
                part:SetAttribute("RivalHubOutfitOriginalTransparency", nil)
            end
            local originalLocalTransparency = part:GetAttribute("RivalHubOutfitOriginalLocalTransparency")
            if originalLocalTransparency ~= nil then
                part.LocalTransparencyModifier = originalLocalTransparency
                part:SetAttribute("RivalHubOutfitOriginalLocalTransparency", nil)
            end
        end
    end
    if _originalAppearance and _originalAppearance.bodyColors then
        local bc = char:FindFirstChildWhichIsA("BodyColors") or Instance.new("BodyColors")
        local o = _originalAppearance.bodyColors
        bc.HeadColor3, bc.TorsoColor3 = o.head, o.torso
        bc.LeftArmColor3, bc.RightArmColor3 = o.leftArm, o.rightArm
        bc.LeftLegColor3, bc.RightLegColor3 = o.leftLeg, o.rightLeg
        bc.Parent = char
    end
    local head = char:FindFirstChild("Head")
    if head and head:IsA("MeshPart") and head:GetAttribute("RivalHubOutfitModifiedMeshPart") then
        pcall(function()
            head.MeshId = head:GetAttribute("RivalHubOutfitOriginalMeshId") or ""
            head.TextureID = head:GetAttribute("RivalHubOutfitOriginalTextureId") or ""
        end)
        head:SetAttribute("RivalHubOutfitModifiedMeshPart", nil)
        head:SetAttribute("RivalHubOutfitOriginalMeshId", nil)
        head:SetAttribute("RivalHubOutfitOriginalTextureId", nil)
    elseif head then
        local specialMesh = head:FindFirstChildWhichIsA("SpecialMesh")
        if specialMesh and specialMesh:GetAttribute("RivalHubOutfitCreatedMesh") then
            specialMesh:Destroy()
        elseif specialMesh and specialMesh:GetAttribute("RivalHubOutfitModifiedMesh") then
            specialMesh.MeshId = specialMesh:GetAttribute("RivalHubOutfitOriginalMeshId") or ""
            specialMesh.TextureId = specialMesh:GetAttribute("RivalHubOutfitOriginalTextureId") or ""
            specialMesh:SetAttribute("RivalHubOutfitModifiedMesh", nil)
            specialMesh:SetAttribute("RivalHubOutfitOriginalMeshId", nil)
            specialMesh:SetAttribute("RivalHubOutfitOriginalTextureId", nil)
        end
    end
end

local function applyNoOutfit(char)
    if not char then char = LP.Character end
    if not char then return end
    for _, d in ipairs(char:GetChildren()) do
        if d.Name:sub(1, #TAG) == TAG then pcall(function() d:Destroy() end) end
    end
    local oldAcc = char:FindFirstChild("AuFfitAccessory")
    if oldAcc then pcall(function() oldAcc:Destroy() end) end
    local oldKorblox = char:FindFirstChild("Korblox_RightLeg")
    if oldKorblox then pcall(function() oldKorblox:Destroy() end) end
    for _, d in ipairs(char:GetChildren()) do
        if d:IsA("CharacterMesh") and d.BodyPart == Enum.BodyPart.Head then
            pcall(function() d:Destroy() end)
        end
    end
    local head = char:FindFirstChild("Head")
    if head then
        head.Transparency = 0
        head.CanCollide = true
        head.LocalTransparencyModifier = 0
        local face = head:FindFirstChild("face")
        if face then face.Transparency = 0 end
        local sm = head:FindFirstChildWhichIsA("SpecialMesh")
        if sm then
            if _originalAppearance and _originalAppearance.headMesh then
                sm.MeshId = _originalAppearance.headMesh
                sm.TextureId = _originalAppearance.headTexture or ""
            else
                pcall(function() sm:Destroy() end)
            end
        end
    end
    pcall(function()
        local neck = char:FindFirstChild("Neck")
        if neck then neck.Enabled = true end
    end)
    for _, partName in ipairs({"RightUpperLeg", "RightLowerLeg", "RightFoot"}) do
        local limb = char:FindFirstChild(partName)
        if limb then limb.Transparency = 0 end
    end
    if _originalAppearance and _originalAppearance.bodyColors then
        local bc = char:FindFirstChildWhichIsA("BodyColors") or Instance.new("BodyColors")
        local o = _originalAppearance.bodyColors
        bc.HeadColor3 = o.head
        bc.TorsoColor3 = o.torso
        bc.LeftArmColor3 = o.leftArm
        bc.RightArmColor3 = o.rightArm
        bc.LeftLegColor3 = o.leftLeg
        bc.RightLegColor3 = o.rightLeg
        bc.Parent = char
    end
    if _originalAppearance and _originalAppearance.shirt then
        local s = char:FindFirstChildWhichIsA("Shirt") or Instance.new("Shirt")
        s.ShirtTemplate = _originalAppearance.shirt
        s.Parent = char
    end
    if _originalAppearance and _originalAppearance.pants then
        local p = char:FindFirstChildWhichIsA("Pants") or Instance.new("Pants")
        p.PantsTemplate = _originalAppearance.pants
        p.Parent = char
    end
    for _, a in ipairs(char:GetChildren()) do
        if a:IsA("Accessory") then
            local h = a:FindFirstChild("Handle")
            if h then h.Transparency = 0 end
        end
    end
    for _, item in ipairs(char:GetChildren()) do
        if item:IsA("Accessory") then
            for _, part in ipairs(item:GetDescendants()) do
                if part:IsA("BasePart") then
                    local original = part:GetAttribute("RivalHubOriginalTransparency")
                    if original ~= nil then part.Transparency = original; part:SetAttribute("RivalHubOriginalTransparency", nil) end
                    local originalLocal = part:GetAttribute("RivalHubOriginalLocalTransparency")
                    if originalLocal ~= nil then part.LocalTransparencyModifier = originalLocal; part:SetAttribute("RivalHubOriginalLocalTransparency", nil) end
                end
            end
        elseif item:IsA("Shirt") then
            local original = item:GetAttribute("RivalHubOriginalTemplate")
            if original ~= nil then item.ShirtTemplate = original; item:SetAttribute("RivalHubOriginalTemplate", nil) end
        elseif item:IsA("Pants") then
            local original = item:GetAttribute("RivalHubOriginalTemplate")
            if original ~= nil then item.PantsTemplate = original; item:SetAttribute("RivalHubOriginalTemplate", nil) end
        elseif item:IsA("ShirtGraphic") then
            local original = item:GetAttribute("RivalHubOriginalGraphic")
            if original ~= nil then item.Graphic = original; item:SetAttribute("RivalHubOriginalGraphic", nil) end
        end
    end
end

-- ============================================================
-- MOON HUB shirt print: clean, centered chest logo on EVERY outfit / skin
-- Uses a SurfaceGui on the front of the torso, so it works with different
-- shirt textures without replacing the player's shirt or pants.
-- ============================================================
function addMoonHubPrint(char)
    if not char then return end

    -- Remove the previous print first (prevents duplicates when switching skins).
    for _, d in ipairs(char:GetDescendants()) do
        if d.Name == TAG .. "logo" then
            pcall(function() d:Destroy() end)
        end
    end

    local torso = char:FindFirstChild("UpperTorso")
        or char:FindFirstChild("Torso")
        or char:FindFirstChild("LowerTorso")
    if not torso or not torso:IsA("BasePart") then return end

    local printGui = Instance.new("SurfaceGui")
    printGui.Name = TAG .. "logo"
    printGui.Adornee = torso
    printGui.Face = Enum.NormalId.Front
    printGui.SizingMode = Enum.SurfaceGuiSizingMode.FixedSize

    -- Match the canvas aspect ratio to the actual torso face.  This avoids
    -- shrinking or stretching the wordmark on different avatar body types.
    local canvasWidth = math.max(200, math.floor(torso.Size.X * 200))
    local canvasHeight = math.max(200, math.floor(torso.Size.Y * 200))
    printGui.CanvasSize = Vector2.new(canvasWidth, canvasHeight)
    printGui.LightInfluence = 0
    printGui.AlwaysOnTop = true
    printGui.ZOffset = 2
    printGui.Parent = torso

    local wordmark = Instance.new("TextLabel")
    wordmark.Name = "MoonHubWordmark"
    wordmark.BackgroundTransparency = 1
    wordmark.BorderSizePixel = 0
    wordmark.Position = UDim2.new(0.02, 0, 0.14, 0)
    wordmark.Size = UDim2.new(0.96, 0, 0.72, 0)
    wordmark.Font = Enum.Font.GothamBlack
    wordmark.Text = "MOON HUB"
    wordmark.TextColor3 = Color3.fromRGB(255, 255, 255)
    wordmark.TextScaled = false
    -- Fixed, torso-scaled font size: the previous TextScaled layout rendered
    -- much too small in-game. This makes the single-line wordmark about
    -- 80–85% of the chest width on standard R6/R15 bodies.
    wordmark.TextSize = math.floor(math.clamp(torso.Size.X * 29, 46, 72))
    wordmark.TextWrapped = false
    wordmark.TextXAlignment = Enum.TextXAlignment.Center
    wordmark.TextYAlignment = Enum.TextYAlignment.Center
    wordmark.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    wordmark.TextStrokeTransparency = 0.35
    wordmark.Parent = printGui
    -- rainbow colors across the text
    local grad = Instance.new("UIGradient")
    grad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0.00, Color3.fromRGB(255, 40, 40)),
        ColorSequenceKeypoint.new(0.17, Color3.fromRGB(255, 150, 0)),
        ColorSequenceKeypoint.new(0.34, Color3.fromRGB(255, 240, 0)),
        ColorSequenceKeypoint.new(0.51, Color3.fromRGB(40, 220, 60)),
        ColorSequenceKeypoint.new(0.68, Color3.fromRGB(0, 180, 255)),
        ColorSequenceKeypoint.new(0.84, Color3.fromRGB(80, 80, 255)),
        ColorSequenceKeypoint.new(1.00, Color3.fromRGB(190, 60, 255)),
    })
    grad.Parent = wordmark
end

-- Moon skins: fully colored body (Black = skin 1, White = skin 2), rainbow MOON HUB shirt print
function applyMoonSkin(char, BODY, HAIR, HAIR2, HOLDER_NAME)
    if not char then char = LP.Character end
    if not char then return end
    pcall(captureOriginalAppearance, char)
    for _, d in ipairs(char:GetChildren()) do
        if d.Name:sub(1, #TAG) == TAG then pcall(function() d:Destroy() end) end
    end

    local bc = char:FindFirstChildWhichIsA("BodyColors") or Instance.new("BodyColors")
    bc.HeadColor3 = BODY
    bc.TorsoColor3 = BODY
    bc.LeftArmColor3 = BODY
    bc.RightArmColor3 = BODY
    bc.LeftLegColor3 = BODY
    bc.RightLegColor3 = BODY
    bc.Parent = char

    local head = char:FindFirstChild("Head")
    if head then
        head.Transparency = 0
        head.LocalTransparencyModifier = 0
        local f = head:FindFirstChild("face")
        if f then f.Transparency = 0 end
    end
    pcall(function() local neck = char:FindFirstChild("Neck"); if neck then neck.Enabled = true end end)

    local holder = Instance.new("Model")
    holder.Name = TAG .. HOLDER_NAME
    holder.Parent = char

    local function piece(base, size, offset, color, shape, material)
        local p = Instance.new("Part")
        p.Name = "Detail"
        p.Shape = shape or Enum.PartType.Ball
        p.Size = size
        p.Color = color
        p.Material = material or Enum.Material.SmoothPlastic
        p.CanCollide = false
        p.CanTouch = false
        p.CanQuery = false
        p.Massless = true
        p.Anchored = false
        p.CastShadow = false
        p.CFrame = base.CFrame * offset
        p.Parent = holder
        local w = Instance.new("Weld")
        w.Part0 = base
        w.Part1 = p
        w.C0 = offset
        w.Parent = p
        return p
    end

    -- Messy fluffy hair (like the reference): scalp cap + many layered pointed strands
    if false and head then
        local hs = head.Size
        local rx, rz = hs.X * 0.5, hs.Z * 0.5
        local top = hs.Y * 0.5
        local HAIR3 = Color3.fromRGB(52, 46, 40)
        -- scalp cap so no skin shows through
        piece(head, Vector3.new(hs.X * 1.12, hs.Y * 0.75, hs.Z * 1.14), CFrame.new(0, top * 0.62, rz * 0.04), HAIR, Enum.PartType.Ball, Enum.Material.Fabric)
        local k = 0
        local function strand(p, d, len, w, col)
            k = k + 1
            local u = d.Unit
            local up = math.abs(u.Y) > 0.95 and Vector3.new(1, 0, 0) or Vector3.new(0, 1, 0)
            local cf = CFrame.lookAt(p, p + u, up) * CFrame.Angles(0, 0, (k % 7) * 0.9) * CFrame.new(0, 0, -len / 2)
            piece(head, Vector3.new(w, w * 0.8, len), cf, col, Enum.PartType.Block, Enum.Material.Fabric)
        end
        -- layers (top -> bottom): strands start on the dome and FALL down/out like a fluffy mop
        local layers = {
            { y = top * 1.02, r = 0.35, n = 12,  len = 0.55, out = 0.35, down = 0.55 },
            { y = top * 0.92, r = 0.65, n = 20, len = 0.60, out = 0.45, down = 0.75 },
            { y = top * 0.75, r = 0.92, n = 28, len = 0.62, out = 0.50, down = 0.95 },
            { y = top * 0.50, r = 1.04, n = 30, len = 0.62, out = 0.35, down = 1.10 },
            { y = top * 0.20, r = 1.06, n = 26, len = 0.55, out = 0.25, down = 1.10 },
        }
        for li, ly in ipairs(layers) do
            for i = 1, ly.n do
                local ang = (i / ly.n) * math.pi * 2 + li * 0.41
                local cx, cz = math.cos(ang), math.sin(ang)
                if not (ly.y < top * 0.9 and cz < -0.5) then
                    local vary = 0.7 + ((k * 29) % 10) / 16
                    local pos = Vector3.new(cx * rx * ly.r, ly.y, cz * rz * ly.r)
                    local sway = ((k % 5) - 2) * 0.18
                    local dir = Vector3.new(cx * ly.out + sway, -ly.down, cz * ly.out + ((k % 3) - 1) * 0.15)
                    strand(pos, dir, ly.len * vary, 0.17, (k % 4 == 0) and HAIR3 or HAIR)
                end
            end
        end
        for i = 1, 14 do
            local ang = i * 0.95
            local rr = (i % 3) * 0.28 + 0.25
            piece(head, Vector3.new(0.42, 0.34, 0.42), CFrame.new(math.cos(ang) * rx * rr, top * (1.0 + (i % 2) * 0.08), math.sin(ang) * rz * rr + rz * 0.05), (i % 3 == 0) and HAIR3 or HAIR, Enum.PartType.Ball, Enum.Material.Fabric)
        end
        -- messy fringe over the forehead (short, drooping, face stays visible)
        for i = -4, 4 do
            local pos = Vector3.new(i * 0.2, top * 0.9, -rz * 0.92)
            strand(pos, Vector3.new(i * 0.2, -1, -0.25), 0.38 + ((i * 7) % 4) * 0.06, 0.15, (i % 2 == 0) and HAIR or HAIR3)
        end
    end

    -- remove any default shirt/pants graphics so the body stays pure black
    for _, item in ipairs(char:GetChildren()) do
        if item:IsA("Shirt") then
            if item:GetAttribute("RivalHubOriginalTemplate") == nil then item:SetAttribute("RivalHubOriginalTemplate", item.ShirtTemplate) end
            item.ShirtTemplate = ""
        elseif item:IsA("Pants") then
            if item:GetAttribute("RivalHubOriginalTemplate") == nil then item:SetAttribute("RivalHubOriginalTemplate", item.PantsTemplate) end
            item.PantsTemplate = ""
        elseif item:IsA("ShirtGraphic") then
            if item:GetAttribute("RivalHubOriginalGraphic") == nil then item:SetAttribute("RivalHubOriginalGraphic", item.Graphic) end
            item.Graphic = ""
        end
    end

    -- headless + one leg removed (hidden on your side)
    local function hidePart(p)
        if p and p:IsA("BasePart") then
            p.Transparency = 1
            p.LocalTransparencyModifier = 1
            for _, c in ipairs(p:GetChildren()) do
                if c:IsA("Decal") or c:IsA("Texture") then c.Transparency = 1 end
            end
        end
    end
    hidePart(head)
    for _, acc in ipairs(char:GetChildren()) do
        if acc:IsA("Accessory") then
            local h = acc:FindFirstChildWhichIsA("BasePart")
            local weld = h and h:FindFirstChildWhichIsA("Weld")
            if weld and weld.Part1 == head or (weld and weld.Part0 == head) then
                for _, d in ipairs(acc:GetDescendants()) do hidePart(d) end
            end
        end
    end
    for _, n in ipairs({"RightUpperLeg", "RightLowerLeg", "RightFoot", "Right Leg"}) do
        hidePart(char:FindFirstChild(n))
    end

    addMoonHubPrint(char)
end

-- Skin 1: Black
local function applyMarhoobOutfit(char)
    applyMoonSkin(char,
        Color3.fromRGB(10, 10, 12),
        Color3.fromRGB(14, 12, 12),
        Color3.fromRGB(30, 26, 26),
        "Marhoob")
end

-- Skin 2: White (same as skin 1, white body instead of black)
function applyWhiteOutfit(char)
    applyMoonSkin(char,
        Color3.fromRGB(250, 250, 252),
        Color3.fromRGB(235, 235, 238),
        Color3.fromRGB(215, 215, 220),
        "White")
end


