function applyOutfitTheme(char, cfg)
    if not (char and type(cfg) == "table") then return end
    if cfg.customApply then return end -- OFF and Outfit 9 keep their own code
    local th = OUTFIT_THEMES[cfg.label]
    if not th then return end
    pcall(captureOriginalAppearance, char) -- so OFF can bring your real look back

    local old = char:FindFirstChild(TAG .. "Theme")
    if old then pcall(function() old:Destroy() end) end
    local holder = Instance.new("Model")
    holder.Name = TAG .. "Theme"
    holder.Parent = char

    local function find(...)
        for _, n in ipairs({...}) do
            local p = char:FindFirstChild(n)
            if p and p:IsA("BasePart") then return p end
        end
        return nil
    end
    local function piece(base, size, offset, color, material, shape, className, transparency)
        local p = Instance.new(className or "Part")
        p.Name = "ThemeDetail"
        if shape and p:IsA("Part") then p.Shape = shape end
        p.Size = size
        p.Color = color
        p.Material = material or Enum.Material.Neon
        p.Transparency = transparency or 0
        p.CanCollide = false
        p.CanTouch = false
        p.CanQuery = false
        p.Massless = true
        p.Anchored = false
        p.CastShadow = false
        p.CFrame = base.CFrame * offset
        p.Parent = holder
        p.LocalTransparencyModifier = 0
        local w = Instance.new("Weld")
        w.Part0 = base
        w.Part1 = p
        w.C0 = offset
        w.Parent = p
        return p
    end
    local function visible(part) return part and part.Transparency < 1 end

    local head = find("Head")
    local torso = find("UpperTorso", "Torso")
    local hip = find("LowerTorso", "Torso")

    -- skin color
    if th.skin then
        local bc = char:FindFirstChildWhichIsA("BodyColors") or Instance.new("BodyColors")
        bc.HeadColor3 = th.skin
        bc.TorsoColor3 = th.skin
        bc.LeftArmColor3, bc.RightArmColor3 = th.skin, th.skin
        bc.LeftLegColor3, bc.RightLegColor3 = th.skin, th.skin
        bc.Parent = char
    end

    -- glowing wrist / ankle bands
    if th.bands then
        local bandColor = th.bandColor or th.glow
        for _, limb in ipairs({
            find("LeftLowerArm", "Left Arm"), find("RightLowerArm", "Right Arm"),
            find("LeftLowerLeg", "Left Leg"), find("RightLowerLeg", "Right Leg"),
        }) do
            if visible(limb) then
                piece(limb, Vector3.new(limb.Size.X * 1.12, 0.14, limb.Size.Z * 1.12),
                    CFrame.new(0, -limb.Size.Y * 0.36, 0), bandColor, Enum.Material.Neon, nil, nil, 0.05)
            end
        end
    end

    -- glowing belt
    if th.belt and hip then
        local y = (hip.Name == "Torso") and -hip.Size.Y * 0.42 or hip.Size.Y * 0.12
        piece(hip, Vector3.new(hip.Size.X * 1.06, 0.16, hip.Size.Z * 1.08), CFrame.new(0, y, 0), th.glow, Enum.Material.Neon)
        piece(hip, Vector3.new(0.34, 0.24, 0.06), CFrame.new(0, y, -hip.Size.Z * 0.54 - 0.03), th.glow2 or th.glow, Enum.Material.Neon)
    end

    -- halo ring above the head
    if th.halo and head then
        local y = head.Size.Y * 0.5 + 1.05
        local n, r = 16, 0.72
        for i = 1, n do
            local a = (i / n) * math.pi * 2
            piece(head, Vector3.new(0.17, 0.17, 0.17), CFrame.new(math.cos(a) * r, y, math.sin(a) * r),
                th.haloColor or th.glow, Enum.Material.Neon, Enum.PartType.Ball)
        end
    end

    -- floating glowing eyes (for the headless outfits)
    if th.eyes and head then
        for _, x in ipairs({ -0.2, 0.2 }) do
            piece(head, Vector3.new(0.2, 0.13, 0.08), CFrame.new(x, 0.12, -head.Size.Z * 0.5 + 0.02), th.glow, Enum.Material.Neon, Enum.PartType.Ball)
        end
    end

    -- horns: bigger + fire on top of them
    if th.hornScale then
        local horns = char:FindFirstChild("AuFfitAccessory")
        if horns and horns:IsA("BasePart") then
            pcall(function()
                local mesh = horns:FindFirstChildWhichIsA("SpecialMesh")
                if mesh then
                    if horns:GetAttribute("MoonBaseScale") == nil then horns:SetAttribute("MoonBaseScale", mesh.Scale) end
                    mesh.Scale = horns:GetAttribute("MoonBaseScale") * th.hornScale
                elseif horns:IsA("MeshPart") then
                    horns.Size = horns.Size * th.hornScale
                end
            end)
            pcall(function()
                for _, child in ipairs(horns:GetDescendants()) do
                    if child:IsA("BasePart") then child.LocalTransparencyModifier = 0 end
                end
                horns.LocalTransparencyModifier = 0
            end)
        end
    end
    if th.hornFire and head then
        for _, x in ipairs({ -0.5, 0.5 }) do
            local p = piece(head, Vector3.new(0.2, 0.2, 0.2), CFrame.new(x, head.Size.Y * 0.5 + 0.9, -0.1), th.glow, Enum.Material.Neon, nil, nil, 1)
            local fire = Instance.new("Fire")
            fire.Color = th.glow
            fire.SecondaryColor = th.glow2 or th.glow
            fire.Size = 1.6
            fire.Heat = 6
            fire.Parent = p
        end
    end

    -- shark fin on the back
    if th.fin and torso then
        local z = torso.Size.Z * 0.5
        piece(torso, Vector3.new(0.14, 1.0, 0.9), CFrame.new(0, 0.25, z + 0.42) * CFrame.Angles(0, math.rad(180), 0),
            th.finColor or th.glow, Enum.Material.SmoothPlastic, nil, "WedgePart")
        piece(torso, Vector3.new(0.16, 0.08, 0.9), CFrame.new(0, -0.25, z + 0.42), th.glow, Enum.Material.Neon)
    end

    -- wings
    if th.wings and torso then
        local z = torso.Size.Z * 0.5 + 0.12
        local main = th.wings == "angel" and Color3.fromRGB(250, 250, 255) or Color3.fromRGB(16, 12, 18)
        local edge = th.wings == "angel" and (th.glow or Color3.fromRGB(255, 215, 90)) or th.glow
        for _, side in ipairs({ -1, 1 }) do
            for i, f in ipairs({ { len = 2.3, y = 0.55, ang = 28 }, { len = 1.9, y = 0.25, ang = 14 }, { len = 1.5, y = -0.05, ang = 2 } }) do
                local cf = CFrame.new(side * (0.45 + f.len * 0.42), f.y + 0.25, z + i * 0.04) * CFrame.Angles(0, 0, math.rad(side * f.ang))
                piece(torso, Vector3.new(f.len, 0.42, 0.08), cf, main, Enum.Material.SmoothPlastic)
                piece(torso, Vector3.new(f.len, 0.07, 0.1), cf * CFrame.new(0, 0.22, 0), edge, Enum.Material.Neon)
            end
        end
    end

    -- particles around the body
    if th.aura and torso then
        local p = piece(torso, Vector3.new(torso.Size.X, torso.Size.Y * 1.6, torso.Size.Z), CFrame.new(0, -0.4, 0), th.glow, Enum.Material.Neon, nil, nil, 1)
        local e = Instance.new("ParticleEmitter")
        e.Color = ColorSequence.new(th.glow, th.glow2 or th.glow)
        e.LightEmission = (th.aura == "smoke") and 0.2 or 1
        e.Rate = (th.aura == "smoke") and 10 or 14
        e.Lifetime = NumberRange.new(0.8, 1.5)
        e.Speed = NumberRange.new(0.4, 1.4)
        e.SpreadAngle = Vector2.new(180, 180)
        e.Acceleration = (th.aura == "bubble" or th.aura == "ember" or th.aura == "smoke") and Vector3.new(0, 2.5, 0) or Vector3.new(0, 0.5, 0)
        local s = (th.aura == "smoke") and 0.9 or ((th.aura == "bubble") and 0.22 or 0.16)
        e.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, s), NumberSequenceKeypoint.new(1, 0) })
        e.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, (th.aura == "smoke") and 0.55 or 0.1), NumberSequenceKeypoint.new(1, 1) })
        if th.aura == "spark" then e.Texture = "rbxasset://textures/particles/sparkles_main.dds" end
        e.Parent = p
    end

    -- soft colored light
    if th.light and torso then
        local holderPart = piece(torso, Vector3.new(0.2, 0.2, 0.2), CFrame.new(0, 0, 0), th.glow, Enum.Material.Neon, nil, nil, 1)
        local light = Instance.new("PointLight")
        light.Color = th.glow
        light.Brightness = 1
        light.Range = 8
        light.Shadows = false
        light.Parent = holderPart
    end
end


function applyOutfitByIndex(index)
    local cfg = OUTFITS[index]
    if not cfg then return end
    local char = LP.Character
    if not char then return end

    -- Vision complete skins handle their own assets; skip Moon body-skin wipe.
    if cfg.visionSkin then
        pcall(function() clearPreviousOutfitAssets(char) end)
        if cfg.customApply then cfg.customApply(char) end
        if outfitSelectorLabel then outfitSelectorLabel.Text = cfg.label end
        if type(scheduleRivalHubSave) == "function" then pcall(scheduleRivalHubSave)
        elseif _G.MoonSave and _G.MoonSave.markDirty then pcall(_G.MoonSave.markDirty) end
        return
    end

    -- Leaving a Vision skin: restore original look first
    pcall(function()
        if type(_G.MoonClearVisionSkin) == "function" and _G.MoonVisionSkinState
            and _G.MoonVisionSkinState.displaySkin and _G.MoonVisionSkinState.displaySkin ~= "Off" then
            _G.MoonClearVisionSkin()
        end
    end)

    clearPreviousOutfitAssets(char)
    for _, item in ipairs(char:GetChildren()) do
        if item:IsA("Accessory") and item.Name:sub(1, #TAG) ~= TAG then
            for _, part in ipairs(item:GetDescendants()) do
                if part:IsA("BasePart") then
                    if part:GetAttribute("RivalHubOriginalTransparency") == nil then
                        part:SetAttribute("RivalHubOriginalTransparency", part.Transparency)
                        part:SetAttribute("RivalHubOriginalLocalTransparency", part.LocalTransparencyModifier)
                    end
                    part.Transparency = 1
                    part.LocalTransparencyModifier = 1
                end
            end
        elseif item:IsA("Shirt") then
            if item:GetAttribute("RivalHubOriginalTemplate") == nil then item:SetAttribute("RivalHubOriginalTemplate", item.ShirtTemplate) end
            item.ShirtTemplate = ""
        elseif item:IsA("Pants") then
            if item:GetAttribute("RivalHubOriginalTemplate") == nil then item:SetAttribute("RivalHubOriginalTemplate", item.PantsTemplate) end
            item.PantsTemplate = ""
        elseif item:IsA("ShirtGraphic") then
            if item:GetAttribute("RivalHubOriginalGraphic") == nil then item:SetAttribute("RivalHubOriginalGraphic", item.Graphic) end
            item.Graphic = ""
        end
    end

    if cfg.customApply then
        cfg.customApply(char)
        if outfitSelectorLabel then outfitSelectorLabel.Text = cfg.label end
        return
    end
    if cfg.bubbleShirt then
        local s = char:FindFirstChildWhichIsA("Shirt") or Instance.new("Shirt")
        s.Name = "BubbleSkinChanger_Shirt"
        s.ShirtTemplate = resolveBubbleTemplate(cfg.bubbleShirt, "Shirt", "ShirtTemplate")
        s.Parent = char
        local p = char:FindFirstChildWhichIsA("Pants") or Instance.new("Pants")
        p.Name = "BubbleSkinChanger_Pants"
        p.PantsTemplate = resolveBubbleTemplate(cfg.bubblePants, "Pants", "PantsTemplate")
        p.Parent = char
        addBubbleHair(char, cfg.bubbleHair)
        if cfg.bubbleHat then addBubbleHair(char, cfg.bubbleHat, "BubbleSkinChanger_Hat") end
        if cfg.korbloxHeadless then pcall(applyBubbleKorbloxHeadless, char) end
        if outfitSelectorLabel then outfitSelectorLabel.Text = cfg.label end
        return
    end
    char:WaitForChild("Head", 5)
    local head = char:FindFirstChild("Head")
    if not head then return end
    for _, d in ipairs(char:GetChildren()) do
        if d:IsA("CharacterMesh") and d.BodyPart == Enum.BodyPart.Head then
            pcall(function() d:Destroy() end)
        end
    end
    local done = false
    if head:IsA("MeshPart") then
        done = pcall(function()
            if not head:GetAttribute("RivalHubOutfitModifiedMeshPart") then
                head:SetAttribute("RivalHubOutfitOriginalMeshId", head.MeshId)
                head:SetAttribute("RivalHubOutfitOriginalTextureId", head.TextureID)
                head:SetAttribute("RivalHubOutfitModifiedMeshPart", true)
            end
            head.MeshId = cfg.headMesh
            head.TextureID = cfg.headTexture or ""
        end)
    end
    if not done then
        local sm = head:FindFirstChildWhichIsA("SpecialMesh")
        if not sm then
            sm = Instance.new("SpecialMesh")
            sm:SetAttribute("RivalHubOutfitCreatedMesh", true)
        elseif not sm:GetAttribute("RivalHubOutfitModifiedMesh") then
            sm:SetAttribute("RivalHubOutfitOriginalMeshId", sm.MeshId)
            sm:SetAttribute("RivalHubOutfitOriginalTextureId", sm.TextureId)
            sm:SetAttribute("RivalHubOutfitModifiedMesh", true)
        end
        sm.Parent = head
        sm.MeshType = Enum.MeshType.FileMesh
        sm.MeshId = cfg.headMesh
        sm.TextureId = cfg.headTexture or ""
    end
    if cfg.shirt then
        local s = char:FindFirstChildWhichIsA("Shirt") or Instance.new("Shirt")
        s.Name = "Shirt"
        s.ShirtTemplate = cfg.shirt
        s.Parent = char
    end
    if cfg.pants then
        local p = char:FindFirstChildWhichIsA("Pants") or Instance.new("Pants")
        p.Name = "Pants"
        p.PantsTemplate = cfg.pants
        p.Parent = char
    end
    local old = char:FindFirstChild("AuFfitAccessory")
    if old then old:Destroy() end
    if cfg.accessory and head then
        local objs = loadObjectsStd(cfg.accessory)
        if objs then
            local handle
            for _, o in ipairs(objs) do
                if o:IsA("BasePart") then handle = o; break end
                local f = o:FindFirstChildWhichIsA("BasePart", true)
                if f then handle = f; break end
            end
            if handle then
                local h = handle:Clone()
                h.Name = "AuFfitAccessory"
                h.CanCollide = false
                h.Anchored = false
                h.Massless = true
                h.Parent = char
                local weld = Instance.new("Weld")
                weld.Part0 = head
                weld.Part1 = h
                weld.C0 = _CFnew(cfg.offset)
                weld.Parent = h
            end
            for _, o in ipairs(objs) do pcall(function() o:Destroy() end) end
        end
    end
    if cfg.headlessKorblox then
        applyHeadlessKorblox(char)
    else
        if char then
            local head2 = char:FindFirstChild("Head")
            if head2 then
                head2.Transparency = 0
                head2.CanCollide = true
                head2.LocalTransparencyModifier = 0
                local face2 = head2:FindFirstChild("face")
                if face2 then face2.Transparency = 0 end
            end
            pcall(function()
                local neck = char:FindFirstChild("Neck")
                if neck then neck.Enabled = true end
            end)
            for _, partName in ipairs({"RightUpperLeg", "RightLowerLeg", "RightFoot"}) do
                local limb = char:FindFirstChild(partName)
                if limb then limb.Transparency = 0 end
            end
            local oldKorblox = char:FindFirstChild("Korblox_RightLeg")
            if oldKorblox then oldKorblox:Destroy() end
        end
    end
    if cfg.blueFire then pcall(addBlueHeadFire, char) end
    if outfitSelectorLabel then outfitSelectorLabel.Text = cfg.label end
end

-- every outfit (except OFF) gets the MOON HUB print + instant save
do
    local _coreApplyOutfit = applyOutfitByIndex
    function applyOutfitByIndex(index)
        _coreApplyOutfit(index)
        local char = LP.Character
        -- new looks for Outfits 1-8 (the Arabic Outfit 9 keeps its own look, never themed)
                if index ~= 1 and char then pcall(addMoonHubPrint, char) end
        if _G.MoonSave and _G.MoonSave.markDirty then pcall(_G.MoonSave.markDirty) end
    end
end


-- ============================================================
-- Moon skins (Black / White) keep-alive (v225)
-- Head + right leg + head accessories stay hidden, and the skin (body color,
-- no shirt/pants, MOON HUB print) is rebuilt automatically whenever the game
-- resets it: ragdoll, bat hit, stun, Medusa, limb rebuild, etc.
-- ============================================================
;(function()
    local RunService = game:GetService("RunService")
    local lastApply = 0
    local acc = 0
    local RIGHT_LEG = {"RightUpperLeg", "RightLowerLeg", "RightFoot", "Right Leg"}

    local function activeSkin()
        local cfg = OUTFITS[currentOutfitIndex]
        if not cfg then return nil end
        -- Skin 1 = Moon black body, Skin 2 = Moon white body
        if cfg.label == "Skin 1" or cfg.label == "Black" then return "Marhoob", Color3.fromRGB(10, 10, 12) end
        if cfg.label == "Skin 2" or cfg.label == "White" then return "White", Color3.fromRGB(250, 250, 252) end
        return nil
    end

    local cacheChar, cacheList, cacheAt = nil, {}, 0

    local function rebuild(char)
        local list = {}
        local function add(p)
            if p and p:IsA("BasePart") then
                list[#list + 1] = p
                for _, c in ipairs(p:GetChildren()) do
                    if c:IsA("Decal") or c:IsA("Texture") then list[#list + 1] = c end
                end
            end
        end
        add(char:FindFirstChild("Head"))
        for _, n in ipairs(RIGHT_LEG) do add(char:FindFirstChild(n)) end
        for _, a in ipairs(char:GetChildren()) do
            if a:IsA("Accessory") and a.Name:sub(1, #TAG) ~= TAG then
                for _, d in ipairs(a:GetDescendants()) do add(d) end
            end
        end
        cacheChar, cacheList, cacheAt = char, list, tick()
    end

    local function hideAll(char)
        if cacheChar ~= char or tick() - cacheAt > 0.25 then rebuild(char) end
        for i = 1, #cacheList do
            local p = cacheList[i]
            if p.Transparency ~= 1 then p.Transparency = 1 end
            if p:IsA("BasePart") and p.LocalTransparencyModifier ~= 1 then
                p.LocalTransparencyModifier = 1
            end
        end
    end

    local function intact(char, holderName, color)
        if not char:FindFirstChild(TAG .. holderName) then return false end
        local bc = char:FindFirstChildWhichIsA("BodyColors")
        if not bc or bc.TorsoColor3 ~= color or bc.HeadColor3 ~= color
            or bc.LeftLegColor3 ~= color or bc.RightLegColor3 ~= color then
            return false
        end
        for _, item in ipairs(char:GetChildren()) do
            if item:IsA("Shirt") and item.ShirtTemplate ~= "" then return false end
            if item:IsA("Pants") and item.PantsTemplate ~= "" then return false end
            if item:IsA("ShirtGraphic") and item.Graphic ~= "" then return false end
        end
        local torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("LowerTorso")
        if torso and not torso:FindFirstChild(TAG .. "logo") then return false end
        return true
    end

    RunService.RenderStepped:Connect(function(dt)
        local holderName, color = activeSkin()
        if not holderName then return end
        if _G._AmbitiousInstantResetBusy then return end
        local char = LP.Character
        if not char or not char.Parent then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return end
        if not char:FindFirstChild("Head") then return end

        pcall(hideAll, char)   -- every frame: head / leg never flash back

        acc = acc + dt
        if acc < 0.1 then return end
        acc = 0
        local ok, good = pcall(intact, char, holderName, color)
        if ok and not good and tick() - lastApply > 0.4 then
            lastApply = tick()
            pcall(applyOutfitByIndex, currentOutfitIndex)
        end
    end)
end)()


