local function isMyPlotByName(plotName)
    local plotsRoot = getPlotsRoot()
    if not plotsRoot then return false end
    local plot = plotsRoot:FindFirstChild(plotName)
    if not plot then return false end
    local sign = plot:FindFirstChild("PlotSign")
    if sign then
        local yb = sign:FindFirstChild("YourBase")
        if yb and yb:IsA("BillboardGui") then
            return yb.Enabled == true
        end
    end
    return false
end

do
-- ===== Auto Steal (V1 Moon Grab + V2 Violette) =====
local autoStealStopProgress = 0.73 -- (V2 only)
local V1_STEAL_START_PROGRESS = 0.60 -- V1: bar starts at exactly 60% on reaching the animal
local _stealLastScan = 0
local _stealPromptData = setmetatable({}, { __mode = "k" })

local function setProgress(value)
    value = _clamp(tonumber(value) or 0, 0, 1)
    updateStealProgress(value, value > 0 and "STEALING" or "READY")
end

local V2Grab = {
    busy = false,
    active = false,
    progress = 0,
    paused = false,
    pauseTime = nil,
    generation = 0,
    phase = "idle",
    data = setmetatable({}, { __mode = "k" }),
}
local V2GrabConfig = {
    STEAL_DURATION = 1.3,
    HOLD_TARGET = 0.8,
    TRIGGER_RADIUS = 18,
    PAUSE_TIMEOUT = 3.0,
    COOLDOWN = 0.05,
}

local function v2PromptDistance(prompt)
    local char = LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root or not prompt then return math.huge end
    local pos = nil
    local parent = prompt.Parent
    if parent then
        if parent:IsA("BasePart") then
            pos = parent.Position
        elseif parent.Parent and parent.Parent:IsA("BasePart") then
            pos = parent.Parent.Position
        else
            local ok, pv = pcall(function()
                if parent:IsA("Model") then return parent:GetPivot().Position end
                return nil
            end)
            if ok then pos = pv end
        end
    end
    if not pos then
        pcall(function()
            local att = prompt:FindFirstAncestorWhichIsA("BasePart")
            if att then pos = att.Position end
        end)
    end
    if not pos then return math.huge end
    return (root.Position - pos).Magnitude
end

local function v2GrabGetCallbacks(prompt)
    local data = V2Grab.data[prompt]
    if data then return data end
    data = { hold = {}, trigger = {}, ready = true }
    pcall(function()
        if type(getconnections) == "function" then
            for _, conn in ipairs(getconnections(prompt.PromptButtonHoldBegan)) do
                if conn.Function then table.insert(data.hold, conn.Function) end
            end
            for _, conn in ipairs(getconnections(prompt.Triggered)) do
                if conn.Function then table.insert(data.trigger, conn.Function) end
            end
        end
    end)
    V2Grab.data[prompt] = data
    return data
end

local function v2FireSteal(prompt, podName, data)
    pcall(function()
        for _, callback in ipairs(data.trigger) do
            task.spawn(function() pcall(callback) end)
        end
        local remote = ReplicatedStorage:FindFirstChild("StealAnimal")
        if remote and podName then
            pcall(function() remote:FireServer(podName) end)
        end
        if prompt then
            pcall(function() prompt:InputHoldBegin() end)
            pcall(function() prompt:Fire() end)
            pcall(function() prompt:InputHoldEnd() end)
        end
    end)
end

local function v2GrabExecuteSteal(prompt, podName)
    if V2Grab.busy or not Steal.AutoStealEnabled or not prompt or not prompt.Parent then return end
    local data = v2GrabGetCallbacks(prompt)
    if not data.ready then return end

    data.ready = false
    V2Grab.busy = true
    V2Grab.active = true
    V2Grab.progress = 0
    V2Grab.paused = false
    V2Grab.pauseTime = nil
    V2Grab.phase = "holding"
    V2Grab.generation = V2Grab.generation + 1
    local runGen = V2Grab.generation
    local startTime = tick()
    local pauseArmed = true
    local fired = false
    isStealing = true
    setProgress(0)

    task.spawn(function()
        for _, callback in ipairs(data.hold) do
            task.spawn(function() pcall(callback) end)
        end
        pcall(function()
            if prompt.InputHoldBegin then prompt:InputHoldBegin() end
        end)

        while runGen == V2Grab.generation
            and Steal.AutoStealEnabled
            and prompt.Parent do -- V2 only

            local skipProgress = false
            local dist = v2PromptDistance(prompt)

            if V2Grab.paused then
                if dist <= V2GrabConfig.TRIGGER_RADIUS then
                    V2Grab.paused = false
                    V2Grab.pauseTime = nil
                    V2Grab.phase = "finishing"
                    startTime = tick() - (V2GrabConfig.HOLD_TARGET * V2GrabConfig.STEAL_DURATION)
                else
                    if not V2Grab.pauseTime then
                        V2Grab.pauseTime = tick()
                    elseif tick() - V2Grab.pauseTime >= V2GrabConfig.PAUSE_TIMEOUT then
                        break
                    end
                    V2Grab.progress = V2GrabConfig.HOLD_TARGET
                    setProgress(V2Grab.progress)
                    task.wait(0.05)
                    skipProgress = true
                end
            end

            if not skipProgress then
                local progress = _clamp((tick() - startTime) / V2GrabConfig.STEAL_DURATION, 0, 1)
                V2Grab.progress = progress
                setProgress(progress)

                if pauseArmed and progress >= V2GrabConfig.HOLD_TARGET then
                    if dist <= V2GrabConfig.TRIGGER_RADIUS then
                        pauseArmed = false
                        V2Grab.paused = false
                        V2Grab.phase = "finishing"
                    else
                        pauseArmed = false
                        V2Grab.paused = true
                        V2Grab.pauseTime = tick()
                        V2Grab.progress = V2GrabConfig.HOLD_TARGET
                        setProgress(V2Grab.progress)
                        V2Grab.phase = "waitingRange"
                    end
                elseif progress >= 1 then
                    V2Grab.phase = "triggering"
                    v2FireSteal(prompt, podName, data)
                    fired = true
                    break
                end
            end
            task.wait(0.05)
        end

        pcall(function()
            if prompt and prompt.Parent and prompt.InputHoldEnd then prompt:InputHoldEnd() end
        end)

        V2Grab.active = false
        V2Grab.busy = false
        V2Grab.paused = false
        V2Grab.pauseTime = nil
        data.ready = true
        isStealing = false
        V2Grab.phase = fired and "success" or "failed"
        task.wait(V2GrabConfig.COOLDOWN)
        if runGen == V2Grab.generation then
            V2Grab.progress = 0
            setProgress(0)
            V2Grab.phase = "idle"
        end
    end)
end

-- cancel any in-progress steal (used when the V1/V2 mode is switched)
function _G.__RivalStealResetState()
    isStealing = false
    V2Grab.generation = V2Grab.generation + 1
    V2Grab.busy = false
    V2Grab.active = false
    setProgress(0)
end

local function findNearestPrompt()
    local char = LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local plots = getPlotsRoot()
    if not root or not plots then return nil, nil end

    local nearestPrompt, nearestDistance, nearestPodName = nil, _huge, nil
    for _, plot in ipairs(plots:GetChildren()) do
        if not isMyPlotByName(plot.Name) then
            local podiums = plot:FindFirstChild("AnimalPodiums")
            if podiums then
                for _, pod in ipairs(podiums:GetChildren()) do
                    pcall(function()
                        local base = pod:FindFirstChild("Base")
                        local spawnPart = base and base:FindFirstChild("Spawn")
                        if spawnPart and spawnPart:IsA("BasePart") then
                            local distance = (spawnPart.Position - root.Position).Magnitude
                            if distance <= getAutoStealRadius() and distance < nearestDistance then
                                local attachment = spawnPart:FindFirstChild("PromptAttachment")
                                if attachment then
                                    for _, child in ipairs(attachment:GetChildren()) do
                                        if child:IsA("ProximityPrompt") and child.ActionText and child.ActionText:find("Steal") then
                                            nearestPrompt = child
                                            nearestDistance = distance
                                            nearestPodName = pod.Name
                                            break
                                        end
                                    end
                                end
                            end
                        end
                    end)
                end
            end
        end
    end
    return nearestPrompt, nearestPodName
end

local function getPromptData(prompt)
    local data = _stealPromptData[prompt]
    if data then return data end
    data = { hold = {}, trigger = {}, ready = true }
    _stealPromptData[prompt] = data
    pcall(function()
        if getconnections then
            for _, connection in ipairs(getconnections(prompt.PromptButtonHoldBegan)) do
                if connection.Function then table.insert(data.hold, connection.Function) end
            end
            for _, connection in ipairs(getconnections(prompt.Triggered)) do
                if connection.Function then table.insert(data.trigger, connection.Function) end
            end
        end
    end)
    return data
end

local function fireSteal(prompt, podName, data)
    pcall(function()
        for _, callback in ipairs(data.trigger) do task.spawn(callback) end
        local remote = ReplicatedStorage:FindFirstChild("StealAnimal")
        if remote and podName then remote:FireServer(podName) end
        if prompt then prompt:Fire() end
    end)
end


-- ===== Auto Steal V2 (Violette half-hold steal) =====
local VioletteSteal = {
    StealDuration = 0.2,
    HalfFireRange = 10,
    HalfHoldMin = 1.3,
    HalfHoldMax = 2.6,
    HalfEntryDelay = 0.1,
    Data = setmetatable({}, { __mode = "k" }),
}
local violetteStealStartTime = nil

local function violettePromptDist(prompt)
    local char = LP.Character
    if not char then return math.huge end
    local root = char:FindFirstChild("HumanoidRootPart")
        or char:FindFirstChild("UpperTorso")
        or char:FindFirstChild("Torso")
    if not root then return math.huge end
    local part = prompt and prompt.Parent
    if part and part:IsA("Attachment") then part = part.Parent end
    if part and part:IsA("BasePart") then
        return (part.Position - root.Position).Magnitude
    end
    local ok, worldPos = pcall(function()
        return prompt.Parent and prompt.Parent.WorldPosition
    end)
    if ok and worldPos then
        return (worldPos - root.Position).Magnitude
    end
    return math.huge
end

local function violetteExecuteSteal(prompt)
    if isStealing or not prompt or not prompt.Parent then return end
    local data = VioletteSteal.Data[prompt]
    if not data then
        data = { hold = {}, trigger = {}, ready = true }
        VioletteSteal.Data[prompt] = data
        if getconnections then
            pcall(function()
                for _, c in ipairs(getconnections(prompt.PromptButtonHoldBegan)) do
                    if c.Function then table.insert(data.hold, c.Function) end
                end
                for _, c in ipairs(getconnections(prompt.Triggered)) do
                    if c.Function then table.insert(data.trigger, c.Function) end
                end
            end)
        end
    end
    if not data.ready then return end
    data.ready = false
    isStealing = true
    violetteStealStartTime = tick()
    if type(updateStealProgress) == "function" then
        pcall(updateStealProgress, 0, "STEALING")
    end
    task.spawn(function()
        for _, fn in ipairs(data.hold) do task.spawn(fn) end
        task.wait(VioletteSteal.HalfHoldMin)
        local inRange = violettePromptDist(prompt) <= VioletteSteal.HalfFireRange
        while true do
            local elapsed = tick() - (violetteStealStartTime or tick())
            if elapsed > VioletteSteal.HalfHoldMax or not prompt.Parent then break end
            if type(updateStealProgress) == "function" then
                local p = math.clamp(elapsed / VioletteSteal.HalfHoldMax, 0, 1)
                pcall(updateStealProgress, p, "STEALING")
            end
            if violettePromptDist(prompt) <= VioletteSteal.HalfFireRange then
                if not inRange then task.wait(VioletteSteal.HalfEntryDelay) end
                for _, fn in ipairs(data.trigger) do task.spawn(fn) end
                break
            end
            task.wait()
        end
        task.wait(0.05)
        data.ready = true
        isStealing = false
        violetteStealStartTime = nil
        if type(updateStealProgress) == "function" then
            pcall(updateStealProgress, 0, "READY")
        end
    end)
end


-- ===== Auto Steal V3 (Rival Hub Auto Steal 1 — full, stop at 75%) =====
local function rivalV1ExecuteSteal(prompt, podName)
    if isStealing then return end
    if not Steal.AutoStealEnabled or not prompt or not prompt.Parent then return end

    if math.random(30) == 1 then
        for p in pairs(Steal.Data or {}) do
            if not p.Parent then Steal.Data[p] = nil end
        end
    end
    Steal.Data = Steal.Data or {}

    if not Steal.Data[prompt] then
        Steal.Data[prompt] = { hold = {}, trigger = {}, ready = true }
        pcall(function()
            if getconnections then
                for _, c in ipairs(getconnections(prompt.PromptButtonHoldBegan)) do
                    if c.Function then table.insert(Steal.Data[prompt].hold, c.Function) end
                end
                for _, c in ipairs(getconnections(prompt.Triggered)) do
                    if c.Function then table.insert(Steal.Data[prompt].trigger, c.Function) end
                end
            end
        end)
    end

    local data = Steal.Data[prompt]
    if not data.ready then return end
    data.ready = false
    isStealing = true

    if type(updateStealProgress) == "function" then
        pcall(updateStealProgress, 0, "STEALING")
    end

    task.spawn(function()
        for _, f in ipairs(data.hold) do task.spawn(f) end

        local startTime = (type(_tick) == "function" and _tick()) or tick()
        local duration = tonumber(Steal.StealDuration) or 1.3
        local stopTime = duration * (tonumber(rivalAutoGrabStopFrac) or 0.75)
        local promptFired = false
        local _clamp = math.clamp

        if rivalAutoGrabStopEnabled then
            while isStealing and Steal.AutoStealEnabled do
                local now = (type(_tick) == "function" and _tick()) or tick()
                local elapsed = now - startTime
                if elapsed >= stopTime then break end
                local progress = _clamp(elapsed / duration, 0, 1)
                if type(updateStealProgress) == "function" then
                    pcall(updateStealProgress, progress, "STEALING")
                end
                if not prompt.Parent or not prompt.Parent.Parent then break end
                local char = LP.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if hrp and prompt.Parent and prompt.Parent.Parent and prompt.Parent.Parent:IsA("BasePart") then
                    if (hrp.Position - prompt.Parent.Parent.Position).Magnitude > (Steal.StealRadius or 61) then
                        break
                    end
                end
                task.wait()
            end

            local stopProgress = _clamp(stopTime / duration, 0, 1)
            if type(updateStealProgress) == "function" then
                pcall(updateStealProgress, stopProgress, "STEALING")
            end

            local phase2Timeout = math.max(2.99 - stopTime - math.max(duration - stopTime, 0), 0.05)
            local phase2Start = (type(_tick) == "function" and _tick()) or tick()

            while isStealing and Steal.AutoStealEnabled do
                local now = (type(_tick) == "function" and _tick()) or tick()
                if now - phase2Start >= phase2Timeout then
                    if type(updateStealProgress) == "function" then pcall(updateStealProgress, 0, "CANCELLED") end
                    data.ready = true
                    isStealing = false
                    task.wait()
                    local newPrompt, newName = findNearestPrompt()
                    if newPrompt then rivalV1ExecuteSteal(newPrompt, newName) end
                    return
                end
                if not prompt.Parent or not prompt.Parent.Parent then
                    isStealing = false
                    if type(updateStealProgress) == "function" then pcall(updateStealProgress, 0, "CANCELLED") end
                    data.ready = true
                    return
                end
                local char = LP.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if hrp and prompt.Parent and prompt.Parent.Parent and prompt.Parent.Parent:IsA("BasePart") then
                    local dist = (hrp.Position - prompt.Parent.Parent.Position).Magnitude
                    if dist <= (rivalAutoGrabSetDelayRadius or 9) then
                        break
                    elseif dist > (Steal.StealRadius or 61) then
                        isStealing = false
                        if type(updateStealProgress) == "function" then pcall(updateStealProgress, 0, "CANCELLED") end
                        data.ready = true
                        return
                    end
                end
                task.wait()
            end

            if isStealing and Steal.AutoStealEnabled then
                local fillStart = (type(_tick) == "function" and _tick()) or tick()
                local fillDuration = math.max(duration - stopTime, 0.05)
                while true do
                    local now = (type(_tick) == "function" and _tick()) or tick()
                    local fp = _clamp((now - fillStart) / fillDuration, 0, 1)
                    local totalProgress = stopProgress + fp * (1 - stopProgress)
                    if type(updateStealProgress) == "function" then
                        pcall(updateStealProgress, totalProgress, "STEALING")
                    end
                    if fp >= 1 and not promptFired then
                        promptFired = true
                        pcall(function()
                            for _, f in ipairs(data.trigger) do task.spawn(f) end
                            local remote = ReplicatedStorage:FindFirstChild("StealAnimal")
                            if remote and podName then remote:FireServer(podName) end
                            if prompt and prompt.Fire then prompt:Fire() end
                        end)
                        break
                    end
                    task.wait()
                end
            end
        else
            while isStealing and Steal.AutoStealEnabled do
                local now = (type(_tick) == "function" and _tick()) or tick()
                local elapsed = now - startTime
                local progress = _clamp(elapsed / duration, 0, 1)
                if type(updateStealProgress) == "function" then
                    pcall(updateStealProgress, progress, "STEALING")
                end
                if not prompt.Parent or not prompt.Parent.Parent then break end
                local char = LP.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if hrp and prompt.Parent.Parent and prompt.Parent.Parent:IsA("BasePart") then
                    if (hrp.Position - prompt.Parent.Parent.Position).Magnitude > (Steal.StealRadius or 61) then break end
                end
                if elapsed >= duration and not promptFired then
                    promptFired = true
                    pcall(function()
                        for _, f in ipairs(data.trigger) do task.spawn(f) end
                        local remote = ReplicatedStorage:FindFirstChild("StealAnimal")
                        if remote and podName then remote:FireServer(podName) end
                        if prompt and prompt.Fire then prompt:Fire() end
                    end)
                    break
                end
                task.wait()
            end
        end

        if type(updateStealProgress) == "function" then pcall(updateStealProgress, 0, "READY") end
        data.ready = true
        isStealing = false
    end)
end


local function executeSteal(prompt, podName)
    if not Steal.AutoStealEnabled or isStealing or not prompt or not prompt.Parent then return end
    if autoStealMode == "V2" then
        violetteExecuteSteal(prompt)
        return
    end
    if autoStealMode == "V3" then
        rivalV1ExecuteSteal(prompt, podName)
        return
    end
    -- V1 = current Moon grab path
    v2GrabExecuteSteal(prompt, podName)
end

function startAutoSteal()
    if autoStealMode ~= "V1" and autoStealMode ~= "V2" and autoStealMode ~= "V3" then autoStealMode = "V1" end
    _G.MoonHubAutoStealMode = autoStealMode
    stopAutoSteal()
    CONFIG.AUTO_STEAL_ENABLED = true
    Steal.AutoStealEnabled = true
    Steal.StealRadius = getAutoStealRadius()
    pcall(syncAutoStealRadiusUI)
    _stealLastScan = 0
    stealConnection = RunService.Heartbeat:Connect(function()
        if not Steal.AutoStealEnabled or isStealing then return end
        if autoStealMode == "V1" and V2Grab and V2Grab.busy then return end
        local now = os.clock()
        if now - _stealLastScan < 0.1 then return end
        _stealLastScan = now
        local p, n = findNearestPrompt()
        if p then
            pcall(executeSteal, p, n)
        end
    end)
    if pbFrame and savedProgressBarPos then
        pcall(function() pbFrame.Position = savedProgressBarPos end)
    end
    updateProgressBarVisibility()
    return true
end
end

function stopAutoSteal()
    CONFIG.AUTO_STEAL_ENABLED = false
    if stealConnection then
        pcall(function() stealConnection:Disconnect() end)
        stealConnection = nil
    end
    isStealing = false
    Steal.AutoStealEnabled = false
    CONFIG.AUTO_STEAL_ENABLED = false
    if type(updateStealProgress) == "function" then
        pcall(updateStealProgress, 0, "READY")
    end
    updateProgressBarVisibility()
end

