function isGamepadInput(inp)
    return inp and inp.UserInputType and inp.UserInputType.Name:match("^Gamepad") ~= nil
end

function isBindableInput(inp)
    if not inp or inp.KeyCode == Enum.KeyCode.Unknown then return false end
    if inp.UserInputType == Enum.UserInputType.Keyboard then return true end
    return isGamepadInput(inp) and GAMEPAD_KEYS[inp.KeyCode] == true
end

function kbMatch(entryOrId, kc)
    if kc == nil then return false end
    local bound = nil
    if type(entryOrId) == "string" then
        bound = _G.RivalBindMap and _G.RivalBindMap[entryOrId]
    elseif type(entryOrId) == "table" then
        if type(KB) == "table" then
            for id, ent in pairs(KB) do
                if ent == entryOrId then
                    bound = _G.RivalBindMap and _G.RivalBindMap[id]
                    break
                end
            end
        end
        if bound == nil then bound = entryOrId.kb or entryOrId.gp end
    else
        bound = entryOrId
    end
    if not bound then return false end
    if bound == "MB3" then return kc == "MB3" or tostring(kc) == "MB3" end
    return bound == kc
end

-- Init bind map from KB defaults (single source of truth)
_G.RivalBindMap = _G.RivalBindMap or {}
local function syncBindMapFromKB()
    if type(KB) ~= "table" then return end
    for id, entry in pairs(KB) do
        if type(entry) == "table" then
            _G.RivalBindMap[id] = entry.kb or entry.gp
        end
    end
end
task.defer(syncBindMapFromKB)

function updateStealProgress(value, state)
    value = _clamp(tonumber(value) or 0, 0, 1)
    state = state or (value > 0 and "STEALING" or "READY")

    if progressTween then pcall(function() progressTween:Cancel() end) end
    if progressFill then
        local target = UDim2.new(value, 0, 1, 0)
        progressTween = TS:Create(progressFill, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Size = target})
        progressTween:Play()
        if state == "STEALING" then
            progressFill.BackgroundColor3 = Color3.fromRGB(0, 110, 255)
        elseif state == "COMPLETE" then
            progressFill.BackgroundColor3 = Color3.fromRGB(220, 230, 240)
        elseif state == "CANCELLED" then
            progressFill.BackgroundColor3 = Color3.fromRGB(105, 110, 125)
        else
            progressFill.BackgroundColor3 = Color3.fromRGB(0, 110, 255)
        end
    end
    if progressPct then progressPct.Text = _floor(value * 100 + 0.5) .. "%" end
    -- status text not used on Moon Hub style bar (FPS/PING shown instead)
end

function resetProgressBar()
    updateStealProgress(0, "READY")
end

local function doTpDown()
    pcall(function()
        local char = LP.Character
        if not char then return end
        local root = char:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local _, yaw = root.CFrame:ToEulerAnglesYXZ()
        root.CFrame = _CFnew(root.Position.X, -7, root.Position.Z) * CFrame.Angles(0, yaw, 0)
        root.AssemblyLinearVelocity = _V3zero
        root.AssemblyAngularVelocity = _V3zero
    end)
end

_G._VynxRunTPDown = doTpDown
_G._VynxTPDownIsAutoOn = function() return false end

do
    local motion = {
        antiBatPulseActive = false,
        antiBatPulseEndedAt = 0,
        recoveryUntil = 0,
        lastMoveDir = _V3zero,
        moveKeys = {
            [Enum.KeyCode.W] = true, [Enum.KeyCode.A] = true,
            [Enum.KeyCode.S] = true, [Enum.KeyCode.D] = true,
            [Enum.KeyCode.Up] = true, [Enum.KeyCode.Left] = true,
            [Enum.KeyCode.Down] = true, [Enum.KeyCode.Right] = true,
        },
    }
    _G.VX7MotionCompat = motion

    -- A REAL hit (bat / Medusa) in progress, while Anti Ragdoll is ON. Aimbots must step
    -- aside on these frames: they keep writing velocity / angular velocity / AutoRotate and
    -- would otherwise fight Anti Ragdoll's recovery, so the hit lands "normally".
    -- Safety valve: after 0.8s of continuous "hit" the aimbot is let through again.
    function motion.isHardHit()
        if antiRagdollMode == nil or antiRagdollMode == "off" then
            motion._hardSince = nil
            return false
        end
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 or _G._AmbitiousInstantResetBusy then
            motion._hardSince = nil
            return false
        end
        local hit = false
        local st
        pcall(function() st = hum:GetState() end)
        if hum.PlatformStand == true then
            hit = true
        elseif st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Ragdoll then
            hit = not (motion.isAntiBatNoise and motion.isAntiBatNoise())
        end
        if not hit then
            local medT = tonumber(_G._AmbitiousMedusaHitTime) or 0
            if medT > 0 and (tick() - medT) < 0.5 then hit = true end
        end
        if not hit then
            motion._hardSince = nil
            return false
        end
        local now = os.clock()
        if not motion._hardSince then motion._hardSince = now end
        if now - motion._hardSince > 0.8 then return false end
        return true
    end
    _G.MoonHubHardHit = function() return motion.isHardHit() end

    function motion.isRagdolled(humanoid)
        if not humanoid then return false end
        local state
        pcall(function() state = humanoid:GetState() end)
        if humanoid.PlatformStand == true
            or state == Enum.HumanoidStateType.Physics
            or state == Enum.HumanoidStateType.Ragdoll
            or state == Enum.HumanoidStateType.FallingDown then
            return true
        end
        local endTime = LP:GetAttribute("RagdollEndTime")
        if endTime ~= nil then
            local ok, serverNow = pcall(function() return workspace:GetServerTimeNow() end)
            if ok and tonumber(endTime) and tonumber(endTime) > serverNow then return true end
        end
        return false
    end

    function motion.getMoveDirection(humanoid)
        local moveDirection = humanoid and humanoid.MoveDirection or _V3zero
        if moveDirection.Magnitude > 0 then
            motion.lastMoveDir = moveDirection
            lastMoveDir = moveDirection
        elseif antiRagdollMode ~= "off" and motion.lastMoveDir.Magnitude > 0 then
            local moveKeyDown = false
            for key in pairs(motion.moveKeys) do
                local ok, down = pcall(function() return UIS:IsKeyDown(key) end)
                if ok and down then moveKeyDown = true; break end
            end
            if moveKeyDown then moveDirection = motion.lastMoveDir end
        end
        return moveDirection
    end

    -- Anti Bat / Anti Ragdoll coordination: the Anti Bat velocity pulse can make the
    -- Humanoid briefly report Physics / FallingDown. That is NOT a real ragdoll, so
    -- Anti Ragdoll must ignore it. A real game ragdoll (RagdollEndTime in the future
    -- or ball-socket constraints on the character) is never ignored.
    function motion.isAntiBatNoise()
        if antiBatEnabled ~= true and _G.MoonHubAntiBatPulsing ~= true then return false end
        local inWindow = motion.antiBatPulseActive == true
            or _G.MoonHubAntiBatPulsing == true
            or _G._AmbitiousAntiBatSpiking == true
            or (os.clock() - (tonumber(motion.antiBatPulseEndedAt) or 0)) < 0.08
        if not inWindow then return false end
        local endTime = LP:GetAttribute("RagdollEndTime")
        if endTime ~= nil then
            local ok, serverNow = pcall(function() return workspace:GetServerTimeNow() end)
            if ok and tonumber(endTime) and tonumber(endTime) > serverNow then return false end
        end
        -- Medusa freeze / recent Medusa hit is always a real hit, never pulse noise.
        local medT = tonumber(_G._AmbitiousMedusaHitTime) or 0
        if medT > 0 and (tick() - medT) < 4 then return false end
        local char = LP.Character
        if char then
            -- PlatformStand is never produced by the Anti Bat pulse: it is the game's ragdoll.
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum and hum.PlatformStand == true then return false end
            for _, d in ipairs(char:GetDescendants()) do
                if d:IsA("BallSocketConstraint") then return false end
            end
        end
        return true
    end

    function motion.isRecoveryWindow()
        return os.clock() < (tonumber(motion.recoveryUntil) or 0)
    end

    function motion.beginRecovery()
        motion.recoveryUntil = os.clock() + 0.18
    end

    function motion.shouldPreserveMotion(humanoid)
        if motion.isHardHit() then return false end
        if autoBatEnabled == true or autoLeftEnabled == true or autoRightEnabled == true then return true end
        if _G._AmbitiousAntiBatSpiking == true
            or _G.MoonHubAntiBatPulsing == true
            or motion.antiBatPulseActive == true then
            return true
        end
        if autoTPEnabled == true or dropActive == true or _G.IsDropping == true
            or _G._AmbitiousZigZagFalling == true then
            return true
        end
        local speedEngine = _G.__RivalHubSpeedEngine
        local speedActive = speedMode == true or laggerToggled == true or laggerCarryToggled == true
            or (speedEngine and speedEngine.started == true)
        local intended = _G.MoonHubSpeedIntended
        if type(intended) == "table" and tonumber(intended.t)
            and (os.clock() - intended.t) <= 0.15 then
            speedActive = true
        end
        if speedActive and motion.getMoveDirection(humanoid).Magnitude > 0.05 then return true end
        return false
    end

    function motion.reset()
        motion.antiBatPulseActive = false
        motion.recoveryUntil = 0
        motion.lastMoveDir = _V3zero
    end
end

local AntiRagdollV1 = {}
AntiRagdollV1.__index = AntiRagdollV1

local BOOST_SPEED = 400
local AR_DEFAULT_SPEED = 16

local stateV1 = {
    active = false,
    isBoosting = false,
    savedWalkSpeed = nil,
    cachedChar = nil,
    ragdollConnections = {},
}

local function disconnectAllV1()
    for _, conn in ipairs(stateV1.ragdollConnections) do
        pcall(function() conn:Disconnect() end)
    end
    stateV1.ragdollConnections = {}
end

local function cacheCharacterV1()
    local char = LP.Character
    if not char then return false end
    local hum = char:FindFirstChildOfClass("Humanoid")
    local root = char:FindFirstChild("HumanoidRootPart")
    if not hum or not root then return false end
    stateV1.cachedChar = { character = char, humanoid = hum, root = root }
    return true
end

local function isRagdolledV1()
    if not stateV1.cachedChar or not stateV1.cachedChar.humanoid then return false end
    local _m = _G.VX7MotionCompat
    if _m and _m.isAntiBatNoise() then return false end
    local hum = stateV1.cachedChar.humanoid
    local st = hum:GetState()
    local ragdollStates = {
        [Enum.HumanoidStateType.Physics] = true,
        [Enum.HumanoidStateType.Ragdoll] = true,
        [Enum.HumanoidStateType.FallingDown] = true,
    }
    return ragdollStates[st] or false
end

local function forceExitRagdollV1()
    if not stateV1.cachedChar or not stateV1.cachedChar.humanoid or not stateV1.cachedChar.root then return end
    local hum = stateV1.cachedChar.humanoid
    local root = stateV1.cachedChar.root
    local motion = _G.VX7MotionCompat
    if motion then motion.beginRecovery() end
    pcall(function()
        LP:SetAttribute("RagdollEndTime", workspace:GetServerTimeNow())
    end)
    for _, descendant in ipairs(stateV1.cachedChar.character:GetDescendants()) do
        if descendant:IsA("BallSocketConstraint") or
           (descendant:IsA("Attachment") and descendant.Name:find("RagdollAttachment")) then
            descendant:Destroy()
        end
    end
    if not stateV1.isBoosting then
        stateV1.isBoosting = true
        stateV1.savedWalkSpeed = hum.WalkSpeed
    end
    -- Keep the selected speed/automated movement owner from being overwritten by V1's boost.
    local preserveMotion = motion and motion.shouldPreserveMotion(hum)
    if preserveMotion then
        if stateV1.savedWalkSpeed ~= nil then hum.WalkSpeed = stateV1.savedWalkSpeed end
    else
        hum.WalkSpeed = BOOST_SPEED
    end
    if hum.Health > 0 then
        hum:ChangeState(Enum.HumanoidStateType.Running)
    end
    root.Anchored = false
end

local function heartbeatLoopV1()
    while stateV1.active do
        task.wait()
        if isRagdolledV1() then
            forceExitRagdollV1()
        elseif stateV1.isBoosting and not isRagdolledV1() then
            stateV1.isBoosting = false
            if stateV1.cachedChar and stateV1.cachedChar.humanoid then
                stateV1.cachedChar.humanoid.WalkSpeed = stateV1.savedWalkSpeed or AR_DEFAULT_SPEED
            end
            stateV1.savedWalkSpeed = nil
        end
    end
end

function AntiRagdollV1.start()
    if stateV1.active then return end
    AntiRagdollV1.stop()
    if not cacheCharacterV1() then
        warn("[AntiRagdollV1] No se pudo cachear el personaje")
        return
    end
    stateV1.active = true
    stateV1.isBoosting = false
    local camConn = RunService.RenderStepped:Connect(function()
        local cam = workspace.CurrentCamera
        if cam and stateV1.cachedChar and stateV1.cachedChar.humanoid then
            cam.CameraSubject = stateV1.cachedChar.humanoid
        end
    end)
    table.insert(stateV1.ragdollConnections, camConn)
    local respawnConn = LP.CharacterAdded:Connect(function()
        stateV1.isBoosting = false
        stateV1.savedWalkSpeed = nil
        task.wait(0.5)
        cacheCharacterV1()
    end)
    table.insert(stateV1.ragdollConnections, respawnConn)
    task.spawn(heartbeatLoopV1)
    print("[AntiRagdollV1] Activado")
end

function AntiRagdollV1.stop()
    stateV1.active = false
    if stateV1.isBoosting and stateV1.cachedChar and stateV1.cachedChar.humanoid then
        stateV1.cachedChar.humanoid.WalkSpeed = stateV1.savedWalkSpeed or AR_DEFAULT_SPEED
    end
    stateV1.isBoosting = false
    stateV1.savedWalkSpeed = nil
    if _G.VX7MotionCompat then _G.VX7MotionCompat.recoveryUntil = 0 end
    disconnectAllV1()
    stateV1.cachedChar = nil
    print("[AntiRagdollV1] Desactivado")
end

function AntiRagdollV1.isRunning() return stateV1.active end

local AntiRagdollV2 = {
    Enabled = false,
    Connection = nil,
    ResetCooldown = 0,
}

function AntiRagdollV2.step(force)
    if not AntiRagdollV2.Enabled then return end
    local char = LP.Character
    if not char then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    local root = char:FindFirstChild("HumanoidRootPart")
    if not hum or not root then return end
    if hum.Health <= 0 or hum:GetState() == Enum.HumanoidStateType.Dead then return end
    local state = hum:GetState()
    local now = _tick()
    local _m = _G.VX7MotionCompat
    -- force = Anti Bat just detected a real hit: never skip it as "pulse noise"
    if not force and _m and _m.isAntiBatNoise() then return end
    if state == Enum.HumanoidStateType.Physics or
       state == Enum.HumanoidStateType.Ragdoll or
       state == Enum.HumanoidStateType.FallingDown then
        if force or now - AntiRagdollV2.ResetCooldown > 0.15 then
            AntiRagdollV2.ResetCooldown = now
            local motion = _G.VX7MotionCompat
            if motion then motion.beginRecovery() end
            pcall(function()
                if hum:GetState() == Enum.HumanoidStateType.GettingUp then return end
                if hum.Health <= 0 or hum:GetState() == Enum.HumanoidStateType.Dead then return end
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                -- Vx7 ownership guard: do not zero velocity owned by Anti Bat,
                -- selected speed, Auto Left/Right, or another movement mode.
                local preserveMotion = motion and motion.shouldPreserveMotion(hum)
                if not preserveMotion then
                    root.Velocity = _V3zero
                    root.RotVelocity = _V3zero
                    root.AssemblyLinearVelocity = _V3zero
                    root.AssemblyAngularVelocity = _V3zero
                end
                for _, obj in ipairs(char:GetDescendants()) do
                    if obj:IsA("Motor6D") then obj.Enabled = true end
                    if obj:IsA("Constraint") then obj.Enabled = true end
                end
                workspace.CurrentCamera.CameraSubject = hum
                local PM = LP.PlayerScripts:FindFirstChild("PlayerModule")
                if PM then
                    local CM = require(PM:FindFirstChild("ControlModule"))
                    if CM then CM:Enable() end
                end
                hum.AutoRotate = true
                hum.PlatformStand = false
                hum.Sit = false
            end)
        end
    end
end

local function startAntiRagdollV2()
    if AntiRagdollV2.Connection then return end
    AntiRagdollV2.Enabled = true
    AntiRagdollV2.Connection = RunService.Heartbeat:Connect(function()
        AntiRagdollV2.step(false)
    end)
end

local function stopAntiRagdollV2()
    AntiRagdollV2.Enabled = false
    if AntiRagdollV2.Connection then
        AntiRagdollV2.Connection:Disconnect()
        AntiRagdollV2.Connection = nil
    end
    AntiRagdollV2.ResetCooldown = 0
    if _G.VX7MotionCompat then _G.VX7MotionCompat.recoveryUntil = 0 end
end

function setAntiRagdollMode(mode)
    if AntiRagdollV1.isRunning() then AntiRagdollV1.stop() end
    if AntiRagdollV2.Enabled then stopAntiRagdollV2() end
    antiRagdollMode = mode
    if mode == "v1" then AntiRagdollV1.start()
    elseif mode == "v2" then startAntiRagdollV2() end
    if _G.updateAntiRagdollUI then _G.updateAntiRagdollUI(mode) end
    -- save removed
end

-- Instant Reset hooks: pause Anti Ragdoll while the character is being reset
-- (it would stand the body back up and cancel the reset). Mode/UI/save untouched.
_G.MoonHubPauseAntiRagdoll = function()
    pcall(function() if AntiRagdollV1.isRunning() then AntiRagdollV1.stop() end end)
    pcall(function() if AntiRagdollV2.Enabled then stopAntiRagdollV2() end end)
end
-- Anti Bat -> Anti Ragdoll hand-over. When Anti Bat steps aside because a hit landed,
-- Anti Ragdoll recovers in that very same frame (no waiting for the next Heartbeat).
_G.MoonHubAntiRagdollNow = function()
    pcall(function()
        if AntiRagdollV2.Enabled then AntiRagdollV2.step(true) end
    end)
    pcall(function()
        if AntiRagdollV1.isRunning() and isRagdolledV1() then forceExitRagdollV1() end
    end)
end
_G.MoonHubResumeAntiRagdoll = function()
    pcall(function()
        if antiRagdollMode == "v1" then
            if not AntiRagdollV1.isRunning() then AntiRagdollV1.start() end
        elseif antiRagdollMode == "v2" then
            if not AntiRagdollV2.Enabled then startAntiRagdollV2() end
        end
    end)
end


-- ============================================================
-- ============================================================


-- ============================================================
-- GROUND DETECTION (TP Down / Auto TP Down)
-- Prima si teletrasportava sempre a Y = -7 alla cieca: se stai sopra
-- una montagna o una piattaforma alta, -7 e' molto sotto il pavimento
-- reale, quindi sembra un no-clip attraverso mezza mappa.
-- Adesso si lancia un raycast verso il basso, si trova la Y reale del
-- suolo sotto di noi e ci si posiziona esattamente sopra.
-- Se sotto non c'e' niente (void) si torna al vecchio -7.
-- Tutto dentro un do-block + funzioni globali per non consumare
-- slot di local nel main chunk.
-- ============================================================
do
  local TP_DOWN_FALLBACK_Y = -7.00
  local TP_DOWN_MAX_DISTANCE = 4000
  local TP_DOWN_MAX_STEPS = 12

  -- Exclude sulle versioni nuove, Blacklist su quelle vecchie.
  local EXCLUDE_FILTER = (function()
    local ok, v = pcall(function() return Enum.RaycastFilterType.Exclude end)
    if ok and v then return v end
    local ok2, v2 = pcall(function() return Enum.RaycastFilterType.Blacklist end)
    if ok2 then return v2 end
    return nil
  end)()

  -- Altezza del centro dell'HumanoidRootPart quando si sta in piedi sul pavimento.
  local function standOffset(hum, hrp)
    local half = 1
    pcall(function() half = hrp.Size.Y * 0.5 end)
    if half <= 0 then half = 1 end
    local off = half * 3
    pcall(function()
      if hum and hum.RigType == Enum.HumanoidRigType.R6 then
        off = half * 3
      elseif hum then
        off = half + (hum.HipHeight or (half * 2))
      end
    end)
    -- SANITY CLAMP: l'InstantReset scrive HipHeight = 1e30 come exploit
    -- per uccidere il character. Se il TP Down parte durante quella
    -- finestra (fino a ~2s) leggeremmo 1e30 e la Y finale sarebbe assurda.
    -- Stesso discorso per NaN o valori negativi.
    if off ~= off or off < 1 or off > 12 then off = half * 3 end
    return off + 0.15
  end

  local function rayDown(fromY, x, z, filter)
    local params = RaycastParams.new()
    params.FilterDescendantsInstances = filter
    if EXCLUDE_FILTER then params.FilterType = EXCLUDE_FILTER end
    params.IgnoreWater = true
    pcall(function() params.RespectCanCollide = true end)
    local res
    pcall(function()
      res = Workspace:Raycast(Vector3.new(x, fromY, z), Vector3.new(0, -TP_DOWN_MAX_DISTANCE, 0), params)
    end)
    return res
  end

  -- Ritorna: Y a cui teletrasportarsi, Y del suolo, distanza dal suolo.
  -- Ritorna nil se sotto non c'e' nessun pavimento.
  function _G.AmbitiousGetGroundTPY(char, hrp, hum)
    char = char or LP.Character
    if not char then return nil end
    hrp = hrp or char:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil end
    hum = hum or char:FindFirstChildOfClass("Humanoid")

    -- Si escludono il proprio personaggio e quelli degli altri player,
    -- altrimenti si atterra sulla testa di qualcuno.
    local filter = {char}
    pcall(function()
      for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LP and plr.Character then
          table.insert(filter, plr.Character)
        end
      end
    end)

    local origin = hrp.Position
    local halfY = 1
    pcall(function() halfY = hrp.Size.Y * 0.5 end)
    local startY = origin.Y - halfY - 0.1
    local groundY = nil

    for _ = 1, TP_DOWN_MAX_STEPS do
      local res = rayDown(startY, origin.X, origin.Z, filter)
      if not res then break end
      local part = res.Instance
      local skip = false
      if part then
        pcall(function()
          if part:IsA("BasePart") and part.CanCollide == false then skip = true end
          local model = part:FindFirstAncestorOfClass("Model")
          if model and model:FindFirstChildOfClass("Humanoid") then skip = true end
        end)
      else
        skip = true
      end
      if skip then
        if part then table.insert(filter, part) end
        startY = res.Position.Y - 0.05
      else
        groundY = res.Position.Y
        break
      end
    end

    if not groundY then return nil end
    local targetY = groundY + standOffset(hum, hrp)
    return targetY, groundY, (origin.Y - groundY)
  end

  -- Y finale da usare per il TP: suolo reale se c'e', altrimenti -7 come prima.
  -- Secondo valore = true se il suolo e' stato trovato davvero.
  function _G.AmbitiousResolveTPDownY(char, hrp, hum)
    local ok, y = pcall(_G.AmbitiousGetGroundTPY, char, hrp, hum)
    if ok and type(y) == "number" then return y, true end
    return TP_DOWN_FALLBACK_Y, false
  end
end

-- Ingresso globale al TP Down (identico al percorso NORMAL di Ambitious:
-- Y del suolo reale tramite raycast, yaw mantenuto, velocita' azzerata,
-- jump bloccato finche' non si tocca terra). TP Ragdoll lo chiama sempre
-- con forceNormal = true.
_G._AmbitiousTPDownJumpLocked = false
function _G.AmbitiousRunTPDown(forceNormal)
  pcall(function()
    local char = LP.Character
    if not char then return end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    local hum2 = char:FindFirstChildOfClass("Humanoid")
    if not hum2 then return end
    local targetY = _G.AmbitiousResolveTPDownY(char, hrp, hum2)
    hrp.CFrame = CFrame.new(hrp.Position.X, targetY, hrp.Position.Z) * CFrame.Angles(0, select(2, hrp.CFrame:ToEulerAnglesYXZ()), 0)
    hrp.AssemblyLinearVelocity = Vector3.zero
    pcall(function() hrp.AssemblyAngularVelocity = Vector3.zero end)
    _G._AmbitiousTPDownJumpLocked = true
    task.spawn(function()
      local groundDeadline = os.clock() + 8
      while os.clock() < groundDeadline do
        local c2 = LP.Character
        local h2 = c2 and c2:FindFirstChildOfClass("Humanoid")
        if not h2 or h2.Health <= 0 then break end
        if h2.FloorMaterial ~= Enum.Material.Air then break end
        RunService.Heartbeat:Wait()
      end
      _G._AmbitiousTPDownJumpLocked = false
    end)
  end)
end

function _G.AmbitiousSafeModeGetCountdownLabel()
  local ok, label = pcall(function()
    return LP.PlayerGui
      and LP.PlayerGui:FindFirstChild("DuelsMachineTopFrame")
      and LP.PlayerGui.DuelsMachineTopFrame:FindFirstChild("DuelsMachineTopFrame")
      and LP.PlayerGui.DuelsMachineTopFrame.DuelsMachineTopFrame:FindFirstChild("Timer")
      and LP.PlayerGui.DuelsMachineTopFrame.DuelsMachineTopFrame.Timer:FindFirstChild("Label")
  end)
  return (ok and label) or nil
end

function _G.AmbitiousSafeModeCountdownNumber(text)
  local t = tostring(text or ""):upper():gsub("^%s+", ""):gsub("%s+$", "")
  if t == "GO" or t == "START" or t == "READY" then return true end
  local n = tonumber(t)
  return n ~= nil and n >= 0 and n <= 10
end

-- Il numero che il cartello sta mostrando, oppure nil se non e' un conto
-- alla rovescia. "GO"/"START" valgono 0: il conto e' finito.
function _G.AmbitiousSafeModeCountdownValue()
  local label = _G.AmbitiousSafeModeGetCountdownLabel()
  if not label then return nil end
  local t = tostring(label.Text or ""):upper():gsub("^%s+", ""):gsub("%s+$", "")
  if t == "GO" or t == "START" or t == "READY" then return 0 end
  local n = tonumber(t)
  if n ~= nil and n >= 0 and n <= 10 then return n end
  return nil
end

function _G.AmbitiousSafeModeInDuelCountdown()
  local label = _G.AmbitiousSafeModeGetCountdownLabel()
  return label and _G.AmbitiousSafeModeCountdownNumber(label.Text) or false
end

_G._AmbitiousIsMedusaHit = _G._AmbitiousIsMedusaHit or function()
  return (tick() - (_G._AmbitiousMedusaHitTime or 0)) < 4
end

_G.AmbitiousBatCounterRagdollSeconds = _G.AmbitiousBatCounterRagdollSeconds or 2.6
_G.AmbitiousBatCounterEnemyLock = _G.AmbitiousBatCounterEnemyLock or {}
_G.AmbitiousBatCounterWatchConns = _G.AmbitiousBatCounterWatchConns or {}

function _G.AmbitiousBCMarkEnemyRagdoll(plr)
  if not plr or plr == LP then return end
  local secs = tonumber(_G.AmbitiousBatCounterRagdollSeconds) or 2.6
  _G.AmbitiousBatCounterEnemyLock[plr] = tick() + secs
end

function _G.AmbitiousStopBatCounterWatcher()
  local conns = _G.AmbitiousBatCounterWatchConns
  for k, c in pairs(conns) do
    pcall(function() c:Disconnect() end)
    conns[k] = nil
  end
  for k in pairs(_G.AmbitiousBatCounterEnemyLock) do
    _G.AmbitiousBatCounterEnemyLock[k] = nil
  end
end

function _G.AmbitiousStartBatCounterWatcher()
  _G.AmbitiousStopBatCounterWatcher()
  local conns = _G.AmbitiousBatCounterWatchConns

  local function hookChar(plr, char)
    if not char then return end
    local key = tostring(plr.UserId) .. "_char"
    if conns[key] then pcall(function() conns[key]:Disconnect() end) end
    conns[key] = char.DescendantAdded:Connect(function(d)
      if d:IsA("BallSocketConstraint") then
        _G.AmbitiousBCMarkEnemyRagdoll(plr)
      end
    end)
  end

  local function watchPlayer(plr)
    if plr == LP then return end
    local key = tostring(plr.UserId) .. "_added"
    if conns[key] then pcall(function() conns[key]:Disconnect() end) end
    conns[key] = plr.CharacterAdded:Connect(function(char)
      hookChar(plr, char)
    end)
    if plr.Character then hookChar(plr, plr.Character) end
  end

  conns["_playerAdded"] = Players.PlayerAdded:Connect(watchPlayer)
  conns["_playerRemoving"] = Players.PlayerRemoving:Connect(function(plr)
    _G.AmbitiousBatCounterEnemyLock[plr] = nil
    local ka = tostring(plr.UserId) .. "_added"
    local kc = tostring(plr.UserId) .. "_char"
    if conns[ka] then pcall(function() conns[ka]:Disconnect() end) conns[ka] = nil end
    if conns[kc] then pcall(function() conns[kc]:Disconnect() end) conns[kc] = nil end
  end)

  for _, plr in ipairs(Players:GetPlayers()) do
    watchPlayer(plr)
  end
end

-- Giocatore piu' vicino a noi (vivo), senza limiti di distanza
function _G.AmbitiousGetNearestEnemy()
  local char = LP.Character
  local hrp = char and char:FindFirstChild("HumanoidRootPart")
  if not hrp then return nil end
  local myPos = hrp.Position
  local best, bestDist = nil, math.huge
  for _, plr in ipairs(Players:GetPlayers()) do
    if plr ~= LP then
      local ec = plr.Character
      local ehrp = ec and ec:FindFirstChild("HumanoidRootPart")
      local ehum = ec and ec:FindFirstChildOfClass("Humanoid")
      if ehrp and ehum and ehum.Health > 0 then
        local d = (ehrp.Position - myPos).Magnitude
        if d < bestDist then
          bestDist = d
          best = plr
        end
      end
    end
  end
  return best
end

-- true se il nemico piu' vicino e' stato ragdollato da meno di 2.6s
function _G.AmbitiousIsNearestEnemyRagdolled()
  local plr = _G.AmbitiousGetNearestEnemy()
  if not plr then return false end
  local lockUntil = _G.AmbitiousBatCounterEnemyLock[plr]
  return lockUntil ~= nil and lockUntil > tick()
end

-- ============================================================
-- AUTO PLAY
-- Un solo comando al posto di Auto Left e Auto Right. La direzione non la
-- scegli tu: la decide DOVE SEI quando parte il primo duello. Da quel
-- momento Auto Play e' a tutti gli effetti il pulsante di quella
-- direzione — si accende, si spegne e si comporta esattamente come
-- l'Auto Right (o l'Auto Left) di sempre, e ad accenderlo sei sempre tu.
-- La rilevazione serve solo a capire QUALE dei due sei, e si fa una volta
-- per tutte.
--
-- IL SEGNALE. Il timer del duello, quello che la Safe Mode gia' guarda e
-- che l'Auto Carry Speed usa per non toccare la velocita' durante il
-- conto alla rovescia, e se ne legge il NUMERO. Dal 2 in giu' si comincia
-- a guardare dove sei e si prende il primo istante in cui sei davvero su
-- una base; prima si e' ancora per strada. Fuori dal countdown non si
-- guarda affatto, perche' passare di li' in un momento qualsiasi non vuol
-- dire nulla.
--
-- LE ZONE si confrontano su X e Z soltanto. La Y cambia con il piano su
-- cui ti trovi, e includerla vorrebbe dire non riconoscere piu' la base
-- appena salti o sali su una rampa.
--
-- RILEVARE NON E' AVVIARE. Il countdown serve solo a capire da che parte
-- sei: finita la rilevazione non parte niente e Auto Play resta spento.
-- Proprio per questo l'ascolto non va acceso a mano — gira da solo
-- dall'avvio dello script. Chiedere una pressione per abilitare un
-- ascoltatore che non agisce sarebbe un passaggio in piu' senza motivo, e
-- per giunta facile da dimenticare proprio prima del duello.
--
-- IL RICORDO DEL SERVER. Se ti buttano fuori e rientri NELLO STESSO
-- server, un secondo duello di apertura non c'e' piu': il countdown non
-- ricomparira', e senza un appiglio Auto Play resterebbe muto per tutta
-- la sessione. Per questo il lato rilevato viene salvato insieme al JobId
-- del server; al rientro, se il JobId coincide, la rilevazione si salta e
-- si riprende il lato di prima (solo il lato: Auto Play resta spento e
-- lo accendi tu). Il JobId e' proprio l'identita' di
-- quella partita: cambiare server significa JobId diverso, quindi nessun
-- ricordo e si ricomincia da capo, che e' il comportamento giusto.
-- Tutto questo vale SOLO nel posto di gioco previsto: altrove non si
-- salva e non si ricorda niente, perche' quelle due coordinate li' non
-- vogliono dire nulla.
--
-- Tutto su _G: zero local aggiunti al chunk principale.
-- ============================================================
_G.AmbitiousAutoPlay = _G.AmbitiousAutoPlay or {}

_G.AmbitiousAutoPlay.cfg = {
  RADIUS = 10,
  -- Da quale numero del conto alla rovescia in giu' si comincia a
  -- guardare dove sei. Prima si e' ancora per strada, e una posizione
  -- letta li' e' una posizione di passaggio.
  AT     = 2,
  LEFT   = {x = -466.48, z = 6.65},
  RIGHT  = {x = -466.90, z = 113.56},
  WAIT   = 25,               -- tetto all'attesa della fine del countdown
  PLACE  = 99606176102979,   -- solo qui si salva e ci si ricorda
}

-- Si riparte da spento e senza lato, anche rieseguendo lo script nella
-- stessa sessione: _G sopravvive, e un watcher vecchio resterebbe appeso
-- qui dentro. Il lato non va perso pero': lo rimette restore() leggendo
-- il salvataggio, che e' la stessa strada del rientro dopo un kick.
if _G.AmbitiousAutoPlay.conn then
  pcall(function() _G.AmbitiousAutoPlay.conn:Disconnect() end)
  _G.AmbitiousAutoPlay.conn = nil
end
_G.AmbitiousAutoPlay.side = nil

function _G.AmbitiousAutoPlay.placeOk()
  local ok, id = pcall(function() return game.PlaceId end)
  return ok and id == _G.AmbitiousAutoPlay.cfg.PLACE
end

-- "L", "R" oppure nil se non sei vicino a nessuna delle due basi.
function _G.AmbitiousAutoPlay.zoneDir()
  local A = _G.AmbitiousAutoPlay
  local char = LP.Character
  local hrp = char and char:FindFirstChild("HumanoidRootPart")
  if not hrp then return nil end
  local p = hrp.Position
  local function near(z)
    local dx, dz = p.X - z.x, p.Z - z.z
    return math.sqrt(dx * dx + dz * dz) <= A.cfg.RADIUS
  end
  if near(A.cfg.LEFT)  then return "L" end
  if near(A.cfg.RIGHT) then return "R" end
  return nil
end

-- Il lato rilevato sta girando?
function _G.AmbitiousAutoPlay.running()
  local A = _G.AmbitiousAutoPlay
  if A.side == "L" then return autoLeftEnabled == true end
  if A.side == "R" then return autoRightEnabled == true end
  return false
end

function _G.AmbitiousAutoPlay.save()
  local A = _G.AmbitiousAutoPlay
  if not A.placeOk() then return end
  local ok, job = pcall(function() return tostring(game.JobId or "") end)
  if not ok or job == "" then return end
  A.saveJob  = job
  A.saveSide = A.side
  -- Si ricorda il LATO, non se era acceso: rientrando decidi tu quando
  -- farlo partire. Ripristinare anche l'acceso vorrebbe dire ritrovarsi a
  -- correre da soli appena finito di caricare.
  if _G.MoonSave and _G.MoonSave.markDirty then pcall(_G.MoonSave.markDirty) end
  if _G.MoonSave and _G.MoonSave.saveNow then pcall(_G.MoonSave.saveNow, true) end
end

-- Accende o spegne il lato rilevato. Da qui in poi Auto Play non e' altro
-- che il pulsante di quella direzione.
function _G.AmbitiousAutoPlay.setSideOn(on)
  local A = _G.AmbitiousAutoPlay
  if A.side == "L" then
    if _G.AmbitiousSetAutoLeft then _G.AmbitiousSetAutoLeft(on and true or false) end
  elseif A.side == "R" then
    if _G.AmbitiousSetAutoRight then _G.AmbitiousSetAutoRight(on and true or false) end
  else
    return
  end
  A.save()
  if _G.AmbitiousRefreshMobileButtonStates then
    pcall(_G.AmbitiousRefreshMobileButtonStates)
  end
end

-- Stato per il bottone: e' semplicemente il lato acceso o spento. La
-- rilevazione non e' uno stato da mostrare — gira per conto suo e non
-- comanda niente.
function _G.AmbitiousAutoPlay.active()
  return _G.AmbitiousAutoPlay.running()
end

-- Smette di ascoltare. Non tocca la direzione.
function _G.AmbitiousAutoPlay.stop()
  local A = _G.AmbitiousAutoPlay
  if A.conn then pcall(function() A.conn:Disconnect() end); A.conn = nil end
end

-- Mette in ascolto del countdown. Parte da sola all'avvio dello script:
-- non c'e' niente da "armare", perche' rilevare non fa succedere nulla —
-- serve solo a sapere da che parte sei. Chiedere una pressione per
-- accendere un ascoltatore che non agisce sarebbe un passaggio in piu'
-- senza motivo, e per giunta facile da dimenticare prima del duello.
function _G.AmbitiousAutoPlay.watch()
  local A = _G.AmbitiousAutoPlay
  if A.side then return end     -- lato gia' noto: non c'e' piu' niente da rilevare
  if A.conn then pcall(function() A.conn:Disconnect() end) end

  A.conn = RunService.Heartbeat:Connect(function()
    if A.side then return end

    -- SI LEGGE IL NUMERO, non un cronometro. Il cartello mostra 5, 4, 3 e
    -- via cosi', quindi l'informazione "a che punto siamo" e' gia' li' —
    -- contare i secondi per conto proprio voleva dire ricostruire a mano
    -- una cosa gia' scritta, e infatti sbagliava: tra un numero e l'altro
    -- il cartello sparisce per un istante e il conto ripartiva da zero.
    -- Dal numero AT in giu' si comincia a guardare: prima si e' ancora per
    -- strada. Fuori dal countdown non si guarda niente, perche' passare
    -- vicino a una base in un momento qualsiasi non vuol dire nulla.
    local ok, n = pcall(_G.AmbitiousSafeModeCountdownValue)
    if not ok or n == nil or n > A.cfg.AT then return end

    local dir = A.zoneDir()
    if not dir then
      -- Ancora per strada, o countdown di passaggio con te da tutt'altra
      -- parte: non si decide niente e non si smette di ascoltare. Quella
      -- che conta e' la prima volta UTILE, se no un cartello visto per
      -- caso spegnerebbe la rilevazione per tutta la sessione.
      return
    end

    -- Arrivato. Si rileva e basta: NON si avvia niente, da qui in poi Auto
    -- Play e' il pulsante di quella direzione e a premerlo sei tu.
    A.side = dir
    A.stop()
    A.save()
    if _G.AmbitiousRefreshMobileButtonStates then
      pcall(_G.AmbitiousRefreshMobileButtonStates)
    end
  end)
end

-- Butta via il ricordo. Serve quando il ricordo e' di un'altra partita:
-- tenerlo non farebbe danni (il confronto sul JobId lo scarterebbe
-- comunque) ma resterebbe li' a sporcare, e soprattutto il ricordo giusto
-- di questa partita deve poterlo sostituire senza ambiguita'.
function _G.AmbitiousAutoPlay.forget()
  local A = _G.AmbitiousAutoPlay
  A.saveJob, A.saveSide = nil, nil
  _G._AmbAutoPlaySavedJob  = nil
  _G._AmbAutoPlaySavedSide = nil
  -- QUI NON SI SALVA. Dimenticare capita quasi sempre mentre la config si
  -- sta ancora caricando, e far partire un salvataggio in quel momento
  -- vorrebbe dire scrivere su disco uno stato applicato a meta' — cioe'
  -- perdere impostazioni che non c'entrano niente con Auto Play.
  -- Azzerare i campi basta: il ricordo e' gia' morto, e il primo
  -- salvataggio normale (un toggle qualsiasi) lo toglie anche dal file.
end

-- Rientro nello stesso server dopo un kick: si salta la rilevazione.
function _G.AmbitiousAutoPlay.restore()
  local A = _G.AmbitiousAutoPlay
  if A.side then return end
  -- Fuori dal posto di gioco previsto non si tocca niente: la config e'
  -- una sola per tutti i giochi, e cancellare da qui vorrebbe dire
  -- buttare il ricordo di una partita che magari e' ancora valida.
  if not A.placeOk() then return end
  local side = _G._AmbAutoPlaySavedSide
  if side ~= "L" and side ~= "R" then return end

  local ok, job = pcall(function() return tostring(game.JobId or "") end)
  if not (ok and job ~= "" and job == _G._AmbAutoPlaySavedJob) then
    -- Server diverso: il vecchio ricordo non vale piu' e viene buttato
    -- subito. Auto Play riparte in ascolto e il prossimo 1v1 scrive il
    -- ricordo nuovo — se restasse il vecchio, con il lato gia' deciso,
    -- resteresti inchiodato alla direzione di un'altra partita.
    A.forget()
    return
  end

  -- Si riprende SOLO il lato. Auto Play resta spento: sapere da che parte
  -- andare non vuol dire volerci andare adesso, e ritrovarsi a correre
  -- appena rientrati sarebbe una sorpresa, non una comodita'. Da qui in
  -- poi il bottone e' quello di quella direzione, e lo premi tu.
  A.side = side           -- lato noto: il countdown non serve piu' guardarlo
  A.stop()
  -- Il ricordo viene riportato anche nei campi che la config riscrive: se
  -- restassero vuoti, il primo salvataggio qualsiasi (basta accendere
  -- un'altra opzione) cancellerebbe il ricordo appena ripreso, e un
  -- secondo kick ti troverebbe senza niente.
  A.saveJob, A.saveSide = job, side
  if _G.AmbitiousRefreshMobileButtonStates then
    pcall(_G.AmbitiousRefreshMobileButtonStates)
  end
end

-- Per controllare a occhio cosa sta facendo, senza riempire lo schermo di
-- avvisi: nella console dell'executor basta
--   print(_G.AmbitiousAutoPlayStatus())
-- Dice il lato (o che sta ancora ascoltando), il server di adesso e
-- quello a cui appartiene il ricordo: se i due JobId sono diversi e il
-- lato risulta ancora quello vecchio, allora il ricordo non e' stato
-- scartato — ed e' quello il sintomo da riportare.
function _G.AmbitiousAutoPlayStatus()
  local A = _G.AmbitiousAutoPlay
  local ok, job = pcall(function() return tostring(game.JobId or "") end)
  return table.concat({
    "lato=" .. tostring(A.side or "nessuno"),
    "ascolto=" .. tostring(A.conn ~= nil),
    "placeOk=" .. tostring(A.placeOk()),
    "jobOra=" .. ((ok and job ~= "" and job) or "?"),
    "jobRicordo=" .. tostring(A.saveJob or _G._AmbAutoPlaySavedJob or "nessuno"),
  }, " | ")
end

function _G.AmbitiousAutoPlayToggle()
  local A = _G.AmbitiousAutoPlay
  -- Nessun lato ancora rilevato: non c'e' niente da accendere, e accendere
  -- "a caso" una delle due direzioni sarebbe peggio che non fare nulla.
  if not A.side then return end
  A.setSideOn(not A.running())
end

-- La config puo' essere gia' stata letta prima che questo blocco
-- esistesse: si prova subito, e ci riprova anche chi la legge.
-- Moon Hub: il ricordo (lato + JobId) viene letto dal save automatico.
pcall(function()
  local MS = _G.MoonSave
  if MS and MS.get then
    local s, j = MS.get("V:AutoPlay Side"), MS.get("V:AutoPlay Job")
    if s == "L" or s == "R" then _G._AmbAutoPlaySavedSide = s end
    if type(j) == "string" and j ~= "" then _G._AmbAutoPlaySavedJob = j end
  end
end)
pcall(_G.AmbitiousAutoPlay.restore)
-- E si mette in ascolto da subito: se il lato e' gia' noto watch() esce
-- da sola, se no aspetta il primo countdown senza che nessuno debba
-- ricordarsi di accendere niente.
pcall(_G.AmbitiousAutoPlay.watch)

-- ============================================================
-- BLOCCO DURANTE IL TP RAGDOLL (equivalente Moon Hub della Safe Mode di
-- Ambitious): Auto Left/Right, TP Bat e Bat Aimbot non devono partire
-- mentre il personaggio viene spostato a forza.
-- ============================================================
function _G.AmbitiousSafeModeForceStop(reason)
  pcall(function()
    if _G.RivalSmartAimbot and _G.RivalSmartAimbot.enabled and _G.RivalSmartAimbot.stop then _G.RivalSmartAimbot.stop() end
  end)
  pcall(function() if autoBatEnabled and disableAutoBat then disableAutoBat() end end)
  pcall(function()
    if TPBatState and TPBatState.enabled and tpBatSetEnabled then tpBatSetEnabled(false) end
  end)
  pcall(function()
    if autoLeftEnabled then autoLeftEnabled = false; if stopAutoLeft then stopAutoLeft() end end
  end)
  pcall(function()
    if autoRightEnabled then autoRightEnabled = false; if stopAutoRight then stopAutoRight() end end
  end)
end

function _G.AmbitiousSafeModeIsLocked()
  return _G.AmbitiousTPRagdollBusy == true
end

if _G._AmbitiousTPRBlockConn then pcall(function() _G._AmbitiousTPRBlockConn:Disconnect() end) end
_G._AmbitiousTPRBlockConn = RunService.Heartbeat:Connect(function()
  if _G.AmbitiousTPRagdollBusy == true then
    _G.AmbitiousSafeModeForceStop("TP RAGDOLL")
  end
end)

-- ============================================================
-- TP RAGDOLL
-- Quando ti stendono, invece di restare a terra dove sei caduto ti
-- riporta in tre salti alla tua base — quella giusta, cioe' la stessa che
-- Auto Play ha rilevato.
--
-- IL LATO NON LO RILEVA DA SOLO: legge quello di Auto Play. E' rilevato
-- una volta per partita e vale per entrambi, quindi rifarne un secondo
-- sarebbe lavoro doppio per arrivare allo stesso numero. Ha anche un
-- effetto utile: la rilevazione di Auto Play gira SEMPRE, anche con TP
-- Ragdoll spento, quindi il giorno che lo accendi il lato e' gia' li'.
--
-- I TRE PUNTI sono in fila: uno fuori, uno lungo il fianco e l'ultimo
-- sulla base. Non e' un teletrasporto solo perche' servono tre pivot —
-- passare per i punti intermedi e' il modo di non attraversare mezza
-- mappa in linea retta.
--
-- IL TEMPO. 1.4 secondi dall'istante in cui vieni colpito: un decimo
-- prima che il ragdoll finisca (1.5). Arrivare a terra gia' spostato vale
-- molto di piu' che spostarsi dopo essersi rialzati.
--
-- LA MEDUSA NO. Li' il recupero e' molto piu' lungo: partire a 1.4
-- secondi vorrebbe dire teletrasportarsi mentre si e' ancora bloccati, e
-- ritrovarsi fermi chissa' dove. Una medusata, per questo sistema, e'
-- come se non fosse successo niente.
--
-- IL BLOCCO. Dal colpo fino alla fine dei salti, Auto Left/Right, TP Bat
-- e i Bat Aimbot non devono partire: ognuno ti trascinerebbe da un'altra
-- parte proprio mentre ti stai spostando. E' esattamente il mestiere del
-- blocco della Safe Mode, quindi la condizione e' stata aggiunta li'
-- invece di scriverne un secondo che fa la stessa cosa.
--
-- Tutto su _G: zero local aggiunti al chunk principale.
-- ============================================================
_G.AmbitiousTPRagdoll = _G.AmbitiousTPRagdoll or {}
_G.AmbitiousTPRagdollEnabled = _G.AmbitiousTPRagdollEnabled == true
_G.AmbitiousTPRagdollBusy = false
-- TP Ragdoll trigger mode: 1 = Bat, 2 = Medusa, 3 = Two (bat + medusa, one TP per hit window)
_G.AmbitiousTPRagdollMode = tonumber(_G.AmbitiousTPRagdollMode) or 1
if _G.AmbitiousTPRagdollMode < 1 or _G.AmbitiousTPRagdollMode > 3 then _G.AmbitiousTPRagdollMode = 1 end

-- Single entry for every trigger: a second hit (bat or medusa) during the
-- same sequence never starts a second TP.
function _G.AmbitiousTPRagdollTrigger(isMedusa)
  local T = _G.AmbitiousTPRagdoll
  if type(_G.RivalAntiBatPanicOff) == "function" then pcall(_G.RivalAntiBatPanicOff, "tp-ragdoll-trigger") end
  local now = tick()
  -- In Two mode (Bat + Medusa), allow only one TP per 3-second hit window.
  -- Keep the original 2-second cooldown for the individual modes.
  local mode = tonumber(_G.AmbitiousTPRagdollMode) or 1
  local cooldown = (mode == 3) and 3.0 or 2.0
  if (now - (tonumber(T.lastTrig) or 0)) < cooldown then return end
  T.lastTrig = now
  _G.AmbitiousTPRagdoll.run(isMedusa == true)
end

_G.AmbitiousTPRagdoll.cfg = {
  -- Due momenti distinti, tutti contati dall'istante del colpo.
  BLOCK = 1.40,   -- si blocca quello che ti muove, e parte il TP Down (era 1.15)
  PIVOT = 1.50,   -- i tre salti (era 1.25)
  -- Solo per la MEDUSA: tempi piu' lunghi (1.59 / 1.69, stessa distanza di 0.10)
  -- MEDUSA: TP exactly 3.10s after the Medusa hit (TP Down 0.10s before)
  BLOCK_MED = 3.12,
  PIVOT_MED = 3.22,
  STEP  = 0.095,  -- pausa dopo ogni salto, ultimo compreso
  -- Solo X e Z: la quota non viene imposta, si tiene quella che hai gia'.
  -- Scriverla vorrebbe dire incastrarti nel terreno o lasciarti appeso a
  -- mezz'aria se il piano non e' esattamente quello previsto — e tanto un
  -- attimo prima il TP Down ti ha gia' messo a terra.
  R = {
    {x = -461.00, z =  62.58},
    {x = -459.24, z = -11.13},
    {x = -484.88, z =  24.08},
  },
  L = {
    {x = -461.00, z =  62.58},
    {x = -468.65, z = 133.95},
    {x = -484.88, z =  96.05},
  },
}

function _G.AmbitiousTPRagdoll.run(isMedusa)
  local T = _G.AmbitiousTPRagdoll
  local side = _G.AmbitiousAutoPlay and _G.AmbitiousAutoPlay.side
  if side ~= "L" and side ~= "R" then return end
  local pts = T.cfg[side]
  if not pts then return end

  T.gen = (T.gen or 0) + 1
  T.done = nil
  local myGen = T.gen

  -- BLOCK - IL BLOCCO. Non serve prima: per un secondo e mezzo sei a terra
  -- e non ti muove niente comunque. Serve da qui in poi, perche' da qui in
  -- poi ti si sposta a forza.
  local blockT = isMedusa and T.cfg.BLOCK_MED or T.cfg.BLOCK
  local pivotT = isMedusa and T.cfg.PIVOT_MED or T.cfg.PIVOT
  if isMedusa then
    -- count from the real Medusa hit moment, not from when we noticed it
    local medT = tonumber(_G._AmbitiousMedusaHitTime) or 0
    local late = (medT > 0) and math.max(0, tick() - medT) or 0
    if late > 0.5 then late = 0 end
    blockT = math.max(0, blockT - late)
    pivotT = math.max(0, pivotT - late)
  end
  task.delay(blockT, function()
    if myGen ~= T.gen then return end
    _G.AmbitiousTPRagdollBusy = true
    if _G.AmbitiousSafeModeForceStop then
      pcall(_G.AmbitiousSafeModeForceStop, "TP RAGDOLL")
    end
    -- TP Down, e sempre quello NORMAL anche se hai scelto Slow Fall o
    -- ZigZag: quelli scendono piano, e qui di tempo ce n'e' un decimo di
    -- secondo prima dei salti. Serve ad arrivare a terra prima di essere
    -- spostato, cosi' la quota da cui partono i pivot e' quella buona.
    if _G.AmbitiousRunTPDown then pcall(_G.AmbitiousRunTPDown, true) end
  end)

  -- PIVOT - I SALTI.
  task.delay(pivotT, function()
    if myGen ~= T.gen then return end
    local char = LP.Character
    if not char then
      _G.AmbitiousTPRagdollBusy = false
      return
    end
    for _, pos in ipairs(pts) do
      if myGen ~= T.gen then return end
      pcall(function()
        -- La quota e' quella attuale, non una scritta a mano.
        local here = char:GetPivot().Position
        char:PivotTo(CFrame.new(pos.x, here.Y, pos.z))
      end)
      -- Pausa dopo OGNI salto, ultimo compreso. Senza, i pivot
      -- finirebbero tutti nello stesso frame e il motore vedrebbe solo
      -- l'ultimo: i punti intermedi sarebbe come non averli mai scritti.
      -- Un frame solo bastava a farli registrare, ma a 240 fps sono
      -- quattro millesimi — un tempo fisso non dipende dagli fps. E dopo
      -- l'ultimo serve comunque, se no il blocco cade nello stesso istante
      -- in cui arrivi e qualcosa puo' ripartire prima che la posizione
      -- sia davvero assestata.
      task.wait(T.cfg.STEP)
    end
    _G.AmbitiousTPRagdollBusy = false
    T.done = myGen
  end)
end

function _G.AmbitiousTPRagdoll.stop()
  local T = _G.AmbitiousTPRagdoll
  T.gen = (T.gen or 0) + 1
  _G.AmbitiousTPRagdollBusy = false
  if T.conn then pcall(function() T.conn:Disconnect() end); T.conn = nil end
  -- Il registro dei ragdoll nemici si spegne solo se non lo sta usando
  -- anche il Bat Counter.
  if not batCounterEnabled and _G.AmbitiousStopBatCounterWatcher then
    pcall(_G.AmbitiousStopBatCounterWatcher)
  end
end

function _G.AmbitiousTPRagdoll.start()
  local T = _G.AmbitiousTPRagdoll
  if T.conn then pcall(function() T.conn:Disconnect() end) end
  T.was = false
  T.medStamp = tonumber(_G._AmbitiousMedusaHitTime) or 0
  -- Serve il registro di chi e' stato ragdollato di recente: senza, non
  -- c'e' modo di sapere se il nemico era gia' a terra. E' lo stesso
  -- watcher del Bat Counter, e riavviarlo quando gira gia' non fa danni
  -- (la prima cosa che fa e' ripulirsi).
  if _G.AmbitiousStartBatCounterWatcher then
    pcall(_G.AmbitiousStartBatCounterWatcher)
  end
  T.conn = RunService.Heartbeat:Connect(function()
    if not _G.AmbitiousTPRagdollEnabled then return end
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    -- MORTO, oppure Instant Reset in corso. Gli stessi due casi che il Bat
    -- Counter gia' scarta, e per lo stesso motivo: il ragdoll che si vede
    -- li' non e' un colpo preso, e' la morte o il nostro stesso reset. Non
    -- basta pero' non far partire: se una sequenza era gia' in corso va
    -- anche annullata, se no i salti arriverebbero addosso al cadavere o
    -- al personaggio appena rinato.
    if not hum or hum.Health <= 0 or _G._AmbitiousInstantResetBusy then
      T.was = false
      if (T.gen or 0) ~= (T.done or -1) then
        T.gen = (T.gen or 0) + 1
        T.done = T.gen
        _G.AmbitiousTPRagdollBusy = false
      end
      return
    end
    local mode = tonumber(_G.AmbitiousTPRagdollMode) or 1
    -- MEDUSA trigger (modes 2 and 3): same timing as the bat sequence.
    if mode == 2 or mode == 3 then
      local medT = tonumber(_G._AmbitiousMedusaHitTime) or 0
      if medT > 0 and medT ~= T.medStamp and (tick() - medT) < 0.5 then
        T.medStamp = medT
        _G.AmbitiousTPRagdollTrigger(true)
      end
    end
    local st = hum:GetState()
    -- Stessi due stati che guarda il Synchronize After Hit. FallingDown e'
    -- escluso apposta: quello e' un inciampo, non un colpo.
    local down = (st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Ragdoll)
    if down and not T.was then
      T.was = true
      -- Medusa: si lascia perdere del tutto.
      local med = _G._AmbitiousIsMedusaHit and _G._AmbitiousIsMedusaHit() or false
      -- NEMICO GIA' A TERRA. Se il piu' vicino e' stato ragdollato da meno
      -- di 2.6 secondi, quello a terra per primo sei stato tu a metterlo:
      -- quindi questo non e' un colpo che hai subito, e' lo strascico dello
      -- scambio. E' lo stesso ragionamento (e lo stesso lock) che usa il
      -- Bat Counter V2 per non contare quell'evento come hit.
      local enemyDown = _G.AmbitiousIsNearestEnemyRagdolled
        and _G.AmbitiousIsNearestEnemyRagdolled() or false
      if (mode == 1 or mode == 3) and not med and not enemyDown then _G.AmbitiousTPRagdollTrigger() end
    elseif not down then
      T.was = false
    end
  end)
end

function _G.AmbitiousTPRagdoll.set(on)
  _G.AmbitiousTPRagdollEnabled = on and true or false
  if _G.AmbitiousTPRagdollEnabled then
    _G.AmbitiousTPRagdoll.start()
  else
    _G.AmbitiousTPRagdoll.stop()
  end
end

if _G.AmbitiousTPRagdollEnabled then _G.AmbitiousTPRagdoll.start() end








_antiDieEnabled = false
_antiDieStopped = false
_antiDieSources = { toggle = false, autobat = false, carry = false, spin = false }

_antiDie = {
    enabled = false, loop = nil, healthConn = nil, charConn = nil,
    lastHealTime = 0, invincibleUntil = 0,
    config = {
        healthThreshold = 50,
        invincibilityFrames = 0.75,
        fallDamageProtection = false,
        ragdollProtection = true,
        autoRevive = true,
    },
}

function _antiDie.SuperHeal(hum)
    if not hum or not hum.Parent then return end
    local maxHealth = hum.MaxHealth or 100
    if maxHealth <= 0 or maxHealth == math.huge then maxHealth = 100 end
    pcall(function()
        hum.Health = maxHealth
        if hum.MaxHealth < maxHealth then hum.MaxHealth = maxHealth end
    end)
    _antiDie.invincibleUntil = _tick() + _antiDie.config.invincibilityFrames
    _antiDie.lastHealTime = _tick()
    pcall(function()
        local char = hum.Parent
        if not char then return end
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("NumberValue") then
                local name = child.Name:lower()
                if name:find("health") or name:find("hp") or name:find("life") then
                    child.Value = maxHealth
                end
            end
            if child:IsA("BoolValue") and child.Name:lower():find("dead") then
                child.Value = false
            end
        end
    end)
end

function _antiDie.PreventDamage(root, hum)
    if not hum then return end
    if hum.Health < (hum.MaxHealth or 100) then _antiDie.SuperHeal(hum) end
    if _tick() < _antiDie.invincibleUntil then
        if hum.Health < (hum.MaxHealth or 100) then
            hum.Health = hum.MaxHealth or 100
        end
    end
    if _antiDie.config.ragdollProtection then
        local state = hum:GetState()
        if state == Enum.HumanoidStateType.Physics or
           state == Enum.HumanoidStateType.Ragdoll or
           state == Enum.HumanoidStateType.FallingDown or
           state == Enum.HumanoidStateType.Dead then
            pcall(function()
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                hum:ChangeState(Enum.HumanoidStateType.Running)
            end)
            _antiDie.SuperHeal(hum)
            if root then
                pcall(function() root.AssemblyAngularVelocity = Vector3.zero end)
            end
        end
    end
    if hum.Health <= 0 then
        _antiDie.SuperHeal(hum)
        pcall(function()
            hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            hum:ChangeState(Enum.HumanoidStateType.Running)
        end)
        if root then
            pcall(function()
                root.CFrame = CFrame.new(root.Position + Vector3.new(0, 2, 0))
                root.AssemblyLinearVelocity = Vector3.zero
            end)
        end
    end
end

function _antiDie.AutoRevive()
    if not _antiDie.config.autoRevive then return end
    local char = LP.Character
    if not char then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    local root = char:FindFirstChild("HumanoidRootPart")
    if not hum then return end
    if hum.Health <= 0 then
        _antiDie.SuperHeal(hum)
        pcall(function()
            hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            hum:ChangeState(Enum.HumanoidStateType.Running)
        end)
        if root then
            pcall(function()
                root.CFrame = CFrame.new(root.Position + Vector3.new(0, 3, 0))
                root.AssemblyLinearVelocity = Vector3.zero
            end)
        end
    end
end

function _antiDie.AttachHealth(char)
    if _antiDie.healthConn then _antiDie.healthConn:Disconnect(); _antiDie.healthConn = nil end
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum then hum = char and char:WaitForChild("Humanoid", 3) end
    if not hum then return end
    _antiDie.healthConn = hum:GetPropertyChangedSignal("Health"):Connect(function()
        if not _antiDie.enabled then return end
        if hum.Health < (hum.MaxHealth or 100) then _antiDie.SuperHeal(hum) end
        if hum.Health <= 0 then _antiDie.AutoRevive() end
    end)
    if hum.Health < (hum.MaxHealth or 100) then _antiDie.SuperHeal(hum) end
end

function _antiDie.StartEngine()
    if _antiDie.enabled and _antiDie.loop then return end
    _antiDie.enabled = true
    _antiDieEnabled = true
    antiDieEnabled = true
    if _antiDie.loop then _antiDie.loop:Disconnect(); _antiDie.loop = nil end
    if _antiDie.healthConn then _antiDie.healthConn:Disconnect(); _antiDie.healthConn = nil end
    _antiDie.loop = RunService.Heartbeat:Connect(function()
        if not _antiDie.enabled then return end
        local char = LP.Character
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        local root = char:FindFirstChild("HumanoidRootPart")
        if not hum then return end
        if hum.Health <= 0 then _antiDie.AutoRevive()
        elseif hum.Health <= _antiDie.config.healthThreshold then _antiDie.SuperHeal(hum)
        elseif hum.Health < (hum.MaxHealth or 100) then _antiDie.SuperHeal(hum) end
        _antiDie.PreventDamage(root, hum)
    end)
    if LP.Character then _antiDie.AttachHealth(LP.Character) end
    if _antiDie.charConn then _antiDie.charConn:Disconnect(); _antiDie.charConn = nil end
    _antiDie.charConn = LP.CharacterAdded:Connect(function(char)
        if not _antiDie.enabled then return end
        task.wait(0.05)
        _antiDie.AttachHealth(char)
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then _antiDie.SuperHeal(hum) end
    end)
end

function _antiDie.StopEngine()
    _antiDie.enabled = false
    _antiDieEnabled = false
    antiDieEnabled = false
    if _antiDie.loop then _antiDie.loop:Disconnect(); _antiDie.loop = nil end
    if _antiDie.healthConn then _antiDie.healthConn:Disconnect(); _antiDie.healthConn = nil end
    if _antiDie.charConn then _antiDie.charConn:Disconnect(); _antiDie.charConn = nil end
    pcall(function()
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum then return end
        hum:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
        hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
        hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
        hum.BreakJointsOnDeath = true
        if hum.MaxHealth == math.huge or hum.MaxHealth <= 0 then
            hum.MaxHealth = 100
            hum.Health = math.min(hum.Health, 100)
        end
    end)
end

function _antiDieSetEnabled(enabled)
    enabled = enabled == true
    if enabled == _antiDieEnabled then return end
    if enabled then
        _antiDie.StartEngine()
    else
        _antiDie.StopEngine()
    end
end

function _antiDieRefresh()
    if _antiDieStopped then return end
    local manual = _antiDieSources.toggle
    _antiDieSetEnabled(manual or _antiDieSources.autobat or _antiDieSources.carry or _antiDieSources.spin)
end

_G.__CrystalAntiDieSource = function(source, enabled)
    if _antiDieStopped or _antiDieSources[source] == nil then return end
    _antiDieSources[source] = enabled == true
    _antiDieRefresh()
end

_G.__CrystalAntiDieSet = function(enabled)
    _G.__CrystalAntiDieSource("autobat", enabled)
end

_G.__CrystalAntiDieIsEnabled = function() return _antiDieEnabled end
_G.__CrystalAntiDieStop = function()
    _antiDieStopped = true
    _antiDieSources.toggle = false
    _antiDieSources.autobat = false
    _antiDieSources.carry = false
    _antiDieSources.spin = false
    _antiDieSetEnabled(false)
end

function activateOnCharacter(char)
    if not _antiDieEnabled then return end
    _antiDie.AttachHealth(char)
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then _antiDie.SuperHeal(hum) end
end

AntiDieModule = {
    enabled = false,
    start = function()
        AntiDieModule.enabled = true
        antiDieEnabled = true
        _antiDieStopped = false
        _G.__CrystalAntiDieSource("toggle", true)
    end,
    stop = function()
        AntiDieModule.enabled = false
        antiDieEnabled = false
        _G.__CrystalAntiDieSource("toggle", false)
    end,
}
_G.AntiDie = AntiDieModule

-- ============================================================
-- INSTANT RESET (character reset) — full port from Ambitious
--   V1 = HipHeight (default, the normal one)   V2 = physical fling
--   * camera frozen from the press until the NEW character is ready
--   * Anti Die / Anti Ragdoll paused silently (menu switch + save untouched)
--     and brought back on the new character
--   * FOV / Stretch skip their frames while it runs (MoonHubInstaResetInProgress)
--   * Anti Bat / ragdoll detectors already ignore it (_AmbitiousInstantResetBusy)
-- ============================================================
do
_G._AmbitiousInstantResetBusy = false
_G.MoonHubInstaResetInProgress = false
_G.AmbitiousInstantResetVersion = 1

-- Wait until Head / HumanoidRootPart / Humanoid really exist on this character
if type(_G._AmbitiousWaitCharReady) ~= "function" then
    _G._AmbitiousWaitCharReady = function(character, timeout)
        character = character or LP.Character
        if not character then return false end
        local deadline = os.clock() + (tonumber(timeout) or 5)
        while os.clock() < deadline do
            if not character.Parent then return false end
            if LP.Character and LP.Character ~= character then return false end
            if character:FindFirstChild("HumanoidRootPart")
                and character:FindFirstChildOfClass("Humanoid") then
                return true
            end
            task.wait(0.05)
        end
        return false
    end
end

-- V2 was removed by request. Instant Reset always uses V1 (HipHeight).
_G._AmbitiousDoInstantResetV2 = nil

-- ---------- V1: HIPHEIGHT ----------
_G._AmbitiousDoInstantResetV1 = function()
    _G._AmbitiousResetGaveUp = false
    local character = LP.Character
    if not character then _G._AmbitiousResetGaveUp = true return end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not humanoid then _G._AmbitiousResetGaveUp = true return end

    local originalHipHeight = humanoid.HipHeight
    local attempts = 0
    local done = false

    while character and character.Parent and humanoid
          and humanoid.Health > 0 and LP.Character == character
          and attempts < 40 do
        pcall(function()
            humanoid.HipHeight = 1e30
            humanoid.AutoRotate = true
            for _, part in ipairs(character:GetChildren()) do
                if part:IsA("BasePart") then part.CanCollide = false end
            end
        end)
        if not character.Parent or humanoid.Health <= 0 or LP.Character ~= character then
            done = true
            break
        end
        attempts = attempts + 1
        task.wait(0.05)
    end

    if not done and character and character.Parent and humanoid and humanoid.Health > 0 then
        pcall(function() humanoid.Health = 0 end)
        task.wait(0.1)
        if not character.Parent or humanoid.Health <= 0 then done = true end
    end

    if not done then
        _G._AmbitiousResetGaveUp = true
        if character and character.Parent and humanoid then
            pcall(function()
                humanoid.HipHeight = originalHipHeight
                for _, part in ipairs(character:GetChildren()) do
                    if part:IsA("BasePart") then part.CanCollide = true end
                end
            end)
        end
    end
end

_G._AmbitiousDoInstantReset = function()
    _G.AmbitiousInstantResetVersion = 1
    _G._AmbitiousDoInstantResetV1()
end

-- ---------- camera frozen during the reset ----------
_G._AmbitiousResetCamConn = nil
_G._AmbitiousResetCamSaved = nil

_G._AmbitiousUnlockResetCamera = function()
    if _G._AmbitiousResetCamConn then
        pcall(function() _G._AmbitiousResetCamConn:Disconnect() end)
        _G._AmbitiousResetCamConn = nil
    end
    local saved = _G._AmbitiousResetCamSaved
    _G._AmbitiousResetCamSaved = nil
    if not saved then return end
    local cam = workspace.CurrentCamera
    if not cam then return end
    pcall(function()
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        cam.CameraType = (saved.type == Enum.CameraType.Scriptable)
            and Enum.CameraType.Custom or saved.type
        cam.CameraSubject = hum or saved.subject
    end)
end

_G._AmbitiousLockResetCamera = function()
    local cam = workspace.CurrentCamera
    if not cam then return end
    _G._AmbitiousUnlockResetCamera()
    _G._AmbitiousResetCamSaved = {
        cframe  = cam.CFrame,
        type    = cam.CameraType,
        subject = cam.CameraSubject,
    }
    cam.CameraType = Enum.CameraType.Scriptable
    _G._AmbitiousResetCamConn = RunService.RenderStepped:Connect(function()
        local c = workspace.CurrentCamera
        local saved = _G._AmbitiousResetCamSaved
        if not c or not saved then return end
        if c.CameraType ~= Enum.CameraType.Scriptable then
            c.CameraType = Enum.CameraType.Scriptable
        end
        c.CFrame = saved.cframe
    end)
end

-- ---------- entry point (key G, mobile button INSTANT RESET) ----------
_G.AmbitiousInstantReset = function()
    if _G._AmbitiousInstantResetBusy then return end
    local oldChar = LP.Character
    local oldHum = oldChar and oldChar:FindFirstChildOfClass("Humanoid")
    if not oldHum or oldHum.Health <= 0 then return end   -- already dead / respawning

    _G._AmbitiousInstantResetBusy = true
    _G.MoonHubInstaResetInProgress = true
    _G._AmbitiousResetOldChar = oldChar
    _G._AmbitiousResetGaveUp = false

    -- Anti Die: technical, silent stop (switch stays ON, save stays ON)
    local wasAntiDie = (_antiDieEnabled == true)
    if wasAntiDie then pcall(_antiDie.StopEngine) end
    -- Anti Ragdoll: would stand the body back up
    pcall(_G.MoonHubPauseAntiRagdoll)

    pcall(_G._AmbitiousLockResetCamera)

    task.spawn(function()
        pcall(_G._AmbitiousDoInstantReset)
    end)

    task.spawn(function()
        local deadline = tick() + 25
        local newChar = nil
        while tick() < deadline do
            if _G._AmbitiousResetGaveUp then break end
            local ch = LP.Character
            if ch and ch.Parent and ch ~= oldChar then
                pcall(_G._AmbitiousWaitCharReady, ch, 10)
                local hum = ch:FindFirstChildOfClass("Humanoid")
                local hrp = ch:FindFirstChild("HumanoidRootPart")
                if hum and hrp and hum.Health > 0 then newChar = ch break end
            end
            task.wait(0.05)
        end
        pcall(_G._AmbitiousUnlockResetCamera)
        _G.MoonHubInstaResetInProgress = false

        -- everything the user had ON comes back on the (new or same) character
        pcall(_G.MoonHubResumeAntiRagdoll)
        if wasAntiDie or (AntiDieModule and AntiDieModule.enabled) then
            pcall(_antiDieRefresh)
            if newChar then pcall(activateOnCharacter, newChar) end
        end
        pcall(function()
            if type(resetMovementState) == "function" then resetMovementState() end
            if type(applyHideButtons) == "function" then applyHideButtons(hideButtonsEnabled == true) end
            if mobSetInstantReset then mobSetInstantReset(false) end
        end)
        if _G._AmbitiousResetGaveUp then
            warn("[Moon Hub] Instant Reset V1: the game blocked this reset; try again")
        end
        _G._AmbitiousInstantResetBusy = false
    end)
end
end
-- <<< INSTANT RESET END


--=========================================================
--  Anti Bat (lógica portada de Clean Anti Bat)
--=========================================================
local AntiBat = { Connection = nil, PulseActive = false }
local ANTIBAT_RANGE = 4000

function stopAntiBat()
    antiBatEnabled = false
    -- Invalidate any pulse still waiting on RenderStepped: it must not write anything later.
    AntiBat.gen = (AntiBat.gen or 0) + 1
    if AntiBat.PulseActive == true then
        pcall(function()
            local c = LP.Character
            local h = c and c:FindFirstChild("HumanoidRootPart")
            if h then
                local o = AntiBat.origXZ or Vector3.zero
                local cur = h.Velocity
                h.Velocity = Vector3.new(o.X, cur.Y, o.Z)
            end
        end)
    end
    if AntiBat.Connection then
        pcall(function() AntiBat.Connection:Disconnect() end)
        AntiBat.Connection = nil
    end
    -- Full wipe — even mid-pulse (needed so Medusa/bat never leaves spikes alive)
    AntiBat.PulseActive = false
    _G.MoonHubAntiBatPulsing = false
    _G._AmbitiousAntiBatSpiking = false
    _G._AmbitiousAntiBatDesiredXZ = nil
    if _G.VX7MotionCompat then
        _G.VX7MotionCompat.antiBatPulseActive = false
        _G.VX7MotionCompat.antiBatPulseEndedAt = os.clock()
    end
end

function startAntiBat()
    stopAntiBat()
    antiBatEnabled = true

    AntiBat.Connection = RunService.Heartbeat:Connect(function()
        if not antiBatEnabled then return end
        -- FASTEST path: kill Anti Bat BEFORE any velocity write if Medusa/ragdoll
        do
            local medT = tonumber(_G._AmbitiousMedusaHitTime) or 0
            if medT > 0 and (tick() - medT) < 1.0 then
                if type(_G.RivalAntiBatPanicOff) == "function" then
                    _G.RivalAntiBatPanicOff("medusa-in-pulse")
                else
                    antiBatEnabled = false
                end
                return
            end
            local char0 = LP.Character
            local hum0 = char0 and char0:FindFirstChildOfClass("Humanoid")
            if hum0 then
                local st0
                pcall(function() st0 = hum0:GetState() end)
                if hum0.PlatformStand == true
                    or st0 == Enum.HumanoidStateType.Physics
                    or st0 == Enum.HumanoidStateType.Ragdoll
                    or st0 == Enum.HumanoidStateType.FallingDown then
                    if type(_G.RivalAntiBatPanicOff) == "function" then
                        _G.RivalAntiBatPanicOff("state-in-pulse")
                    else
                        antiBatEnabled = false
                    end
                    return
                end
            end
            local et0 = LP:GetAttribute("RagdollEndTime")
            if et0 ~= nil then
                local ok0, sn0 = pcall(function() return workspace:GetServerTimeNow() end)
                if ok0 and tonumber(et0) and tonumber(et0) > (sn0 or 0) then
                    if type(_G.RivalAntiBatPanicOff) == "function" then
                        _G.RivalAntiBatPanicOff("attr-in-pulse")
                    else
                        antiBatEnabled = false
                    end
                    return
                end
            end
        end
        if AntiBat.PulseActive or _G.MoonHubAntiBatPulsing then return end
        if dropActive or _G.IsDropping then return end
        local character = LP.Character
        if not character then return end
        local hrp = character:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local v = hrp.Velocity
        local originalXZ = _V3new(v.X, 0, v.Z)
        AntiBat.origXZ = originalXZ

        -- Mark the one-frame pulse as the temporary motion owner. The speed
        -- engine publishes its target but does not overwrite this pulse.
        local pulseGen = AntiBat.gen
        AntiBat.PulseActive = true
        _G.MoonHubAntiBatPulsing = true
        _G._AmbitiousAntiBatSpiking = true
        if _G.VX7MotionCompat then _G.VX7MotionCompat.antiBatPulseActive = true end
        hrp.Velocity = Vector3.new(
            math.random(-ANTIBAT_RANGE, ANTIBAT_RANGE),
            v.Y,
            math.random(-ANTIBAT_RANGE, ANTIBAT_RANGE)
        )
        RunService.RenderStepped:Wait()
        -- Anti Bat was switched off / wiped while this pulse was in flight: everything was
        -- already restored and cleared at that instant, so do NOTHING here.
        if AntiBat.gen ~= pulseGen then return end
        if hrp and hrp.Parent then
            local cur = hrp.Velocity
            local desiredXZ = _G._AmbitiousAntiBatDesiredXZ
            if typeof(desiredXZ) == "Vector3" then
                hrp.Velocity = Vector3.new(desiredXZ.X, cur.Y, desiredXZ.Z)
            else
                hrp.Velocity = Vector3.new(originalXZ.X, cur.Y, originalXZ.Z)
            end
        end
        AntiBat.PulseActive = false
        _G.MoonHubAntiBatPulsing = false
        _G._AmbitiousAntiBatSpiking = false
        if _G.VX7MotionCompat then
            _G.VX7MotionCompat.antiBatPulseActive = false
            _G.VX7MotionCompat.antiBatPulseEndedAt = os.clock()
        end
        if not antiBatEnabled then _G._AmbitiousAntiBatDesiredXZ = nil end
    end)
end

LP.CharacterAdded:Connect(function()
    task.wait(0.3)
    if antiBatEnabled then startAntiBat() end
end)

setAntiFlingVisual = nil

local _antiFlingState = {
    connection    = nil,
    threshold     = 80,
    spinThreshold = 40,
}
local _ANTI_FLING_DRIVE_GRACE = 0.3

local function _afHubSpeedLive()
    local live = _G.__RivalHubLiveSpeed
    if type(live) ~= "table" then return false end
    local stamp, speed = tonumber(live.t), tonumber(live.v)
    if not stamp or not speed or speed <= 0 then return false end
    return (os.clock() - stamp) <= _ANTI_FLING_DRIVE_GRACE
end

local function _afOwnMoverActive()
    if autoBatEnabled then return true end
    if autoLeftEnabled or autoRightEnabled then return true end
    return false
end

