    if mobSetLagger2 then mobSetLagger2(laggerToggled) end
    if setLaggerModeVisual then setLaggerModeVisual(laggerToggled) end
    if setLaggerCarryVisual then setLaggerCarryVisual(laggerCarryToggled) end
end

-- Moon Hub speed modes: exactly one of Normal / Carry / Lagger / Lagger Carry is active.
function getCurrentSpeedModeName()
    if laggerCarryToggled then return "Lagger Carry"
    elseif laggerToggled then return "Lagger"
    elseif speedMode then return "Carry" end
    return "Normal"
end

function setSpeedMode(mode)
    if mode ~= "Carry" and mode ~= "Lagger" and mode ~= "Lagger Carry" then mode = "Normal" end
    -- Auto Carry lock: while the game's carry slowdown is detected, stay in a Carry mode
    if _AutoCarry and _AutoCarry.enabled and _AutoCarry.locked and not _AutoCarry.restoring then
        if mode ~= "Carry" and mode ~= "Lagger Carry" then return end
    end
    speedMode = (mode == "Carry")
    laggerToggled = (mode == "Lagger")
    laggerCarryToggled = (mode == "Lagger Carry")
    resetMovementState()
    if _G.__RivalHubApplySpeedNow then pcall(_G.__RivalHubApplySpeedNow) end
end

-- ============================================================
-- AUTO CARRY SPEED (ported from MoonHub)
-- Detects the game's carry slowdown (WalkSpeed < 25) -> switches to Carry / Lagger Carry,
-- locks the mode while carrying, then restores the previous mode when carry ends.
-- ============================================================
_AutoCarry = _AutoCarry or {enabled = false, wasLow = false, locked = false, savedMode = nil, restoring = false}
_AutoCarry.enabled = false
_AutoCarry.wasLow, _AutoCarry.locked, _AutoCarry.savedMode, _AutoCarry.restoring = false, false, nil, false

function _autoCarryRestore()
    _AutoCarry.locked = false
    _AutoCarry.wasLow = false
    if _AutoCarry.savedMode then
        local m = _AutoCarry.savedMode
        _AutoCarry.savedMode = nil
        _AutoCarry.restoring = true
        pcall(setSpeedMode, m)
        _AutoCarry.restoring = false
    end
end

-- Carry detection ported 1:1 from Rival (_spd_scanPodiums / _spd_nearAnimalTarget / _spd_detectAnimalHold)
autoCarryMode = "NORMAL" -- Fixed mode: Soft option removed
autoCarryModeBtn = nil
_acLastScan = _acLastScan or 0
_acPodiums = _acPodiums or {}

function _autoCarryScanPodiums()
    local list = {}
    local plots = workspace:FindFirstChild("Plots")
    if not plots then return list end
    for _, plot in ipairs(plots:GetChildren()) do
        local sign = plot:FindFirstChild("PlotSign")
        local isMine = false
        if sign then
            local yb = sign:FindFirstChild("YourBase")
            if yb and yb:IsA("BillboardGui") and yb.Enabled then isMine = true end
        end
        if not isMine then
            local podiums = plot:FindFirstChild("AnimalPodiums")
            if podiums then
                for _, podium in ipairs(podiums:GetChildren()) do
                    if podium:IsA("Model") then
                        local base = podium:FindFirstChild("Base")
                        local spawn = base and base:FindFirstChild("Spawn")
                        if spawn and spawn:IsA("BasePart") then
                            table.insert(list, spawn.Position)
                        end
                    end
                end
            end
        end
    end
    return list
end

function _autoCarryNearAnimalTarget()
    local now = tick()
    if now - _acLastScan > 2 then
        _acLastScan = now
        _acPodiums = _autoCarryScanPodiums()
    end
    local char = LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root then return false end
    local rp = root.Position
    for _, pos in ipairs(_acPodiums) do
        if (rp - pos).Magnitude <= 10 then return true end
    end
    return false
end

function _autoCarryDetectHold()
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum and hum.WalkSpeed > 0 and hum.WalkSpeed < 25 then
        return true
    end
    if LP:GetAttribute("Stealing") == true or (char and char:GetAttribute("Stealing") == true) then
        return true
    end
    return false
end

function setAutoCarry(on)
    on = on == true
    _AutoCarry.enabled = on
    if not on then _autoCarryRestore() end
    if _G.RivalAutoCarrySetVisual then pcall(_G.RivalAutoCarrySetVisual, on) end
end
_G.RivalSetAutoCarry = setAutoCarry

function _autoCarryStep()
    if not _AutoCarry.enabled then return end
    local char = LP and LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    local isLow = _autoCarryDetectHold()
    if isLow == _AutoCarry.wasLow then return end
    _AutoCarry.wasLow = isLow
    if isLow then
        _AutoCarry.locked = true
        local cur = getCurrentSpeedModeName()
        if cur ~= "Carry" and cur ~= "Lagger Carry" then
            _AutoCarry.savedMode = cur
            _AutoCarry.restoring = true
            pcall(setSpeedMode, cur == "Lagger" and "Lagger Carry" or "Carry")
            _AutoCarry.restoring = false
        end
    else
        _autoCarryRestore()
    end
end

_G._RivalAutoCarryGen = (_G._RivalAutoCarryGen or 0) + 1
do
    local gen = _G._RivalAutoCarryGen
    task.spawn(function()
        while _G._RivalAutoCarryGen == gen do
            task.wait(0.05)
            pcall(_autoCarryStep)
        end
    end)
end

-- Carry key: Lagger* -> Carry, Carry -> Normal, Normal -> Carry (same as Moon Hub)
function toggleCarryMode()
    local mode = getCurrentSpeedModeName()
    if mode == "Lagger" or mode == "Lagger Carry" then setSpeedMode("Carry")
    elseif mode == "Carry" then setSpeedMode("Normal")
    else setSpeedMode("Carry") end
end

-- Lagger key: Normal/Carry -> Lagger Carry, Lagger Carry -> Lagger, Lagger -> Lagger Carry (same as Moon Hub)
function toggleLaggerMode()
    local mode = getCurrentSpeedModeName()
    if mode == "Lagger Carry" then setSpeedMode("Lagger")
    else setSpeedMode("Lagger Carry") end
end

function toggleLaggerCarryMode()
    setSpeedMode(getCurrentSpeedModeName() == "Lagger Carry" and "Normal" or "Lagger Carry")
end

function toggleLaggerCycle()
    toggleLaggerMode()
end

function _flatUnit(d)
    local v = _V3new(d.X, 0, d.Z)
    if v.Magnitude < 1e-4 then return _V3zero end
    return v.Unit
end

_alSuppressed, _arSuppressed = false, false
function _alAcquire() if not _alSuppressed then _alSuppressed = true; _suppressBodyLock() end end
function _alRelease() if _alSuppressed then _alSuppressed = false; _unsuppressBodyLock(true) end end
function _arAcquire() if not _arSuppressed then _arSuppressed = true; _suppressBodyLock() end end
function _arRelease() if _arSuppressed then _arSuppressed = false; _unsuppressBodyLock(true) end end

_autoToggleStamp = 0
function _autoToggleDebounced()
    local now = tick()
    if now - _autoToggleStamp < 0.12 then return true end
    _autoToggleStamp = now
    return false
end

function stopAutoLeft()
    if moonPendingCarryResume == "AutoLeft" then moonPendingCarryResume = nil end
    if alConn then alConn:Disconnect(); alConn = nil end
    alPhase = 1
    local char = LP.Character
    if char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then hum:Move(_V3zero, false) end
    end
    if autoLeftSetVisual then autoLeftSetVisual(false) end
    if mobSetAutoLeft then mobSetAutoLeft(false) end
    _alRelease()
end

function startAutoLeft()
    if _G.MoonIsHoldingBrainrot() then
        autoLeftEnabled = false
        moonTogglePending("AutoLeft")
        return
    end
    if moonPendingCarryResume == "AutoLeft" then moonPendingCarryResume = nil end
    if autoRightEnabled then
        autoRightEnabled = false
        stopAutoRight()
        if autoRightSetVisual then autoRightSetVisual(false) end
        if mobSetAutoRight then mobSetAutoRight(false) end
    end
    _G._AmbitiousAntiBatDesiredXZ = nil
    _G.MoonHubSpeedIntended = nil
    _alAcquire()
    if alConn then alConn:Disconnect() end
    alPhase = 1
    alConn = RunService.Heartbeat:Connect(function()
        if not autoLeftEnabled then return end
        local char = LP.Character
        if not char then return end
        local root = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not root or not hum then return end
        local spd = getAutoPathSpeed()
        if alPhase == 1 then
            local tgt = _V3new(AP.L1.X, root.Position.Y, AP.L1.Z)
            if (tgt - root.Position).Magnitude < 1 then
                alPhase = 2
                local d = AP.L2 - root.Position
                local mv = _flatUnit(d)
                hum:Move(mv, false)
                if not (_G.MoonHubAntiBatPulsing or _G._AmbitiousAntiBatSpiking) then
                    root.AssemblyLinearVelocity = _V3new(mv.X * spd, root.AssemblyLinearVelocity.Y, mv.Z * spd)
                end
                return
            end
            local d = AP.L1 - root.Position
            local mv = _flatUnit(d)
            hum:Move(mv, false)
            if not (_G.MoonHubAntiBatPulsing or _G._AmbitiousAntiBatSpiking) then
                    root.AssemblyLinearVelocity = _V3new(mv.X * spd, root.AssemblyLinearVelocity.Y, mv.Z * spd)
                end
        elseif alPhase == 2 then
            local tgt = _V3new(AP.L2.X, root.Position.Y, AP.L2.Z)
            if (tgt - root.Position).Magnitude < 1 then
                hum:Move(_V3zero, false)
                if not (_G.MoonHubAntiBatPulsing or _G._AmbitiousAntiBatSpiking) then
                    root.AssemblyLinearVelocity = _V3zero
                end
                autoLeftEnabled = false
                if alConn then alConn:Disconnect(); alConn = nil end
                alPhase = 1
                if autoLeftSetVisual then autoLeftSetVisual(false) end
                if mobSetAutoLeft then mobSetAutoLeft(false) end
                _alRelease()
                local facePos = _V3new(AP.L_FACE.X, root.Position.Y, AP.L_FACE.Z)
                if (facePos - root.Position).Magnitude > 0.01 then
                    root.CFrame = _CFnew(root.Position, facePos)
                end
                return
            end
            local d = AP.L2 - root.Position
            local mv = _flatUnit(d)
            hum:Move(mv, false)
            if not (_G.MoonHubAntiBatPulsing or _G._AmbitiousAntiBatSpiking) then
                    root.AssemblyLinearVelocity = _V3new(mv.X * spd, root.AssemblyLinearVelocity.Y, mv.Z * spd)
                end
        end
    end)
end

