function getClosestTarget()
    local char = LP.Character
    if not char then return nil end
    local root = char:FindFirstChild("HumanoidRootPart")
    if not root then return nil end
    local rpos = root.Position
    local closest, minDist = nil, _huge
    local plist = _GetPlayersCached()
    for i = 1, #plist do
        local plr = plist[i]
        if plr ~= LP then
            local c = plr.Character
            if c then
                local tRoot = c:FindFirstChild("HumanoidRootPart")
                if tRoot then
                    local hum = c:FindFirstChildOfClass("Humanoid")
                    if hum and hum.Health > 0 then
                        local dx = tRoot.Position.X - rpos.X
                        local dy = tRoot.Position.Y - rpos.Y
                        local dz = tRoot.Position.Z - rpos.Z
                        local d = dx*dx + dy*dy + dz*dz
                        if d < minDist then minDist = d; closest = tRoot end
                    end
                end
            end
        end
    end
    return closest
end

function trySwing()
    pcall(function()
        local char = LP.Character
        if not char then return end
        local currentTool = char:FindFirstChildOfClass("Tool")
        if currentTool and not isBatTool(currentTool) then return end
        local bat = findBat()
        if bat then
            if bat.Parent ~= char then
                local hum = char:FindFirstChildOfClass("Humanoid")
                if hum then pcall(function() hum:EquipTool(bat) end) end
            end
            pcall(function() bat:Activate() end)
        end
    end)
end

do
local ACTIVATE_DISTANCE = 13
local MIN_FOLLOW_DISTANCE = 1
local PREDICTION_TIME = 0.22
local PREDICT_AHEAD = 3
local JUMP_SPEED_BOOST = 1.5
local JUMP_THRESHOLD = 8
local ACTIVATION_DELAY = 0.2
local AIRBORNE_THRESHOLD = 0.15
local FLOAT_Y_THRESHOLD = 3
local FALLING_THRESHOLD = -8
local RISING_THRESHOLD = 8
local VERTICAL_OFFSET_MULTIPLIER = 0.15
local JUMPBOOST_Y_THRESHOLD = 35
local EXTREME_JUMPBOOST_THRESHOLD = 50
local JUMPBOOST_SUSTAINED_TIME = 0.15
local MAX_VELOCITY_CHANGE = 150
local VELOCITY_SMOOTHING = 0.2
local MAX_HORIZONTAL_VELOCITY = 80
local ERRATIC_MOVEMENT_THRESHOLD = 3
local SERVER_TICKRATE = 1/60
local PING_SAMPLE_SIZE = 10
local MIN_PING_COMPENSATION = 0.03
local MAX_PING_COMPENSATION = 0.25
local ACCELERATION_PREDICTION_WEIGHT = 0.3
local DIRECTION_CHANGE_DETECTION_TIME = 0.12
local QUICK_DIRECTION_CHANGE_MULTIPLIER = 1.5
local GRAVITY = 196.2
local AIR_CONTROL_FACTOR = 0.8
local AERIAL_VELOCITY_DECAY = 0.95
local AERIAL_DIRECTION_CHANGE_WEIGHT = 0.6
local MIN_AIRBORNE_TIME = 0.08
local AERIAL_SMOOTHING = 0.15
local STRAFE_DETECTION_THRESHOLD = 0.7
local HIGH_JUMP_THRESHOLD = 20
local FALLING_SPEED_THRESHOLD = -15
local GRAVITY_PREDICTION_WEIGHT = 1.0
local MULTI_JUMP_DETECTION_WINDOW = 0.2
local UPWARD_VELOCITY_RESET_THRESHOLD = 10
local VERTICAL_POSITION_LEAD = 2.5
local FALLING_VERTICAL_LEAD = 3.5

local predictionSphere = nil
local targetPlayer = nil
local lastTargetPos = nil
local targetVelocity = Vector3.new(0, 0, 0)
local smoothedVelocity = Vector3.new(0, 0, 0)
local velocityHistory = {}
local MAX_HISTORY = 8
local airborneTime = 0
local lastActivationTime = 0
local highYVelocityTime = 0
local pingHistory = {}
local currentPing = 0.1
local accelerationHistory = {}
local MAX_ACCEL_HISTORY = 4
local lastDirectionChangeTime = 0
local previousDirection = nil
local wasAirborne = false
local aerialVelocityHistory = {}
local MAX_AERIAL_HISTORY = 6
local aerialSmoothVelocity = Vector3.new(0, 0, 0)
local lastYVelocity = 0
local peakHeight = 0
local groundHeight = 0
local lastJumpTime = 0
local isMultiJumping = false
local verticalVelocityHistory = {}
local MAX_VERTICAL_HISTORY = 5

local function getNearestPlayer()
    local char = LP.Character
    if not char then return nil end
    local root = char:FindFirstChild("HumanoidRootPart")
    if not root then return nil end
    local myPos = root.Position
    local nearestDist = math.huge
    local nearestPlayer = nil
    local MAX_TARGET_DISTANCE = 250
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LP and p.Character then
            local otherRoot = p.Character:FindFirstChild("HumanoidRootPart")
            local otherHum = p.Character:FindFirstChildOfClass("Humanoid")
            if otherRoot and otherHum and otherHum.Health > 0 then
                local targetPos = otherRoot.Position
                if type(_G.MoonAntiVoidPosition) == "function" then targetPos = _G.MoonAntiVoidPosition(p, targetPos) end
                local dist = (myPos - targetPos).Magnitude
                if dist <= MAX_TARGET_DISTANCE and dist < nearestDist then
                    nearestDist = dist
                    nearestPlayer = p
                end
            end
        end
    end
    return nearestPlayer
end

local function getAverageVelocity()
    if #velocityHistory == 0 then return Vector3.new(0, 0, 0) end
    local sum = Vector3.new(0, 0, 0)
    for _, vel in ipairs(velocityHistory) do sum = sum + vel end
    return sum / #velocityHistory
end

local function getAverageAcceleration()
    if #accelerationHistory == 0 then return Vector3.new(0, 0, 0) end
    local sum = Vector3.new(0, 0, 0)
    for _, a in ipairs(accelerationHistory) do sum = sum + a end
    return sum / #accelerationHistory
end

local function getAverageAerialVelocity()
    if #aerialVelocityHistory == 0 then return Vector3.new(0, 0, 0) end
    local sum = Vector3.new(0, 0, 0)
    for _, vel in ipairs(aerialVelocityHistory) do
        sum = sum + Vector3.new(vel.X, 0, vel.Z)
    end
    return sum / #aerialVelocityHistory
end

local function getAverageVerticalVelocity()
    if #verticalVelocityHistory == 0 then return 0 end
    local sum = 0
    for _, y in ipairs(verticalVelocityHistory) do sum = sum + y end
    return sum / #verticalVelocityHistory
end

local function detectMultiJump(currentYVel, wasRising)
    local t = tick()
    if lastYVelocity < -5 and currentYVel > UPWARD_VELOCITY_RESET_THRESHOLD then
        if t - lastJumpTime < MULTI_JUMP_DETECTION_WINDOW then return true end
        lastJumpTime = t
        return true
    end
    return false
end

local function isFallingFromHeight(currentPos, yVel)
    return (currentPos.Y - groundHeight > HIGH_JUMP_THRESHOLD) and yVel < FALLING_SPEED_THRESHOLD
end

local function isAerialStrafing()
    if #aerialVelocityHistory < 3 then return false end
    local dc = 0
    for i = 2, #aerialVelocityHistory do
        local v1 = Vector3.new(aerialVelocityHistory[i-1].X, 0, aerialVelocityHistory[i-1].Z)
        local v2 = Vector3.new(aerialVelocityHistory[i].X, 0, aerialVelocityHistory[i].Z)
        if v1.Magnitude > 3 and v2.Magnitude > 3 then
            if v1.Unit:Dot(v2.Unit) < STRAFE_DETECTION_THRESHOLD then
                dc = dc + 1
            end
        end
    end
    return dc >= 2
end

local function detectDirectionChange(currentVel)
    local horizontal = Vector3.new(currentVel.X, 0, currentVel.Z)
    if horizontal.Magnitude < 5 then return false end
    if previousDirection then
        local dot = previousDirection:Dot(horizontal.Unit)
        if dot < 0.5 then
            local t = tick()
            if t - lastDirectionChangeTime < DIRECTION_CHANGE_DETECTION_TIME then
                previousDirection = horizontal.Unit
                lastDirectionChangeTime = t
                return true
            end
            lastDirectionChangeTime = t
        end
    end
    previousDirection = horizontal.Unit
    return false
end

local function isErraticMovement()
    if #velocityHistory < 3 then return false end
    local changes = 0
    for i = 2, #velocityHistory do
        local v1 = Vector3.new(velocityHistory[i-1].X, 0, velocityHistory[i-1].Z)
        local v2 = Vector3.new(velocityHistory[i].X, 0, velocityHistory[i].Z)
        if v1.Magnitude > 5 and v2.Magnitude > 5 then
            if v1.Unit:Dot(v2.Unit) < 0.3 then changes = changes + 1 end
        end
    end
    return changes >= ERRATIC_MOVEMENT_THRESHOLD
end

local function isInfiniteJumping()
    if #velocityHistory < 3 then return false end
    local yc = 0
    for i = 2, #velocityHistory do
        if math.abs(velocityHistory[i].Y - velocityHistory[i-1].Y) > 15 then
            yc = yc + 1
        end
    end
    return yc >= 2
end

local function isJumpBoostCheat()
    return math.abs(targetVelocity.Y) > JUMPBOOST_Y_THRESHOLD and highYVelocityTime > JUMPBOOST_SUSTAINED_TIME
end

local function isExtremeJumpBoost()
    return math.abs(targetVelocity.Y) > EXTREME_JUMPBOOST_THRESHOLD
end

local function isFloating()
    return airborneTime > AIRBORNE_THRESHOLD and math.abs(targetVelocity.Y) > FLOAT_Y_THRESHOLD
end

local function checkAirborne(targetRoot)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = {targetPlayer.Character, LP.Character}
    local rayResult = workspace:Raycast(targetRoot.Position, Vector3.new(0, -100, 0), params)
    if rayResult then
        groundHeight = rayResult.Position.Y
        return false
    end
    return true
end

local function clampVelocityChange(newVel, oldVel, maxChange)
    local delta = newVel - oldVel
    if delta.Magnitude > maxChange then
        return oldVel + (delta.Unit * maxChange)
    end
    return newVel
end

local function smoothVelocity(current, target, alpha)
    return current:Lerp(target, alpha)
end

local function predictAerialPosition(currentPos, velocity, dt, isStrafing, isFastFalling, isMultiJump)
    local horizVel = Vector3.new(velocity.X, 0, velocity.Z)
    local vertVel = velocity.Y

    if isStrafing then
        local avgAerial = getAverageAerialVelocity()
        horizVel = Vector3.new(avgAerial.X, 0, avgAerial.Z) * AIR_CONTROL_FACTOR
    else
        horizVel = horizVel * AIR_CONTROL_FACTOR
    end

    horizVel = horizVel * AERIAL_VELOCITY_DECAY

    local gravityEffect = GRAVITY * GRAVITY_PREDICTION_WEIGHT
    if isMultiJump then
        gravityEffect = gravityEffect * 0.3
        vertVel = vertVel * 0.9
    end

    local verticalDisplacement
    if isFastFalling then
        verticalDisplacement = (vertVel * dt) - (0.5 * gravityEffect * 1.2 * dt * dt) - (FALLING_VERTICAL_LEAD * dt)
    else
        verticalDisplacement = (vertVel * dt) - (0.5 * gravityEffect * dt * dt)
    end

    if vertVel > RISING_THRESHOLD and not isMultiJump then
        verticalDisplacement = verticalDisplacement + (VERTICAL_POSITION_LEAD * dt)
    end

    return currentPos + horizVel * dt + Vector3.new(0, verticalDisplacement, 0)
end

local function predictServerPosition(currentPos, velocity, acceleration, ping, isQuickTurn, isAerial, isStrafing, isFastFalling, isMultiJump)
    local serverDelay = ping + SERVER_TICKRATE
    if isQuickTurn then serverDelay = serverDelay * QUICK_DIRECTION_CHANGE_MULTIPLIER end
    if isAerial then
        return predictAerialPosition(currentPos, velocity, serverDelay, isStrafing, isFastFalling, isMultiJump)
    end

    local predictedPos = currentPos + velocity * serverDelay
    if acceleration.Magnitude > 1 then
        predictedPos = predictedPos + (acceleration * ACCELERATION_PREDICTION_WEIGHT) * (serverDelay * serverDelay * 0.5)
    end
    return predictedPos
end

local SPHERE_SMOOTH_SPEED = 15

local function createPredictionSphere()
    if predictionSphere then predictionSphere:Destroy() end
    predictionSphere = Instance.new("Part")
    predictionSphere.Name = "PredictionSphere"
    predictionSphere.Shape = Enum.PartType.Ball
    predictionSphere.Size = Vector3.new(2, 2, 2)
    predictionSphere.Anchored = true
    predictionSphere.CanCollide = false
    predictionSphere.Material = Enum.Material.Neon
    predictionSphere.Color = Color3.fromRGB(100, 180, 255)
    predictionSphere.Transparency = 0.4
    local light = Instance.new("PointLight")
    light.Color = Color3.fromRGB(100, 180, 255)
    light.Range = 8
    light.Brightness = 2
    light.Parent = predictionSphere
    predictionSphere.Parent = workspace
    return predictionSphere
end

local function updatePredictionSphere(targetPosition, dt)
    if not predictionSphere then return end
    local alpha = math.min(1, dt * SPHERE_SMOOTH_SPEED)
    predictionSphere.CFrame = predictionSphere.CFrame:Lerp(CFrame.new(targetPosition), alpha)
end

local function updateRotationAngular(lookDirection, rootPart)
    if not rootPart then return end
    if lookDirection.Magnitude < 0.01 then return end
    local currentLook = rootPart.CFrame.LookVector
    local targetDir = lookDirection.Unit
    local axis = currentLook:Cross(targetDir)
    local angle = math.asin(math.clamp(axis.Magnitude, -1, 1))
    if axis.Magnitude > 0.01 then
        local rotSpeed = 80
        rootPart.AssemblyAngularVelocity = axis.Unit * angle * rotSpeed
    else
        rootPart.AssemblyAngularVelocity = Vector3.zero
    end
end

local circleConnection = nil
local circleSafetyConn = nil

-- Ported from Vision's Bat Aimbot: ping-compensated prediction + hybrid legacy/predicted steering.
local _mba = { C = {
    ACTIVATE_DISTANCE = 13, MIN_FOLLOW_DISTANCE = 1, PREDICTION_TIME = 0.22, PREDICT_AHEAD = 3,
    MAX_VELOCITY_CHANGE = 150, VELOCITY_SMOOTHING = 0.2, MAX_HORIZONTAL_VELOCITY = 80,
    SERVER_TICKRATE = 1 / 60, MIN_PING_COMPENSATION = 0.03, MAX_PING_COMPENSATION = 0.25,
    ACCELERATION_PREDICTION_WEIGHT = 0.3, DIRECTION_CHANGE_DETECTION_TIME = 0.12,
    QUICK_DIRECTION_CHANGE_MULTIPLIER = 1.5, GRAVITY = 196.2, AIR_CONTROL_FACTOR = 0.8,
    MIN_AIRBORNE_TIME = 0.08,
} }   -- single local (Lua local-variable limit); helpers live on this table
function _mba.avg(list)
    if #list == 0 then return Vector3.zero end
    local sum = Vector3.zero
    for _, v in ipairs(list) do sum = sum + v end
    return sum / #list
end
function _mba.push(list, value, maxCount)
    table.insert(list, value)
    if #list > maxCount then table.remove(list, 1) end
end
function _mba.reset()
    _mba.targetPlayer = nil
    _mba.lastTargetPos = nil
    _mba.targetVelocity = Vector3.zero
    _mba.smoothedVelocity = Vector3.zero
    _mba.velocityHistory = {}
    _mba.accelerationHistory = {}
    _mba.aerialVelocityHistory = {}
    _mba.previousDirection = nil
    _mba.lastDirectionChangeTime = 0
    _mba.airborneTime = 0
end
_mba.reset()
_mba.currentPing, _mba.realPingMs, _mba.lastPingCheck = 0.1, 0, 0

local function getRivalHubAimbotBat(char)
    local equipped = char and char:FindFirstChildOfClass("Tool")
    if equipped then
        local name = equipped.Name:lower()
        if name:find("bat", 1, true) or name:find("slap", 1, true) then return equipped end
    end
    local backpack = LP:FindFirstChildOfClass("Backpack")
    if backpack then
        for _, tool in ipairs(backpack:GetChildren()) do
            if tool:IsA("Tool") then
                local name = tool.Name:lower()
                if name:find("bat", 1, true) or name:find("slap", 1, true) then return tool end
            end
        end
    end
    return nil
end

local function getRivalHubRenderCFrame(root)
    if not root then return nil end
    local ok, rendered = pcall(root.GetRenderCFrame, root)
    return ok and rendered or root.CFrame
end

startCircleCombat = function()
    if circleConnection then return end
    local bubbleAimbot = _G.__RivalHubBubbleAimbotState or { nextSwingAt = 0, target = nil, intendedVelocity = Vector3.zero }
    _G.__RivalHubBubbleAimbotState = bubbleAimbot

    local function clearAngV()
        local c = LP.Character
        local r = c and c:FindFirstChild("HumanoidRootPart")
        if r then
            local a = r:FindFirstChild("_RivalHub_AngV"); if a then a:Destroy() end
            local at = r:FindFirstChild("_RivalHub_Att"); if at then at:Destroy() end
        end
    end

    local function ensureAngV(r)
        if not r then return nil end
        local a = r:FindFirstChild("_RivalHub_AngV"); if a then a:Destroy() end
        local at = r:FindFirstChild("_RivalHub_Att"); if at then at:Destroy() end
        local att = Instance.new("Attachment")
        att.Name = "_RivalHub_Att"
        att.Parent = r
        local angV = Instance.new("AngularVelocity")
        angV.Name = "_RivalHub_AngV"
        angV.Attachment0 = att
        angV.RelativeTo = Enum.ActuatorRelativeTo.World
        angV.MaxTorque = math.huge
        angV.AngularVelocity = Vector3.zero
        angV.Parent = r
        return angV
    end

    circleConnection = RunService.RenderStepped:Connect(function(deltaTime)
        if not State.bypassBatEnabled then
            if circleConnection then circleConnection:Disconnect(); circleConnection = nil end
            if circleSafetyConn then circleSafetyConn:Disconnect(); circleSafetyConn = nil end
            clearAngV()
            return
        end

        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local humanoid = char and char:FindFirstChildOfClass("Humanoid")
        if not root or not humanoid or humanoid.Health <= 0 then
            clearAngV()
            return
        end
        if _G.MoonHubHardHit and _G.MoonHubHardHit() then
            clearAngV()
            return
        end
        humanoid.AutoRotate = false

        local angV = nil
        clearAngV()   -- direct AssemblyAngularVelocity (Vision method); no AngularVelocity constraint

        local bat = getRivalHubAimbotBat(char)
        if bat and bat.Parent ~= char then
            pcall(humanoid.EquipTool, humanoid, bat)
        end
        if not bat then return end

        targetPlayer = getNearestPlayer()
        local targetRoot = targetPlayer and targetPlayer.Character and targetPlayer.Character:FindFirstChild("HumanoidRootPart")
        local targetHum = targetPlayer and targetPlayer.Character and targetPlayer.Character:FindFirstChildOfClass("Humanoid")
        if not targetRoot or not targetHum or targetHum.Health <= 0 then
            bubbleAimbot.target = nil
            _mba.reset()
            root.AssemblyAngularVelocity = Vector3.zero
            local nv = root.AssemblyLinearVelocity
            root.AssemblyLinearVelocity = Vector3.new(0, nv.Y * 0.5, 0)   -- Vision: stop drifting with no target
            pcall(function() humanoid:Move(Vector3.zero, false) end)
            humanoid.AutoRotate = true
            return
        end

        bubbleAimbot.target = targetRoot
        local C = _mba.C
        local targetPosition, isGhost = targetRoot.Position, false
        if type(_G.MoonAntiVoidPosition) == "function" then targetPosition, isGhost = _G.MoonAntiVoidPosition(targetPlayer, targetPosition) end

        -- ping compensation (every 0.5 s)
        if tick() - _mba.lastPingCheck >= 0.5 then
            _mba.lastPingCheck = tick()
            local okP, ping = pcall(function() return game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue() end)
            if okP and type(ping) == "number" then _mba.realPingMs = math.floor(ping) end
            _mba.currentPing = math.clamp(_mba.realPingMs / 1000, C.MIN_PING_COMPENSATION, C.MAX_PING_COMPENSATION)
        end

        if _mba.targetPlayer ~= targetPlayer then
            _mba.reset()
            _mba.targetPlayer = targetPlayer
            _mba.lastTargetPos = targetPosition
            _mba.targetVelocity = isGhost and Vector3.zero or targetRoot.AssemblyLinearVelocity
            _mba.smoothedVelocity = _mba.targetVelocity
        end

        local dt = math.max(deltaTime or 0, 1 / 240)
        if isGhost then
            _mba.targetVelocity, _mba.smoothedVelocity, _mba.lastTargetPos = Vector3.zero, Vector3.zero, targetPosition
        elseif _mba.lastTargetPos then
            local velocity = (targetPosition - _mba.lastTargetPos) / dt
            local change = velocity - _mba.targetVelocity
            if change.Magnitude > C.MAX_VELOCITY_CHANGE then
                velocity = _mba.targetVelocity + change.Unit * C.MAX_VELOCITY_CHANGE
            end
            local hz = Vector3.new(velocity.X, 0, velocity.Z)
            if hz.Magnitude > C.MAX_HORIZONTAL_VELOCITY then
                hz = hz.Unit * C.MAX_HORIZONTAL_VELOCITY
                velocity = Vector3.new(hz.X, velocity.Y, hz.Z)
            end
            _mba.push(_mba.accelerationHistory, (velocity - _mba.targetVelocity) / dt, 4)
            _mba.push(_mba.velocityHistory, velocity, 8)
            _mba.targetVelocity = velocity
            _mba.smoothedVelocity = _mba.smoothedVelocity:Lerp(velocity, C.VELOCITY_SMOOTHING)
            _mba.lastTargetPos = targetPosition
        end

        local airborne = targetHum.FloorMaterial == Enum.Material.Air
        _mba.airborneTime = airborne and (_mba.airborneTime + dt) or 0
        if airborne and _mba.airborneTime >= C.MIN_AIRBORNE_TIME then
            _mba.push(_mba.aerialVelocityHistory, _mba.targetVelocity, 6)
        elseif not airborne then
            _mba.aerialVelocityHistory = {}
        end
        local velocity = _mba.smoothedVelocity
        if airborne and #_mba.aerialVelocityHistory > 0 then
            local aerial = _mba.avg(_mba.aerialVelocityHistory)
            velocity = Vector3.new(aerial.X, _mba.targetVelocity.Y, aerial.Z) * C.AIR_CONTROL_FACTOR
        end

        local quickChange = false
        local hv = Vector3.new(_mba.targetVelocity.X, 0, _mba.targetVelocity.Z)
        if hv.Magnitude > 5 then
            local direction = hv.Unit
            if _mba.previousDirection and _mba.previousDirection:Dot(direction) < 0.5 then
                quickChange = tick() - _mba.lastDirectionChangeTime < C.DIRECTION_CHANGE_DETECTION_TIME
                _mba.lastDirectionChangeTime = tick()
            end
            _mba.previousDirection = direction
        end

        local lead = _mba.currentPing + C.SERVER_TICKRATE
        if quickChange then lead = lead * C.QUICK_DIRECTION_CHANGE_MULTIPLIER end
        local acceleration = _mba.avg(_mba.accelerationHistory)
        local predicted = targetPosition + velocity * lead
            + acceleration * C.ACCELERATION_PREDICTION_WEIGHT * (lead * lead * 0.5)
        local predictionTime = C.PREDICTION_TIME * 1.1
        if airborne then
            predicted = predicted + velocity * predictionTime
                + Vector3.new(0, -0.5 * C.GRAVITY * predictionTime * predictionTime, 0)
        else
            predicted = predicted + velocity * predictionTime
        end
        local flatVelocity = Vector3.new(velocity.X, 0, velocity.Z)
        local predictedTarget = flatVelocity.Magnitude > 1 and (predicted + flatVelocity.Unit * C.PREDICT_AHEAD) or predicted
        local bubbleGoal = predictedTarget - root.Position

        -- legacy (target-version) approach offset + rotation, blended with the predicted one
        local legacyTarget = targetPosition + _G.MoonSafeFacingOffset(targetRoot, 0.3)
        local legacyDirection = legacyTarget - root.Position
        local legacyFlat = Vector3.new(legacyDirection.X, 0, legacyDirection.Z)
        local legacyFlatUnit = legacyFlat.Magnitude > 0 and legacyFlat.Unit or Vector3.zero
        local legacyY = (targetPosition.Y + 3.7 - root.Position.Y) * 19.5 + velocity.Y * 0.8
        if humanoid.FloorMaterial ~= Enum.Material.Air then legacyY = math.max(legacyY, 13) end
        legacyY = math.clamp(legacyY, -70, 110)

        local spd = tonumber(State.bypassBatSpeed) or tonumber(BYPASS_AIMBOT_SPEED) or 58
        if spd ~= spd or spd <= 0 or spd == math.huge then spd = 58 end
        spd = math.clamp(spd, 1, 120)
        local legacyVelocity = Vector3.new(legacyFlatUnit.X * spd, legacyY, legacyFlatUnit.Z * spd)
        local bubbleVelocity = bubbleGoal.Magnitude > C.MIN_FOLLOW_DISTANCE and bubbleGoal.Unit * spd or Vector3.zero

        if bubbleGoal.Magnitude > 0.01 then
            local cross = root.CFrame.LookVector:Cross(bubbleGoal.Unit)
            local angle = math.asin(math.clamp(cross.Magnitude, -1, 1))
            root.AssemblyAngularVelocity = cross.Magnitude > 0.01 and cross.Unit * angle * 80 or Vector3.zero
        end
        if legacyDirection.Magnitude > 0.1 then
            local goalCF = CFrame.lookAt(root.Position, legacyTarget)
            local diffCF = root.CFrame:ToObjectSpace(goalCF)
            local rx, ry, rz = diffCF:ToOrientation()
            rx = math.clamp(rx, -2.5, 2.5); ry = math.clamp(ry, -2.5, 2.5); rz = math.clamp(rz, -2.5, 2.5)
            local legacyAngular = root.CFrame:VectorToWorldSpace(Vector3.new(rx * 42, ry * 42, rz * 42))
            root.AssemblyAngularVelocity = root.AssemblyAngularVelocity:Lerp(legacyAngular, 0.45)
        end

        local distance = (targetPosition - root.Position).Magnitude
        if distance <= C.ACTIVATE_DISTANCE then
            local now = tick()
            if now >= (bubbleAimbot.nextSwingAt or 0) then
                bubbleAimbot.nextSwingAt = now + 0.08
                pcall(bat.Activate, bat)
                local remote = bat:FindFirstChildWhichIsA("RemoteEvent")
                if remote then pcall(function() remote:FireServer() end) end
            end
        end

        if bubbleGoal.Magnitude > C.MIN_FOLLOW_DISTANCE then
            local hybrid = bubbleVelocity:Lerp(legacyVelocity, 0.45)
            bubbleAimbot.intendedVelocity = hybrid
            root.AssemblyLinearVelocity = root.AssemblyLinearVelocity:Lerp(hybrid, 0.8)
            pcall(function() humanoid:Move(legacyFlatUnit, false) end)
        else
            bubbleAimbot.intendedVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y * 0.5, 0)
            root.AssemblyLinearVelocity = bubbleAimbot.intendedVelocity
            pcall(function() humanoid:Move(Vector3.zero, false) end)
        end
    end)

    circleSafetyConn = RunService.Heartbeat:Connect(function()
        if not State.bypassBatEnabled then
            if circleSafetyConn then circleSafetyConn:Disconnect(); circleSafetyConn = nil end
            return
        end
        local c = LP.Character
        local r = c and c:FindFirstChild("HumanoidRootPart")
        if not r then return end
        local v = r.AssemblyLinearVelocity
        if math.abs(v.X) > 350 or math.abs(v.Z) > 350 then
            r.AssemblyLinearVelocity = bubbleAimbot.intendedVelocity or Vector3.zero
        end
    end)
end

stopCircleCombat = function()
    if circleConnection then
        circleConnection:Disconnect()
        circleConnection = nil
    end
    if circleSafetyConn then
        circleSafetyConn:Disconnect()
        circleSafetyConn = nil
    end
    do
        local c = LP.Character
        local r = c and c:FindFirstChild("HumanoidRootPart")
        if r then
            local a = r:FindFirstChild("_RivalHub_AngV"); if a then a:Destroy() end
            local at = r:FindFirstChild("_RivalHub_Att"); if at then at:Destroy() end
        end
    end
    if predictionSphere then
        predictionSphere:Destroy()
        predictionSphere = nil
    end
    local char = LP.Character
    if char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then hum.AutoRotate = true end
        local root = char:FindFirstChild("HumanoidRootPart")
        if root then root.AssemblyAngularVelocity = Vector3.zero end
    end
    _mba.reset()
    targetPlayer = nil
    lastTargetPos = nil
    targetVelocity = Vector3.zero
    smoothedVelocity = Vector3.zero
    velocityHistory = {}
    accelerationHistory = {}
    aerialVelocityHistory = {}
    verticalVelocityHistory = {}
    aerialSmoothVelocity = Vector3.zero
    airborneTime = 0
    highYVelocityTime = 0
    previousDirection = nil
    wasAirborne = false
    lastYVelocity = 0
    peakHeight = 0
    isMultiJumping = false
    lastActivationTime = 0
    if _G.__RivalHubBubbleAimbotState then
        _G.__RivalHubBubbleAimbotState.target = nil
        _G.__RivalHubBubbleAimbotState.nextSwingAt = 0
    end
end

end

function stopAimbotAdapt()
    State.bypassBatEnabled = false
    if stopCircleCombat then pcall(stopCircleCombat) end
    _aimbotConn = nil
    local char = LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        hum.AutoRotate = true
        hum.PlatformStand = false
        pcall(function() hum:ChangeState(Enum.HumanoidStateType.Running) end)
    end
    if root then
        local sv = root.AssemblyLinearVelocity   -- Vision resetAutoBatMotion: keep 30% of horizontal speed
        root.AssemblyLinearVelocity = _V3new(sv.X * 0.3, sv.Y, sv.Z * 0.3)
        root.AssemblyAngularVelocity = _V3zero
    end
    _prevAutoRotate = nil
    lastMoveDir = _V3zero
    _unsuppressBodyLock(true)
end

function startAimbotAdapt()
    State.bypassBatSpeed = tonumber(State.bypassBatSpeed) or tonumber(BYPASS_AIMBOT_SPEED) or 58
    State.bypassBatEnabled = true
    _suppressBodyLock()
    local hum0 = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    if hum0 and _prevAutoRotate == nil then _prevAutoRotate = hum0.AutoRotate end
    startCircleCombat()
end

function disableAutoBat()
    if moonPendingCarryResume == "AutoBat" then moonPendingCarryResume = nil end
    autoBatEnabled = false
    if autoBatSetVisual then autoBatSetVisual(false) end
    if mobSetAutoBat then mobSetAutoBat(false) end
    stopAimbotAdapt()
end

function enableAutoBat()
    if _G.MoonIsHoldingBrainrot() then
        autoBatEnabled = false
        moonTogglePending("AutoBat")
        return
    end
    if moonPendingCarryResume == "AutoBat" then moonPendingCarryResume = nil end
    if autoLeftEnabled then
        autoLeftEnabled = false
        if autoLeftSetVisual then autoLeftSetVisual(false) end
        stopAutoLeft()
    end
    if autoRightEnabled then
        autoRightEnabled = false
        if autoRightSetVisual then autoRightSetVisual(false) end
        stopAutoRight()
    end
    autoBatEnabled = true
    if autoBatSetVisual then autoBatSetVisual(true) end
    if mobSetAutoBat then mobSetAutoBat(true) end
    startAimbotAdapt()
end

function findBat()
    local char = LP.Character
    if not char then return nil end
    for _, name in ipairs(BAT_COUNTER_SLAP_LIST) do
        local t = char:FindFirstChild(name)
        if t and t:IsA("Tool") then return t end
    end
    local bp = LP:FindFirstChildOfClass("Backpack")
    if bp then
        for _, name in ipairs(BAT_COUNTER_SLAP_LIST) do
            local t = bp:FindFirstChild(name)
            if t and t:IsA("Tool") then
                local hum = char:FindFirstChildOfClass("Humanoid")
                if hum then pcall(function() hum:EquipTool(t) end) end
                return t
            end
        end
    end
    for _, ch in ipairs(char:GetChildren()) do
        if ch:IsA("Tool") and (ch.Name:lower():find("bat") or ch.Name:lower():find("slap")) then
            return ch
        end
    end
    return nil
end

function isBatTool(tool)
    if not tool then return false end
    for _, name in ipairs(BAT_COUNTER_SLAP_LIST) do
        if tool.Name == name then return true end
    end
    return tool.Name:lower():find("bat") or tool.Name:lower():find("slap")
end

--------------------------------------------------------------------
-- Bat Counter (V1, from Ambitious): when you get ragdolled it turns you toward the
-- nearest enemy and swings your bat for 0.7s, then releases the aim.
--------------------------------------------------------------------
do
    local SLAPS = {"Bat", "Slap", "Iron Slap", "Gold Slap", "Diamond Slap", "Emerald Slap",
        "Ruby Slap", "Dark Matter Slap", "Flame Slap", "Nuclear Slap", "Galaxy Slap", "Glitched Slap"}
    local debounce = false
    local runtimeEnabled = false
    local medusaHandledStamp = 0
    -- Same filter TP Ragdoll uses: ignore the ragdoll if the nearest enemy is already down.
    local BAT_SKIP_IF_ENEMY_DOWN = true

    -- Keep the source's Medusa timestamp signal available in this host script.
    if _G.MoonHubMedusaWatcherCleanup then pcall(_G.MoonHubMedusaWatcherCleanup) end
    local medusaWatchConns = {}
    local medusaCharConn
    local function clearMedusaWatcher()
        for _, c in ipairs(medusaWatchConns) do pcall(function() c:Disconnect() end) end
        medusaWatchConns = {}
    end
    local function hookMedusaPart(part)
        if not part:IsA("BasePart") then return end
        table.insert(medusaWatchConns, part:GetPropertyChangedSignal("Anchored"):Connect(function()
            if part.Anchored and part.Transparency == 1 then
                _G._AmbitiousMedusaHitTime = tick()
                if type(_G.RivalAntiBatPanicOff) == "function" then
                    pcall(_G.RivalAntiBatPanicOff, "medusa")
                end
                -- Instant medusa path for modes 2 and 3 (reply with BAT only, never medusa tool)
                local mode = tonumber(_G.batCounterMode) or tonumber(batCounterMode) or 3
                if batCounterEnabled and runtimeEnabled and (mode == 2 or mode == 3) then
                    local st = tonumber(_G._AmbitiousMedusaHitTime) or 0
                    if st ~= 0 and st ~= medusaHandledStamp then
                        medusaHandledStamp = st
                        if type(_G.__MoonHubFireBatCounterReply) == "function" then
                            pcall(_G.__MoonHubFireBatCounterReply, "medusa-instant")
                        end
                    end
                end
            end
        end))
    end
    local function attachMedusaWatcher(char)
        clearMedusaWatcher()
        _G._AmbitiousMedusaHitTime = 0
        if not char then return end
        for _, part in ipairs(char:GetDescendants()) do hookMedusaPart(part) end
        table.insert(medusaWatchConns, char.DescendantAdded:Connect(hookMedusaPart))
    end
    if LP.Character then attachMedusaWatcher(LP.Character) end
    medusaCharConn = LP.CharacterAdded:Connect(function(char)
        task.wait()
        attachMedusaWatcher(char)
    end)
    _G.MoonHubMedusaWatcherCleanup = function()
        clearMedusaWatcher()
        if medusaCharConn then pcall(function() medusaCharConn:Disconnect() end); medusaCharConn = nil end
    end

    -- look at nearest enemy (unlimited radius)
    local look = { part = nil, align = nil, conn = nil, died = nil, humanoid = nil, prevAutoRotate = nil }
    local lookParent = workspace:FindFirstChild("Terrain") or workspace

    local function restoreLookAutoRotate(hum, clearSaved)
        hum = hum or look.humanoid
        if hum then
            if type(_G.MoonHubRestoreAutoRotate) == "function" then
                pcall(_G.MoonHubRestoreAutoRotate, hum, look.prevAutoRotate)
            elseif look.prevAutoRotate ~= nil then
                hum.AutoRotate = look.prevAutoRotate
            else
                hum.AutoRotate = true
            end
        end
        if clearSaved then
            look.humanoid = nil
            look.prevAutoRotate = nil
        end
    end

    local function nearestEnemyRoot()
        local char = LP.Character
        local myRoot = char and char:FindFirstChild("HumanoidRootPart")
        if not myRoot then return nil end
        local best, bestDist = nil, math.huge
        for _, plr in ipairs(Players:GetPlayers()) do
            if plr ~= LP then
                local c = plr.Character
                local r = c and c:FindFirstChild("HumanoidRootPart")
                local h = c and c:FindFirstChildOfClass("Humanoid")
                if r and h and h.Health > 0 then
                    local targetPos = r.Position
                    if type(_G.MoonAntiVoidPosition) == "function" then targetPos = _G.MoonAntiVoidPosition(plr, targetPos) end
                    local d = (targetPos - myRoot.Position).Magnitude
                    if d < bestDist then bestDist, best = d, r end
                end
            end
        end
        return best
    end

    local function lookStop()
        if look.conn then look.conn:Disconnect() look.conn = nil end
        if look.died then look.died:Disconnect() look.died = nil end
        if look.part then look.part:Destroy() look.part = nil end
        if look.align then look.align:Destroy() look.align = nil end
        local char = LP.Character
        local hum = look.humanoid or (char and char:FindFirstChildOfClass("Humanoid"))
        restoreLookAutoRotate(hum, true)
    end

    local function lookStart()
        lookStop()
        local char = LP.Character
        local myRoot = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not myRoot or not hum or hum.Health <= 0 then return end
        look.humanoid = hum
        look.prevAutoRotate = hum.AutoRotate
        look.died = hum.Died:Connect(lookStop)

        local ep = Instance.new("Part")
        ep.Name = "MoonLookAnchor"
        ep.Size = Vector3.new(1, 1, 1)
        ep.Transparency = 1
        ep.CanCollide = false
        ep.Anchored = true
        ep.CFrame = myRoot.CFrame
        ep.Parent = lookParent
        look.part = ep

        local attExt = Instance.new("Attachment", ep)
        local attLocal = myRoot:FindFirstChild("RootAttachment")
        if not attLocal then
            attLocal = Instance.new("Attachment")
            attLocal.Name = "RootAttachment"
            attLocal.Parent = myRoot
        end
        local ao = Instance.new("AlignOrientation")
        ao.Name = "MoonLookOrientation"
        ao.Mode = Enum.OrientationAlignmentMode.TwoAttachment
        ao.Attachment0 = attLocal
        ao.Attachment1 = attExt
        ao.MaxTorque = 999999
        ao.MaxAngularVelocity = 999999
        ao.Responsiveness = 200
        ao.Enabled = false
        ao.Parent = lookParent
        look.align = ao

        look.conn = RunService.Heartbeat:Connect(function()
            local c = LP.Character
            local root = c and c:FindFirstChild("HumanoidRootPart")
            local h = c and c:FindFirstChildOfClass("Humanoid")
            if not root or not h or h.Health <= 0 then lookStop() return end
            local target = nearestEnemyRoot()
            if target and look.part and look.align then
                h.AutoRotate = false
                look.align.Enabled = true
                local targetPos = target.Position
                local targetPlayer = Players:GetPlayerFromCharacter(target.Parent)
                if type(_G.MoonAntiVoidPosition) == "function" then targetPos = _G.MoonAntiVoidPosition(targetPlayer, targetPos) end
                local flat = Vector3.new(targetPos.X, root.Position.Y, targetPos.Z)
                look.part.CFrame = CFrame.lookAt(root.Position, flat)
            else
                restoreLookAutoRotate(h, false)
                if look.align then look.align.Enabled = false end
            end
        end)
    end

    local function findBat()
        local char = LP.Character
        if not char then return nil end
        local bp = LP:FindFirstChildOfClass("Backpack")
        for _, name in ipairs(SLAPS) do
            local t = char:FindFirstChild(name) or (bp and bp:FindFirstChild(name))
            if t then return t end
        end
        for _, ch in ipairs(char:GetChildren()) do
            if ch:IsA("Tool") and ch.Name:lower():find("bat") then return ch end
        end
        if bp then
            for _, ch in ipairs(bp:GetChildren()) do
                if ch:IsA("Tool") and ch.Name:lower():find("bat") then return ch end
            end
        end
        return nil
    end

    local function swingBat(bat, char)
        local hum = char:FindFirstChildOfClass("Humanoid")
        if bat.Parent ~= char then
            if hum then pcall(function() hum:EquipTool(bat) end) end
            task.wait(0.05)
        end
        local remote = bat:FindFirstChildOfClass("RemoteEvent") or bat:FindFirstChildOfClass("RemoteFunction")
        if remote and remote:IsA("RemoteEvent") then
            pcall(function() remote:FireServer() end)
            task.wait(0.15)
            pcall(function() remote:FireServer() end)
        else
            pcall(function() bat:Activate() end)
            task.wait(0.15)
            pcall(function() bat:Activate() end)
        end
    end

    -- ragdoll check used by the bat counter (FallingDown is ignored on purpose)
    -- (same definition TP Ragdoll uses to detect a bat hit: Physics / Ragdoll state only)
    local function isRagdolled(hum)
        local st = hum:GetState()
        return st == Enum.HumanoidStateType.Physics
            or st == Enum.HumanoidStateType.Ragdoll
    end

    -- Connected once at load, BEFORE Anti Ragdoll V1 (Heartbeat) is ever started, so each frame
    -- the counter reads the humanoid state first and Anti Ragdoll clears it afterwards
    -- (Anti Ragdoll V2 runs on RenderStepped, i.e. before the physics/replicated state arrives).
    -- Rising-edge memory so we only counter on a NEW bat ragdoll hit
    local wasRagdolled = false
    local stateConn = nil
    local charHookConn = nil

    -- Shared: always reply with BAT only (never medusa tool)
    local function fireBatCounterReply(reason)
        -- Anti Bat OFF first, synchronously, before the reply starts
        if type(_G.RivalAntiBatPanicOff) == "function" then pcall(_G.RivalAntiBatPanicOff, "bat-counter-reply") end
        if not batCounterEnabled or not runtimeEnabled or debounce then return end
        if _G._AmbitiousInstantResetBusy then return end
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return end
        debounce = true
        if _G.AmbitiousAntiDieArmNow then pcall(_G.AmbitiousAntiDieArmNow) end
        -- face the nearest enemy THIS instant (the smooth look-at below only keeps it locked)
        pcall(function()
            local root = char:FindFirstChild("HumanoidRootPart")
            local tr = nearestEnemyRoot()
            if root and tr then
                root.CFrame = CFrame.lookAt(root.Position, Vector3.new(tr.Position.X, root.Position.Y, tr.Position.Z))
            end
        end)
        task.spawn(function()
            lookStart()
            local bat = findBat()
            if bat then
                task.spawn(function() swingBat(bat, char) end)
            end
            task.wait(0.7)
            lookStop()
            task.wait(0.5)
            debounce = false
        end)
    end
    _G.__MoonHubFireBatCounterReply = fireBatCounterReply

    local function getMode()
        local mode = tonumber(_G.batCounterMode) or tonumber(batCounterMode) or 3
        if mode < 1 or mode > 3 then mode = 3 end
        return mode
    end

    -- Bat-hit detection copied from TP Ragdoll: ragdoll edge that is NOT a Medusa hit
    -- and NOT "nearest enemy already down".
    local function isMedusaHitNow()
        if type(_G._AmbitiousIsMedusaHit) == "function" then
            local ok, r = pcall(_G._AmbitiousIsMedusaHit)
            if ok and r == true then return true end
        end
        -- instant check (no waiting): Medusa freezes parts of your character (anchored + invisible)
        local char = LP.Character
        if char then
            for _, part in ipairs(char:GetDescendants()) do
                if part:IsA("BasePart") and part.Anchored and part.Transparency == 1 then
                    return true
                end
            end
        end
        return false
    end

    local function isEnemyAlreadyDown()
        if not BAT_SKIP_IF_ENEMY_DOWN then return false end
        if type(_G.AmbitiousIsNearestEnemyRagdolled) == "function" then
            local ok, r = pcall(_G.AmbitiousIsNearestEnemyRagdolled)
            return ok and r == true
        end
        return false
    end

    local function tryBatHitReply()
        -- A bat ragdoll edge: Anti Bat must already be OFF before any decision below
        if type(_G.RivalAntiBatPanicOff) == "function" then pcall(_G.RivalAntiBatPanicOff, "bat-hit") end
        local mode = getMode()
        if mode == 2 then return end            -- mode 2: Medusa only, bat is ignored
        if mode == 3 then                       -- mode 3: bat or Medusa, reply instantly
            fireBatCounterReply("bat")
            return
        end
        -- mode 1: BAT only (never Medusa) - decided instantly, no delay
        if isMedusaHitNow() then return end
        if isEnemyAlreadyDown() then return end
        fireBatCounterReply("bat")
    end

    local function tryMedusaReply()
        local mode = getMode()
        if mode == 1 then return end -- mode 1 never reacts to medusa
        local stamp = tonumber(_G._AmbitiousMedusaHitTime) or 0
        if stamp == 0 or stamp == medusaHandledStamp then return end
        if (tick() - stamp) > 1.5 then return end
        medusaHandledStamp = stamp
        fireBatCounterReply("medusa")
    end

    local function onBatCounterHeartbeat()
        if not batCounterEnabled or not runtimeEnabled then
            wasRagdolled = false
            return
        end
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum then
            wasRagdolled = false
            return
        end
        if hum.Health <= 0 or _G._AmbitiousInstantResetBusy then
            wasRagdolled = false
            return
        end

        local rag = isRagdolled(hum)
        local justGotBatHit = rag and not wasRagdolled
        wasRagdolled = rag

        if justGotBatHit then
            tryBatHitReply()
        end
        -- medusa path also polled here (modes 2/3)
        tryMedusaReply()
    end

    -- StateChanged: catches bat ragdoll even if Anti Ragdoll clears it before next Heartbeat
    local function hookBatCounterState(hum)
        if stateConn then pcall(function() stateConn:Disconnect() end); stateConn = nil end
        if not hum then return end
        stateConn = hum.StateChanged:Connect(function(_, newSt)
            if not batCounterEnabled or not runtimeEnabled then return end
            if newSt == Enum.HumanoidStateType.Physics
                or newSt == Enum.HumanoidStateType.Ragdoll then
                if not wasRagdolled then
                    wasRagdolled = true
                    tryBatHitReply()
                end
            elseif newSt ~= Enum.HumanoidStateType.Physics
                and newSt ~= Enum.HumanoidStateType.Ragdoll then
                -- only clear if not PlatformStand still
                local h = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                if h and not isRagdolled(h) then
                    wasRagdolled = false
                end
            end
        end)
    end

    -- Connect before optional Anti Ragdoll Heartbeat handlers, as in the source.
    if _G.__RivalHubBatCounterV1Conn then
        pcall(function() _G.__RivalHubBatCounterV1Conn:Disconnect() end)
    end
    _G.__RivalHubBatCounterV1Conn = RunService.Heartbeat:Connect(onBatCounterHeartbeat)
    Conns.batCounter = _G.__RivalHubBatCounterV1Conn

    if LP.Character then
        hookBatCounterState(LP.Character:FindFirstChildOfClass("Humanoid"))
    end
    if charHookConn then pcall(function() charHookConn:Disconnect() end) end
    charHookConn = LP.CharacterAdded:Connect(function(ch)
        wasRagdolled = false
        task.defer(function()
            hookBatCounterState(ch:FindFirstChildOfClass("Humanoid") or ch:WaitForChild("Humanoid", 5))
        end)
    end)

    function startBatCounter()
        runtimeEnabled = true
        wasRagdolled = false
        -- enemy-ragdoll watcher (needed by the bat detection); TP Ragdoll normally starts it
        pcall(function()
            local c = _G.AmbitiousBatCounterWatchConns
            if type(_G.AmbitiousStartBatCounterWatcher) == "function" and (type(c) ~= "table" or next(c) == nil) then
                _G.AmbitiousStartBatCounterWatcher()
            end
        end)
        if not _G.__RivalHubBatCounterV1Conn then
            _G.__RivalHubBatCounterV1Conn = RunService.Heartbeat:Connect(onBatCounterHeartbeat)
        end
        Conns.batCounter = _G.__RivalHubBatCounterV1Conn
        local ch = LP.Character
        if ch then hookBatCounterState(ch:FindFirstChildOfClass("Humanoid")) end
    end

    -- Source stop behavior: clear debounce and release the aim; listener remains idle.
    function stopBatCounter()
        runtimeEnabled = false
        debounce = false
        wasRagdolled = false
        pcall(lookStop)
    end
end


function findMedusa()
    local c = LP.Character
    if not c then return nil end
    for _, t in ipairs(c:GetChildren()) do
        if t:IsA("Tool") then
            local n = t.Name:lower()
            if n:find("medusa") or n:find("head") or n:find("stone") then return t end
        end
    end
    local bp = LP:FindFirstChild("Backpack")
    if bp then
        for _, t in ipairs(bp:GetChildren()) do
            if t:IsA("Tool") then
                local n = t.Name:lower()
                if n:find("medusa") or n:find("head") or n:find("stone") then return t end
            end
        end
    end
    return nil
end

function useMedusaCounter()
    -- Anti Bat OFF first, synchronously, before the counter does anything
    if type(_G.RivalAntiBatPanicOff) == "function" then pcall(_G.RivalAntiBatPanicOff, "medusa-counter") end
    if medusaDebounce then return end
    if _tick() - medusaLastUsed < MEDUSA_COOLDOWN then return end
    local c = LP.Character
    if not c then return end
    medusaDebounce = true
    local med = findMedusa()
    if not med then medusaDebounce = false; return end
    if med.Parent ~= c then
        local hum2 = c:FindFirstChildOfClass("Humanoid")
        if hum2 then hum2:EquipTool(med) end
    end
    pcall(function() med:Activate() end)
    medusaLastUsed = _tick()
    medusaDebounce = false
end

function onAnchorChanged(part)
    return part:GetPropertyChangedSignal("Anchored"):Connect(function()
        if part.Anchored and part.Transparency == 1 then
            -- Medusa hit: Anti Bat dies this very instant, whatever the listener order
            if type(_G.RivalAntiBatPanicOff) == "function" then pcall(_G.RivalAntiBatPanicOff, "medusa-anchor") end
        end
        if medusaCounterEnabled and part.Anchored and part.Transparency == 1 then useMedusaCounter() end
    end)
end

function setupMedusaCounter(char)
    for _, c in pairs(Conns.anchor) do pcall(function() c:Disconnect() end) end
    Conns.anchor = {}
    if not char or not medusaCounterEnabled then return end
    for _, part in ipairs(char:GetDescendants()) do
        if part:IsA("BasePart") then
            table.insert(Conns.anchor, onAnchorChanged(part))
        end
    end
    table.insert(Conns.anchor, char.DescendantAdded:Connect(function(part)
        if part:IsA("BasePart") then
            table.insert(Conns.anchor, onAnchorChanged(part))
        end
    end))
end

function stopMedusaCounter()
    for _, c in pairs(Conns.anchor) do pcall(function() c:Disconnect() end) end
    Conns.anchor = {}
end

local DROP_ASCEND_DURATION = 0.2
local DROP_ASCEND_SPEED = 150
local _dropConn = nil

function stopDropBrainrot()
    dropActive = false
    if _dropConn then
        _dropConn:Disconnect()
        _dropConn = nil
    end
    for _, t in ipairs(dropConnections) do
        if type(t) == "thread" then pcall(task.cancel, t)
        elseif type(t) == "RBXScriptConnection" then pcall(t.Disconnect, t) end
    end
    dropConnections = {}
    local c = LP.Character
    if c then
        local root = c:FindFirstChild("HumanoidRootPart")
        if root then root.AssemblyLinearVelocity = _V3zero end
    end
    if dropBrainrotSetVisual then dropBrainrotSetVisual(false) end
    if mobSetDropBR then mobSetDropBR(false) end
end

function runDropBrainrot()
    if dropActive then return end
    local char = LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not root or not hum then return end
    if autoBatEnabled then
        autoBatEnabled = false
        if autoBatSetVisual then autoBatSetVisual(false) end
        if mobSetAutoBat then mobSetAutoBat(false) end
        if stopAimbotAdapt then stopAimbotAdapt() end
    end
    dropActive = true
    if dropBrainrotSetVisual then dropBrainrotSetVisual(true) end
    if mobSetDropBR then mobSetDropBR(false) end
    local t0 = _tick()
    if _dropConn then _dropConn:Disconnect() end
    _dropConn = RunService.Heartbeat:Connect(function()
        local r = char and char:FindFirstChild("HumanoidRootPart")
        if not r then
            if _dropConn then _dropConn:Disconnect(); _dropConn = nil end
            dropActive = false
            if dropBrainrotSetVisual then dropBrainrotSetVisual(false) end
            if mobSetDropBR then mobSetDropBR(false) end
            return
        end
        if _tick() - t0 >= DROP_ASCEND_DURATION then
            if _dropConn then _dropConn:Disconnect(); _dropConn = nil end
            local rp = _RayParams_new()
            rp.FilterDescendantsInstances = {char}
            rp.FilterType = Enum.RaycastFilterType.Exclude
            local rr = workspace:Raycast(r.Position, _V3new(0, -2000, 0), rp)
            if rr then
                local hum2 = char:FindFirstChildOfClass("Humanoid")
                local off = ((hum2 and hum2.HipHeight) or 2) + (r.Size.Y / 2)
                r.CFrame = _CFnew(r.Position.X, rr.Position.Y + off, r.Position.Z)
                r.AssemblyLinearVelocity = _V3zero
            end
            dropActive = false
            if dropBrainrotSetVisual then dropBrainrotSetVisual(false) end
            if mobSetDropBR then mobSetDropBR(false) end
            return
        end
        r.Velocity = _V3new(r.Velocity.X, DROP_ASCEND_SPEED, r.Velocity.Z)
    end)
end

function executeDropWithToggle(setVisual)
    if dropActive then return end
    task.spawn(function()
        if setVisual then setVisual(true) end
        runDropBrainrot()
        while dropActive do task.wait() end
        task.wait(0.1)
        if setVisual then setVisual(false) end
    end)
end

