local function _vC3(t) return Color3.fromRGB(t[1], t[2], t[3]) end

function _v4mpClearSky()
    for _, child in ipairs(Lighting:GetChildren()) do
        if child:GetAttribute("_AdaptDuelsSky") then
            pcall(function() child:Destroy() end)
        end
    end
    local terrain = workspace:FindFirstChildOfClass("Terrain")
    if terrain then
        for _, child in ipairs(terrain:GetChildren()) do
            if child:GetAttribute("_AdaptDuelsSky") then
                pcall(function() child:Destroy() end)
            end
        end
    end
end

function applyCustomSky(mode)
    _v4mpClearSky()
    local preset = SKY_PRESETS[mode]
    if not preset or preset.kind == "off" then
        Lighting.ClockTime = 14
        Lighting.Brightness = 2
        Lighting.OutdoorAmbient = Color3.fromRGB(127,127,127)
        Lighting.Ambient = Color3.fromRGB(127,127,127)
        Lighting.FogEnd = 100000
        Lighting.GlobalShadows = true
        skyTheme = "Off"
        return
    end
    Lighting.FogStart = 0
    Lighting.FogEnd = 100000
    Lighting.FogColor = Color3.fromRGB(200,200,200)
    Lighting.ColorShift_Top = Color3.fromRGB(0,0,0)
    Lighting.ColorShift_Bottom = Color3.fromRGB(0,0,0)
    Lighting.GlobalShadows = true
    Lighting.ClockTime = preset.clock or 14
    Lighting.Brightness = math.max(tonumber(preset.brightness) or 2, 2.5)
    if preset.outAmb then Lighting.OutdoorAmbient = _vC3(preset.outAmb) end
    if preset.ambient then Lighting.Ambient = _vC3(preset.ambient) end
    local amb = Lighting.Ambient
    local out = Lighting.OutdoorAmbient
    Lighting.Ambient = Color3.fromRGB(math.max(amb.R * 255, 135), math.max(amb.G * 255, 135), math.max(amb.B * 255, 135))
    Lighting.OutdoorAmbient = Color3.fromRGB(math.max(out.R * 255, 145), math.max(out.G * 255, 145), math.max(out.B * 255, 145))
    if preset.sky then
        local skyInst = Instance.new("Sky")
        skyInst:SetAttribute("_AdaptDuelsSky", true)
        if preset.sky.stars then skyInst.StarCount = preset.sky.stars end
        if preset.sky.moon then skyInst.MoonAngularSize = preset.sky.moon end
        if preset.sky.sun then skyInst.SunAngularSize = preset.sky.sun end
        if preset.sky.moonTex then skyInst.MoonTextureId = "rbxasset://sky/moon.jpg" end
        skyInst.Parent = Lighting
    end
    if preset.atm then
        local atm = Instance.new("Atmosphere")
        atm:SetAttribute("_AdaptDuelsSky", true)
        atm.Density = preset.atm.dens or 0.3
        atm.Color = _vC3(preset.atm.color)
        atm.Decay = _vC3(preset.atm.decay)
        atm.Glare = preset.atm.glare or 1
        atm.Haze = preset.atm.haze or 1
        atm.Parent = Lighting
    end
    local terrain = workspace:FindFirstChildOfClass("Terrain")
    if preset.clouds and terrain then
        local clouds = Instance.new("Clouds")
        clouds:SetAttribute("_AdaptDuelsSky", true)
        clouds.Cover = preset.clouds.cover or 0.5
        clouds.Density = preset.clouds.dens or 0.5
        clouds.Color = _vC3(preset.clouds.color)
        clouds.Parent = terrain
    end
    skyTheme = mode
end

function enableVividGraphics()
    if vividGraphicsEnabled and #_vividEffects > 0 then return end
    vividGraphicsEnabled = true
    for _, eff in ipairs(_vividEffects) do
        pcall(function() eff:Destroy() end)
    end
    _vividEffects = {}
    local color = Instance.new("ColorCorrectionEffect")
    color.Parent = Lighting
    color.Saturation = 0.6; color.Contrast = 0.4; color.Brightness = 0.05
    color.TintColor = Color3.fromRGB(255, 240, 220)
    table.insert(_vividEffects, color)
    local bloom = Instance.new("BloomEffect")
    bloom.Parent = Lighting
    bloom.Intensity = 0.8; bloom.Size = 24; bloom.Threshold = 1
    table.insert(_vividEffects, bloom)
    local atmosphere = Instance.new("Atmosphere")
    atmosphere.Parent = Lighting
    atmosphere.Density = 0.3; atmosphere.Offset = 0.25
    atmosphere.Color = Color3.fromRGB(199, 199, 255)
    atmosphere.Decay = Color3.fromRGB(106, 112, 125)
    atmosphere.Glare = 0.2; atmosphere.Haze = 1
    table.insert(_vividEffects, atmosphere)
    local sun = Instance.new("SunRaysEffect")
    sun.Parent = Lighting
    sun.Intensity = 0.2; sun.Spread = 0.8
    table.insert(_vividEffects, sun)
    local dof = Instance.new("DepthOfFieldEffect")
    dof.Parent = Lighting
    dof.FocusDistance = 25; dof.InFocusRadius = 10
    dof.NearIntensity = 0.2; dof.FarIntensity = 0.4
    table.insert(_vividEffects, dof)
    task.spawn(function()
        while vividGraphicsEnabled and color and color.Parent do
            color.Contrast = 0.35 + math.sin(tick() * 2) * 0.05
            task.wait(0.03)
        end
    end)
end

function disableVividGraphics()
    vividGraphicsEnabled = false
    for _, eff in ipairs(_vividEffects) do
        pcall(function() eff:Destroy() end)
    end
    _vividEffects = {}
end

function toggleVividGraphics(on)
    if on then enableVividGraphics() else disableVividGraphics() end
    -- save removed
end

-- Split Aimbot: the "Aimbot Bypass" mobile button + its key row exist only while the feature is ON
_G.MoonAimbotSplit = false          -- Split Aimbot: OFF by default (auto Anti-Bat switch is the normal behaviour)
_G.MoonAimbotFixed = false          -- Fixed Aimbot: OFF by default
_G.MoonAimbotFixedMode = "normal"   -- "normal" | "bypass"
function _G.MoonRefreshAimbotBypassUI()
    local on = _G.MoonAimbotSplit == true
    local panel = MobilePanel or _G.RivalHubMobilePanel
    if panel then
        local b = panel:FindFirstChild("AimbotBypass")
        if b then
            local list = _G.RivalHubMobileHideList
            local listOn = not (type(list) == "table" and list.AimbotBypass == false)
            b:SetAttribute("RivalForceHidden", not on)
            b.Visible = on and listOn and (hideButtonsEnabled ~= true)
            b.Active = on
        end
    end
    local row = _G.MoonAimbotBypassKeyRow
    if row and row.Parent then row.Visible = on end
end

function applyHideButtons(state)
    hideButtonsEnabled = state == true
    _G.RivalHubHideMobileButtons = hideButtonsEnabled
    local list = _G.RivalHubMobileHideList
    if type(list) ~= "table" then list = {} end
    local panel = MobilePanel or _G.RivalHubMobilePanel
    if panel then
        -- Moon-style: scan descendants so nested buttons also hide/show
        for _, child in ipairs(panel:GetDescendants()) do
            if child:IsA("TextButton") or child:IsA("ImageButton") then
                local key = child.Name
                local listOn = true
                if list[key] == false then listOn = false end
                -- Master ON = hide all; Master OFF = show only buttons still ON in list
                if hideButtonsEnabled then
                    child.Visible = false
                else
                    child.Visible = listOn
                end
            end
        end
        -- also direct children (some builds parent buttons directly)
        for _, child in ipairs(panel:GetChildren()) do
            if child:IsA("TextButton") or child:IsA("ImageButton") then
                local key = child.Name
                local listOn = true
                if list[key] == false then listOn = false end
                if hideButtonsEnabled then
                    child.Visible = false
                else
                    child.Visible = listOn
                end
            end
        end
    end
    if type(_G.MoonRefreshAimbotBypassUI) == "function" then pcall(_G.MoonRefreshAimbotBypassUI) end
end

function toggleHideButtons(on)
    applyHideButtons(on)
    if setHideButtonsVisual then setHideButtonsVisual(on) end
    -- save removed
end

function resetMobileButtonPositions()
    -- First-run mobile buttons: default grid, all visible, hide master OFF
    if not MobilePanel then return end
    local BTN_W, BTN_H = 52, 52
    savedButtonPositions = {}
    for _, child in ipairs(MobilePanel:GetChildren()) do
        if child:IsA("TextButton") then
            local defX, defY = 0, 0
            if type(getDefaultButtonPosition) == "function" then
                defX, defY = getDefaultButtonPosition(child.Name)
            end
            child.Position = UDim2.new(0, defX, 0, defY)
            child.Size = UDim2.new(0, BTN_W, 0, BTN_H)
            child.Visible = (child.Name ~= "AimbotBypass") or (_G.MoonAimbotSplit == true)
            child.Active = true
            savedButtonPositions[child.Name] = { X = defX, Y = defY }
            -- paint inactive (first-run look)
            if type(paintFloatingBtn) == "function" then
                pcall(paintFloatingBtn, child, false)
            end
        end
    end
    floatingButtonScale = 1
    if type(applyFloatingButtonScale) == "function" then
        pcall(applyFloatingButtonScale)
    end
    -- every hide-list item ON + master OFF (all buttons shown)
    _G.RivalHubMobileHideList = {
        DropBR = true, AutoLeft = true, Aimbot = true, AutoRight = true,
        TpDown = true, Carry = true, Lagger1 = true, Lagger2 = true,
        InstantReset = true, AimbotBypass = true,
    }
    hideButtonsEnabled = false
    applyHideButtons(false)
    if setHideButtonsVisual then pcall(setHideButtonsVisual, false) end
    -- refresh hide-list option switches in Settings UI if present
    pcall(function()
        local guiRoot = main or gui
        if not guiRoot then return end
        local holder = guiRoot:FindFirstChild("Hide Mobile Buttons Options", true)
        if not holder then return end
        for _, r in ipairs(holder:GetChildren()) do
            if r:IsA("Frame") and r.Name:match("^HideOpt_") then
                local track = r:FindFirstChild("Track")
                local knob = track and track:FindFirstChild("Knob")
                if track and knob then
                    track.BackgroundColor3 = Color3.fromRGB(80, 150, 255)
                    knob.Position = UDim2.new(1, -18, 0.5, -8)
                end
            end
        end
    end)
end
_G.RivalHubResetMobileButtons = resetMobileButtonPositions

