_G.MoonHubRainbowConn = nil

--=========================================================
--  paintFloatingBtn  (OFF = clean logo, ON = solid blue)
--=========================================================
function paintFloatingBtn(btnFrame, active)
    if not btnFrame then return end
    active = active == true
    local label  = btnFrame:FindFirstChild("TextLabel")
    local stroke = btnFrame:FindFirstChildOfClass("UIStroke")
    local img = btnFrame:FindFirstChild("ButtonImage")
    local bg = btnFrame:FindFirstChild("BtnGrad")
    if bg then bg.Enabled = false end
    for _, name in ipairs({"RainbowFill"}) do
        local g = btnFrame:FindFirstChild(name)
        if g then pcall(function() g:Destroy() end) end
    end
    if stroke then
        local g = stroke:FindFirstChild("RainbowStroke")
        if g then pcall(function() g:Destroy() end) end
    end
    if active then
        btnFrame.BackgroundColor3 = Color3.fromRGB(0, 132, 255)
        btnFrame.BackgroundTransparency = 0
        if img then img.Visible = true; img.ImageTransparency = 0.75 end
    else
        btnFrame.BackgroundColor3 = Color3.fromRGB(32, 24, 56)
        btnFrame.BackgroundTransparency = 0.55
        if img then
            img.Visible = true
            img.ImageColor3 = Color3.fromRGB(255, 255, 255)
            img.ImageTransparency = 0.22
        end
    end
    if label then
        label.TextColor3 = Color3.fromRGB(255, 255, 255)
        label.TextStrokeTransparency = 0.45
        label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    end
    if stroke then
        stroke.Color = active and Color3.fromRGB(90, 190, 255) or Color3.fromRGB(70, 90, 130)
        stroke.Thickness = active and 2 or 1.5
        stroke.Transparency = active and 0 or 0.12
    end
end


function applyFloatingButtonScale()
    for _, uiScale in ipairs(_floatingUIScales) do
        if uiScale and uiScale.Parent then
            uiScale.Scale = floatingButtonScale
        end
    end
end

function applyMobileButtonShape()
    local style = mobileButtonStyle or "Circle"
    local radius = style == "Circle" and UDim.new(1, 0)
        or (style == "Rounded" and UDim.new(0, 18) or UDim.new(0, 0))
    local function applyTo(btn)
        if not btn then return end
        local corner = btn:FindFirstChildOfClass("UICorner")
        if corner then corner.CornerRadius = radius end
        local image = btn:FindFirstChild("ButtonImage")
        if image then
            local ic = image:FindFirstChildOfClass("UICorner")
            if ic then ic.CornerRadius = radius end
        end
    end
    if MobilePanel then
        for _, child in ipairs(MobilePanel:GetChildren()) do
            if child:IsA("TextButton") then applyTo(child) end
        end
    end
    for _, uiScale in ipairs(_floatingUIScales or {}) do
        if uiScale and uiScale.Parent and uiScale.Parent:IsA("GuiButton") then
            applyTo(uiScale.Parent)
        end
    end
end


local function drag(f, dragZoneHeight)
    -- Reference drag method: record the initial pointer and frame position,
    -- then apply the pointer delta. Lock always cancels an active drag.
    local dragging, dragStart, startPos, moved = false, nil, nil, false
    local zone = dragZoneHeight or math.huge

    f.Active = true
    f.InputBegan:Connect(function(input)
        if uiLocked or _isDraggingButton then return end
        if input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch then return end

        local absPos = f.AbsolutePosition
        if input.Position.Y > absPos.Y + zone then return end

        dragging = true
        dragStart = input.Position
        startPos = f.Position
        moved = false
    end)

    UIS.InputChanged:Connect(function(input)
        if not dragging then return end
        if uiLocked then
            dragging = false
            return
        end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement
            and input.UserInputType ~= Enum.UserInputType.Touch then return end

        local delta = input.Position - dragStart
        if delta.Magnitude > 5 then moved = true end
        if moved then
            f.Position = UDim2.new(
                startPos.X.Scale, startPos.X.Offset + delta.X,
                startPos.Y.Scale, startPos.Y.Offset + delta.Y
            )
        end
    end)

    UIS.InputEnded:Connect(function(input)
        local isRelease = input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch
        if dragging and isRelease then
            dragging = false
            if moved then
                -- Persist Auto Steal bar / any dragged frame position immediately
                if f == pbFrame or (type(f.Name) == "string" and f.Name == "RivalHubAutoStealHud") then
                    savedProgressBarPos = f.Position
                end
                if _G.MoonSave and _G.MoonSave.markDirty then
                    pcall(_G.MoonSave.markDirty)
                end
            end
        end
    end)
end

_G.__RivalHubSpeedEngine = _G.__RivalHubSpeedEngine or { started = false, conn = nil }
