end)

function setupMovementAndIndicators(char)
    if steppedConn then steppedConn:Disconnect(); steppedConn = nil end
    if movementLoop then movementLoop:Disconnect(); movementLoop = nil end

    local ccAcc = 0
    steppedConn = RunService.Heartbeat:Connect(function(dt)
        ccAcc = ccAcc + dt
        if ccAcc < 0.05 then return end
        ccAcc = 0
        local plist = _GetPlayersCached()
        for i = 1, #plist do
            local p = plist[i]
            if p ~= LP then
                local ch = p.Character
                if ch then
                    local parts = ch:GetChildren()
                    for j = 1, #parts do
                        local part = parts[j]
                        if part:IsA("BasePart") and part.CanCollide then
                            part.CanCollide = false
                        end
                    end
                end
            end
        end
    end)

    local _mvUiAcc, _mvLastTxt, _mvLastCol = 0, nil, nil
    movementLoop = RunService.RenderStepped:Connect(function(_mvDt)
        local char2 = LP.Character
        if not char2 then return end
        local hum = char2:FindFirstChildOfClass("Humanoid")
        local hrp = char2:FindFirstChild("HumanoidRootPart")
        if not hum or not hrp then return end
        if not autoBatEnabled and not autoLeftEnabled and not autoRightEnabled then
            if _isRagdollState(hum) then
                lastMoveDir = _V3zero
            else
                local md = hum.MoveDirection
                if md.Magnitude > 0 then
                    lastMoveDir = md
                end
            end
        end
        _mvUiAcc = _mvUiAcc + (_mvDt or 0)
        if _mvUiAcc >= 0.1 and speedLabel and speedLabel.Parent then
            _mvUiAcc = 0
            local displaySpeed = getActiveMoveSpeed and getActiveMoveSpeed() or 0
            local theme = (getThemeColor and getThemeColor()) or Color3.fromRGB(40, 140, 255)
            local txt = "Speed: " .. string.format("%.1f", tonumber(displaySpeed) or 0)
            if txt ~= _mvLastTxt then
                _mvLastTxt = txt
                speedLabel.Text = txt
            end
            if theme ~= _mvLastCol then
                _mvLastCol = theme
                speedLabel.TextColor3 = theme
                local title = speedLabel.Parent and speedLabel.Parent:FindFirstChild("RaptureLinkLabel")
                if title then title.TextColor3 = theme end
            end
        end
    end)
    setupSpeedIndicator(char)
    startEnemySpeed()
end

function toggleLockUI(state)
    -- Lock ON  => nothing can be dragged
    -- Lock OFF => main + mobile buttons + progress bar move normally
    if state == nil then
        uiLocked = not uiLocked
    else
        uiLocked = state == true
    end
    mobileButtonsLocked = uiLocked
    if uiLocked then
        _isDraggingButton = false
    end
    if setLockUIVisual then
        pcall(setLockUIVisual, uiLocked)
    end
end

function disableAllAimbots()
    if autoBatEnabled then
        disableAutoBat()
        if autoBatSetVisual then autoBatSetVisual(false) end
        if mobSetAutoBat then mobSetAutoBat(false) end
    end
end

function stopAllBackgroundTasks()
    if movementLoop then movementLoop:Disconnect(); movementLoop = nil end
    if steppedConn then steppedConn:Disconnect(); steppedConn = nil end
    stopEnemySpeed()
    if stretchEnabled then disableStretch() end
    if stretchConn then stretchConn:Disconnect(); stretchConn = nil end
    if stretchFovConn then stretchFovConn:Disconnect(); stretchFovConn = nil end
    if AntiRagdollV1.isRunning() then AntiRagdollV1.stop() end
    if AntiRagdollV2.Enabled then stopAntiRagdollV2() end
    if antiDieEnabled then AntiDieModule.stop() end
    if antiBatEnabled then stopAntiBat() end
    if antiFlingEnabled then stopAntiFling() end
    antiVoidEnabled = false
    if _G.AmbitiousAntiVoid then pcall(_G.AmbitiousAntiVoid.setEnabled, false) end
    stopBatCounter()
    stopMedusaCounter()
    stopAutoSteal()
    disableAutoBat()
    stopAutoLeft()
    stopAutoRight()
    if _G.__RivalHubStopBatV2 then pcall(_G.__RivalHubStopBatV2) end
    if TPBatState and TPBatState.enabled and tpBatSetEnabled then pcall(tpBatSetEnabled, false) end
    if antiLagEnabled then disableAntiLag() end
    pcall(function() if _G.MoonHubAntiLag1 then _G.MoonHubAntiLag1.disable() end end)
    pcall(function() if _G.MoonHubAntiLag2 then _G.MoonHubAntiLag2.disable() end end)
    if espEnabled then toggleESP(false) end
    if espLineEnabled then stopESPLine() end
    if dropActive then stopDropBrainrot() end
    if bodyLockEnabled then stopBodyLock() end
    _blSuppressCount = 0
    _blWasEnabled = false
    if _blRestoreTimer then pcall(task.cancel, _blRestoreTimer); _blRestoreTimer = nil end
    if _bodyLockConn then _bodyLockConn:Disconnect(); _bodyLockConn = nil end
    for _, t in ipairs(dropConnections) do
        if type(t) == "thread" then pcall(task.cancel, t)
        elseif type(t) == "RBXScriptConnection" then pcall(t.Disconnect, t) end
    end
    dropConnections = {}
    dropActive = false
    alPhase = 1
    arPhase = 1
    lastDropTime = 0
    medusaDebounce = false
    medusaLastUsed = 0
    if _G.__RivalHubStopSpeedEngine then pcall(_G.__RivalHubStopSpeedEngine) end
end

