function resetFloatingPositions()
    savedButtonPositions = {}
    if MobilePanel then
        for _, btn in ipairs(MobilePanel:GetChildren()) do
            if btn:IsA("TextButton") and btn.Name then
                local defX, defY = getDefaultButtonPosition(btn.Name)
                btn.Position = UDim2.new(0, defX, 0, defY)
                -- open / default look
                if type(paintFloatingBtn) == "function" then
                    pcall(paintFloatingBtn, btn, btn:GetAttribute("MobActive") == true)
                end
            end
        end
    end
    if type(applyFloatingButtonScale) == "function" then pcall(applyFloatingButtonScale) end
    if type(applyMobileButtonShape) == "function" then pcall(applyMobileButtonShape) end
    if pbFrame then
        -- Moon Hub exact default Auto Steal bar position
        pbFrame.AnchorPoint = Vector2.new(0.5, 1)
        pbFrame.Position = UDim2.new(0.5, 0, 1, -32)
        pbFrame.Size = UDim2.new(0, 560, 0, 86)
        if not pbScale then
            pbScale = Instance.new("UIScale", pbFrame)
        end
        pbScale.Scale = (tonumber(stealBarScaleValue) or 81) / 100
        savedProgressBarPos = nil
    end
    savedMobilePanelPos = nil
end

function resetToFactoryDefaults()
    _isResetting = true
    local ok, err = pcall(function()
        stopAutoSteal()
        stopBatCounter()
        stopMedusaCounter()
        if AntiRagdollV2.Enabled then stopAntiRagdollV2() end
        if antiDieEnabled then AntiDieModule.stop() end
        if antiBatEnabled and stopAntiBat then stopAntiBat() end
        if antiFlingEnabled and stopAntiFling then stopAntiFling() end
