local LOGO_B64 = [==[]==]
local function b64decode(data)
    local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local map = {}
    for i = 1, #chars do map[string.byte(chars, i)] = i - 1 end
    local out, buf, bits = {}, 0, 0
    for i = 1, #data do
        local v = map[string.byte(data, i)]
        if v ~= nil then
            buf = buf * 64 + v
            bits += 6
            if bits >= 8 then
                bits -= 8
                out[#out + 1] = string.char(math.floor(buf / 2 ^ bits) % 256)
                buf = buf % 2 ^ bits
            end
        end
    end
    return table.concat(out)
end

local LOGO_FILE = "MoonHub_logo_v214.jpg"
local function resolveLogo()
    local ok, result = pcall(function()
        if type(getcustomasset) ~= "function" then return nil end
        if not moonLocalFileExists(LOGO_FILE) then
            if type(writefile) ~= "function" then return nil end
            writefile(LOGO_FILE, b64decode(LOGO_B64))
        end
        return getcustomasset(LOGO_FILE)
    end)
    if ok and result then return result end
    return "rbxassetid://110245528345873"
end

