        if miniBtn then miniBtn.Visible = true end
    end

    closeBtn.MouseButton1Click:Connect(hideGui)
    -- "Moon Hub" open button: tap = open menu, drag = move (position auto-saved)
    do
        local mDragging, mInput, mStart, mStartPos, mStartAbs, mMoved = false, nil, nil, nil, nil, false
        local function mIsPress(input)
            return input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch
        end
        miniBtn.InputBegan:Connect(function(input)
            if not mIsPress(input) then return end
            mDragging = true
            mInput = input
            mStart = input.Position
            mStartPos = miniBtn.Position
            mStartAbs = miniBtn.AbsolutePosition
            mMoved = false
        end)
        UIS.InputChanged:Connect(function(input)
            if not mDragging then return end
            local same
            if mInput and mInput.UserInputType == Enum.UserInputType.Touch then
                same = input == mInput
            else
                same = input.UserInputType == Enum.UserInputType.MouseMovement
            end
            if not same then return end
            local delta = input.Position - mStart
            if not mMoved and delta.Magnitude > 8 then mMoved = true end
            if mMoved then
                local cam = workspace.CurrentCamera
                local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
                local sz = miniBtn.AbsoluteSize
                local nx = math.clamp(mStartAbs.X + delta.X, -sz.X / 2, vp.X - sz.X / 2)
                local ny = math.clamp(mStartAbs.Y + delta.Y, -sz.Y / 2, vp.Y - sz.Y / 2)
                miniBtn.Position = UDim2.new(
                    mStartPos.X.Scale, mStartPos.X.Offset + (nx - mStartAbs.X),
                    mStartPos.Y.Scale, mStartPos.Y.Offset + (ny - mStartAbs.Y)
                )
            end
        end)
        UIS.InputEnded:Connect(function(input)
            if not mDragging then return end
            local same
            if mInput and mInput.UserInputType == Enum.UserInputType.Touch then
                same = input == mInput
            else
                same = input.UserInputType == Enum.UserInputType.MouseButton1
            end
            if not same then return end
            mDragging = false
            mInput = nil
            if mMoved then
                mMoved = false
                _G.__RivalHubMiniOriginalPos = miniBtn.Position
                -- save the new position immediately
                pcall(function()
                    if _G.MoonSave and _G.MoonSave.markDirty then _G.MoonSave.markDirty() end
                end)
            else
                showGui()
            end
        end)
    end


