    local function animPill(pill, dot, on)
        -- Moon Hub exact: ON blue / OFF red
        local stroke = pill:FindFirstChildOfClass("UIStroke")
        local onColor = Color3.fromRGB(0, 132, 255)
        local info = TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        TS:Create(dot, info, {
            Position = on and UDim2.new(1, -16, 0.5, -6) or UDim2.new(0, 3, 0.5, -6),
            BackgroundColor3 = on and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(18, 18, 22),
        }):Play()
        TS:Create(pill, info, {
            BackgroundColor3 = on and onColor or Color3.fromRGB(225, 55, 55),
            BackgroundTransparency = on and 0 or 0.2,
        }):Play()
        if stroke then
            TS:Create(stroke, info, {
                Color = on and Color3.fromRGB(90, 190, 255) or Color3.fromRGB(150, 30, 30),
                Transparency = on and 0.2 or 0.45,
                Thickness = on and 1.5 or 1,
            }):Play()
        end
    end

    local function mkToggle(page, txt, cb)
        local row = mkRow(page, 42)
        mkLabel(row, txt)
        local pill, dot = mkPill(row, 48)
        local on = false
        local function sv(s) on = s; animPill(pill, dot, s) end
        local clk = Instance.new("TextButton", pill)
        clk.Size = UDim2.new(1,0,1,0)
        clk.BackgroundTransparency = 1
        clk.Text = ""
        clk.AutoButtonColor = false
        clk.ZIndex = 10
        clk.MouseButton1Click:Connect(function()
            on = not on
            sv(on)
            pcall(cb, on)
            if _G.MoonSave then _G.MoonSave.markDirty() end
        end)
        if _G.MoonSave then
            local key = "T:" .. tostring(txt)
            local n = 1
            while _G.MoonSave.items[key] do n = n + 1; key = "T:" .. tostring(txt) .. "#" .. n end
            _G.MoonSave.register(key, function() return on end, function(v)
                v = v == true
                if on ~= v then
                    on = v
                    sv(v)
                    pcall(cb, v)
                end
            end, 50)
        end
        return sv
    end

