    local function mkBox(parent, default, w, xOff, cb)
        local tb = Instance.new("TextBox", parent)
        local bw = w or 50
        local xo = math.max(xOff or 56, bw + 12)
        local initialValue = tonumber(default) or 0
        local lastCommitted = initialValue
        local committing = false
        tb.Size = UDim2.new(0, bw, 0, 24)
        tb.Position = UDim2.new(1, -xo, 0.5, -12)
        tb.BackgroundColor3 = INP
        tb.BackgroundTransparency = 0.7
        tb.BorderSizePixel = 0
        tb.Text = tostring(default)
        tb.TextColor3 = WHITE
        tb.Font = Enum.Font.GothamMedium
        tb.TextSize = 11
        tb.ClearTextOnFocus = false
        tb.ZIndex = 8
        Instance.new("UICorner", tb).CornerRadius = UDim.new(0, 6)
        local bs = Instance.new("UIStroke", tb)
        bs.Color = ROW_BORDER
        bs.Thickness = 1.2
        bs.Transparency = 0.25

        local function animateStroke(color, transparency)
            pcall(function()
                TS:Create(bs, TweenInfo.new(0.12), {Color = color, Transparency = transparency}):Play()
            end)
        end
        tb.Focused:Connect(function()
            animateStroke(getThemeColor(), 0)
        end)

        local function commitBox(rawValue, silent)
            if committing then return false end
            committing = true
            local value = tonumber(rawValue)
            if not value or value ~= value or value == math.huge or value == -math.huge then
                tb.Text = tostring(lastCommitted)
                committing = false
                return false
            end
            if value == lastCommitted then
                tb.Text = tostring(lastCommitted)
                committing = false
                return true
            end

            local ok, result = true, nil
            if cb then ok, result = pcall(cb, value) end
            if not ok or result == false then
                tb.Text = tostring(lastCommitted)
                committing = false
                return false
            end

            -- Callbacks may clamp the value and update the TextBox themselves.
            local displayed = tonumber(tb.Text)
            if not displayed or displayed ~= displayed or displayed == math.huge or displayed == -math.huge then
                displayed = value
                tb.Text = tostring(displayed)
            end
            lastCommitted = displayed
            if not silent and _G.MoonSave and type(_G.MoonSave.markDirty) == "function" then
                pcall(_G.MoonSave.markDirty)
            end
            committing = false
            return true
        end

        tb.FocusLost:Connect(function()
            animateStroke(ROW_BORDER, 0.25)
            commitBox(tb.Text, false)
        end)

        if _G.MoonSave then
            local lbl = parent:FindFirstChildWhichIsA("TextLabel")
            local key = "B:" .. (lbl and lbl.Text or tostring(default))
            local n = 1
            while _G.MoonSave.items[key] do
                n = n + 1
                key = "B:" .. (lbl and lbl.Text or "Box") .. "#" .. n
            end
            _G.MoonSave.register(key, function()
                return lastCommitted
            end, function(v)
                local restored = tonumber(v)
                if not restored or restored ~= restored or restored == math.huge or restored == -math.huge then return end
                tb.Text = tostring(restored)
                commitBox(restored, true)
            end, 10)
        end
        return tb
    end

    -- Moon Hub style keybinds: click -> Press... -> press key (works reliably)
    KeySys = KeySys or {
        listenId = nil,
        listenStarted = 0,
        buttons = {},
        entries = {},
        listenConn = nil,
    }

    local function keyNameFromEntry(entry)
        if not entry then return "None" end
        if entry.kb == "MB3" then return "MB3" end
        if entry.gp then
            return (tostring(entry.gp):gsub("Enum.KeyCode.", ""):gsub("Button", "BTN "):gsub("DPad", "DPad "))
        end
        if entry.kb then
            return tostring(entry.kb):gsub("Enum.KeyCode.", "")
        end
        return "None"
    end

    local function refreshKeybindButton(keyId)
        local btn = KeySys.buttons[keyId]
        if not btn then return end
        if KeySys.listenId == keyId then
            btn.Text = "Press..."
            btn.TextColor3 = WHITE
            btn.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
            btn.BackgroundTransparency = 0.18
        else
            local bound = type(_G.RivalBindMap)=="table" and _G.RivalBindMap[keyId] or nil
            if bound ~= nil then
                if type(KB[keyId]) ~= "table" then KB[keyId] = { kb = nil, gp = nil } end
                if bound == "MB3" then KB[keyId].kb = "MB3"; KB[keyId].gp = nil
                else KB[keyId].kb = bound; KB[keyId].gp = nil end
                KeySys.entries[keyId] = KB[keyId]
                btn.Text = keyNameFromEntry(KB[keyId])
            else
                local entry = KB[keyId] or KeySys.entries[keyId]
                btn.Text = keyNameFromEntry(entry)
            end
            btn.TextColor3 = WHITE
        end
    end

    local function refreshAllKeybindButtons()
        for keyId in pairs(KeySys.buttons) do
            refreshKeybindButton(keyId)
        end
    end
    KeySys.refreshAll = refreshAllKeybindButtons
    _G.RivalHubRefreshKeybinds = refreshAllKeybindButtons

    local function stopListening()
        KeySys.listenId = nil
        _anyKeyListening = false
        _G.RivalHubKeySysListenId = nil
        if KeySys.listenConn then
            pcall(function() KeySys.listenConn:Disconnect() end)
            KeySys.listenConn = nil
        end
        refreshAllKeybindButtons()
    end

    local function clearDuplicateBinds(targetId, isGp, code)
        for id, entry in pairs(KB) do
            if id ~= targetId and type(entry) == "table" then
                if isGp then
                    if entry.gp == code then entry.gp = nil end
                else
                    if entry.kb == code then entry.kb = nil end
                end
            end
        end
    end

        local function beginListen(keyId)
        -- Instant arm: no debounce, refresh only this button
        if type(KB[keyId]) ~= "table" then KB[keyId] = { kb = nil, gp = nil } end
        -- switch target without full stopListening (avoids lag)
        if type(KeySys) == "table" then
            local prev = KeySys.listenId
            KeySys.entries[keyId] = KB[keyId]
            KeySys.listenId = keyId
            KeySys.listenStarted = tick()
            if prev and prev ~= keyId and KeySys.buttons[prev] then
                pcall(refreshKeybindButton, prev)
            end
        end
        _anyKeyListening = true
        _G.RivalHubKeySysListenId = keyId
        _G.RivalHubListenStarted = tick()
        -- Press... text only — no color change
        local btn = KeySys.buttons and KeySys.buttons[keyId]
        if btn then
            btn.Text = "Press..."
            btn.TextColor3 = WHITE
            btn.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
            btn.BackgroundTransparency = 0.18
        end
    end

    local function addKeybindProp(page, labelText, kbEntry, keyId)
        keyId = keyId or labelText
        if type(kbEntry) ~= "table" then
            kbEntry = { kb = nil, gp = nil }
            KB[keyId] = kbEntry
        end
        local row = mkRow(page, 40)
        mkLabel(row, labelText)

        local clearBtn = Instance.new("TextButton", row)
        clearBtn.Size = UDim2.new(0, 22, 0, 24)
        clearBtn.Position = UDim2.new(1, -110, 0.5, -12)
        clearBtn.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
        clearBtn.BackgroundTransparency = 0.18
        clearBtn.BorderSizePixel = 0
        clearBtn.Text = "×"
        clearBtn.TextColor3 = WHITE
        clearBtn.Font = Enum.Font.GothamBlack
        clearBtn.TextSize = 14
        clearBtn.ZIndex = 9
        clearBtn.AutoButtonColor = false
        Instance.new("UICorner", clearBtn).CornerRadius = UDim.new(0, 7)

        local btn = Instance.new("TextButton", row)
        btn.Size = UDim2.new(0, 72, 0, 24)
        btn.Position = UDim2.new(1, -84, 0.5, -12)
        btn.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
        btn.BackgroundTransparency = 0.18
        btn.BorderSizePixel = 0
        btn.Text = keyNameFromEntry(kbEntry)
        btn.TextColor3 = WHITE
        btn.Font = Enum.Font.GothamSemibold
        btn.TextSize = 11
        btn.ZIndex = 9
        btn.AutoButtonColor = false
        Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 7)

        KeySys.buttons[keyId] = btn
        KeySys.entries[keyId] = kbEntry
        KB[keyId] = kbEntry

        local function doBegin()
            beginListen(keyId)
        end
        btn.MouseButton1Click:Connect(doBegin)
        local function doClear()
            kbEntry.kb = nil
            kbEntry.gp = nil
            if type(_G.RivalBindMap) == "table" then _G.RivalBindMap[keyId] = nil end
            if type(KB) == "table" then KB[keyId] = kbEntry end
            if type(stopListening) == "function" then stopListening() end
            if type(refreshAllKeybindButtons) == "function" then refreshAllKeybindButtons() end
        end
        clearBtn.MouseButton1Click:Connect(doClear)

        table.insert(keyButtonRefs, {btn = btn, entry = kbEntry, keyId = keyId})
        return btn
    end

    local speedPage = contentPages["Speed"]

    mkSect(speedPage, "Movement Speeds")
    do local row = mkRow(speedPage, 42); mkLabel(row, "Normal Speed"); normalBox = mkBox(row, NS, 50, 56, function(v) if v == v and v > 0 and v < math.huge then NS = v; if _G.__RivalHubApplySpeedNow then pcall(_G.__RivalHubApplySpeedNow) end else return false end end) end
    do local row = mkRow(speedPage, 42); mkLabel(row, "Carry Speed"); carryBox = mkBox(row, CS, 50, 56, function(v) if v == v and v > 0 and v < math.huge then CS = v; if _G.__RivalHubApplySpeedNow then pcall(_G.__RivalHubApplySpeedNow) end else return false end end) end
    do local row = mkRow(speedPage, 42); mkLabel(row, "Lagger Normal Speed"); laggerBox = mkBox(row, LAGGER_SPEED, 50, 56, function(v) if v == v and v > 0 and v < math.huge then LAGGER_SPEED = v; if _G.__RivalHubApplySpeedNow then pcall(_G.__RivalHubApplySpeedNow) end else return false end end) end
    do local row = mkRow(speedPage, 42); mkLabel(row, "Lagger Carry Speed"); lagger2Box = mkBox(row, LAGGER_CARRY_SPEED, 50, 56, function(v) if v == v and v > 0 and v < math.huge then LAGGER_CARRY_SPEED = v; if _G.__RivalHubApplySpeedNow then pcall(_G.__RivalHubApplySpeedNow) end else return false end end) end

    _G.RivalAutoCarrySetVisual = mkToggle(speedPage, "Auto Carry Speed", function(on)
        setAutoCarry(on == true)
    end)

    -- Auto Carry always uses NORMAL mode; the mode selector was removed.
        autoCarryMode = "NORMAL"

    -- ============================================================
    -- SPIN (fixed ordinary rotation) + Anti Die lock
    -- While Spin is ON (manual) OR Auto Spin On Carry is actively spinning
    -- (holding a brainrot): Anti Die is forced ON and locked (cannot be
    -- switched off). When both Spin and active Auto-carry spin are OFF,
    -- Anti Die unlocks and follows the manual switch again.
    -- ============================================================
    mkSect(speedPage, "Spin")
    do
        local old = _G.MoonSpin
        if type(old) == "table" then
            old.alive = false
            if old.conn then pcall(function() old.conn:Disconnect() end) end
        end
        -- One fixed spin behavior: the old Normal/Root mode selector is removed.
        local SP = { enabled = false, userWanted = false, carryLock = false, antiDieCarryLock = false, speed = 360, autoCarry = true, alive = true, wasAutoBat = false, pauseForAutoBat = false, lastCharacter = LP.Character }
        _G.MoonSpin = SP
        local MIN_S, MAX_S = 1, 10000000000
        local setSpinVisual, speedBox, setAutoVisual

        local function getHR()
            local c = LP.Character
            return c and c:FindFirstChildOfClass("Humanoid"), c and c:FindFirstChild("HumanoidRootPart")
        end
        local function clearAngular(root)
            if not root then return end
            local actuator = root:FindFirstChild("MoonRootSpin")
            if actuator then pcall(function() actuator:Destroy() end) end
            pcall(function() root.AssemblyAngularVelocity = Vector3.zero end)
        end
        local function applySpinAngularVelocity(root)
            if not root then return end
            local actuator = root:FindFirstChild("MoonRootSpin")
            if not actuator or not actuator:IsA("BodyAngularVelocity") then
                if actuator then pcall(function() actuator:Destroy() end) end
                actuator = Instance.new("BodyAngularVelocity")
                actuator.Name = "MoonRootSpin"
                actuator.P = 3000
                actuator.MaxTorque = Vector3.new(0, math.huge, 0)
                actuator.Parent = root
            end
            actuator.AngularVelocity = Vector3.new(0, math.rad(SP.speed), 0)
        end
        local function stopLoop()
            if SP.conn then SP.conn:Disconnect(); SP.conn = nil end
            local h, r = getHR()
            clearAngular(r)
            if h then pcall(function() h.AutoRotate = true end) end
        end
        local function startLoop()
            if SP.conn then return end
            SP.conn = RunService.Stepped:Connect(function(_, dt)
                if not SP.enabled or not SP.alive then return end
                local h, r = getHR()
                if not h or not r or h.Health <= 0 then return end

                -- Pause the ordinary spin while Auto Bat is running. A character
                -- reset releases the pause even if Auto Bat was still marked active.
                local currentCharacter = LP.Character
                local characterChanged = currentCharacter ~= SP.lastCharacter
                if characterChanged then
                    SP.lastCharacter = currentCharacter
                    SP.pauseForAutoBat = false
                    SP.wasAutoBat = (autoBatEnabled == true)
                end
                local autoBatNow = (autoBatEnabled == true)
                if autoBatNow and not SP.wasAutoBat then
                    SP.pauseForAutoBat = true
                elseif not autoBatNow then
                    SP.pauseForAutoBat = false
                end
                SP.wasAutoBat = autoBatNow
                if SP.pauseForAutoBat then
                    clearAngular(r)
                    h.AutoRotate = true
                    return
                end

                -- Shift Lock and Spin both want to control yaw. When Shift Lock
                -- is active, let Spin own yaw for this short interval so Roblox
                -- AutoRotate cannot cancel the angular actuator. Mouse-lock/camera
                -- mode stays active; when Spin stops, AutoRotate is restored.
                local shiftLockActive = false
                pcall(function()
                    shiftLockActive = UserSettings():GetService("UserGameSettings").RotationType
                        == Enum.RotationType.CameraRelative
                end)
                local desiredAutoRotate = not shiftLockActive
                if h.AutoRotate ~= desiredAutoRotate then h.AutoRotate = desiredAutoRotate end
                applySpinAngularVelocity(r)
            end)
        end
        -- Anti Die is forced ON + locked while Spin (manual) OR Auto Spin On Carry
        -- is active (or currently carry-locked). User cannot turn Anti Die off until
        -- both Spin and Auto Spin On Carry are off (and no active carry lock).
        local function syncSpinAntiDie()
            -- Force + lock Anti Die only while Spin is actually running:
            -- manual Spin ON, or Auto Spin On Carry currently active (holding).
            local force = (SP.userWanted == true) or (SP.carryLock == true)
            SP.antiDieCarryLock = force
            pcall(_G.__CrystalAntiDieSource, "spin", force)
            if setAntiDieVisual then
                local show = force
                    or (_antiDieSources and (_antiDieSources.toggle == true or _antiDieSources.carry == true or _antiDieSources.autobat == true))
                pcall(setAntiDieVisual, show)
            end
            if _G.MoonSave and _G.MoonSave.markDirty then
                pcall(_G.MoonSave.markDirty)
            end
        end
        SP.syncSpinAntiDie = syncSpinAntiDie

        local function apply()
            local want = (SP.userWanted or SP.carryLock) == true
            SP.enabled = want
            if want then
                local _, r = getHR(); clearAngular(r)
                startLoop()
            else
                stopLoop()
            end
            if setSpinVisual then pcall(setSpinVisual, want) end
            syncSpinAntiDie()
        end
        SP.apply = apply

        setSpinVisual = mkToggle(speedPage, "Spin", function(on)
            if SP.carryLock and not on then
                task.defer(function() if setSpinVisual then pcall(setSpinVisual, true) end end)
                return
            end
            SP.userWanted = on == true
            apply()
            if _G.MoonSave then _G.MoonSave.markDirty() end
        end)

        do
            local row = mkRow(speedPage, 42); mkLabel(row, "Spin Speed")
            speedBox = mkBox(row, SP.speed, 70, 78, function(v)
                if v == v and v >= MIN_S and v <= MAX_S then
                    SP.speed = v
                    if _G.MoonSave then _G.MoonSave.markDirty() end
                else
                    return false
                end
            end)
        end
        setAutoVisual = mkToggle(speedPage, "Auto Spin On Carry", function(on)
            SP.autoCarry = on == true
            -- if Auto turns off while not holding, release carryLock; apply syncs Anti Die
            if not SP.autoCarry then
                SP.carryLock = false
            end
            apply()
            if _G.MoonSave then _G.MoonSave.markDirty() end
        end)
        if setAutoVisual then setAutoVisual(true) end

        -- auto save / reset (defaults: Spin OFF, fixed ordinary spin, 360, Auto ON)
        if _G.MoonSave then
            local MSv = _G.MoonSave
            MSv.register("T:Spin", function() return SP.userWanted == true end, function(v)
                SP.userWanted = v == true
                apply()
            end, 50)
            MSv.register("V:Spin Speed", function() return SP.speed end, function(v)
                v = tonumber(v)
                if v and v == v and v >= MIN_S and v <= MAX_S then
                    SP.speed = v
                    if speedBox then speedBox.Text = tostring(v) end
                end
            end, 20)
            MSv.register("T:Auto Spin On Carry", function() return SP.autoCarry == true end, function(v)
                SP.autoCarry = v == true
                if setAutoVisual then setAutoVisual(SP.autoCarry) end
                if not SP.autoCarry then SP.carryLock = false end
                apply()
            end, 50)
        end

        -- While holding a brainrot + Auto Spin On Carry: force spin (carryLock).
        -- Anti Die lock follows Spin OR Auto (via syncSpinAntiDie), not hold alone.
        task.spawn(function()
            local wasAutoSpinCarry = false
            while SP.alive and _G.MoonSpin == SP do
                task.wait(0.1)
                local holding = false
                local ok, a = pcall(_G.MoonIsHoldingBrainrot)
                local ok2, b = pcall(_autoCarryDetectHold)
                holding = (ok and a == true) or (ok2 and b == true)

                local autoSpinCarry = holding and SP.autoCarry
                if autoSpinCarry ~= wasAutoSpinCarry then
                    wasAutoSpinCarry = autoSpinCarry
                    SP.carryLock = autoSpinCarry
                    apply()
                else
                    -- still refresh Anti Die lock if user toggled Spin/Auto mid-hold
                    syncSpinAntiDie()
                end
            end
            SP.carryLock = false
            SP.antiDieCarryLock = false
            pcall(_G.__CrystalAntiDieSource, "spin", false)
            pcall(_G.__CrystalAntiDieSource, "carry", false)
        end)

        -- Apply initial Anti Die lock (only if Spin is already ON / carry-locked)
        task.defer(function()
            syncSpinAntiDie()
        end)
    end


    local combatPage = contentPages["Custom"]

    infJumpSetVisual = mkToggle(combatPage, "Infinite Jump", function(on)
        InfiniteJump.setMode("hold")
        if on then InfiniteJump.start() else InfiniteJump.stop() end
    end)

    -- Moon Hub style: normal ON/OFF switch + arrow that opens a V1 / V2 selector.
    -- Switch ON starts the engine picked in the selector (default V2); OFF stops it.
    do
        local ACTIVE = Color3.fromRGB(0, 132, 255)
        local arChoice = (antiRagdollMode == "v1") and "v1" or "v2"
        local expanded = false

        local arToggleSet
        arToggleSet = mkToggle(combatPage, "Anti Ragdoll", function(on)
            setAntiRagdollMode(on and arChoice or "off")
