        end
        local btnV1 = mkModeBtn("V1", 0)
        local btnV2 = mkModeBtn("V2", 0.5)

        local function selectorVisual(choice)
            local isV2 = (choice ~= "v1")
            TS:Create(slide, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Position = isV2 and UDim2.new(0.5, 4, 0, 5) or UDim2.new(0, 4, 0, 5),
            }):Play()
            TS:Create(btnV1, TweenInfo.new(0.14), { TextTransparency = isV2 and 0.5 or 0 }):Play()
            TS:Create(btnV2, TweenInfo.new(0.14), { TextTransparency = isV2 and 0 or 0.5 }):Play()
        end

        if arRow then
            local arrow = Instance.new("TextButton", arRow)
            arrow.Name = "ModeArrow"
            arrow.Size = UDim2.new(0, 26, 0, 24)
            arrow.Position = UDim2.new(1, -104, 0.5, -12)
            arrow.BackgroundColor3 = Color3.fromRGB(15, 15, 15)
            arrow.BackgroundTransparency = 0.18
            arrow.BorderSizePixel = 0
            arrow.Text = "▼"
            arrow.TextColor3 = Color3.fromRGB(255, 255, 255)
            arrow.Font = Enum.Font.GothamBold
            arrow.TextSize = 11
            arrow.AutoButtonColor = false
            arrow.ZIndex = 10
            Instance.new("UICorner", arrow).CornerRadius = UDim.new(0, 7)
            local arrowStroke = Instance.new("UIStroke", arrow)
            arrowStroke.Color = Color3.fromRGB(50, 50, 50)
            arrowStroke.Transparency = 0.5

            local function setExpanded(v)
                expanded = v
                arrow.Text = v and "▲" or "▼"
                if v then
                    holder.Visible = true
                    TS:Create(holder, TweenInfo.new(0.16), { Size = UDim2.new(1, -4, 0, 42) }):Play()
                else
                    local t = TS:Create(holder, TweenInfo.new(0.16), { Size = UDim2.new(1, -4, 0, 0) })
                    t.Completed:Connect(function() if not expanded then holder.Visible = false end end)
                    t:Play()
                end
            end
            arrow.MouseButton1Click:Connect(function() setExpanded(not expanded) end)
        end

        -- picking V1 / V2: switches the running engine live if the switch is ON, otherwise just remembers it
        local function applyChoice(choice)
            arChoice = (choice == "v1") and "v1" or "v2"
            selectorVisual(arChoice)
            if antiRagdollMode ~= "off" then setAntiRagdollMode(arChoice) end
        end
        btnV1.MouseButton1Click:Connect(function() applyChoice("v1") end)
        btnV2.MouseButton1Click:Connect(function() applyChoice("v2") end)
        if _G.MoonSave then
            _G.MoonSave.register("V:Anti Ragdoll Mode", function() return arChoice end, function(v)
                if v == "v1" or v == "v2" then applyChoice(v) end
            end, 20)
        end

        slide.Position = (arChoice == "v1") and UDim2.new(0, 4, 0, 5) or UDim2.new(0.5, 4, 0, 5)
        btnV1.TextTransparency = (arChoice == "v1") and 0 or 0.5
        btnV2.TextTransparency = (arChoice == "v1") and 0.5 or 0

        -- called by setAntiRagdollMode / config load / reset: keeps switch + selector in sync
        _G.updateAntiRagdollUI = function(mode)
            if mode == "v1" or mode == "v2" then
                arChoice = mode
                selectorVisual(mode)
                arToggleSet(true)
            else
                arToggleSet(false)
            end
        end
        _G.updateAntiRagdollUI(antiRagdollMode)
        setAntiRagVisual = function(on)
