            return
        end
        antiDieEnabled = on
        if on then AntiDieModule.start() else AntiDieModule.stop() end
        if _G.MoonSave then _G.MoonSave.markDirty() end
    end)
    if setAntiDieVisual then setAntiDieVisual(antiDieEnabled) end
    if _G.MoonSave then
        -- save only the manual switch (never the forced Spin/Auto lock)
        _G.MoonSave.register("T:Anti Die", function() return _antiDieSources.toggle == true end, function(v)
            v = v == true
            if v then AntiDieModule.start() else AntiDieModule.stop() end
            local forced = _G.MoonSpin and _G.MoonSpin.antiDieCarryLock == true
            if setAntiDieVisual then
                pcall(setAntiDieVisual, v or forced or (_antiDieSources.carry == true) or (_antiDieSources.spin == true))
            end
        end, 50)
    end

    setAntiBatVisual = mkToggle(combatPage, "Anti Bat", function(on)
        if on then startAntiBat() else stopAntiBat() end
    end)
    bodyLockSetVisual = mkToggle(combatPage, "Body Lock", function(on)
        bodyLockEnabled = on
        if on then
            if _blSuppressCount == 0 then startBodyLock() end
        else
            stopBodyLock()
        end
    end)
    do
        local row = mkRow(combatPage, 42)
        mkLabel(row, "Body Lock")
        bodyLockRangeBox = mkBox(row, bodyLockRange, 50, 56, function(v)
            if v and v > 0 then
                bodyLockRange = _clamp(_floor(v), 5, 200)
                if bodyLockRangeBox then bodyLockRangeBox.Text = tostring(bodyLockRange) end
            end
        end)
    end

    setBatCounterVisual = mkToggle(combatPage, "Bat Counter", function(on)
        batCounterEnabled = on
        if on then startBatCounter() else stopBatCounter() end
    end)

    -- Bat Counter modes (arrow): 1=bat only, 2=medusa only, 3=bat or medusa
    do
        local ACTIVE = Color3.fromRGB(0, 132, 255)
        local bcMode = tonumber(batCounterMode) or 3
        if bcMode < 1 or bcMode > 3 then bcMode = 3 end
        batCounterMode = bcMode
        local expanded = false

        local bcRow
        for _, ch in ipairs(combatPage:GetChildren()) do
            if ch:IsA("Frame") and ch.LayoutOrder == pageCounters[combatPage] then
                bcRow = ch
            end
        end

        local holder = Instance.new("Frame", combatPage)
        holder.Name = "Bat Counter Mode Selector"
        holder.Size = UDim2.new(1, -4, 0, 0)
        holder.BackgroundColor3 = Color3.fromRGB(10, 10, 10)
        holder.BackgroundTransparency = 0.7
        holder.BorderSizePixel = 0
        holder.LayoutOrder = getNextOrder(combatPage)
        holder.ClipsDescendants = true
        holder.Visible = false
        holder.ZIndex = 7
        Instance.new("UICorner", holder).CornerRadius = UDim.new(0, 10)
        local holderStroke = Instance.new("UIStroke", holder)
        holderStroke.Color = Color3.fromRGB(50, 50, 50)
        holderStroke.Transparency = 0.5

        local slide = Instance.new("Frame", holder)
        slide.Name = "SelectedSlide"
        slide.Size = UDim2.new(1/3, -8, 1, -10)
        slide.BackgroundColor3 = ACTIVE
        slide.BackgroundTransparency = 0.1
        slide.BorderSizePixel = 0
        slide.ZIndex = 8
        Instance.new("UICorner", slide).CornerRadius = UDim.new(0, 8)

        local function mkModeBtn(text, xScale)
            local b = Instance.new("TextButton", holder)
            b.Name = text .. "Btn"
            b.Size = UDim2.new(1/3, 0, 1, 0)
            b.Position = UDim2.new(xScale, 0, 0, 0)
            b.BackgroundTransparency = 1
            b.Text = text
            b.TextColor3 = Color3.fromRGB(255, 255, 255)
            b.Font = Enum.Font.GothamBlack
            b.TextSize = 12
            b.AutoButtonColor = false
            b.ZIndex = 10
            return b
        end
        local btn1 = mkModeBtn("Bat", 0)
        local btn2 = mkModeBtn("Medusa", 1/3)
        local btn3 = mkModeBtn("Two", 2/3)

        local function selectorVisual(mode)
            mode = tonumber(mode) or 3
            if mode < 1 or mode > 3 then mode = 3 end
            local x = (mode - 1) / 3
            TS:Create(slide, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Position = UDim2.new(x, 4, 0, 5),
            }):Play()
            for i, b in ipairs({btn1, btn2, btn3}) do
                TS:Create(b, TweenInfo.new(0.14), {
                    TextTransparency = (i == mode) and 0 or 0.5
                }):Play()
            end
        end

        if bcRow then
            local arrow = Instance.new("TextButton", bcRow)
            arrow.Name = "ModeArrow"
            arrow.Size = UDim2.new(0, 26, 0, 24)
            arrow.Position = UDim2.new(1, -104, 0.5, -12)
            arrow.BackgroundColor3 = Color3.fromRGB(15, 15, 15)
            arrow.BackgroundTransparency = 0.18
            arrow.BorderSizePixel = 0
            arrow.Text = "▼"
            arrow.TextColor3 = Color3.fromRGB(255, 255, 255)
            arrow.Font = Enum.Font.GothamBold
            arrow.TextSize = 11
            arrow.AutoButtonColor = false
            arrow.ZIndex = 10
            Instance.new("UICorner", arrow).CornerRadius = UDim.new(0, 7)
            local arrowStroke = Instance.new("UIStroke", arrow)
            arrowStroke.Color = Color3.fromRGB(50, 50, 50)
            arrowStroke.Transparency = 0.5

            local function setExpanded(v)
                expanded = v
                arrow.Text = v and "▲" or "▼"
                if v then
                    holder.Visible = true
                    TS:Create(holder, TweenInfo.new(0.16), { Size = UDim2.new(1, -4, 0, 42) }):Play()
                else
                    local tw = TS:Create(holder, TweenInfo.new(0.16), { Size = UDim2.new(1, -4, 0, 0) })
                    tw.Completed:Connect(function() if not expanded then holder.Visible = false end end)
                    tw:Play()
                end
            end
            arrow.MouseButton1Click:Connect(function() setExpanded(not expanded) end)
        end

        local function applyChoice(mode)
            mode = tonumber(mode) or 3
            if mode < 1 or mode > 3 then mode = 3 end
            batCounterMode = mode
            _G.batCounterMode = mode
            selectorVisual(mode)
            if type(scheduleRivalHubSave) == "function" then
                pcall(scheduleRivalHubSave)
            elseif _G.MoonSave and _G.MoonSave.markDirty then
                pcall(_G.MoonSave.markDirty)
            end
        end
        btn1.MouseButton1Click:Connect(function() applyChoice(1) end)
        btn2.MouseButton1Click:Connect(function() applyChoice(2) end)
        btn3.MouseButton1Click:Connect(function() applyChoice(3) end)

        if _G.MoonSave then
            _G.MoonSave.register("V:Bat Counter Mode", function()
                return tonumber(batCounterMode) or 3
            end, function(v)
                local n = tonumber(v) or 3
                if n < 1 or n > 3 then n = 3 end
                applyChoice(n)
            end, 20)
        end

        slide.Position = UDim2.new((bcMode - 1) / 3, 4, 0, 5)
        btn1.TextTransparency = (bcMode == 1) and 0 or 0.5
        btn2.TextTransparency = (bcMode == 2) and 0 or 0.5
        btn3.TextTransparency = (bcMode == 3) and 0 or 0.5
    end

    setMedusaVisual = mkToggle(combatPage, "Medusa Counter", function(on)
        medusaCounterEnabled = on
        if on then
            if LP.Character then setupMedusaCounter(LP.Character) else stopMedusaCounter() end
        else
            stopMedusaCounter()
        end
        if setMedusaVisual then setMedusaVisual(on) end
    end)

    -- Auto Steal last in Custom (like Moon Hub)
    setInstaGrab = mkToggle(combatPage, "Auto Steal", function(on)
        CONFIG.AUTO_STEAL_ENABLED = on == true
        if on then
            pcall(startAutoSteal)
        else
            pcall(stopAutoSteal)
        end
        updateProgressBarVisibility()
    end)

    -- Auto Steal Mode: V1 = Moon, V2 = Violette, V3 = Rival (stop 75%)
    do
        local row = mkRow(combatPage, 42)
        mkLabel(row, "Auto Steal Mode")
        local WHITE = Color3.fromRGB(255, 255, 255)
        local carousel = Instance.new("Frame", row)
        carousel.Size = UDim2.new(0, 124, 0, 28)
        carousel.Position = UDim2.new(1, -132, 0.5, -14)
        carousel.BackgroundColor3 = Color3.fromRGB(22, 24, 30)
        carousel.BorderSizePixel = 0
        carousel.ZIndex = 8
        Instance.new("UICorner", carousel).CornerRadius = UDim.new(1, 0)
        local cStroke = Instance.new("UIStroke", carousel)
        cStroke.Color = Color3.fromRGB(0, 145, 255)
        cStroke.Thickness = 1
        cStroke.Transparency = 0.35
        local modeBtn = Instance.new("TextLabel", carousel)
        modeBtn.Size = UDim2.new(1, -58, 1, 0)
        modeBtn.Position = UDim2.new(0, 29, 0, 0)
        modeBtn.BackgroundTransparency = 1
        modeBtn.Text = tostring(autoStealMode or "V1")
        modeBtn.TextColor3 = WHITE
        modeBtn.Font = Enum.Font.GothamBold
        modeBtn.TextSize = 11
        modeBtn.ZIndex = 9
        autoStealModeBtn = modeBtn
        local function applyMode(newMode)
            if newMode ~= "V1" and newMode ~= "V2" and newMode ~= "V3" then return end
            autoStealMode = newMode
            _G.MoonHubAutoStealMode = autoStealMode
            modeBtn.Text = autoStealMode
            isStealing = false
            pcall(syncAutoStealRadiusUI)
            Steal.StealRadius = getAutoStealRadius()
            if CONFIG.AUTO_STEAL_ENABLED then
                pcall(stopAutoSteal)
                pcall(startAutoSteal)
            end
            if type(updateStealProgress) == "function" then pcall(updateStealProgress, 0, "READY") end
            if type(scheduleRivalHubSave) == "function" then pcall(scheduleRivalHubSave)
            elseif _G.MoonSave and _G.MoonSave.markDirty then pcall(_G.MoonSave.markDirty) end
        end
        local function mkArrow(glyph, x)
            local btn = Instance.new("TextButton", carousel)
            btn.Size = UDim2.new(0, 25, 1, -4)
            btn.Position = UDim2.new(0, x, 0, 2)
            btn.BackgroundColor3 = Color3.fromRGB(28, 31, 40)
            btn.BackgroundTransparency = 0.12
            btn.BorderSizePixel = 0
            btn.Text = glyph
            btn.TextColor3 = Color3.fromRGB(0, 145, 255)
            btn.Font = Enum.Font.GothamBold
            btn.TextSize = 18
            btn.AutoButtonColor = false
            btn.ZIndex = 10
            Instance.new("UICorner", btn).CornerRadius = UDim.new(1, 0)
            btn.Activated:Connect(function()
                do local o={V1="V2",V2="V3",V3="V1"}; applyMode(o[autoStealMode] or "V1") end
            end)
            return btn
        end
        mkArrow("‹", 2)
        mkArrow("›", 97)
        _G._rivalHubStealModeSetter = function(m)
            if m == "V1" or m == "V2" or m == "V3" then applyMode(m) end
        end
        if _G.MoonSave then
            _G.MoonSave.register("V:Auto Steal Mode", function() return autoStealMode end, function(v)
                if (v == "V1" or v == "V2" or v == "V3") and v ~= autoStealMode then applyMode(v) end
            end, 20)
        end
    end

    do
        local row = mkRow(combatPage, 42)
        autoStealRadiusRow = row
        mkLabel(row, "Steal Radius")
        radInput = mkBox(row, CONFIG.STEAL_RANGE or 61, 50, 56, function(v)
            -- Radius editable only on Auto Steal V2
            if autoStealMode == "V1" then
                if radInput then radInput.Text = tostring(AUTO_STEAL_V1_RADIUS) end
                Steal.StealRadius = AUTO_STEAL_V1_RADIUS
                return
            end
            local n = tonumber(v)
            if n and n >= 5 and n <= 300 then
                CONFIG.STEAL_RANGE = _floor(n + 0.5)
                Steal.StealRadius = CONFIG.STEAL_RANGE
                if radInput then radInput.Text = tostring(CONFIG.STEAL_RANGE) end
                if type(scheduleRivalHubSave) == "function" then pcall(scheduleRivalHubSave)
                elseif _G.MoonSave and _G.MoonSave.markDirty then pcall(_G.MoonSave.markDirty) end
            end
        end)
        -- initial visibility: V1 hides radius, V2 shows it
        pcall(syncAutoStealRadiusUI)
        if _G.MoonSave and not _G.MoonSave.items["N:Steal Radius"] then
            _G.MoonSave.register("N:Steal Radius", function()
                return tonumber(CONFIG and CONFIG.STEAL_RANGE) or 61
            end, function(v)
                local n = tonumber(v)
                if n and n >= 5 and n <= 300 then
                    CONFIG.STEAL_RANGE = _floor(n + 0.5)
                    if autoStealMode == "V2" or autoStealMode == "V3" then
                        Steal.StealRadius = CONFIG.STEAL_RANGE
                        if radInput then radInput.Text = tostring(CONFIG.STEAL_RANGE) end
                    end
                end
            end, 25)
        end
    end

    -- Aimbot (last item of the Custom tab): which Bypass aimbot the AIMBOT button uses when the enemy has Anti Bat
    do
        local row = mkRow(combatPage, 42)
        mkLabel(row, "Bypass Aimbot")
        local function mkArrowPick(parent, width, getText, onStep)
            local box = Instance.new("Frame", parent)
            box.Size = UDim2.new(0, width, 1, 0)
            box.Position = UDim2.new(1, -(width + 8), 0, 0)
            box.BackgroundTransparency = 1
            box.ZIndex = 8
            local lbl = Instance.new("TextLabel", box)
            lbl.Size = UDim2.new(1, -60, 0, 26)
            lbl.Position = UDim2.new(0, 30, 0.5, -13)
            lbl.BackgroundTransparency = 1
            lbl.Text = getText()
            lbl.TextColor3 = WHITE
            lbl.Font = Enum.Font.GothamBold
            lbl.TextSize = 11
            lbl.ZIndex = 9
            local function mk(glyph, x, dir)
                local b = Instance.new("TextButton", box)
                b.Size = UDim2.new(0, 28, 0, 26)
                b.Position = UDim2.new(0, x, 0.5, -13)
                b.BackgroundColor3 = INP
                b.BackgroundTransparency = 0.7
                b.BorderSizePixel = 0
                b.Text = glyph
                b.TextColor3 = WHITE
                b.Font = Enum.Font.GothamBold
                b.TextSize = 13
                b.AutoButtonColor = false
                b.ZIndex = 9
                Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
                b.Activated:Connect(function()
                    onStep(dir)
                    lbl.Text = getText()
                end)
            end
            mk("<", 0, -1)
            mk(">", width - 28, 1)
            return lbl
        end
        do local bv = tonumber(_G.RivalAimbotBypassVersion) or 1; if bv < 1 or bv > 4 then bv = 1 end; _G.RivalAimbotBypassVersion = bv end
_G.RivalAimbotNormalVersion = (tonumber(_G.RivalAimbotNormalVersion) == 2) and 2 or 1
        _G.MoonSaveRefs.bypassLbl = mkArrowPick(row, 100, function()
            local bv = tonumber(_G.RivalAimbotBypassVersion) or 1
            if bv == 4 then return "v4" elseif bv == 3 then return "v3" elseif bv == 2 then return "v2" else return "v1" end
        end, function(dir)
            local bv = tonumber(_G.RivalAimbotBypassVersion) or 1
            local step = (tonumber(dir) or 1) >= 0 and 1 or -1
            bv = bv + step
            if bv > 4 then bv = 1 end
            if bv < 1 then bv = 4 end
            _G.RivalAimbotBypassVersion = bv
            if _G.RivalSmartAimbot and _G.RivalSmartAimbot.enabled and _G.RivalSmartAimbot.setVersion then
                pcall(_G.RivalSmartAimbot.setVersion, bv)
            end
        end)
        if _G.MoonSave then
            _G.MoonSave.register("V:Bypass Aimbot", function() return _G.RivalAimbotBypassVersion end, function(v)
                local n = tonumber(v) or 1; if n < 1 or n > 4 then n = 1 end; _G.RivalAimbotBypassVersion = n
                local l = _G.MoonSaveRefs.bypassLbl
                if l then l.Text = (n == 4 and "v4") or (n == 3 and "v3") or (n == 2 and "v2") or "v1" end
            end, 20)
        end
    end

    -- Normal Aimbot: v1 = current Moon, v2 = Clean Hub full (under Bypass Aimbot)
    do
        local row = mkRow(combatPage, 42)
        mkLabel(row, "Normal Aimbot")
        local function mkArrowPick(parent, width, getText, onStep)
            local box = Instance.new("Frame", parent)
            box.Size = UDim2.new(0, width, 1, 0)
            box.Position = UDim2.new(1, -(width + 8), 0, 0)
            box.BackgroundTransparency = 1
            box.ZIndex = 8
            local lbl = Instance.new("TextLabel", box)
            lbl.Size = UDim2.new(1, -60, 0, 26)
            lbl.Position = UDim2.new(0, 30, 0.5, -13)
            lbl.BackgroundTransparency = 1
            lbl.Text = getText()
            lbl.TextColor3 = WHITE
            lbl.Font = Enum.Font.GothamBold
            lbl.TextSize = 11
            lbl.ZIndex = 9
            local function mk(glyph, x, dir)
                local b = Instance.new("TextButton", box)
                b.Size = UDim2.new(0, 28, 0, 26)
                b.Position = UDim2.new(0, x, 0.5, -13)
                b.BackgroundColor3 = INP
                b.BackgroundTransparency = 0.7
                b.BorderSizePixel = 0
                b.Text = glyph
                b.TextColor3 = WHITE
                b.Font = Enum.Font.GothamBold
                b.TextSize = 13
                b.AutoButtonColor = false
                b.ZIndex = 9
                Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
                b.Activated:Connect(function()
                    onStep(dir)
                    lbl.Text = getText()
                end)
            end
            mk("<", 0, -1)
            mk(">", width - 28, 1)
            return lbl
        end
        _G.RivalAimbotNormalVersion = (tonumber(_G.RivalAimbotNormalVersion) == 2) and 2 or 1
        _G.MoonSaveRefs.normalAimLbl = mkArrowPick(row, 100, function()
            return (_G.RivalAimbotNormalVersion == 2) and "v2" or "v1"
        end, function(dir)
            _G.RivalAimbotNormalVersion = (_G.RivalAimbotNormalVersion == 1) and 2 or 1
            if _G.RivalSmartAimbot and _G.RivalSmartAimbot.enabled and _G.RivalSmartAimbot.mode == "normal" then
                pcall(function()
                    stopNormal(true)
                    startNormal()
                end)
            end
            if type(scheduleRivalHubSave) == "function" then pcall(scheduleRivalHubSave)
            elseif _G.MoonSave and _G.MoonSave.markDirty then pcall(_G.MoonSave.markDirty) end
        end)
        if _G.MoonSave then
            _G.MoonSave.register("V:Normal Aimbot", function() return _G.RivalAimbotNormalVersion end, function(v)
                _G.RivalAimbotNormalVersion = (tonumber(v) == 2) and 2 or 1
                local l = _G.MoonSaveRefs.normalAimLbl
                if l then l.Text = (_G.RivalAimbotNormalVersion == 2) and "v2" or "v1" end
            end, 20)
        end
    end

    -- Split Aimbot: turns OFF the automatic Anti-Bat switch. AUTO BAT button = Normal aimbot (v1/v2),
    -- new AIMBOT BYPASS button + key = Bypass aimbot (v1/v2/v3). Turn it OFF = auto switch again.
    _G.MoonAimbotSplitSetVisual = mkToggle(combatPage, "Dual Mode", function(on)
        on = on == true
        _G.MoonAimbotSplit = on
        if on and _G.MoonAimbotFixed == true then
            -- Split and Fixed are exclusive (Smart.setSplit turns Fixed off and applies the mode once)
            _G.MoonAimbotFixed = false
            if _G.MoonAimbotFixedSetVisual then pcall(_G.MoonAimbotFixedSetVisual, false) end
        end
        local S = _G.RivalSmartAimbot
        if S and S.setSplit then
            pcall(S.setSplit, on)
        elseif type(_G.MoonRefreshAimbotBypassUI) == "function" then
            pcall(_G.MoonRefreshAimbotBypassUI)
        end
    end)

    -- Fixed Aimbot: same AUTO BAT button / key, no new button. Turns OFF the automatic Anti-Bat switch.
    -- Open the arrow: Normal (left) | Bypass (right). AUTO BAT then always runs the chosen one
    -- (Normal v1/v2 or Bypass v1/v2/v3, following the versions selected above).
    do
        local BLUE_ON = Color3.fromRGB(0, 132, 255)
        local DARK_OFF = Color3.fromRGB(18, 28, 42)
        local fixedPaint = nil

        _G.MoonAimbotFixedSetVisual = mkToggle(combatPage, "Manual Mode", function(on)
            on = on == true
            _G.MoonAimbotFixed = on
            if on and _G.MoonAimbotSplit == true then
                -- Fixed and Split are exclusive
                _G.MoonAimbotSplit = false
                if _G.MoonAimbotSplitSetVisual then pcall(_G.MoonAimbotSplitSetVisual, false) end
                if type(_G.MoonRefreshAimbotBypassUI) == "function" then pcall(_G.MoonRefreshAimbotBypassUI) end
            end
            local S = _G.RivalSmartAimbot
            if S and S.setFixed then pcall(S.setFixed, on) end
        end)

        local fixedRow = nil
        for _, child in ipairs(combatPage:GetChildren()) do
            if child:IsA("Frame") then
                local lbl = child:FindFirstChildWhichIsA("TextLabel")
                if lbl and lbl.Text == "Manual Mode" then fixedRow = child end
            end
        end

        local ROW_H = 38
        local holder = Instance.new("Frame")
        holder.Name = "Fixed Aimbot Options"
        holder.BackgroundTransparency = 1
        holder.Size = UDim2.new(1, -4, 0, 0)
        holder.BorderSizePixel = 0
        holder.LayoutOrder = getNextOrder(combatPage)
        holder.ZIndex = 7
        holder.ClipsDescendants = true
        holder.Visible = false
        holder.Parent = combatPage

        local opt = Instance.new("Frame")
        opt.BackgroundColor3 = Color3.fromRGB(28, 30, 38)
        opt.BackgroundTransparency = 0.35
        opt.Size = UDim2.new(1, -8, 0, ROW_H)
        opt.Position = UDim2.new(0, 4, 0, 4)
        opt.BorderSizePixel = 0
        opt.ZIndex = 8
        opt.Parent = holder
        Instance.new("UICorner", opt).CornerRadius = UDim.new(0, 8)

        local function mkSide(text, xScale, xOff, mode)
            local b = Instance.new("TextButton")
            b.Size = UDim2.new(0.5, -9, 1, -10)
            b.Position = UDim2.new(xScale, xOff, 0, 5)
            b.BackgroundColor3 = DARK_OFF
            b.BorderSizePixel = 0
            b.Text = text
            b.TextColor3 = Color3.fromRGB(255, 255, 255)
            b.Font = Enum.Font.GothamBold
            b.TextSize = 12
            b.AutoButtonColor = false
            b.ZIndex = 10
            b.Parent = opt
            Instance.new("UICorner", b).CornerRadius = UDim.new(0, 7)
            b.MouseButton1Click:Connect(function()
                local S = _G.RivalSmartAimbot
                if S and S.setFixedMode then pcall(S.setFixedMode, mode)
                else _G.MoonAimbotFixedMode = mode end
                if fixedPaint then fixedPaint() end
                if _G.MoonSave then _G.MoonSave.markDirty() end
            end)
            return b
        end
        local normalBtn = mkSide("Normal", 0, 6, "normal")   -- left
        local bypassBtn = mkSide("Bypass", 0.5, 3, "bypass") -- right

        fixedPaint = function()
            local isBypass = _G.MoonAimbotFixedMode == "bypass"
            normalBtn.BackgroundColor3 = isBypass and DARK_OFF or BLUE_ON
            bypassBtn.BackgroundColor3 = isBypass and BLUE_ON or DARK_OFF
        end
        fixedPaint()
        _G.MoonSaveRefs.fixedModePaint = fixedPaint

        local HOLDER_H = ROW_H + 8
        local function expandHolder(open)
            local info = TweenInfo.new(0.22, Enum.EasingStyle.Quart, open and Enum.EasingDirection.Out or Enum.EasingDirection.In)
            holder:SetAttribute("_expandToken", (holder:GetAttribute("_expandToken") or 0) + 1)
            local token = holder:GetAttribute("_expandToken")
            if open then
                holder.Visible = true
                holder.Size = UDim2.new(1, -4, 0, 0)
                TS:Create(holder, info, { Size = UDim2.new(1, -4, 0, HOLDER_H) }):Play()
            else
                local tw = TS:Create(holder, info, { Size = UDim2.new(1, -4, 0, 0) })
                tw.Completed:Connect(function()
                    if holder and holder.Parent and holder:GetAttribute("_expandToken") == token then
                        holder.Visible = false
                    end
                end)
                tw:Play()
            end
        end

        if fixedRow then
