_G.MoonHubPersistence = MoonPersistence
local function mkLabel(row, text, widthScale)
    local l = userMkLabel(row, text)
    if widthScale then l.Size = UDim2.new(widthScale, 0, 1, 0) end
    return l
end
local function mkToggle(page, txt, cb)
    local set = userMkToggle(page, txt, function(on)
        MoonPersistence.ToggleStates[txt] = on == true
        if cb then cb(on) end
    end)
    MoonPersistence.ToggleStates[txt] = false
    MoonPersistence.ToggleSetters[txt] = function(value)
        value = value == true
        set(value)
        MoonPersistence.ToggleStates[txt] = value
        if cb then pcall(cb, value) end
    end
    return function(value)
        value = value and true or false
        set(value)
        MoonPersistence.ToggleStates[txt] = value
    end
end
