_G.MoonHubAntiLag1 = _G.MoonHubAntiLag1 or {
    enabled = false,
    descConn = nil,
    removeAccessories = true,
}

local function _al1ApplyDerender(obj)
    pcall(function()
        if not obj or not obj.Parent then return end
        if obj:GetAttribute("_AmbitiousHubSky") ~= nil then return end
        if obj:IsA("Sky") or obj:IsA("Atmosphere") or obj:IsA("Clouds") then return end
        -- protect local character accessories from wipe
        if obj:IsA("Accessory") or obj:IsA("Hat") then
            local char = LP.Character
            if char and obj:IsDescendantOf(char) then return end
            pcall(function() obj:Destroy() end)
            return
        end
        if obj:IsA("BasePart") then
            local char = LP.Character
            if char and obj:IsDescendantOf(char) then return end
            obj.Material = Enum.Material.Plastic
            obj.Reflectance = 0
            obj.CastShadow = false
            pcall(function()
                obj.TopSurface = Enum.SurfaceType.Smooth
                obj.BottomSurface = Enum.SurfaceType.Smooth
                obj.FrontSurface = Enum.SurfaceType.Smooth
                obj.BackSurface = Enum.SurfaceType.Smooth
                obj.LeftSurface = Enum.SurfaceType.Smooth
                obj.RightSurface = Enum.SurfaceType.Smooth
            end)
            for _, child in ipairs(obj:GetChildren()) do
                if child:IsA("Decal") or child:IsA("Texture") then
                    child.Transparency = 0.5
                end
            end
        elseif obj:IsA("Decal") or obj:IsA("Texture") then
            obj.Transparency = 1
        elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam")
            or obj:IsA("Fire") or obj:IsA("Smoke") or obj:IsA("Sparkles") then
            obj.Enabled = false
        elseif obj:IsA("PointLight") or obj:IsA("SpotLight") or obj:IsA("SurfaceLight") then
            obj.Enabled = false
        elseif obj:IsA("SelectionBox") and obj.Name ~= "AmbitiousHubESP" and obj.Name ~= "MoonHubESP" then
            pcall(function() obj:Destroy() end)
        end
    end)
end

function _G.MoonHubAntiLag1.enable()
    local A = _G.MoonHubAntiLag1
    if A.enabled then return end
    A.enabled = true
    antiLagEnabled = true

    _G._MoonAL1_Brightness = _G._MoonAL1_Brightness or Lighting.Brightness
    _G._MoonAL1_Clock = _G._MoonAL1_Clock or Lighting.ClockTime
    _G._MoonAL1_Ambient = _G._MoonAL1_Ambient or Lighting.OutdoorAmbient

    pcall(function()
        settings().Rendering.QualityLevel = 1
        settings().Rendering.MeshPartDetailLevel = Enum.MeshPartDetailLevel.Disabled
    end)

    pcall(function()
        Lighting.GlobalShadows = false
        Lighting.FogEnd = 1e10
        Lighting.FogStart = 0
        Lighting.Brightness = 1
        Lighting.EnvironmentDiffuseScale = 0
        Lighting.EnvironmentSpecularScale = 0
        Lighting.ShadowSoftness = 0
        Lighting.ExposureCompensation = 0
        pcall(function() Lighting.Technology = Enum.Technology.Compatibility end)
        for _, e in ipairs(Lighting:GetChildren()) do
            pcall(function()
                if e:GetAttribute("_AmbitiousVivid") or e:GetAttribute("_MoonHubSky") then return end
                if e:IsA("BlurEffect") or e:IsA("SunRaysEffect")
                    or e:IsA("ColorCorrectionEffect") or e:IsA("BloomEffect")
                    or e:IsA("DepthOfFieldEffect") or e:IsA("BrightnessEffect")
                    or e:IsA("DitheringEffect") then
                    e.Enabled = false
                end
            end)
        end
    end)

    -- batch workspace (soft: delay + hard per-frame cap to avoid FPS spike on enable)
    task.spawn(function()
        task.wait(0.4)
        if not A.enabled then return end
        local pending = {}
        for _, c in ipairs(workspace:GetChildren()) do table.insert(pending, c) end
        while A.enabled and #pending > 0 do
            local n = 0
            local deadline = os.clock() + 0.00035
            while #pending > 0 and n < 32 and os.clock() < deadline do
                local obj = table.remove(pending)
                _al1ApplyDerender(obj)
                local ok, kids = pcall(function() return obj:GetChildren() end)
                if ok then for _, k in ipairs(kids) do table.insert(pending, k) end end
                n = n + 1
            end
            RunService.Heartbeat:Wait()
        end
    end)

    if A.descConn then pcall(function() A.descConn:Disconnect() end) end
    A.descConn = workspace.DescendantAdded:Connect(function(obj)
        if not A.enabled then return end
        task.defer(function() _al1ApplyDerender(obj) end)
    end)
end

function _G.MoonHubAntiLag1.disable()
    local A = _G.MoonHubAntiLag1
    A.enabled = false
    if A.descConn then
        pcall(function() A.descConn:Disconnect() end)
        A.descConn = nil
    end
    pcall(function()
        if _G._MoonAL1_Brightness then Lighting.Brightness = _G._MoonAL1_Brightness end
        if _G._MoonAL1_Clock then Lighting.ClockTime = _G._MoonAL1_Clock end
        if _G._MoonAL1_Ambient then Lighting.OutdoorAmbient = _G._MoonAL1_Ambient end
        Lighting.ExposureCompensation = 0
        Lighting.GlobalShadows = true
    end)
end

function _G.MoonHubAntiLag1.isOn()
    return _G.MoonHubAntiLag1.enabled == true
end

