function AL2._alApplyLowFlags()
    local env = (getgenv and getgenv()) or _G
    local setter = rawget(env, "setfflag") or rawget(_G, "set_fflag")
    local getter = rawget(env, "getfflag") or rawget(_G, "get_fflag")
    -- Only change flags when the original values can also be queried and restored.
    if type(setter) ~= "function" or type(getter) ~= "function" then return end
    for _, flag in ipairs(AL2.AL_LOW_FLAGS) do
        local ok, current = pcall(getter, flag[1])
        if ok and current ~= nil then
            if AL2._alFlagOriginals[flag[1]] == nil then
                AL2._alFlagOriginals[flag[1]] = tostring(current)
            end
            pcall(setter, flag[1], tostring(flag[2]))
        end
    end
end

function AL2._alSaveLighting()
    if AL2._alLightOrig then return end
    AL2._alLightOrig = {
        Brightness = Lighting.Brightness,
        ClockTime = Lighting.ClockTime,
        OutdoorAmbient = Lighting.OutdoorAmbient,
        Ambient = Lighting.Ambient,
        GlobalShadows = Lighting.GlobalShadows,
        EnvironmentDiffuseScale = Lighting.EnvironmentDiffuseScale,
        EnvironmentSpecularScale = Lighting.EnvironmentSpecularScale,
        FogStart = Lighting.FogStart,
        FogEnd = Lighting.FogEnd,
    }
end

function AL2._alApplyLowPermanentSettings()
    if next(AL2._alWorldOrig) == nil then
        pcall(function() AL2._alWorldOrig.renderQuality = settings().Rendering.QualityLevel end)
        pcall(function() AL2._alWorldOrig.savedQuality = UserSettings():GetService("UserGameSettings").SavedQualityLevel end)
        local terrain = workspace:FindFirstChildOfClass("Terrain")
        if terrain then
            AL2._alWorldOrig.terrainObject = terrain
            AL2._alWorldOrig.terrain = {
                Decoration = terrain.Decoration, WaterWaveSize = terrain.WaterWaveSize,
                WaterWaveSpeed = terrain.WaterWaveSpeed, WaterReflectance = terrain.WaterReflectance,
                WaterTransparency = terrain.WaterTransparency,
            }
            local clouds = terrain:FindFirstChildOfClass("Clouds")
            if clouds then AL2._alWorldOrig.cloudsObject = clouds; AL2._alWorldOrig.cloudsEnabled = clouds.Enabled end
        end
        AL2._alWorldOrig.atmospheres = {}
        for _, atmosphere in ipairs(Lighting:GetChildren()) do
            if atmosphere:IsA("Atmosphere") then
                AL2._alWorldOrig.atmospheres[atmosphere] = {
                    Density = atmosphere.Density, Glare = atmosphere.Glare, Haze = atmosphere.Haze,
                }
            end
        end
    end
    pcall(function() settings().Rendering.QualityLevel = Enum.QualityLevel.Level01 end)
    pcall(function()
        UserSettings():GetService("UserGameSettings").SavedQualityLevel = Enum.SavedQualitySetting.QualityLevel1
    end)
    pcall(function()
        Lighting.GlobalShadows = false
        Lighting.EnvironmentDiffuseScale = 0
        Lighting.EnvironmentSpecularScale = 0
        Lighting.FogStart = 0
        Lighting.FogEnd = 1e10
    end)
    pcall(function()
        local atmosphere = Lighting:FindFirstChildOfClass("Atmosphere")
        if atmosphere then
            atmosphere.Density = 0
            atmosphere.Glare = 0
            atmosphere.Haze = 0
        end
    end)
    pcall(function()
        local terrain = workspace:FindFirstChildOfClass("Terrain")
        if terrain then
            terrain.Decoration = false
            terrain.WaterWaveSize = 0
            terrain.WaterWaveSpeed = 0
            terrain.WaterReflectance = 0
            local clouds = terrain:FindFirstChildOfClass("Clouds")
            if clouds then clouds.Enabled = false end
        end
    end)
end

function AL2._alChange(object, property, value)
    pcall(function()
        local original = object[property]
        if original == value then return end
        object[property] = value
        local bucket = AL2._alSaved[object]
        if not bucket then bucket = {}; AL2._alSaved[object] = bucket end
        if not bucket[property] then bucket[property] = { value = original } end
    end)
end

function AL2._alIsProtectedVisual(object)
    local char = LP.Character
    if char and (object == char or object:IsDescendantOf(char)) then return true end
    if object:GetAttribute("_AdaptDuelsSky") then return true end
    for _, effect in ipairs((_G.MoonHubVividEffects or {}) or {}) do if effect == object then return true end end
    local parent = object
    while parent and parent ~= workspace do
        if parent:IsA("LayerCollector") or parent:IsA("GuiObject") or parent:IsA("GuiBase2d") then
            return true
        end
        local name = parent.Name or ""
        if name:match("^Crystal") or name:match("^Eclipse") or name:match("^ESP_")
            or name:match("^BloodHounds") or name:match("^Yout") or name:match("^Vision") then
            return true
        end
        parent = parent.Parent
    end
    return false
end

function AL2.applyAntiLagDerender(obj)
    pcall(function()
        if not AL2._alRunning then return end
        if AL2._alIsProtectedVisual(obj) then return end

        if obj:IsA("Terrain") then
            AL2._alChange(obj, "Decoration", false)
            AL2._alChange(obj, "WaterWaveSize", 0)
            AL2._alChange(obj, "WaterWaveSpeed", 0)
            AL2._alChange(obj, "WaterReflectance", 0)
            AL2._alChange(obj, "WaterTransparency", 1)
        end
        if obj:IsA("BasePart") then
            AL2._alChange(obj, "Material", Enum.Material.Plastic)
            AL2._alChange(obj, "MaterialVariant", "")
            AL2._alChange(obj, "Reflectance", 0)
            AL2._alChange(obj, "CastShadow", false)
            if obj:IsA("MeshPart") then
                AL2._alChange(obj, "TextureID", "")
                AL2._alChange(obj, "RenderFidelity", Enum.RenderFidelity.Performance)
                AL2._alChange(obj, "DoubleSided", false)
            elseif obj:IsA("PartOperation") then
                AL2._alChange(obj, "RenderFidelity", Enum.RenderFidelity.Performance)
            end
        elseif obj:IsA("SpecialMesh") then
            AL2._alChange(obj, "TextureId", "")
        elseif obj:IsA("SurfaceAppearance") then
            AL2._alDetached[obj] = true
            AL2._alChange(obj, "Parent", nil)
        elseif obj:IsA("Decal") or obj:IsA("Texture") then
            AL2._alChange(obj, "Transparency", 1)
            AL2._alChange(obj, "Texture", "")
        elseif obj:IsA("ParticleEmitter") then
            AL2._alChange(obj, "Enabled", false)
            AL2._alChange(obj, "Rate", 0)
            pcall(function() obj:Clear() end)
        elseif obj:IsA("Trail") then
            AL2._alChange(obj, "Enabled", false)
            pcall(function() obj:Clear() end)
        elseif obj:IsA("Beam") or obj:IsA("Fire") or obj:IsA("Smoke")
            or obj:IsA("Sparkles") or obj:IsA("Light") or obj:IsA("PostEffect")
            or obj:IsA("Clouds") then
            AL2._alChange(obj, "Enabled", false)
        elseif obj:IsA("Atmosphere") then
            AL2._alChange(obj, "Density", 0)
            AL2._alChange(obj, "Haze", 0)
            AL2._alChange(obj, "Glare", 0)
        elseif obj:IsA("Sky") then
            for _, face in ipairs({"SkyboxBk","SkyboxDn","SkyboxFt","SkyboxLf","SkyboxRt","SkyboxUp","SunTextureId","MoonTextureId"}) do
                AL2._alChange(obj, face, "")
            end
            AL2._alChange(obj, "StarCount", 0)
            AL2._alChange(obj, "CelestialBodiesShown", false)
        elseif obj:IsA("Shirt") then
            AL2._alChange(obj, "ShirtTemplate", "")
        elseif obj:IsA("Pants") then
            AL2._alChange(obj, "PantsTemplate", "")
        elseif obj:IsA("ShirtGraphic") then
            AL2._alChange(obj, "Graphic", "")
        elseif obj:IsA("Animator") then
            if not AL2._alAnimators[obj] then
                local char = LP.Character
                if not (char and obj:IsDescendantOf(char)) then
                    AL2._alAnimators[obj] = true
                    local token = AL2._alGeneration
                    local ok, conn = pcall(function()
                        return obj.AnimationPlayed:Connect(function(track)
                            if not AL2._alRunning or AL2._alGeneration ~= token then return end
                            task.defer(function()
                                if AL2._alRunning and AL2._alGeneration == token then
                                    pcall(function() track:Stop(0) end)
                                end
                            end)
                        end)
                    end)
                    if ok then table.insert(AL2._alConns, conn) end
                    pcall(function()
                        for _, track in ipairs(obj:GetPlayingAnimationTracks()) do
                            if track.IsPlaying then
                                AL2._alStoppedTracks[track] = {
                                    animator = obj,
                                    time = track.TimePosition,
                                    speed = track.Speed,
                                }
                                track:Stop(0)
                            end
                        end
                    end)
                end
            end
        end
    end)
end

function AL2.enable()
    if AL2._alRunning then return end
    AL2._alRunning = true
    AL2.enabled = true
    antiLagEnabled = true
    AL2._alGeneration = AL2._alGeneration + 1
    local token = AL2._alGeneration

    AL2._alSaveLighting()
    AL2._alApplyLowFlags()
    AL2._alApplyLowPermanentSettings()

    for _, delaySeconds in ipairs({2, 6, 12, 20}) do
        task.delay(delaySeconds, function()
            if AL2._alRunning and AL2._alGeneration == token then
                AL2._alApplyLowFlags()
            end
        end)
    end

    pcall(function() game:GetService("ReplicatedFirst"):RemoveDefaultLoadingScreen() end)

    table.insert(AL2._alConns, workspace.DescendantAdded:Connect(function(obj)
        task.defer(function()
            if AL2._alRunning and AL2._alGeneration == token then
                pcall(AL2.applyAntiLagDerender, obj)
            end
        end)
    end))
    table.insert(AL2._alConns, Lighting.DescendantAdded:Connect(function(obj)
        task.defer(function()
            if AL2._alRunning and AL2._alGeneration == token then
                pcall(AL2.applyAntiLagDerender, obj)
            end
        end)
    end))

    local function walkBatched(roots, apply, shouldContinue)
        task.spawn(function()
            local pending = {}
            for _, root in ipairs(roots) do
                if root then
                    local ok, children = pcall(function() return root:GetChildren() end)
                    if ok then for _, c in ipairs(children) do table.insert(pending, c) end end
                end
            end
            while #pending > 0 and shouldContinue() do
                local deadline = os.clock() + 0.0008
                local n = 0
                while #pending > 0 and n < 40 and os.clock() < deadline do
                    local obj = table.remove(pending)
                    pcall(apply, obj)
                    local ok, children = pcall(function() return obj:GetChildren() end)
                    if ok then for _, c in ipairs(children) do table.insert(pending, c) end end
                    n = n + 1
                end
                RunService.Heartbeat:Wait()
            end
        end)
    end

    walkBatched({workspace, Lighting}, AL2.applyAntiLagDerender, function()
        return AL2._alRunning and AL2._alGeneration == token
    end)
end

function AL2.disable()
    if not AL2._alRunning then
        AL2.enabled = false
        return
    end
    AL2._alRunning = false
    AL2.enabled = false
    -- only clear shared flag if no other anti-lag is active
    if not ((_G.MoonHubAntiLag1 and _G.MoonHubAntiLag1.enabled) or (_G.MoonHubAntiLag and _G.MoonHubAntiLag.enabled)) then
        antiLagEnabled = false
    end
    AL2._alGeneration = AL2._alGeneration + 1

    if AL2._alScanCancel then pcall(AL2._alScanCancel); AL2._alScanCancel = nil end

    for _, conn in ipairs(AL2._alConns) do pcall(function() conn:Disconnect() end) end
    AL2._alConns = {}

    for object, properties in pairs(AL2._alSaved) do
        for property, original in pairs(properties) do
            pcall(function() object[property] = original.value end)
        end
    end
    AL2._alSaved = setmetatable({}, { __mode = "k" })
    AL2._alDetached = {}
    AL2._alAnimators = setmetatable({}, { __mode = "k" })

    for track, state in pairs(AL2._alStoppedTracks) do
        pcall(function()
            if state.animator.Parent and not track.IsPlaying then
                track:Play(0, 1, state.speed)
                track.TimePosition = state.time
            end
        end)
    end
    AL2._alStoppedTracks = setmetatable({}, { __mode = "k" })

    if AL2._alLightOrig then
        pcall(function()
            Lighting.Brightness = AL2._alLightOrig.Brightness
            Lighting.ClockTime = AL2._alLightOrig.ClockTime
            Lighting.OutdoorAmbient = AL2._alLightOrig.OutdoorAmbient
            Lighting.Ambient = AL2._alLightOrig.Ambient
            Lighting.GlobalShadows = AL2._alLightOrig.GlobalShadows
            Lighting.EnvironmentDiffuseScale = AL2._alLightOrig.EnvironmentDiffuseScale
            Lighting.EnvironmentSpecularScale = AL2._alLightOrig.EnvironmentSpecularScale
            Lighting.FogStart = AL2._alLightOrig.FogStart
            Lighting.FogEnd = AL2._alLightOrig.FogEnd
        end)
    end
    pcall(function()
        if AL2._alWorldOrig.renderQuality ~= nil then settings().Rendering.QualityLevel = AL2._alWorldOrig.renderQuality end
        if AL2._alWorldOrig.savedQuality ~= nil then UserSettings():GetService("UserGameSettings").SavedQualityLevel = AL2._alWorldOrig.savedQuality end
        local terrain, state = AL2._alWorldOrig.terrainObject, AL2._alWorldOrig.terrain
        if terrain and terrain.Parent and state then
            for property, value in pairs(state) do terrain[property] = value end
        end
        local clouds = AL2._alWorldOrig.cloudsObject
        if clouds and clouds.Parent and AL2._alWorldOrig.cloudsEnabled ~= nil then clouds.Enabled = AL2._alWorldOrig.cloudsEnabled end
        for atmosphere, values in pairs(AL2._alWorldOrig.atmospheres or {}) do
            if atmosphere.Parent then for property, value in pairs(values) do atmosphere[property] = value end end
        end
    end)
    AL2._alWorldOrig = {}
    local env = (getgenv and getgenv()) or _G
    local setter = rawget(env, "setfflag") or rawget(_G, "set_fflag")
    if type(setter) == "function" then
        for name, value in pairs(AL2._alFlagOriginals) do pcall(setter, name, value) end
    end
    AL2._alFlagOriginals = {}
end

function AL2.isOn()
    return AL2.enabled == true or AL2._alRunning == true
end
end -- Anti Lag 2 module


-- Unified Anti Lag controller (Default / Anti Lag 1 / Anti Lag 2)
_G.MoonHubAntiLagMode = _G.MoonHubAntiLagMode or "Default"
_G.MoonHubAntiLagModes = { "Default", "Anti Lag 1", "Anti Lag 2" }

function _G.MoonHubAntiLagApply(on)
    on = on == true
    -- always stop all three first
    pcall(function()
        if _G.MoonHubAntiLag1 and _G.MoonHubAntiLag1.disable then _G.MoonHubAntiLag1.disable() end
    end)
    pcall(function()
        if _G.MoonHubAntiLag2 and _G.MoonHubAntiLag2.disable then _G.MoonHubAntiLag2.disable() end
    end)
    pcall(function()
        if type(disableAntiLag) == "function" then disableAntiLag() end
    end)
    pcall(function()
        if _G.MoonHubAntiLag and _G.MoonHubAntiLag.undo then _G.MoonHubAntiLag.undo() end
    end)
    antiLagEnabled = false
    if not on then
        if type(scheduleRivalHubSave) == "function" then pcall(scheduleRivalHubSave)
        elseif _G.MoonSave and _G.MoonSave.markDirty then pcall(_G.MoonSave.markDirty) end
        return
    end
    local mode = tostring(_G.MoonHubAntiLagMode or "Default")
    if mode == "Anti Lag 1" then
        if _G.MoonHubAntiLag1 then _G.MoonHubAntiLag1.enable() end
        antiLagEnabled = true
    elseif mode == "Anti Lag 2" then
        if _G.MoonHubAntiLag2 then _G.MoonHubAntiLag2.enable() end
        antiLagEnabled = true
    else
        -- Default Moon / VX7 path
        if type(enableAntiLag) == "function" then
            enableAntiLag()
        elseif _G.MoonHubAntiLag and _G.MoonHubAntiLag.apply then
            _G.MoonHubAntiLag.apply()
        end
        antiLagEnabled = true
    end
    if type(scheduleRivalHubSave) == "function" then pcall(scheduleRivalHubSave)
    elseif _G.MoonSave and _G.MoonSave.markDirty then pcall(_G.MoonSave.markDirty) end
end


-- Anti Lag (ported from VX7)
--------------------------------------------------------------------
if type(_G.MoonHubAntiLag) == "table" and type(_G.MoonHubAntiLag.undo) == "function" then
    pcall(_G.MoonHubAntiLag.undo)
end
_G.MoonHubAntiLag = {
    enabled = false,
    connections = {},
    loop = nil,
    whitelist = {},
    mapWhitelist = {},
}

function _G.MoonHubAntiLag.isProtected(instance)
    if not instance then return true end
    local character = localPlayer.Character
    if character and (instance == character or instance:IsDescendantOf(character)) then return true end
    local backpack = localPlayer:FindFirstChild("Backpack")
    if backpack and (instance == backpack or instance:IsDescendantOf(backpack)) then return true end
    local ok, result = pcall(function()
        local parent = instance
        while parent and parent ~= workspace and parent ~= game do
            if parent:GetAttribute("VX7ESP") == true
                or parent:GetAttribute("VX7GhostBody") == true
                or parent:GetAttribute("VX7AntiTPBatProxy") == true
                or (type(parent.Name) == "string" and parent.Name:match("^VX7"))
                or (parent:IsA("BasePart") and type(parent.Name) == "string" and parent.Name:match("^Sentry_%d+$")) then
                return true
            end
            parent = parent.Parent
        end
        return false
    end)
    if ok and result then return true end
    local movingAnimals = workspace:FindFirstChild("RenderedMovingAnimals")
    if movingAnimals and (instance == movingAnimals or instance:IsDescendantOf(movingAnimals)) then return true end
    ok, result = pcall(function()
        local parent = instance
        while parent and parent ~= workspace and parent ~= game do
            if parent:FindFirstChildOfClass("Humanoid") then return true end
            if parent:IsA("Model") and parent:FindFirstChildOfClass("AnimationController") then return true end
            parent = parent.Parent
        end
        return false
    end)
    if ok and result then return true end
    ok, result = pcall(function()
        local root = character and (character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("UpperTorso"))
        if not root then return false end
        if instance:IsA("Model") then
            local part = instance.PrimaryPart or instance:FindFirstChildWhichIsA("BasePart")
            if part and (root.Position - part.Position).Magnitude <= 10 then return true end
        end
        return false
    end)
    return ok and result == true
end

function _G.MoonHubAntiLag.add(set, instance)
    if instance then set[instance] = true end
end

function _G.MoonHubAntiLag.findPath(...)
    local current = workspace
    for _, name in ipairs({...}) do
        current = current and current:FindFirstChild(name)
        if not current then return nil end
    end
    return current
end

function _G.MoonHubAntiLag.rebuildWhitelist()
    local A = _G.MoonHubAntiLag
    table.clear(A.whitelist)
    table.clear(A.mapWhitelist)
    _G.MoonHubAntiLag.add(A.whitelist, workspace:FindFirstChild("Camera"))
    _G.MoonHubAntiLag.add(A.whitelist, workspace:FindFirstChild("Terrain"))
    _G.MoonHubAntiLag.add(A.whitelist, workspace:FindFirstChild("Debris"))
    _G.MoonHubAntiLag.add(A.whitelist, workspace:FindFirstChild("Plots"))
    _G.MoonHubAntiLag.add(A.whitelist, workspace:FindFirstChild("RenderedMovingAnimals"))
    _G.MoonHubAntiLag.add(A.whitelist, _G.MoonHubAntiLag.findPath("Map"))
    _G.MoonHubAntiLag.add(A.mapWhitelist, _G.MoonHubAntiLag.findPath("Map", "WallModels"))
    _G.MoonHubAntiLag.add(A.mapWhitelist, _G.MoonHubAntiLag.findPath("Map", "__StreamCheck_DontDelete"))
    _G.MoonHubAntiLag.add(A.mapWhitelist, _G.MoonHubAntiLag.findPath("Map", "Carpet"))
    _G.MoonHubAntiLag.add(A.mapWhitelist, _G.MoonHubAntiLag.findPath("Map", "Ground"))
    _G.MoonHubAntiLag.add(A.mapWhitelist, _G.MoonHubAntiLag.findPath("Map", "Ground_Left"))
    _G.MoonHubAntiLag.add(A.mapWhitelist, _G.MoonHubAntiLag.findPath("Map", "Ground_Right"))
end

function _G.MoonHubAntiLag.isUUID(name)
    return type(name) == "string" and name:match("^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$") ~= nil
end

function _G.MoonHubAntiLag.removeAnimControllers()
    local A = _G.MoonHubAntiLag
    for index, descendant in ipairs(workspace:GetDescendants()) do
        if not A.enabled then return end
        if not A.isProtected(descendant) and descendant:IsA("AnimationController") then
            pcall(function() descendant:Destroy() end)
        end
        if index % 50 == 0 then RunService.Heartbeat:Wait() end
    end
end

function _G.MoonHubAntiLag.removeVisuals()
    local A = _G.MoonHubAntiLag
    -- Soft pass: never freeze the client on enable
    local list = {}
    pcall(function()
        for _, d in ipairs(workspace:GetDescendants()) do
            table.insert(list, d)
            if #list % 120 == 0 then RunService.Heartbeat:Wait() end
            if not A.enabled then return end
        end
    end)
    for index, descendant in ipairs(list) do
        if not A.enabled then return end
        if index % 25 == 0 then RunService.Heartbeat:Wait() end
        if not A.isProtected(descendant) then
            pcall(function()
                if descendant:IsA("AnimationController") then
                    descendant:Destroy()
                elseif descendant:IsA("Texture") or descendant:IsA("Decal") or descendant:IsA("SurfaceAppearance") then
                    descendant:Destroy()
                elseif descendant:IsA("SpecialMesh") then
                    descendant.TextureId = ""
                elseif descendant:IsA("MeshPart") then
                    descendant.TextureID = ""
                    descendant.CastShadow = false
                elseif descendant:IsA("ParticleEmitter") or descendant:IsA("Trail") or descendant:IsA("Beam")
                    or descendant:IsA("Fire") or descendant:IsA("Smoke") or descendant:IsA("Sparkles")
                    or descendant:IsA("Highlight") or descendant:IsA("Explosion") or descendant:IsA("PointLight")
                    or descendant:IsA("SpotLight") or descendant:IsA("SurfaceLight") then
                    descendant:Destroy()
                elseif descendant:IsA("BasePart") then
                    descendant.CastShadow = false
                    descendant.Material = Enum.Material.Plastic
                    descendant.MaterialVariant = ""
                    descendant.Reflectance = 0
                end
            end)
        end
    end
end

function _G.MoonHubAntiLag.hasSound(instance)
    if instance:IsA("Sound") or instance:IsA("SoundGroup") then return true end
    return instance:FindFirstChildOfClass("Sound", true) ~= nil
        or instance:FindFirstChildOfClass("SoundGroup", true) ~= nil
end

function _G.MoonHubAntiLag.cleanMap()
    local A = _G.MoonHubAntiLag
    local map = workspace:FindFirstChild("Map")
    if not map then return end
    local kids = map:GetChildren()
    for i, child in ipairs(kids) do
        if not A.enabled then return end
        if not A.mapWhitelist[child] and not A.hasSound(child) and not A.isProtected(child) then
            pcall(function() child:Destroy() end)
        end
        if i % 5 == 0 then RunService.Heartbeat:Wait() end
    end
end

function _G.MoonHubAntiLag.cleanWorkspace()
    local A = _G.MoonHubAntiLag
    A.rebuildWhitelist()
    local kids = workspace:GetChildren()
    for i, child in ipairs(kids) do
        if not A.enabled then return end
        if not A.whitelist[child] and not A.isUUID(child.Name)
            and not Players:FindFirstChild(child.Name) and not A.isProtected(child) and not A.hasSound(child) then
            pcall(function() child:Destroy() end)
        end
        if i % 4 == 0 then RunService.Heartbeat:Wait() end
    end
    A.cleanMap()
end

function _G.MoonHubAntiLag.cleanLighting()
    for _, child in ipairs(game:GetService("Lighting"):GetChildren()) do
        if not child:IsA("Sky") and not child:IsA("Atmosphere") and not child:IsA("Clouds") and child:IsA("PostEffect") then
            pcall(function() child:Destroy() end)
        end
    end
end

function _G.MoonHubAntiLag.apply()
    local A = _G.MoonHubAntiLag
    if A.enabled then return end
    A.enabled = true
    _G.MoonHubAntiLagEnabled = true
    task.spawn(function()
        -- Old-style fast path: high-impact cleanup first (soft yields inside clean*)
        pcall(A.cleanWorkspace)
        if not A.enabled then return end
        pcall(A.cleanLighting)
        if not A.enabled then return end
        for _, connection in ipairs(A.connections) do pcall(function() connection:Disconnect() end) end
        A.connections = {}
        table.insert(A.connections, workspace.DescendantAdded:Connect(function(descendant)
            if not A.enabled or A.isProtected(descendant) then return end
            task.defer(function()
                if not A.enabled or A.isProtected(descendant) then return end
                pcall(function()
                    if descendant:IsA("Texture") or descendant:IsA("Decal") or descendant:IsA("SurfaceAppearance")
                        or descendant:IsA("ParticleEmitter") or descendant:IsA("Trail") or descendant:IsA("Beam")
                        or descendant:IsA("Fire") or descendant:IsA("Smoke") or descendant:IsA("Sparkles")
                        or descendant:IsA("Highlight") or descendant:IsA("AnimationController") then
                        descendant:Destroy()
                    end
                end)
            end)
        end))
        table.insert(A.connections, game:GetService("Lighting").DescendantAdded:Connect(function(descendant)
            if not A.enabled or descendant:IsA("Sky") or descendant:IsA("Atmosphere") or descendant:IsA("Clouds") then return end
            if descendant:IsA("PostEffect") then pcall(function() descendant:Destroy() end) end
        end))
        local materialService = game:GetService("MaterialService")
        table.insert(A.connections, materialService.DescendantAdded:Connect(function(descendant)
            if not A.enabled or A.isProtected(descendant) then return end
            pcall(function() descendant:Destroy() end)
        end))
        if A.loop then pcall(task.cancel, A.loop) end
        task.spawn(function()
            -- one combined heavy pass (anim controllers + visuals)
            pcall(A.removeVisuals)
        end)
        A.loop = task.spawn(function()
            while A.enabled do
                task.wait(2)
                if A.enabled then
                    pcall(A.cleanWorkspace)
                    pcall(A.cleanLighting)
                end
            end
        end)
    end)
end

function _G.MoonHubAntiLag.undo()
    local A = _G.MoonHubAntiLag
    A.enabled = false
    _G.MoonHubAntiLagEnabled = false
    for _, connection in ipairs(A.connections) do pcall(function() connection:Disconnect() end) end
    A.connections = {}
    if A.loop then pcall(task.cancel, A.loop); A.loop = nil end
    -- VX7 behavior: disabling stops future cleanup; deleted items/materials are not restored.
end

createSection(visual, "Performance")
-- Anti Lag / Anti Lag 1 / Anti Lag 2: only ONE can be ON. Must turn the active one OFF before enabling another.
do
    local _alGuard = false -- prevent re-entry from visual setters

    local function isMainRunning()
        return (_G.MoonHubAntiLag and _G.MoonHubAntiLag.enabled == true) or false
    end
    local function isAL1Running()
        return (_G.MoonHubAntiLag1 and _G.MoonHubAntiLag1.enabled == true) or false
    end
    local function isAL2Running()
        return (_G.MoonHubAntiLag2 and (_G.MoonHubAntiLag2.enabled == true or _G.MoonHubAntiLag2._alRunning == true)) or false
    end
    local function anyOtherRunning(except)
        if except ~= "main" and isMainRunning() then return true end
        if except ~= "al1" and isAL1Running() then return true end
        if except ~= "al2" and isAL2Running() then return true end
        return false
    end
    local function anyRunning()
        return isMainRunning() or isAL1Running() or isAL2Running()
    end
    local function flushSave()
        if type(scheduleRivalHubSave) == "function" then pcall(scheduleRivalHubSave)
        elseif _G.MoonSave and _G.MoonSave.markDirty then pcall(_G.MoonSave.markDirty) end
        if _G.MoonSave and _G.MoonSave.saveNow then pcall(_G.MoonSave.saveNow, true) end
    end
    local function stopAllExcept(keep)
        if keep ~= "main" then
            pcall(function()
                if _G.MoonHubAntiLag and _G.MoonHubAntiLag.undo then _G.MoonHubAntiLag.undo() end
                if type(disableAntiLag) == "function" then disableAntiLag() end
            end)
        end
        if keep ~= "al1" then
            pcall(function() if _G.MoonHubAntiLag1 then _G.MoonHubAntiLag1.disable() end end)
    pcall(function() if _G.MoonHubAntiLag2 then _G.MoonHubAntiLag2.disable() end end)
        end
        if keep ~= "al2" then
            pcall(function() if _G.MoonHubAntiLag2 then _G.MoonHubAntiLag2.disable() end end)
        end
    end

    _G.MoonHubAntiLagVisual = mkToggle(visual, "Anti Lag", function(on)
        if _alGuard then return end
        if on then
            if anyOtherRunning("main") then
                _alGuard = true
                if _G.MoonHubAntiLagVisual then pcall(_G.MoonHubAntiLagVisual, false) end
                _alGuard = false
                return
            end
            _G.MoonHubAntiLagMode = "Default"
            stopAllExcept("main")
            pcall(function()
                if _G.MoonHubAntiLag and _G.MoonHubAntiLag.apply then
                    _G.MoonHubAntiLag.apply()
                elseif type(enableAntiLag) == "function" then
                    enableAntiLag()
                end
            end)
            antiLagEnabled = true
        else
            pcall(function()
                if _G.MoonHubAntiLag and _G.MoonHubAntiLag.undo then _G.MoonHubAntiLag.undo() end
                if type(disableAntiLag) == "function" then disableAntiLag() end
            end)
            antiLagEnabled = anyRunning()
        end
        flushSave()
    end)
    if _G.MoonHubAntiLagVisual then _G.MoonHubAntiLagVisual(false) end

    _G.MoonHubAntiLag1Visual = mkToggle(visual, "Anti Lag 1", function(on)
        if _alGuard then return end
        if on then
            if anyOtherRunning("al1") then
                _alGuard = true
                if _G.MoonHubAntiLag1Visual then pcall(_G.MoonHubAntiLag1Visual, false) end
                _alGuard = false
                return
            end
            _G.MoonHubAntiLagMode = "Anti Lag 1"
            stopAllExcept("al1")
            if _G.MoonHubAntiLag1 then _G.MoonHubAntiLag1.enable() end
            antiLagEnabled = true
        else
            if _G.MoonHubAntiLag1 then _G.MoonHubAntiLag1.disable() end
            antiLagEnabled = anyRunning()
        end
        flushSave()
    end)
    if _G.MoonHubAntiLag1Visual then _G.MoonHubAntiLag1Visual(false) end

    _G.MoonHubAntiLag2Visual = mkToggle(visual, "Anti Lag 2", function(on)
        if _alGuard then return end
        if on then
            if anyOtherRunning("al2") then
                _alGuard = true
                if _G.MoonHubAntiLag2Visual then pcall(_G.MoonHubAntiLag2Visual, false) end
                _alGuard = false
                return
            end
            _G.MoonHubAntiLagMode = "Anti Lag 2"
            stopAllExcept("al2")
            if _G.MoonHubAntiLag2 then _G.MoonHubAntiLag2.enable() end
            antiLagEnabled = true
        else
            if _G.MoonHubAntiLag2 then _G.MoonHubAntiLag2.disable() end
            antiLagEnabled = anyRunning()
        end
        flushSave()
    end)
    if _G.MoonHubAntiLag2Visual then _G.MoonHubAntiLag2Visual(false) end
end

-- Early apply from save (only one anti-lag) — old fast activation
pcall(function()
    local MS = _G.MoonSave
    if not (MS and MS.get) then return end
    local al2 = MS.get("T:Anti Lag 2") == true
    local al1 = MS.get("T:Anti Lag 1") == true
    local al  = MS.get("T:Anti Lag") == true

    if al2 then
        _G.MoonHubAntiLagMode = "Anti Lag 2"
        if _G.MoonHubAntiLag2Visual then pcall(_G.MoonHubAntiLag2Visual, true) end
        antiLagEnabled = true
        task.defer(function()
            if _G.MoonHubAntiLagMode == "Anti Lag 2" and _G.MoonHubAntiLag2 then
                pcall(function() _G.MoonHubAntiLag2.enable() end)
            end
        end)
    elseif al1 then
        _G.MoonHubAntiLagMode = "Anti Lag 1"
        if _G.MoonHubAntiLag1Visual then pcall(_G.MoonHubAntiLag1Visual, true) end
        antiLagEnabled = true
        task.defer(function()
            if _G.MoonHubAntiLagMode == "Anti Lag 1" and _G.MoonHubAntiLag1 then
                pcall(function() _G.MoonHubAntiLag1.enable() end)
            end
        end)
    elseif al then
        _G.MoonHubAntiLagMode = "Default"
        if _G.MoonHubAntiLagVisual then pcall(_G.MoonHubAntiLagVisual, true) end
        antiLagEnabled = true
        task.defer(function()
            if _G.MoonHubAntiLagMode == "Default" then
                pcall(function()
                    if _G.MoonHubAntiLag and _G.MoonHubAntiLag.apply then
                        _G.MoonHubAntiLag.apply()
                    elseif type(enableAntiLag) == "function" then
                        enableAntiLag()
                    end
                end)
            end
        end)
    else
        _G.MoonHubAntiLagMode = "Default"
        pcall(function() if _G.MoonHubAntiLag2 then _G.MoonHubAntiLag2.disable() end end)
        pcall(function() if _G.MoonHubAntiLag1 then _G.MoonHubAntiLag1.disable() end end)
    pcall(function() if _G.MoonHubAntiLag2 then _G.MoonHubAntiLag2.disable() end end)
        pcall(function() if _G.MoonHubAntiLag and _G.MoonHubAntiLag.undo then _G.MoonHubAntiLag.undo() end end)
        antiLagEnabled = false
    end
end)
