local function normalizeVX7PlayerAnimMode(mode)
    if mode == "Pack 1" or mode == "Hit Harder" then return "TRYHARD" end
    if mode == "Pack 2" then return "Zombie" end
    for _, choice in ipairs(VX7PlayerAnimModes) do
        if choice == mode then return mode end
    end
    return "Unwalk"
end

local VX7PlayerAnim = {
    enabled = false,
    mode = "Unwalk",
    unwalkConnection = nil,
    packConnections = {},
    characterConnection = nil,
    savedCharacter = nil,
    savedIds = nil,
    applying = false,
    refreshQueued = false,
}
local VX7AnimSlots = {"idle1", "idle2", "walk", "run", "jump", "fall", "climb", "swim", "swimidle"}

local function vx7GetAnimateObjects(animate)
    if not animate then return nil end
    local function child(parent, name, objectName)
        local folder = parent and parent:FindFirstChild(name)
        local object = folder and folder:FindFirstChild(objectName)
        if object and object:IsA("Animation") then return object end
        return nil
    end
    return {
        idle1 = child(animate, "idle", "Animation1"),
        idle2 = child(animate, "idle", "Animation2"),
        walk = child(animate, "walk", "WalkAnim"),
        run = child(animate, "run", "RunAnim"),
        jump = child(animate, "jump", "JumpAnim"),
        fall = child(animate, "fall", "FallAnim"),
        climb = child(animate, "climb", "ClimbAnim"),
        swim = child(animate, "swim", "Swim"),
        swimidle = child(animate, "swimidle", "SwimIdle"),
    }
end

local function vx7DisconnectPackConnections()
    for _, connection in ipairs(VX7PlayerAnim.packConnections) do pcall(function() connection:Disconnect() end) end
    VX7PlayerAnim.packConnections = {}
end

local function vx7CaptureDefaults(character)
    if VX7PlayerAnim.savedCharacter == character and VX7PlayerAnim.savedIds then return end
    local objects = vx7GetAnimateObjects(character and character:FindFirstChild("Animate"))
    if not objects then return end
    VX7PlayerAnim.savedCharacter = character
    VX7PlayerAnim.savedIds = {}
    for _, slot in ipairs(VX7AnimSlots) do
        local animation = objects[slot]
        VX7PlayerAnim.savedIds[slot] = animation and animation.AnimationId or nil
    end
end

local function vx7StopCharacterTracks(character)
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not humanoid then return end
    for _, track in ipairs(humanoid:GetPlayingAnimationTracks()) do pcall(function() track:Stop(0) end) end
end

local function vx7RestartAnimate(animate)
    if not animate then return end
    pcall(function() animate.Disabled = true; task.wait(); animate.Disabled = false end)
end

local function vx7RestorePlayerAnimPack(character)
    vx7DisconnectPackConnections()
    character = character or VX7PlayerAnim.savedCharacter or localPlayer.Character
    if not (VX7PlayerAnim.savedIds and character and VX7PlayerAnim.savedCharacter == character) then return end
    local animate = character:FindFirstChild("Animate")
    local objects = vx7GetAnimateObjects(animate)
    if not objects then return end
    VX7PlayerAnim.applying = true
    for _, slot in ipairs(VX7AnimSlots) do
        local animation = objects[slot]
        local originalId = VX7PlayerAnim.savedIds[slot]
        if animation and originalId then pcall(function() animation.AnimationId = originalId end) end
    end
    vx7StopCharacterTracks(character)
    vx7RestartAnimate(animate)
    VX7PlayerAnim.applying = false
    VX7PlayerAnim.savedCharacter = nil
    VX7PlayerAnim.savedIds = nil
end

local function vx7ApplyPlayerAnimPack(character)
    if not VX7PlayerAnim.enabled or VX7PlayerAnim.mode == "Unwalk" then return end
    character = character or localPlayer.Character
    local pack = VX7PlayerAnimPacks[normalizeVX7PlayerAnimMode(VX7PlayerAnim.mode)]
    local animate = character and character:FindFirstChild("Animate")
    local objects = vx7GetAnimateObjects(animate)
    if not (pack and objects) then return end
    vx7CaptureDefaults(character)
    if not VX7PlayerAnim.savedIds then return end
    vx7DisconnectPackConnections()
    VX7PlayerAnim.applying = true
    for index, slot in ipairs(VX7AnimSlots) do
        local animation = objects[slot]
        local assetId = pack[index]
        if animation and assetId then
            pcall(function() animation.AnimationId = "rbxassetid://" .. tostring(assetId) end)
        end
    end
    vx7StopCharacterTracks(character)
    vx7RestartAnimate(animate)
    VX7PlayerAnim.applying = false

    for _, slot in ipairs(VX7AnimSlots) do
        local animation = objects[slot]
        if animation then
            table.insert(VX7PlayerAnim.packConnections, animation:GetPropertyChangedSignal("AnimationId"):Connect(function()
                if VX7PlayerAnim.applying or not VX7PlayerAnim.enabled or VX7PlayerAnim.refreshQueued then return end
                VX7PlayerAnim.refreshQueued = true
                task.defer(function()
                    VX7PlayerAnim.refreshQueued = false
                    if VX7PlayerAnim.enabled and VX7PlayerAnim.mode ~= "Unwalk" then
                        VX7PlayerAnim.applying = true
                        vx7ApplyPlayerAnimPack(character)
                        VX7PlayerAnim.applying = false
                    end
                end)
            end))
        end
    end
    table.insert(VX7PlayerAnim.packConnections, character.ChildAdded:Connect(function(child)
        if child.Name == "Animate" and VX7PlayerAnim.enabled and VX7PlayerAnim.mode ~= "Unwalk" then
            task.delay(0.08, function()
                if VX7PlayerAnim.enabled and VX7PlayerAnim.mode ~= "Unwalk" then
                    VX7PlayerAnim.savedCharacter = nil
                    VX7PlayerAnim.savedIds = nil
                    vx7ApplyPlayerAnimPack(character)
                end
            end)
        end
    end))
end

local function vx7SetUnwalk(enabled)
    enabled = enabled == true
    if VX7PlayerAnim.unwalkConnection then
        pcall(function() VX7PlayerAnim.unwalkConnection:Disconnect() end)
        VX7PlayerAnim.unwalkConnection = nil
    end
    local character = localPlayer.Character
    if not enabled then
        if VX7PlayerAnim.mode == "Unwalk" or not VX7PlayerAnim.enabled then
            vx7RestorePlayerAnimPack(character)
        end
        return
    end
    local animate = character and character:FindFirstChild("Animate")
    local objects = vx7GetAnimateObjects(animate)
    if not objects then return end
    vx7CaptureDefaults(character)
    local ids = VX7PlayerAnim.savedIds
    local idle = ids and (ids.idle1 or ids.idle2)
    if not idle then return end
    VX7PlayerAnim.applying = true
    for _, slot in ipairs({"walk", "run"}) do
        local animation = objects[slot]
        if animation then pcall(function() animation.AnimationId = idle end) end
    end
    vx7StopCharacterTracks(character)
    vx7RestartAnimate(animate)
    VX7PlayerAnim.applying = false
end

local function vx7ApplySelectedMode()
    if not VX7PlayerAnim.enabled then return end
    if VX7PlayerAnim.mode == "Unwalk" then
        vx7SetUnwalk(true)
    else
        vx7SetUnwalk(false)
        vx7ApplyPlayerAnimPack(localPlayer.Character)
    end
end

local function vx7SetPlayerAnimEnabled(enabled)
    VX7PlayerAnim.enabled = enabled == true
    if VX7PlayerAnim.enabled then
        vx7ApplySelectedMode()
    else
        vx7DisconnectPackConnections()
        vx7RestorePlayerAnimPack(localPlayer.Character)
        vx7SetUnwalk(false)
    end
end

local function vx7SetPlayerAnimMode(mode)
    VX7PlayerAnim.mode = normalizeVX7PlayerAnimMode(mode)
    if VX7PlayerAnim.enabled then
        vx7DisconnectPackConnections()
        vx7RestorePlayerAnimPack(localPlayer.Character)
        vx7SetUnwalk(false)
        vx7ApplySelectedMode()
    end
end

VX7PlayerAnim.characterConnection = localPlayer.CharacterAdded:Connect(function(character)
    if not VX7PlayerAnim.enabled then
        VX7PlayerAnim.savedCharacter = nil
        VX7PlayerAnim.savedIds = nil
        return
    end
    if VX7PlayerAnim.mode == "Unwalk" then
        task.delay(0.15, function()
            if VX7PlayerAnim.enabled and VX7PlayerAnim.mode == "Unwalk" then vx7SetUnwalk(true) end
        end)
    else
        if not character:WaitForChild("Animate", 5) then return end
        VX7PlayerAnim.savedCharacter = nil
        VX7PlayerAnim.savedIds = nil
        task.wait(0.2)
        if VX7PlayerAnim.enabled and VX7PlayerAnim.mode ~= "Unwalk" then vx7ApplyPlayerAnimPack(character) end
    end
end)

_G.MoonHubAnimationCleanup = function()
    VX7PlayerAnim.enabled = false
    vx7DisconnectPackConnections()
    vx7RestorePlayerAnimPack(localPlayer.Character)
    vx7SetUnwalk(false)
    if VX7PlayerAnim.characterConnection then
        pcall(function() VX7PlayerAnim.characterConnection:Disconnect() end)
        VX7PlayerAnim.characterConnection = nil
    end
end
_G.MoonHubSetPlayerAnimEnabled = vx7SetPlayerAnimEnabled
_G.MoonHubSetPlayerAnimMode = vx7SetPlayerAnimMode

createSection(visual, "Player Animations")

do
    local store = {}
    function store.save() end
    function store.load() return nil end
    _G.MoonHubPlayerAnimStore = store
end

