local function makeVX7ModeArrow(text, direction)
    local button = Instance.new("TextButton", vx7ModeSelector)
    button.Size = UDim2.new(0, 30, 1, 0)
    button.Position = direction < 0 and UDim2.new(0, 0, 0, 0) or UDim2.new(1, -30, 0, 0)
    button.BackgroundTransparency = 1
    button.Text = text
    button.TextColor3 = color4
    button.Font = Enum.Font.GothamBold
    button.TextSize = 14
    button.AutoButtonColor = false
    button.ZIndex = 10
    button.MouseButton1Click:Connect(function()
        local index = table.find(VX7PlayerAnimModes, VX7PlayerAnim.mode) or 1
        index = (index - 1 + direction) % #VX7PlayerAnimModes + 1
        local mode = VX7PlayerAnimModes[index]
        vx7ModeLabel.Text = mode
        TweenService:Create(vx7ModeStroke, TweenInfo.new(0.12), {Color = getThemeColor(), Transparency = 0.2}):Play()
        vx7SetPlayerAnimMode(mode)
        MoonPersistence.Values["Player Anim Mode"] = mode
        
    end)
    return button
end
makeVX7ModeArrow("<", -1)
makeVX7ModeArrow(">", 1)
MoonPersistence.Values["Player Anim Mode"] = VX7PlayerAnim.mode

-- Factory-reset hook: Player Anim mode back to the default ("Unwalk") and saved file rewritten.
_G.MoonHubResetPlayerAnim = function()
    pcall(vx7SetPlayerAnimEnabled, false)
    VX7PlayerAnim.mode = "Unwalk"
    pcall(vx7SetPlayerAnimMode, "Unwalk")
    VX7PlayerAnim.mode = "Unwalk"
    vx7ModeLabel.Text = "Unwalk"
    MoonPersistence.Values["Player Anim Mode"] = "Unwalk"
    
end

-- Restore from the dedicated file first (before anything can overwrite it with defaults).
do
local vx7SavedAnim = _G.MoonHubPlayerAnimStore and _G.MoonHubPlayerAnimStore.load() or nil
if vx7SavedAnim and type(vx7SavedAnim.mode) == "string" and table.find(VX7PlayerAnimModes, vx7SavedAnim.mode) then
    VX7PlayerAnim.mode = vx7SavedAnim.mode
    vx7ModeLabel.Text = vx7SavedAnim.mode
    MoonPersistence.Values["Player Anim Mode"] = vx7SavedAnim.mode
end

MoonPersistence.ValueSetters["Player Anim Mode"] = function(value)
    -- while the global restore runs, the dedicated file wins over the generic config
    if _G._MoonHubRestoreDone ~= true and vx7SavedAnim and type(vx7SavedAnim.mode) == "string" then
        value = vx7SavedAnim.mode
    end
    if table.find(VX7PlayerAnimModes, value) then
        VX7PlayerAnim.mode = value
        vx7ModeLabel.Text = value
        MoonPersistence.Values["Player Anim Mode"] = value
        vx7SetPlayerAnimMode(value)
    end
end
if _G.MoonSave then
    _G.MoonSave.register("V:Player Anim Mode", function() return VX7PlayerAnim.mode end, function(v)
        if type(v) == "string" and table.find(VX7PlayerAnimModes, v) then
            VX7PlayerAnim.mode = v
            vx7ModeLabel.Text = v
            MoonPersistence.Values["Player Anim Mode"] = v
            pcall(vx7SetPlayerAnimMode, v)
        end
    end, 20)
end

do
    local origToggleSetter = MoonPersistence.ToggleSetters["Player Anim"]
    MoonPersistence.ToggleSetters["Player Anim"] = function(value)
        if _G._MoonHubRestoreDone ~= true and vx7SavedAnim and type(vx7SavedAnim.enabled) == "boolean" then
            value = vx7SavedAnim.enabled
        end
        if origToggleSetter then origToggleSetter(value == true) end
    end
    -- apply the saved ON/OFF state right away as well
    if vx7SavedAnim and vx7SavedAnim.enabled == true and origToggleSetter then
        pcall(origToggleSetter, true)
    end
end
end

