local function vx7NewTextButton(parent, text, size, position, zIndex)
    local button = Instance.new("TextButton", parent)
    button.Size = size
    button.Position = position
    button.BackgroundColor3 = color5
    button.BackgroundTransparency = 0.28
    button.BorderSizePixel = 0
    button.Text = text
    button.TextColor3 = color4
    button.Font = Enum.Font.GothamBold
    button.TextSize = 12
    button.AutoButtonColor = false
    button.ZIndex = zIndex or 9
    Instance.new("UICorner", button).CornerRadius = UDim.new(0, 7)
    local stroke = Instance.new("UIStroke", button)
    stroke.Color = color3
    stroke.Transparency = 0.35
    return button
end

local function vx7MakeToggleRow(parent, text, expandable, callback)
    local row = createRow(parent, 40)
    local label = mkLabel(row, text, 0.58)
    local offset = 10
    if expandable then
        local expander = vx7NewTextButton(row, "⌄", UDim2.fromOffset(25, 25), UDim2.new(0, 6, 0.5, -12), 9)
        expander.TextSize = 14
        label.Position = UDim2.new(0, 39, 0, 0)
        label.Size = UDim2.new(0.52, 0, 1, 0)
        offset = 44
    end
    local pill, dot = mkPill(row, offset)
    local enabled = false
    local function set(value, silent)
        enabled = value == true
        animPill(pill, dot, enabled)
        MoonPersistence.ToggleStates[text] = enabled
        if not silent and callback then pcall(callback, enabled) end
    end
    MoonPersistence.ToggleSetters[text] = function(value) set(value == true, false) end
    if _G.MoonSave then
        _G.MoonSave.register("T:" .. text, function() return enabled end, function(v)
            v = v == true
            if enabled ~= v then set(v, false) end
        end, 50)
    end
    local hit = Instance.new("TextButton", pill)
    hit.Size = UDim2.new(1, 0, 1, 0)
    hit.BackgroundTransparency = 1
    hit.Text = ""
    hit.AutoButtonColor = false
    hit.ZIndex = 10
    hit.MouseButton1Click:Connect(function()
        set(not enabled, false)
    end)
    local panel
    if expandable then
        panel = Instance.new("Frame", parent)
        panel.Name = text:gsub("%s+", "") .. "Controls"
        panel.Size = UDim2.new(1, -4, 0, 38)
        panel.BackgroundTransparency = 1
        panel.BorderSizePixel = 0
        panel.ClipsDescendants = true
        panel.LayoutOrder = nextOrder(parent)
        panel.ZIndex = 7
        local expanded = true
        panel:SetAttribute("Expanded", true)
        local expander = row:FindFirstChildOfClass("TextButton")
        if expander then
            expander.MouseButton1Click:Connect(function()
                expanded = not expanded
                panel:SetAttribute("Expanded", expanded)
                expander.Text = expanded and "⌄" or ">"
                panel.Visible = expanded
                panel.Size = expanded and UDim2.new(1, -4, 0, 38) or UDim2.new(1, -4, 0, 0)
            end)
        end
    end
    return row, set, panel
end

local function vx7MakeStepper(parent, caption, value, minimum, maximum, onChanged)
    local row = createRow(parent, 38)
    local label = mkLabel(row, caption, 0.48)
    label.TextSize = 10
    local minus = vx7NewTextButton(row, "-", UDim2.fromOffset(25, 25), UDim2.new(1, -112, 0.5, -12), 9)
    minus.TextSize = 15
    local valueBox = Instance.new("TextBox", row)
    valueBox.Size = UDim2.fromOffset(54, 25)
    valueBox.Position = UDim2.new(1, -83, 0.5, -12)
    valueBox.BackgroundColor3 = color5
    valueBox.BackgroundTransparency = 0.18
    valueBox.BorderSizePixel = 0
    valueBox.Text = tostring(value)
    valueBox.TextColor3 = color4
    valueBox.Font = Enum.Font.GothamBold
    valueBox.TextSize = 10
    valueBox.ClearTextOnFocus = true
    valueBox.PlaceholderText = tostring(minimum) .. "-" .. tostring(maximum)
    valueBox.ZIndex = 9
    Instance.new("UICorner", valueBox).CornerRadius = UDim.new(0, 6)
    local valueStroke = Instance.new("UIStroke", valueBox)
    valueStroke.Color = color3
    valueStroke.Transparency = 0.35
    local plus = vx7NewTextButton(row, "+", UDim2.fromOffset(25, 25), UDim2.new(1, -28, 0.5, -12), 9)
    plus.TextSize = 14
    local current = value
    local function commit(nextValue, silent)
        current = math.clamp(math.floor(tonumber(nextValue) or current), minimum, maximum)
        valueBox.Text = tostring(current)
        if onChanged then pcall(onChanged, current) end
        MoonPersistence.Values[caption] = current
    end
    MoonPersistence.Values[caption] = current
    MoonPersistence.ValueSetters[caption] = function(nextValue) commit(nextValue, true) end
    if _G.MoonSave then
        _G.MoonSave.register("S:" .. caption, function() return current end, function(v)
            if tonumber(v) then commit(v, true) end
        end, 20)
    end
    minus.MouseButton1Click:Connect(function() commit(current - 5) end)
    plus.MouseButton1Click:Connect(function() commit(current + 5) end)
    valueBox.FocusLost:Connect(function() commit(valueBox.Text) end)
    return row, valueBox, commit
end

