-- Sky presets from VX7. Original Lighting objects/properties are restored on disable.
local Lighting = game:GetService("Lighting")
local VX7Sky = { originals = nil, created = {}, enabled = false, mode = "Cyber" }
local function vx7SkySaveOriginals()
    if VX7Sky.originals then return end
    local snapshot = { props = {}, objects = {} }
    for _, property in ipairs({"Technology", "Brightness", "ClockTime", "ExposureCompensation", "Ambient", "OutdoorAmbient", "FogEnd", "GlobalShadows"}) do
        pcall(function() snapshot.props[property] = Lighting[property] end)
    end
    if _G.MoonHubVX7PotatoGraphicsActive then
        snapshot.props.GlobalShadows = false
    end
    for _, object in ipairs(Lighting:GetChildren()) do
        if object:IsA("Sky") or object:IsA("Atmosphere") or object:IsA("PostEffect") then
            local parent = object.Parent
            object.Parent = nil
            table.insert(snapshot.objects, { object = object, parent = parent })
        end
    end
    local terrain = workspace:FindFirstChildOfClass("Terrain")
    if terrain then
        for _, object in ipairs(terrain:GetChildren()) do
            if object:IsA("Clouds") then
                local parent = object.Parent
                object.Parent = nil
                table.insert(snapshot.objects, { object = object, parent = parent })
            end
        end
    end
    VX7Sky.originals = snapshot
end
local function vx7SkyClearCreated()
    for _, object in ipairs(VX7Sky.created) do pcall(function() object:Destroy() end) end
    table.clear(VX7Sky.created)
end
local function vx7SkyAdd(className, name, parent, properties)
    local object = Instance.new(className)
    object.Name = name
    for property, value in pairs(properties or {}) do pcall(function() object[property] = value end) end
    object.Parent = parent
    table.insert(VX7Sky.created, object)
    return object
end
local VX7SkyPresets = {
    Cyber = {
        asset = "9994573642", nightOnly = false, day = {1.5, -0.15, Color3.fromRGB(30,30,50), Color3.fromRGB(40,40,70)}, night = {3, 0.05, Color3.fromRGB(0,20,40), Color3.fromRGB(10,30,60)},
        dayBloom = {0.15,30,0.9}, nightBloom = {0.35,36,0.8}, dayTint = Color3.fromRGB(0,100,200), nightTint = Color3.fromRGB(0,150,255),
        dayAtmo = {0.4,0.15,Color3.fromRGB(0,80,160),Color3.fromRGB(0,30,80),0.1,0.5}, nightAtmo = {0.25,0.1,Color3.fromRGB(0,100,200),Color3.fromRGB(0,40,100),0.3,0.8},
    },
    Sakura = {
        asset = "10174567842", day = {2,-0.1,Color3.fromRGB(80,60,100),Color3.fromRGB(100,70,130)}, night = {4,0.08,Color3.fromRGB(60,40,70),Color3.fromRGB(80,50,100)},
        dayBloom = {0.25,35,0.85}, nightBloom = {0.5,42,0.7}, dayTint = Color3.fromRGB(200,100,150), nightTint = Color3.fromRGB(255,150,200),
        dayAtmo = {0.45,0.12,Color3.fromRGB(200,120,170),Color3.fromRGB(100,40,80),0.15,0.6}, nightAtmo = {0.3,0.08,Color3.fromRGB(255,160,210),Color3.fromRGB(140,60,100),0.4,1},
    },
    Moonlight = {
        asset = "9994573642", day = {2.8,0.02,Color3.fromRGB(180,130,160),Color3.fromRGB(200,150,180)}, night = {2.2,0.05,Color3.fromRGB(120,60,110),Color3.fromRGB(140,70,120)},
        dayBloom = {0.2,32,0.85}, nightBloom = {0.4,38,0.75}, dayTint = Color3.fromRGB(200,100,160), nightTint = Color3.fromRGB(255,120,200),
        dayAtmo = {0.45,0.1,Color3.fromRGB(220,120,200),Color3.fromRGB(160,60,130),0.5,1}, nightAtmo = {0.5,0.08,Color3.fromRGB(255,80,180),Color3.fromRGB(140,30,100),0.7,1.4},
    },
    Heaven = {
        asset = "9994573642", time = 12, all = {4.5,-0.02,Color3.fromRGB(250,245,230),Color3.fromRGB(255,250,240)}, bloom = {0.6,45,0.85}, tint = Color3.fromRGB(255,252,235),
        atmo = {0.2,0.05,Color3.fromRGB(255,252,235),Color3.fromRGB(255,245,215),3.5,1.2}, clouds = {0.9,0.4,Color3.fromRGB(255,255,255)},
    },
    ["Lavender Dream"] = {
