        atmo = {0.4,0.08,Color3.fromRGB(200,160,255),Color3.fromRGB(160,120,220),1.4,1.8}, clouds = {0.55,0.5,Color3.fromRGB(220,200,255)}, stars = 800,
    },
}
local function vx7SkyApply(mode)
    local preset = VX7SkyPresets[mode]
    if not preset then return end
    vx7SkySaveOriginals()
    vx7SkyClearCreated()
    local isNight = Lighting.ClockTime < 6 or Lighting.ClockTime > 18
    local base = preset.all or (isNight and preset.night or preset.day)
    pcall(function() Lighting.Technology = Enum.Technology.Future end)
    Lighting.Brightness = base[1]
    Lighting.ExposureCompensation = base[2]
    Lighting.Ambient = base[3]
    Lighting.OutdoorAmbient = base[4]
    if preset.time then Lighting.ClockTime = preset.time end
    local sky = vx7SkyAdd("Sky", "CustomSky", Lighting, {
        SkyboxBk = "rbxassetid://" .. preset.asset, SkyboxDn = "rbxassetid://" .. preset.asset,
        SkyboxFt = "rbxassetid://" .. preset.asset, SkyboxLf = "rbxassetid://" .. preset.asset,
        SkyboxRt = "rbxassetid://" .. preset.asset, SkyboxUp = "rbxassetid://" .. preset.asset,
    })
    if mode == "Moonlight" then sky.StarCount = 5000; sky.MoonAngularSize = 22; sky.MoonTextureId = "rbxasset://sky/moon.jpg" end
    if mode == "Heaven" then sky.SunAngularSize = 18; sky.StarCount = 0 end
    if mode == "Lavender Dream" then sky.StarCount = 800; sky.MoonAngularSize = 16; sky.MoonTextureId = "rbxasset://sky/moon.jpg" end
    local bloom = preset.bloom or (isNight and preset.nightBloom or preset.dayBloom)
    vx7SkyAdd("BloomEffect", "CustomBloom", Lighting, {Intensity=bloom[1], Size=bloom[2], Threshold=bloom[3]})
    local tint = preset.tint or (isNight and preset.nightTint or preset.dayTint)
    local ccProps
    if mode == "Cyber" then
        ccProps = isNight and {Brightness=0.05,Contrast=0.15,Saturation=0.2,TintColor=tint} or {Brightness=-0.08,Contrast=0.05,Saturation=0.1,TintColor=tint}
    elseif mode == "Sakura" then
        ccProps = isNight and {Brightness=0.03,Contrast=0.1,Saturation=0.25,TintColor=tint} or {Brightness=-0.05,Contrast=0.05,Saturation=0.15,TintColor=tint}
    elseif mode == "Moonlight" then
        ccProps = isNight and {Brightness=0.02,Contrast=0.08,Saturation=0.2,TintColor=tint} or {Brightness=-0.03,Contrast=0.05,Saturation=0.15,TintColor=tint}
    else
        ccProps = {Brightness=mode == "Heaven" and 0.02 or 0.02, Contrast=0.05, Saturation=mode == "Heaven" and 0.1 or 0.15, TintColor=tint}
    end
    vx7SkyAdd("ColorCorrectionEffect", "CustomCC", Lighting, ccProps)
    local atmo = preset.atmo or (isNight and preset.nightAtmo or preset.dayAtmo)
    vx7SkyAdd("Atmosphere", "CustomAtmo", Lighting, {Density=atmo[1],Offset=atmo[2],Color=atmo[3],Decay=atmo[4],Glare=atmo[5],Haze=atmo[6]})
    if preset.clouds then
        local terrain = workspace:FindFirstChildOfClass("Terrain")
        if terrain then vx7SkyAdd("Clouds", "CustomClouds", terrain, {Cover=preset.clouds[1],Density=preset.clouds[2],Color=preset.clouds[3]}) end
    end
    VX7Sky.mode = mode
    VX7VisualState.SkyMode = mode
end
local function vx7SkyRestore()
    vx7SkyClearCreated()
    local snapshot = VX7Sky.originals
    if not snapshot then return end
    for property, value in pairs(snapshot.props) do
        local restoreValue = value
        if property == "GlobalShadows" and _G.MoonHubVX7PotatoGraphicsActive then restoreValue = false end
        pcall(function() Lighting[property] = restoreValue end)
    end
    for _, item in ipairs(snapshot.objects) do
        if item.object and item.object.Parent == nil then pcall(function() item.object.Parent = item.parent end) end
    end
    VX7Sky.originals = nil
end
local function vx7SetSky(enabled)
    VX7Sky.enabled = enabled == true
    VX7VisualState.SkyEnabled = VX7Sky.enabled
    if VX7Sky.enabled then vx7SkyApply(VX7VisualState.SkyMode) else vx7SkyRestore() end
end

-- Camera FOV and Stretched Rez controls.
local vx7SavedFov = nil
local vx7FovBound = false
local vx7StretchBound = false
local function vx7ApplyCameraFov(value, referenceFov)
    local camera = workspace.CurrentCamera
    if not camera then return end
    pcall(function()
        local target = math.min(value, 120)
        camera.FieldOfView = target
        local focusPos, cameraPos = camera.Focus.Position, camera.CFrame.Position
        local delta = focusPos - cameraPos
        local magnitude = delta.Magnitude
        if magnitude > 0.001 then
            local ratio = value / (referenceFov or 70)
            camera.CFrame = CFrame.new(focusPos - delta.Unit * magnitude * ratio, focusPos)
        end
    end)
end
local function vx7SetFov(enabled)
    enabled = enabled == true
    VX7VisualState.FovEnabled = enabled
    if enabled then
        if workspace.CurrentCamera and not vx7SavedFov then vx7SavedFov = workspace.CurrentCamera.FieldOfView end
        if not vx7FovBound then
            RunService:BindToRenderStep("MoonHub_VX7_FOV", Enum.RenderPriority.Camera.Value + 1, function()
                if VX7VisualState.FovEnabled and not _G.MoonHubInstaResetInProgress then
                    vx7ApplyCameraFov(VX7VisualState.FovValue, vx7SavedFov)
                end
            end)
            vx7FovBound = true
        end
    else
        if vx7FovBound then pcall(function() RunService:UnbindFromRenderStep("MoonHub_VX7_FOV") end); vx7FovBound = false end
        if workspace.CurrentCamera and vx7SavedFov then pcall(function() workspace.CurrentCamera.FieldOfView = vx7SavedFov end) end
        vx7SavedFov = nil
    end
end
local function vx7SetStretch(enabled)
    enabled = enabled == true
    VX7VisualState.StretchEnabled = enabled
    if enabled then
        if not vx7StretchBound then
            RunService:BindToRenderStep("MoonHub_VX7_StretchRes", Enum.RenderPriority.Camera.Value + 1, function()
                if _G.MoonHubInstaResetInProgress then return end
                local camera = workspace.CurrentCamera
                if not camera then return end
                pcall(function()
                    camera.CFrame = camera.CFrame * CFrame.new(0, 0, 0, 1, 0, 0, 0, 0.7, 0, 0, 0, 1)
                    camera.FieldOfView = VX7VisualState.StretchFov
                end)
            end)
            vx7StretchBound = true
        end
    else
        if vx7StretchBound then pcall(function() RunService:UnbindFromRenderStep("MoonHub_VX7_StretchRes") end); vx7StretchBound = false end
        pcall(function() if workspace.CurrentCamera then workspace.CurrentCamera.FieldOfView = 70 end end)
    end
end

-- Speed displays from Moon Hub v8.1.3 (exact method):
-- 1) Local overhead: BillboardGui on Head → "MOON HUB" + "Speed: X.X"
-- 2) Enemy speed: BillboardGui on enemy Head → horizontal velocity number
local vx7SyncOpponentSpeed
do
    local speedLabel = nil
    local localSpeedConn = nil
    local localSpeedAcc = 0
    local enemySpeedLabels = {}
    local enemySpeedConn = nil
    local enemySpeedAcc = 0

    local function getLocalActiveSpeed()
        -- FIX: use this script's real speed (Normal/Carry/Lagger boxes), not State.* defaults
        if type(getActiveMoveSpeed) == "function" then
            local okS, realSpd = pcall(getActiveMoveSpeed)
            if okS and tonumber(realSpd) then return tonumber(realSpd) end
        end
        -- Prefer configured mode speed (same idea as v8.1.3 getActiveMoveSpeed / CarrySystem)
        local mode = currentSpeedMode or (State and State.SpeedMode) or "Normal"
        if mode == "Carry" then
            return tonumber(State and State.CarrySpeed) or 29
        elseif mode == "Lagger" then
            return tonumber(State and State.LaggerSpeed) or 45
        elseif mode == "Lagger Carry" then
            return tonumber(State and State.LaggerCarrySpeed) or 15
        end
        return tonumber(State and State.NormalSpeed) or 60
    end

    -- ============================================================
    -- LOCAL SPEED INDICATOR (exact v8.1.3 setupSpeedIndicator style)
    -- ============================================================
    local function setupSpeedIndicator(char)
        if not char then return end
        local head = char:FindFirstChild("Head") or char:WaitForChild("Head", 5)
        if not head then return end
        local oldBB = head:FindFirstChild("RaptureDuelSpeedIndicator")
            or head:FindFirstChild("MoonHubSpeedIndicator")
        if oldBB then oldBB:Destroy() end

        local theme = getThemeColor()
        local bb = Instance.new("BillboardGui")
        bb.Name = "MoonHubSpeedIndicator"
        bb.Size = UDim2.new(0, 220, 0, 140)
        bb.StudsOffset = Vector3.new(0, 3.6, 0)
        bb.AlwaysOnTop = true
        bb.Parent = head

        local title = Instance.new("TextLabel", bb)
        title.Name = "RaptureLinkLabel"
        title.Size = UDim2.new(1, 0, 0, 30)
        title.Position = UDim2.new(0, 0, 0, 0)
        title.BackgroundTransparency = 1
        title.Text = "MOON HUB"
        title.TextColor3 = theme
        title.Font = Enum.Font.GothamBlack
        title.TextSize = 34
        title.TextStrokeTransparency = 0
        title.TextStrokeColor3 = Color3.fromRGB(32, 24, 56)
        title.TextXAlignment = Enum.TextXAlignment.Center
        title.ZIndex = 5

        local best = Instance.new("TextLabel", bb)
        best.Name = "BestScripLabel"
        best.Size = UDim2.new(1, 0, 0, 22)
        best.Position = UDim2.new(0, 0, 0, 34)
        best.BackgroundTransparency = 1
        best.Text = ""
        best.Visible = false
        best.TextColor3 = theme
        best.Font = Enum.Font.GothamBold
        best.TextSize = 18
        best.TextStrokeTransparency = 0
        best.TextStrokeColor3 = Color3.fromRGB(32, 24, 56)
        best.TextXAlignment = Enum.TextXAlignment.Center
        best.ZIndex = 5

        speedLabel = Instance.new("TextLabel", bb)
        speedLabel.Name = "SpeedLabel"
        speedLabel.Size = UDim2.new(1, 0, 0, 28)
        speedLabel.Position = UDim2.new(0, 0, 0, 60)
        speedLabel.BackgroundTransparency = 1
        speedLabel.Text = "Speed: " .. string.format("%.1f", tonumber(getLocalActiveSpeed()) or 0)
        speedLabel.TextColor3 = theme
        speedLabel.Font = Enum.Font.GothamBold
        speedLabel.TextSize = 28
        speedLabel.TextStrokeTransparency = 0
        speedLabel.TextStrokeColor3 = Color3.fromRGB(32, 24, 56)
        speedLabel.ZIndex = 5
    end

    local function startLocalSpeedLoop()
        if localSpeedConn then localSpeedConn:Disconnect() end
        localSpeedAcc = 0
        local speedSig = RunService.PreSimulation or RunService.Heartbeat
        localSpeedConn = speedSig:Connect(function(dt)
            localSpeedAcc = localSpeedAcc + (typeof(dt) == "number" and dt or 0.016)
            if not speedLabel or not speedLabel.Parent then return end
            if localSpeedAcc < 0.12 then return end
            localSpeedAcc = 0
            local theme = getThemeColor()
            speedLabel.Text = "Speed: " .. string.format("%.1f", tonumber(getLocalActiveSpeed()) or 0)
            if speedLabel.TextColor3 ~= theme then speedLabel.TextColor3 = theme end
        end)
    end

    -- ============================================================
    -- ENEMY SPEED LABELS (exact v8.1.3 updateEnemySpeedLabels method)
    -- ============================================================
    local function clearOpponentDisplay(player)
        local label = enemySpeedLabels[player]
        if label then
            local bb = label.Parent
            if bb then pcall(function() bb:Destroy() end) end
        end
        enemySpeedLabels[player] = nil
    end

    local function clearAllOpponentDisplays()
        for player in pairs(enemySpeedLabels) do clearOpponentDisplay(player) end
    end

    local function updateEnemySpeedLabels()
        enemySpeedAcc = enemySpeedAcc + 1
        if enemySpeedAcc < 6 then return end
        enemySpeedAcc = 0
        local theme = getThemeColor()
        local players = Players:GetPlayers()
        for i = 1, #players do
            local player = players[i]
            if player ~= localPlayer then
                local char = player.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if hrp and hum and hum.Health > 0 then
                    local v = hrp.AssemblyLinearVelocity
                    local speed = math.sqrt(v.X * v.X + v.Z * v.Z)
                    local label = enemySpeedLabels[player]
                    local head = char:FindFirstChild("Head")
                    if label and (not label.Parent or not label.Parent.Parent or label.Parent.Parent ~= head) then
                        clearOpponentDisplay(player)
                        label = nil
                    end
                    if not label and head then
                        local bb = Instance.new("BillboardGui")
                        bb.Size = UDim2.new(0, 100, 0, 25)
                        bb.StudsOffset = Vector3.new(0, 5.5, 0)
                        bb.AlwaysOnTop = true
                        bb.Name = "EnemySpeedGui"
                        bb.Parent = head
                        local tl = Instance.new("TextLabel", bb)
                        tl.Size = UDim2.new(1, 0, 1, 0)
                        tl.BackgroundTransparency = 1
                        tl.TextColor3 = theme
                        tl.Font = Enum.Font.GothamBold
                        tl.TextScaled = true
                        tl.TextStrokeTransparency = 0
                        tl.TextStrokeColor3 = Color3.fromRGB(32, 24, 56)
                        enemySpeedLabels[player] = tl
                        label = tl
                    end
                    if label then
                        label.Text = string.format("%.1f", tonumber(speed) or 0)
                        if label.TextColor3 ~= theme then label.TextColor3 = theme end
                    end
                else
                    clearOpponentDisplay(player)
                end
            end
        end
    end

    local function startEnemySpeed()
        if enemySpeedConn then enemySpeedConn:Disconnect() end
        enemySpeedConn = RunService.Heartbeat:Connect(updateEnemySpeedLabels)
    end

    local function setupAll(char)
        setupSpeedIndicator(char)
        startLocalSpeedLoop()
        startEnemySpeed()
    end

    if localPlayer.Character then
        task.defer(function() setupAll(localPlayer.Character) end)
    end
    localPlayer.CharacterAdded:Connect(function(char)
        task.defer(function()
            task.wait(0.15)
            setupAll(char)
        end)
    end)

    vx7SyncOpponentSpeed = function()
        startEnemySpeed()
    end

    _G.MoonHubSpeedDisplayCleanup = function()
        if localSpeedConn then localSpeedConn:Disconnect(); localSpeedConn = nil end
        if enemySpeedConn then enemySpeedConn:Disconnect(); enemySpeedConn = nil end
        clearAllOpponentDisplays()
        speedLabel = nil
        local char = localPlayer.Character
        local head = char and char:FindFirstChild("Head")
        if head then
            local bb = head:FindFirstChild("MoonHubSpeedIndicator") or head:FindFirstChild("RaptureDuelSpeedIndicator")
            if bb then pcall(function() bb:Destroy() end) end
        end
    end
end

-- Player ESP: local Highlights on other players only.
local VX7Esp = { highlights = {}, characterConnections = {}, added = nil, removing = nil }
local function vx7ClearHighlight(player)
    local item = VX7Esp.highlights[player]
    if item then pcall(function() item:Destroy() end) end
    VX7Esp.highlights[player] = nil
end
local function vx7HighlightCharacter(player, character)
    vx7ClearHighlight(player)
    if not VX7VisualState.EspPlayerEnabled or player == localPlayer or not character then return end
    local highlight = Instance.new("Highlight")
    highlight.Name = "MoonHub_VX7_ESPPlayer"
    highlight.Adornee = character
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.FillTransparency = 0.78
    highlight.OutlineTransparency = 0.2
    highlight.FillColor = getThemeColor()
    highlight.OutlineColor = getThemeColor()
    pcall(function() highlight:SetAttribute("VX7ESP", true) end)
    highlight.Parent = character
    VX7Esp.highlights[player] = highlight
end
local function vx7WatchPlayer(player)
    if player == localPlayer then return end
    if VX7Esp.characterConnections[player] then pcall(function() VX7Esp.characterConnections[player]:Disconnect() end) end
    if player.Character then vx7HighlightCharacter(player, player.Character) end
    VX7Esp.characterConnections[player] = player.CharacterAdded:Connect(function(character)
        task.wait(0.1)
        vx7HighlightCharacter(player, character)
    end)
end
local function vx7SetPlayerEsp(enabled)
    VX7VisualState.EspPlayerEnabled = enabled == true
    vx7SyncOpponentSpeed()
    if enabled then
        for _, player in ipairs(Players:GetPlayers()) do vx7WatchPlayer(player) end
        if not VX7Esp.added then VX7Esp.added = Players.PlayerAdded:Connect(vx7WatchPlayer) end
        if not VX7Esp.removing then
            VX7Esp.removing = Players.PlayerRemoving:Connect(function(player)
                vx7ClearHighlight(player)
                local connection = VX7Esp.characterConnections[player]
                if connection then pcall(function() connection:Disconnect() end) end
                VX7Esp.characterConnections[player] = nil
            end)
        end
    else
        if VX7Esp.added then VX7Esp.added:Disconnect(); VX7Esp.added = nil end
        if VX7Esp.removing then VX7Esp.removing:Disconnect(); VX7Esp.removing = nil end
        for player, connection in pairs(VX7Esp.characterConnections) do pcall(function() connection:Disconnect() end); VX7Esp.characterConnections[player] = nil end
        for player in pairs(VX7Esp.highlights) do vx7ClearHighlight(player) end
    end
end

-- ESP Lines: one lightweight ScreenGui and one RenderStep updater.
local VX7LineEsp = { gui = nil, lines = {}, added = nil, removing = nil, bound = false }
local function vx7EnsureLine(player)
    if player == localPlayer or VX7LineEsp.lines[player] then return end
    local playerGui = localPlayer:FindFirstChildOfClass("PlayerGui") or localPlayer:WaitForChild("PlayerGui")
    if not VX7LineEsp.gui or not VX7LineEsp.gui.Parent then
        VX7LineEsp.gui = Instance.new("ScreenGui")
        VX7LineEsp.gui.Name = "MoonHub_VX7_ESPLine"
        VX7LineEsp.gui.ResetOnSpawn = false
        VX7LineEsp.gui.IgnoreGuiInset = true
        VX7LineEsp.gui.DisplayOrder = 5
        VX7LineEsp.gui.ZIndexBehavior = Enum.ZIndexBehavior.Global
        VX7LineEsp.gui.Parent = playerGui
    end
    local line = Instance.new("Frame")
    line.Name = "Line_" .. tostring(player.UserId)
    line.AnchorPoint = Vector2.new(0.5, 0.5)
    line.BackgroundColor3 = getThemeColor()
    line.BorderSizePixel = 0
    line.Size = UDim2.fromOffset(1, 1)
    line.Visible = false
    line.ZIndex = 3
    line.Parent = VX7LineEsp.gui
    VX7LineEsp.lines[player] = line
end
local function vx7SetLineEsp(enabled)
    enabled = false
    VX7VisualState.EspLinesEnabled = false
    vx7SyncOpponentSpeed()
    if enabled then
        for _, player in ipairs(Players:GetPlayers()) do vx7EnsureLine(player) end
        if not VX7LineEsp.added then VX7LineEsp.added = Players.PlayerAdded:Connect(vx7EnsureLine) end
        if not VX7LineEsp.removing then
            VX7LineEsp.removing = Players.PlayerRemoving:Connect(function(player)
                local line = VX7LineEsp.lines[player]
                if line then pcall(function() line:Destroy() end) end
                VX7LineEsp.lines[player] = nil
            end)
        end
        if not VX7LineEsp.bound then
            RunService:BindToRenderStep("MoonHub_VX7_ESPLine", Enum.RenderPriority.Last.Value, function()
                if not VX7VisualState.EspLinesEnabled then return end
                local camera = workspace.CurrentCamera
                if not camera then return end
                local viewport = camera.ViewportSize
                local origin = Vector2.new(viewport.X / 2, viewport.Y)
                if VX7VisualState.EspLineOrigin == "Top" then origin = Vector2.new(viewport.X / 2, 0)
                elseif VX7VisualState.EspLineOrigin == "Middle" then origin = Vector2.new(viewport.X / 2, viewport.Y / 2) end
                for player, line in pairs(VX7LineEsp.lines) do
                    local character = player.Character
                    local root = character and (character:FindFirstChild("HumanoidRootPart") or character:FindFirstChild("Head"))
                    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
                    if root and humanoid and humanoid.Health > 0 then
                        local point, onScreen = camera:WorldToViewportPoint(root.Position)
                        if point.Z > 0 and onScreen then
                            local target = Vector2.new(point.X, point.Y)
                            local delta = target - origin
                            line.Position = UDim2.fromOffset((target.X + origin.X) * 0.5, (target.Y + origin.Y) * 0.5)
                            line.Size = UDim2.fromOffset(math.max(delta.Magnitude, 1), 2)
                            line.Rotation = math.deg(math.atan2(delta.Y, delta.X))
                            line.BackgroundColor3 = getThemeColor()
                            line.Visible = true
                        else
                            line.Visible = false
                        end
                    else
                        line.Visible = false
                    end
                end
            end)
            VX7LineEsp.bound = true
        end
    else
        if VX7LineEsp.added then VX7LineEsp.added:Disconnect(); VX7LineEsp.added = nil end
        if VX7LineEsp.removing then VX7LineEsp.removing:Disconnect(); VX7LineEsp.removing = nil end
        if VX7LineEsp.bound then pcall(function() RunService:UnbindFromRenderStep("MoonHub_VX7_ESPLine") end); VX7LineEsp.bound = false end
        for player, line in pairs(VX7LineEsp.lines) do pcall(function() line:Destroy() end); VX7LineEsp.lines[player] = nil end
        if VX7LineEsp.gui then pcall(function() VX7LineEsp.gui:Destroy() end); VX7LineEsp.gui = nil end
    end
end


