    if nextIndex < 1 then nextIndex = #OUTFITS end
    if nextIndex > #OUTFITS then nextIndex = 1 end
    currentOutfitIndex = nextIndex
    pcall(applyOutfitByIndex, currentOutfitIndex)
    moonOutfitLabel.Text = OUTFITS[currentOutfitIndex].label
    if _G.MoonSave and _G.MoonSave.markDirty then pcall(_G.MoonSave.markDirty) end
end
moonOutfitLeft.Activated:Connect(function() moonOutfitChange(-1) end)
moonOutfitRight.Activated:Connect(function() moonOutfitChange(1) end)
if _G.MoonSave then
    _G.MoonSave.register("V:Outfit", function() return currentOutfitIndex end, function(v)
        v = math.floor(tonumber(v) or 1)
        if not OUTFITS[v] then v = 1 end -- unknown / old saved value -> OFF
        currentOutfitIndex = v
        pcall(applyOutfitByIndex, v)
        moonOutfitLabel.Text = OUTFITS[v].label
    end, 60)
    _G.MoonSave.register("V:VX7 Avatar", function() return VX7A and VX7A.index or 0 end, function(v)
        v = tonumber(v)
        -- VX7 skins removed
    end, 61)
end

        end
        local okV, errV = pcall(MoonVisualBuild, visualPage, mkSect, mkRow, mkLabel, mkToggle, mkPill, animPill, getNextOrder)
        if not okV then warn("[MoonHub] Visual tab error: " .. tostring(errV)) end
    end

    local configPage = contentPages["Settings"]

    local function mkStepperRow(page, labelText, minV, maxV, default, onChange)
        local row = mkRow(page, 42)
        mkLabel(row, labelText)
        local value = _clamp(_floor(tonumber(default) or minV), minV, maxV)

        local function mkStepBtn(txt, xOff)
            local b = Instance.new("TextButton", row)
            b.Size = UDim2.new(0, 26, 0, 24)
            b.Position = UDim2.new(1, xOff, 0.5, -12)
            b.BackgroundColor3 = Color3.fromRGB(30, 30, 35)
            b.BackgroundTransparency = 0.3
            b.BorderSizePixel = 0
            b.Text = txt
            b.TextColor3 = WHITE
            b.Font = Enum.Font.GothamBold
            b.TextSize = 18
            b.AutoButtonColor = false
            b.ZIndex = 9
            Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
            return b
        end
        local minus = mkStepBtn("-", -120)
        local plus = mkStepBtn("+", -34)

        local valLabel = Instance.new("TextLabel", row)
        valLabel.Size = UDim2.new(0, 52, 0, 24)
        valLabel.Position = UDim2.new(1, -90, 0.5, -12)
        valLabel.BackgroundTransparency = 1
        valLabel.Text = tostring(value) .. "%"
        valLabel.TextColor3 = WHITE
        valLabel.Font = Enum.Font.GothamBold
        valLabel.TextSize = 12
        valLabel.ZIndex = 9

        local function apply(v, force)
            v = _clamp(_floor(tonumber(v) or value), minV, maxV)
            if v == value and not force then return end
            value = v
            valLabel.Text = tostring(value) .. "%"
            if onChange then pcall(onChange, value) end
        end

        minus.MouseButton1Click:Connect(function() apply(value - 1) end)
        plus.MouseButton1Click:Connect(function() apply(value + 1) end)
        if _G.MoonSave then
            _G.MoonSave.register("S:" .. labelText, function() return value end, function(v)
                if tonumber(v) then apply(v, true) end
            end, 15)
        end
        return apply, valLabel
    end

    mkSect(configPage, "Interface")

    local setMenuSize = mkStepperRow(configPage, "Menu Size", 50, 130, uiScaleValue or 91, function(v)
        uiScaleValue = v
        if mainUIScale then mainUIScale.Scale = v / 100 end
    end)

    local setMobileSize = mkStepperRow(configPage, "Mobile Buttons Size", 50, 150, _floor((floatingButtonScale or 1) * 100 + 0.5), function(v)
        floatingButtonScale = v / 100
