    -- Mobile Button Shape (under Lock) — Square / Rounded / Circle
    do
        local styles = {"Square", "Rounded", "Circle"}
        local row = mkRow(configPage, 42)
        mkLabel(row, "Mobile Button Style")
        local function mkArrowPick(parent, width, getText, onStep)
            local box = Instance.new("Frame", parent)
            box.Size = UDim2.new(0, width, 1, 0)
            box.Position = UDim2.new(1, -(width + 8), 0, 0)
            box.BackgroundTransparency = 1
            box.ZIndex = 8
            local lbl = Instance.new("TextLabel", box)
            lbl.Size = UDim2.new(1, -60, 0, 26)
            lbl.Position = UDim2.new(0, 30, 0.5, -13)
            lbl.BackgroundTransparency = 1
            lbl.Text = getText()
            lbl.TextColor3 = WHITE
            lbl.Font = Enum.Font.GothamBold
            lbl.TextSize = 11
            lbl.ZIndex = 9
            local function mk(glyph, x, dir)
                local b = Instance.new("TextButton", box)
                b.Size = UDim2.new(0, 28, 0, 26)
                b.Position = UDim2.new(0, x, 0.5, -13)
                b.BackgroundColor3 = INP
                b.BackgroundTransparency = 0.7
                b.BorderSizePixel = 0
                b.Text = glyph
                b.TextColor3 = WHITE
                b.Font = Enum.Font.GothamBold
                b.TextSize = 13
                b.AutoButtonColor = false
                b.ZIndex = 9
                Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
                b.Activated:Connect(function()
                    onStep(dir)
                    lbl.Text = getText()
                end)
            end
            mk("<", 0, -1)
            mk(">", width - 28, 1)
            return lbl
        end
        _G.MoonSaveRefs.styleLbl = mkArrowPick(row, 120, function()
            return tostring(mobileButtonStyle or "Rounded")
        end, function(dir)
            local cur = mobileButtonStyle or "Rounded"
            local idx = 1
            for i, s in ipairs(styles) do
                if s == cur then idx = i break end
            end
            idx = (idx - 1 + dir) % #styles + 1
            mobileButtonStyle = styles[idx]
            if type(applyMobileButtonShape) == "function" then
                pcall(applyMobileButtonShape)
            end
        end)
        if _G.MoonSave then
            _G.MoonSave.register("V:Mobile Button Style", function() return mobileButtonStyle end, function(v)
                if table.find(styles, v) then
                    mobileButtonStyle = v
                    if type(applyMobileButtonShape) == "function" then pcall(applyMobileButtonShape) end
                    local l = _G.MoonSaveRefs.styleLbl
                    if l then l.Text = v end
                end
            end, 15)
        end
    end

    setLockUIVisual = mkToggle(configPage, "Lock", function(on)
        if type(toggleLockUI) == "function" then
            pcall(toggleLockUI, on == true)
        else
            uiLocked = on == true
        end
    end)

    local setSkipIntroVisual = mkToggle(configPage, "Skip Intro", function(on)
        if type(_rivalSaveSkipIntroFlag) == "function" then
            _rivalSaveSkipIntroFlag(on == true)
        else
