            { key = "Aimbot", label = "Auto Bat" },
            { key = "AutoRight", label = "Auto Right" },
            { key = "TpDown", label = "TP Down" },
            { key = "Carry", label = "Carry Speed" },
            { key = "Lagger1", label = "Lagger Carry" },
            { key = "Lagger2", label = "Lagger Normal" },
            { key = "InstantReset", label = "Instant Reset" },
            { key = "AimbotBypass", label = "Aimbot Bypass" },
        }
