        local hmList = Instance.new("UIListLayout")
        hmList.Padding = UDim.new(0, GAP)
        hmList.SortOrder = Enum.SortOrder.LayoutOrder
        hmList.HorizontalAlignment = Enum.HorizontalAlignment.Center
        hmList.Parent = hmHolder

        local hmPad = Instance.new("UIPadding")
        hmPad.PaddingTop = UDim.new(0, 4)
        hmPad.Parent = hmHolder

        local function expandHolder(open)
            local info = TweenInfo.new(0.22, Enum.EasingStyle.Quart, open and Enum.EasingDirection.Out or Enum.EasingDirection.In)
            local sx, ox = hmHolder.Size.X.Scale, hmHolder.Size.X.Offset
            hmHolder:SetAttribute("_expandToken", (hmHolder:GetAttribute("_expandToken") or 0) + 1)
            local token = hmHolder:GetAttribute("_expandToken")
            if open then
                hmHolder.Visible = true
                if hmHolder.Size.Y.Offset >= HOLDER_H then
                    hmHolder.Size = UDim2.new(sx, ox, 0, 0)
                end
                TS:Create(hmHolder, info, { Size = UDim2.new(sx, ox, 0, HOLDER_H) }):Play()
            else
                local tw = TS:Create(hmHolder, info, { Size = UDim2.new(sx, ox, 0, 0) })
                tw.Completed:Connect(function()
                    if hmHolder and hmHolder.Parent and hmHolder:GetAttribute("_expandToken") == token then
                        hmHolder.Visible = false
                    end
                end)
                tw:Play()
            end
        end

        for i, item in ipairs(HIDE_ITEMS) do
            local r = Instance.new("Frame")
            r.Name = "HideOpt_" .. item.key
            r.BackgroundColor3 = Color3.fromRGB(28, 30, 38)
            r.BackgroundTransparency = 0.35
            r.Size = UDim2.new(1, -8, 0, ROW_H)
            r.BorderSizePixel = 0
            r.LayoutOrder = i
            r.ZIndex = 8
            r.Parent = hmHolder
            Instance.new("UICorner", r).CornerRadius = UDim.new(0, 8)

            local lbl = Instance.new("TextLabel")
            lbl.BackgroundTransparency = 1
            lbl.Text = item.label
            lbl.TextColor3 = Color3.fromRGB(255, 255, 255)
            lbl.TextSize = 12
            lbl.Font = Enum.Font.GothamSemibold
            lbl.TextXAlignment = Enum.TextXAlignment.Left
            lbl.Position = UDim2.new(0, 12, 0, 0)
            lbl.Size = UDim2.new(1, -70, 1, 0)
            lbl.ZIndex = 9
            lbl.Parent = r

            local startOn = _G.RivalHubMobileHideList[item.key]
            if startOn == nil then startOn = true end

            local track = Instance.new("Frame")
            track.Name = "Track"
            track.BackgroundColor3 = startOn and Color3.fromRGB(0, 132, 255) or Color3.fromRGB(225, 55, 55)
            track.Size = UDim2.new(0, 42, 0, 20)
            track.Position = UDim2.new(1, -52, 0.5, -10)
            track.BorderSizePixel = 0
            track.ZIndex = 9
            track.Parent = r
            Instance.new("UICorner", track).CornerRadius = UDim.new(1, 0)

            local knob = Instance.new("Frame")
            knob.Name = "Knob"
            knob.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            knob.Size = UDim2.new(0, 16, 0, 16)
            knob.Position = startOn and UDim2.new(1, -18, 0.5, -8) or UDim2.new(0, 2, 0.5, -8)
            knob.BorderSizePixel = 0
            knob.ZIndex = 10
            knob.Parent = track
            Instance.new("UICorner", knob).CornerRadius = UDim.new(1, 0)

            local function paint(on)
                on = on and true or false
                TS:Create(track, TweenInfo.new(0.15), {
                    BackgroundColor3 = on and Color3.fromRGB(0, 132, 255) or Color3.fromRGB(225, 55, 55)
                }):Play()
                TS:Create(knob, TweenInfo.new(0.15), {
                    Position = on and UDim2.new(1, -18, 0.5, -8) or UDim2.new(0, 2, 0.5, -8)
                }):Play()
            end

            local hit = Instance.new("TextButton")
            hit.BackgroundTransparency = 1
            hit.Size = UDim2.fromScale(1, 1)
            hit.Text = ""
            hit.ZIndex = 11
            hit.Parent = r
            hit.MouseButton1Click:Connect(function()
                local on = not (_G.RivalHubMobileHideList[item.key] ~= false)
                _G.RivalHubMobileHideList[item.key] = on
                paint(on)
                applyHideButtons(hideButtonsEnabled)
                if _G.MoonSave then _G.MoonSave.markDirty() end
            end)
            paint(startOn)
            _G.MoonSaveRefs.hidePainters[item.key] = paint
        end
        if _G.MoonSave then
            _G.MoonSave.register("V:Hide Mobile List", function()
                local out = {}
                for _, it in ipairs(HIDE_ITEMS) do
                    out[it.key] = _G.RivalHubMobileHideList[it.key] ~= false
                end
                return out
            end, function(t)
                if type(t) ~= "table" then return end
                for _, it in ipairs(HIDE_ITEMS) do
                    if t[it.key] ~= nil then
                        local on = t[it.key] == true
                        _G.RivalHubMobileHideList[it.key] = on
                        local p = _G.MoonSaveRefs.hidePainters[it.key]
                        if p then pcall(p, on) end
                    end
                end
                if type(applyHideButtons) == "function" then pcall(applyHideButtons, hideButtonsEnabled) end
            end, 15)
        end

        if hideRow then
            local hmArrow = Instance.new("TextButton")
            hmArrow.Name = "HideMobileArrow"
            hmArrow.BackgroundColor3 = Color3.fromRGB(20, 20, 28)
            hmArrow.BackgroundTransparency = 0.15
            hmArrow.BorderSizePixel = 0
