    local function mkFullBtn(parent, text, textColor)
        local row = mkRow(parent, 44)
        row.Size = UDim2.new(1, 0, 0, 44)
        local btn = Instance.new("TextButton", row)
        btn.Size = UDim2.new(1, -12, 0.8, 0)
        btn.Position = UDim2.new(0, 6, 0.1, 0)
        local BLUE = Color3.fromRGB(0, 132, 255)
        local BG = Color3.fromRGB(18, 28, 42)
        btn.BackgroundColor3 = BG
        btn.BorderSizePixel = 0
        btn.Text = text
        btn.TextColor3 = textColor or Color3.fromRGB(230, 240, 255)
        btn.Font = Enum.Font.GothamBold
        btn.TextSize = 13
        btn.AutoButtonColor = false
        btn.ZIndex = 8
        Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 10)
        local stroke = Instance.new("UIStroke", btn)
        stroke.Color = BLUE
        stroke.Thickness = 1.5
        stroke.Transparency = 0.35
        btn.MouseEnter:Connect(function()
            btn.BackgroundColor3 = BLUE
            btn.TextColor3 = Color3.fromRGB(255, 255, 255)
        end)
        btn.MouseLeave:Connect(function()
            btn.BackgroundColor3 = BG
            btn.TextColor3 = textColor or Color3.fromRGB(230, 240, 255)
        end)
        return btn
    end

    -- Apply loaded config toggles (Moon Hub save)
    do
        local pend = _G._MoonHubPendingConfig
        if type(pend) == "table" and pend.Loaded and type(pend.Toggles) == "table" then
            local T = pend.Toggles
            if T["Anti Bat"] == true and type(startAntiBat) == "function" then
                pcall(startAntiBat)
                if setAntiBatVisual then pcall(setAntiBatVisual, true) end
            end
            if false and type(startAntiFling) == "function" then
                antiFlingEnabled = true
                pcall(startAntiFling)
                if setAntiFlingVisual then pcall(setAntiFlingVisual, true) end
            end
            if T["Anti Die"] == true then
                antiDieEnabled = true
                if setAntiDieVisual then pcall(setAntiDieVisual, true) end
                if AntiDieModule and AntiDieModule.start then pcall(AntiDieModule.start) end
            end
            if _G.AmbitiousTPRagdollEnabled == true and _G.AmbitiousTPRagdoll and _G.AmbitiousTPRagdoll.set then
                pcall(_G.AmbitiousTPRagdoll.set, true)
                if _G._RivalSetTPRagdollVisual then pcall(_G._RivalSetTPRagdollVisual, true) end
            end
            if type(antiRagdollMode) == "string" and antiRagdollMode ~= "off" and type(setAntiRagdollMode) == "function" then
                pcall(setAntiRagdollMode, antiRagdollMode)
                if _G.updateAntiRagdollUI then pcall(_G.updateAntiRagdollUI, antiRagdollMode) end
            end
            if hideButtonsEnabled == true and type(toggleHideButtons) == "function" then
                pcall(toggleHideButtons, true)
                if setHideButtonsVisual then pcall(setHideButtonsVisual, true) end
            end
            if mainUIScale and tonumber(uiScaleValue) then
                mainUIScale.Scale = uiScaleValue / 100
            end
            if type(applyFloatingButtonScale) == "function" then pcall(applyFloatingButtonScale) end
            if type(applyMobileButtonShape) == "function" then pcall(applyMobileButtonShape) end
            if pbScale and tonumber(stealBarScaleValue) then pbScale.Scale = stealBarScaleValue / 100 end
            if type(_G.RivalHubRefreshKeybinds) == "function" then pcall(_G.RivalHubRefreshKeybinds) end
        end
    end

    -- Auto-save is active (Moon Hub config)


    local resetMobBtn = mkFullBtn(configPage, "RESET MOBILE BUTTONS")
    resetMobBtn.MouseButton1Click:Connect(function()
        pcall(function()
            if type(resetMobileButtonPositions) == "function" then
                resetMobileButtonPositions()
            elseif type(_G.RivalHubResetMobileButtons) == "function" then
                _G.RivalHubResetMobileButtons()
            end
