        resetMobBtn.Text = "DONE"
        task.delay(1.0, function()
            if resetMobBtn and resetMobBtn.Parent then resetMobBtn.Text = "RESET MOBILE BUTTONS" end
        end)
    end)

    -- RESET SETTINGS: the whole script goes back to first-run state (save file deleted)
    local _resetLayoutConfirm = false
    local _resetLayoutTimer = nil
    local resetLayoutBtn = mkFullBtn(configPage, "RESET SETTINGS")
    resetLayoutBtn.MouseButton1Click:Connect(function()
        if not _resetLayoutConfirm then
            _resetLayoutConfirm = true
            resetLayoutBtn.Text = "CLICK AGAIN TO CONFIRM"
            if _resetLayoutTimer then task.cancel(_resetLayoutTimer) end
            _resetLayoutTimer = task.delay(3, function()
                _resetLayoutConfirm = false
                if resetLayoutBtn and resetLayoutBtn.Parent then
                    resetLayoutBtn.Text = "RESET SETTINGS"
                end
            end)
            return
        end
        if _resetLayoutTimer then task.cancel(_resetLayoutTimer); _resetLayoutTimer = nil end
        _resetLayoutConfirm = false
        resetLayoutBtn.Text = "RESETTING..."
        local ok, err = false, "save system not loaded"
        if _G.MoonSave and type(_G.MoonSave.resetAll) == "function" then
            local callOK, result = pcall(_G.MoonSave.resetAll)
            ok = callOK and result == true
            if not callOK then err = result
            elseif result ~= true then err = "reset or disk save failed" end
        end
        if not ok then warn("[Moon Hub] Reset Settings: " .. tostring(err)) end
        resetLayoutBtn.Text = ok and "DONE" or "RESET FAILED"
        task.delay(1.2, function()
            if resetLayoutBtn and resetLayoutBtn.Parent then
                resetLayoutBtn.Text = "RESET SETTINGS"
            end
        end)
    end)

