    -- Keep all five pages separate; each top tab owns its own controls.

    pbFrame = Instance.new("Frame", gui)
    pbFrame.Name = "RivalHubAutoStealHud"
    -- Moon Hub Auto Steal bar dimensions
    local BAR_W, BAR_H = 560, 86
    pbFrame.Size = UDim2.new(0, BAR_W, 0, BAR_H)
    pbFrame.AnchorPoint = Vector2.new(0.5, 1)
    pbFrame.Position = UDim2.new(0.5, 0, 1, -32)
    pbFrame.BackgroundColor3 = Color3.fromRGB(32, 24, 56)
    pbFrame.BackgroundTransparency = 0
    pbFrame.BorderSizePixel = 0
    pbFrame.Active = true
    pbFrame.Visible = false
