    pbScale = Instance.new("UIScale", pbFrame)
    pbScale.Scale = (tonumber(stealBarScaleValue) or 81) / 100
    -- Moon Hub logo background on bar
    pcall(function()
        local barBg = Instance.new("ImageLabel", pbFrame)
        barBg.Name = "MoonHubBackgroundImage"
        barBg.Size = UDim2.new(1, 0, 1, 0)
        barBg.BackgroundTransparency = 1
        barBg.Image = _G.RivalHubLogoAsset or "rbxassetid://110245528345873"
        barBg.ImageTransparency = 0
        barBg.ScaleType = Enum.ScaleType.Crop
        barBg.ZIndex = 501
        barBg.Active = false
        Instance.new("UICorner", barBg).CornerRadius = UDim.new(0, 32)
        local shade = Instance.new("Frame", pbFrame)
        shade.Name = "ReadabilityShade"
        shade.Size = UDim2.new(1, 0, 1, 0)
        shade.BackgroundColor3 = Color3.fromRGB(32, 24, 56)
        shade.BackgroundTransparency = 1
        shade.BorderSizePixel = 0
        shade.ZIndex = 502
        Instance.new("UICorner", shade).CornerRadius = UDim.new(0, 32)
    end)

    -- Moon Hub exact bar layout (title + FPS + PING + %)
    local hudTitle = Instance.new("TextLabel", pbFrame)
    hudTitle.Name = "AutoStealTitle"
    hudTitle.Size = UDim2.new(0, 220, 0, 22)
    hudTitle.Position = UDim2.new(0, 16, 0, 3)
    hudTitle.BackgroundTransparency = 1
    hudTitle.Text = "AUTO STEAL"
    hudTitle.TextColor3 = Color3.fromRGB(255, 255, 255)
    hudTitle.TextStrokeColor3 = Color3.fromRGB(32, 24, 56)
    hudTitle.TextStrokeTransparency = 0
    hudTitle.Font = Enum.Font.GothamBlack
    hudTitle.TextSize = 22
    hudTitle.TextXAlignment = Enum.TextXAlignment.Left
    hudTitle.ZIndex = 510

    local fpsLabel = Instance.new("TextLabel", pbFrame)
    fpsLabel.Name = "FPSLabel"
    fpsLabel.Size = UDim2.new(0, 150, 0, 20)
    fpsLabel.Position = UDim2.new(0, 16, 0, 26)
    fpsLabel.BackgroundTransparency = 1
    fpsLabel.Text = "FPS: --"
    fpsLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    fpsLabel.TextStrokeColor3 = Color3.fromRGB(32, 24, 56)
    fpsLabel.TextStrokeTransparency = 0
    fpsLabel.Font = Enum.Font.GothamBold
    fpsLabel.TextSize = 20
    fpsLabel.TextXAlignment = Enum.TextXAlignment.Left
    fpsLabel.ZIndex = 510

    local pingLabel = Instance.new("TextLabel", pbFrame)
    pingLabel.Name = "PingLabel"
    pingLabel.Size = UDim2.new(0, 170, 0, 20)
    pingLabel.Position = UDim2.new(0, 160, 0, 26)
    pingLabel.BackgroundTransparency = 1
    pingLabel.Text = "PING: --"
    pingLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    pingLabel.TextStrokeColor3 = Color3.fromRGB(32, 24, 56)
    pingLabel.TextStrokeTransparency = 0
    pingLabel.Font = Enum.Font.GothamBold
    pingLabel.TextSize = 20
    pingLabel.TextXAlignment = Enum.TextXAlignment.Left
    pingLabel.ZIndex = 510

    progressPct = Instance.new("TextLabel", pbFrame)
    progressPct.Name = "ProgressPercent"
    progressPct.Size = UDim2.new(0, 80, 0, 20)
    progressPct.Position = UDim2.new(1, -96, 0, 26)
    progressPct.BackgroundTransparency = 1
    progressPct.Text = "0%"
    progressPct.TextColor3 = Color3.fromRGB(255, 255, 255)
    progressPct.TextStrokeColor3 = Color3.fromRGB(32, 24, 56)
    progressPct.TextStrokeTransparency = 0
    progressPct.Font = Enum.Font.GothamBlack
    progressPct.TextSize = 20
    progressPct.TextXAlignment = Enum.TextXAlignment.Right
    progressPct.ZIndex = 510

    progressStatus = fpsLabel -- keep ref used by updateStealProgress for status text optional
    infoLabel = pingLabel

    local stealTrack = Instance.new("Frame", pbFrame)
    stealTrack.Name = "ProgressTrack"
    stealTrack.Size = UDim2.new(1, -32, 0, 12)
    stealTrack.Position = UDim2.new(0, 16, 1, -22)
    stealTrack.BackgroundColor3 = Color3.fromRGB(20, 16, 38)
    stealTrack.BackgroundTransparency = 0.12
    stealTrack.BorderSizePixel = 0
    stealTrack.ClipsDescendants = true
    stealTrack.ZIndex = 510
    Instance.new("UICorner", stealTrack).CornerRadius = UDim.new(0, 8)

    progressFill = Instance.new("Frame", stealTrack)
    progressFill.Name = "ProgressFill"
    progressFill.Size = UDim2.new(0, 0, 1, 0)
    progressFill.BackgroundColor3 = (getThemeColor and getThemeColor()) or Color3.fromRGB(80, 150, 255)
    progressFill.BorderSizePixel = 0
    progressFill.ZIndex = 511
    Instance.new("UICorner", progressFill).CornerRadius = UDim.new(0, 8)

    -- FPS + Ping live update (Moon Hub style)
    do
        local fpsValue, frameCount, sampleStart = 0, 0, os.clock()
        RunService.RenderStepped:Connect(function()
            frameCount = frameCount + 1
            local now = os.clock()
            local elapsed = now - sampleStart
            if elapsed >= 0.5 then
                fpsValue = frameCount / elapsed
                frameCount = 0
                sampleStart = now
            end
        end)
        task.spawn(function()
            while pbFrame and pbFrame.Parent do
                local ping = 0
                pcall(function() ping = LP:GetNetworkPing() * 1000 end)
                if fpsLabel and fpsLabel.Parent then
                    fpsLabel.Text = string.format("FPS: %d", math.floor(fpsValue + 0.5))
                end
                if pingLabel and pingLabel.Parent then
                    pingLabel.Text = string.format("PING: %d", math.floor(ping + 0.5))
                end
                task.wait(0.5)
            end
        end)
    end

    drag(pbFrame)
    -- Restore last saved Auto Steal bar position (if any)
    if savedProgressBarPos then
        pcall(function()
            pbFrame.Position = savedProgressBarPos
        end)
    elseif _G.MoonSave and _G.MoonSave.get then
        local tpos = _G.MoonSave.get("P:Steal Bar")
        if type(tpos) == "table" then
            local xs, xo = tonumber(tpos.xs), tonumber(tpos.xo)
            local ys, yo = tonumber(tpos.ys), tonumber(tpos.yo)
            if xs and xo and ys and yo then
                savedProgressBarPos = UDim2.new(xs, xo, ys, yo)
                pbFrame.Position = savedProgressBarPos
            end
        end
    end

end

do
    local BAV2_ANG = "_GB_AngV"
    local BAV2_ATT = "_GB_Att"
    local BAV2_CLEAN = {
        "LockBAV","LockAngVel","LockBodyAtt","BatLock","LockBAVAtt",
        "AutoBatAtt","AutoBatAV","AntiBatDet","AntiAim","VelocityLock"
    }

    local V2 = {
        enabled = false,
        conn = nil,
        safetyConn = nil,
        target = nil,
        equipped = false,
        intendedVelocity = Vector3.zero,
        attachment = nil,
        angularVelocity = nil,
        speed = 58,
        swingRange = 12,
    }
    _G.__RivalHubBatV2 = V2

    local function cleanMovers(root)
        if not root then return end
        pcall(function()
            for _, n in ipairs(BAV2_CLEAN) do
                local c = root:FindFirstChild(n)
                if c then c:Destroy() end
            end
            for _, child in ipairs(root:GetChildren()) do
                if child.Name ~= BAV2_ANG and child.Name ~= BAV2_ATT then
                    local ln = child.Name:lower()
                    if ln:find("lockb") or ln:find("lockangv")
                       or ln:find("batlock") or ln:find("antiaim")
                       or ln:find("velocitylock") then
                        child:Destroy()
                    end
                end
            end
        end)
    end

    local function ensureAngular(root)
        if not root then return end
        pcall(function()
            local a = root:FindFirstChild(BAV2_ANG); if a then a:Destroy() end
            local b = root:FindFirstChild(BAV2_ATT); if b then b:Destroy() end
        end)
        local att = Instance.new("Attachment")
        att.Name = BAV2_ATT
        att.Parent = root
        local angV = Instance.new("AngularVelocity")
        angV.Name = BAV2_ANG
        angV.Attachment0 = att
        angV.RelativeTo = Enum.ActuatorRelativeTo.World
        angV.MaxTorque = math.huge
        angV.AngularVelocity = Vector3.zero
        angV.Parent = root
        V2.attachment = att
        V2.angularVelocity = angV
    end

    local function removeAngular()
        pcall(function() if V2.angularVelocity and V2.angularVelocity.Parent then V2.angularVelocity:Destroy() end end)
        pcall(function() if V2.attachment and V2.attachment.Parent then V2.attachment:Destroy() end end)
        V2.angularVelocity = nil
        V2.attachment = nil
    end

    local function pickTarget(root)
        local best, bestD = nil, math.huge
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p.Character then
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                if hrp and hum and hum.Health > 0 then
                    local d = (hrp.Position - root.Position).Magnitude
                    if d < bestD then bestD = d; best = hrp end
                end
            end
        end
        return best, bestD
    end

    local function getBat(char)
        local eq = char and char:FindFirstChildOfClass("Tool")
        if eq then
            local n = eq.Name:lower()
            if n:find("bat") or n:find("slap") then return eq end
        end
        local bp = LP:FindFirstChildOfClass("Backpack")
        if bp then
            for _, t in ipairs(bp:GetChildren()) do
                if t:IsA("Tool") then
                    local n = t.Name:lower()
                    if n:find("bat") or n:find("slap") then return t end
                end
            end
        end
        return nil
    end

    local function stopBatV2()
        V2.enabled = false
        V2.equipped = false
        V2.target = nil
        if V2.conn then V2.conn:Disconnect(); V2.conn = nil end
        if V2.safetyConn then V2.safetyConn:Disconnect(); V2.safetyConn = nil end
        local c = LP.Character
        local root = c and c:FindFirstChild("HumanoidRootPart")
        if root then pcall(function() root.Velocity = root.Velocity * 0.3 end) end
        local hum = c and c:FindFirstChildOfClass("Humanoid")
        if hum then hum.AutoRotate = true end
        if V2.angularVelocity then
            pcall(function() V2.angularVelocity.AngularVelocity = Vector3.zero end)
        end
        removeAngular()
        if _unsuppressBodyLock then pcall(_unsuppressBodyLock, true) end
    end

    local function startBatV2()
        stopBatV2()
        pcall(function() if _G.__RivalHubStopBatV3 then _G.__RivalHubStopBatV3() end end)
        pcall(function() if _G.__RivalHubStopBatV4 then _G.__RivalHubStopBatV4() end end)
        V2.enabled = true
        V2.equipped = false
        V2.target = nil
        V2.intendedVelocity = Vector3.zero
        V2.speed = tonumber(State and State.bypassBatSpeed) or 58
        if _suppressBodyLock then pcall(_suppressBodyLock) end

        local c = LP.Character
        local root = c and c:FindFirstChild("HumanoidRootPart")
        if root then
            cleanMovers(root)
            ensureAngular(root)
        end

        V2.conn = RunService.Heartbeat:Connect(function()
            if not V2.enabled then return end
            local char = LP.Character
            local hum  = char and char:FindFirstChildOfClass("Humanoid")
            local hrp  = char and char:FindFirstChild("HumanoidRootPart")
            if not hrp or not hum or hum.Health <= 0 then return end
            if _G.MoonHubHardHit and _G.MoonHubHardHit() then
                if V2.angularVelocity then pcall(function() V2.angularVelocity.AngularVelocity = Vector3.zero end) end
                return
            end

            cleanMovers(hrp)
            if not V2.angularVelocity or not V2.angularVelocity.Parent then
                ensureAngular(hrp)
            end

            if not V2.equipped then
                V2.equipped = true
                if not char:FindFirstChildOfClass("Tool") then
                    local b = getBat(char)
                    if b then pcall(function() hum:EquipTool(b) end) end
                end
            end

            local target, dist = pickTarget(hrp)
            if not target then
                V2.target = nil
                hum.AutoRotate = true
                if V2.angularVelocity then
                    V2.angularVelocity.AngularVelocity = Vector3.zero
                end
                return
            end
            V2.target = target

            local aimPos = target.Position
                + _G.MoonSafeFacingOffset(target, (target.Velocity.Magnitude < 0.1 and 1.5 or 5))
            local delta = aimPos - hrp.Position
            local flat  = Vector3.new(delta.X, 0, delta.Z)
            hum.AutoRotate = false

            if delta.Magnitude > 0.01 and flat.Magnitude > 0.01 then
                local curY   = hrp.Orientation.Y
                local yawD   = (math.deg(math.atan2(-flat.X, -flat.Z)) - curY + 180) % 360 - 180
                local curX   = hrp.Orientation.X
                local pitchD = (math.deg(math.atan2(delta.Y, flat.Magnitude)) - curX + 180) % 360 - 180
                local rotY   = math.clamp(math.rad(yawD)   * 40, -28, 28)
                local rotX   = math.clamp(math.rad(pitchD) * 40, -28, 28)
                local yawR   = math.rad(hrp.Orientation.Y)
                local fwd    = Vector3.new(math.cos(yawR), 0, -math.sin(yawR))
                V2.angularVelocity.AngularVelocity = Vector3.new(0, rotY, 0) + fwd * rotX
            else
                V2.angularVelocity.AngularVelocity = Vector3.zero
            end

            local spd = tonumber(State and State.bypassBatSpeed) or tonumber(V2.speed) or 58
            V2.intendedVelocity =
                (flat.Magnitude > 0.1 and flat.Unit * spd or Vector3.zero)
                + (math.abs(delta.Y) > 0.8
                    and Vector3.new(0, math.sign(delta.Y) * spd, 0)
                    or  Vector3.new(0, -2, 0))
            hrp.AssemblyLinearVelocity = V2.intendedVelocity
            hrp.Velocity = V2.intendedVelocity

            if flat.Magnitude > 0.3 then
                pcall(function() hum:Move(flat.Unit, false) end)
            else
                pcall(function() hum:Move(Vector3.zero, false) end)
            end

            if dist <= V2.swingRange then
                local bat = char:FindFirstChildOfClass("Tool")
                if bat and (bat.Name:lower():find("bat") or bat.Name:lower():find("slap")) then
                    pcall(function()
                        bat:Activate()
                        local re = bat:FindFirstChildWhichIsA("RemoteEvent")
                        if re then re:FireServer() end
                    end)
                end
            end
        end)

        V2.safetyConn = RunService.RenderStepped:Connect(function()
            if not V2.enabled then return end
            local char = LP.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum then return end

            if V2.target and V2.target.Parent then
                local delta = V2.target.Position - hrp.Position
                local flat = Vector3.new(delta.X, 0, delta.Z)
                if flat.Magnitude > 0.3 then
                    pcall(function() hum:Move(flat.Unit, false) end)
                end
                if math.abs(hrp.AssemblyLinearVelocity.X - V2.intendedVelocity.X) > 30
                   or math.abs(hrp.AssemblyLinearVelocity.Z - V2.intendedVelocity.Z) > 30 then
                    hrp.AssemblyLinearVelocity = V2.intendedVelocity
                end
            end

            local v = hrp.Velocity
            if math.abs(v.X) > 350 or math.abs(v.Z) > 350 then
                hrp.Velocity = V2.intendedVelocity
            end
            cleanMovers(hrp)
        end)
    end

    _G.__RivalHubStartBatV2 = startBatV2
    _G.__RivalHubStopBatV2  = stopBatV2
    _G.__RivalHubIsBatV2    = function() return V2.enabled == true end

    LP.CharacterAdded:Connect(function()
        task.wait(0.5)
        if V2.enabled then
            V2.equipped = false
            V2.target = nil
            local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
            if hrp then
                cleanMovers(hrp)
                ensureAngular(hrp)
            end
        end
    end)
end


-- Moon-style mobile buttons visibility (open/closed)
_G.RivalHubHideMobileButtons = _G.RivalHubHideMobileButtons == true
_G.RivalHubApplyMobileButtonsHidden = function()
    local hideAll = _G.RivalHubHideMobileButtons == true
    local panel = MobilePanel or _G.RivalHubMobilePanel
    if not panel then return end
    for _, d in ipairs(panel:GetDescendants()) do
        if d:IsA("TextButton") or d:IsA("ImageButton") then
            if hideAll then
                d.Visible = false
            else
                -- restore: if button was user-hidden via attribute keep it
                local forced = d:GetAttribute("RivalForceHidden")
                if forced == true then
                    d.Visible = false
                else
                    d.Visible = true
                end
            end
        end
    end
    if panel:IsA("ScreenGui") or panel:IsA("Frame") then
        -- panel itself stays; only buttons hide
    end
    if type(_G.MoonRefreshAimbotBypassUI) == "function" then pcall(_G.MoonRefreshAimbotBypassUI) end
end

function createMobilePanel()
    if not _G.RivalHubLogoAsset then
        _G.RivalHubLogoAsset = "rbxassetid://110245528345873"
        pcall(function()
            if type(resolveLogo) == "function" then
                _G.RivalHubLogoAsset = resolveLogo()
            end
        end)
    end
    local panel = Instance.new("ScreenGui")
    panel.Name = "RivalHubMobilePanel"
    panel.ResetOnSpawn = false
    panel.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    pcall(function() if syn and syn.protect_gui then syn.protect_gui(panel) end end)
    local okPanel = pcall(function() panel.Parent = game:GetService("CoreGui") end)
    if not okPanel then panel.Parent = LP:WaitForChild("PlayerGui") end

    local BTN_W, BTN_H = 52, 52
    local buttons = {}
    local buttonNames = {"DropBR", "AutoLeft", "Aimbot", "AutoRight", "TpDown", "Carry", "Lagger1", "Lagger2", "InstantReset", "AimbotBypass"}
    local buttonTexts = {"DROP\nBR", "AUTO\nLEFT", "AUTO\nBAT", "AUTO\nRIGHT", "TP\nDOWN", "CARRY\nSPD", "LAGGER\nCARRY", "LAGGER\nNORMAL", "INSTANT\nRESET", "AIMBOT\nBYPASS"}

    local function createButton(name, text, order, isToggle, callback)
        local btn = Instance.new("TextButton", panel)
        btn.Name = name
        btn.Size = UDim2.new(0, BTN_W, 0, BTN_H)
        btn.BackgroundColor3 = Color3.fromRGB(10,10,10)
        btn.BorderSizePixel = 0
        btn.Text = ""
        btn.AutoButtonColor = false
        btn.ZIndex = 10

        local savedPos = savedButtonPositions[name]
        if savedPos then
            btn.Position = UDim2.new(0, savedPos.X or 0, 0, savedPos.Y or 0)
        else
            local defX, defY = getDefaultButtonPosition(name)
            btn.Position = UDim2.new(0, defX, 0, defY)
        end

        -- Moon Hub style: circle + logo image + purple idle
        btn.BackgroundColor3 = Color3.fromRGB(32, 24, 56)
        local corner = Instance.new("UICorner", btn)
        corner.CornerRadius = UDim.new(0, 18) -- Rounded default (more curved)

        local buttonImage = Instance.new("ImageLabel", btn)
        buttonImage.Name = "ButtonImage"
        buttonImage.Size = UDim2.new(1, 0, 1, 0)
        buttonImage.BackgroundTransparency = 1
        buttonImage.Image = _G.RivalHubLogoAsset or "rbxassetid://110245528345873"
        buttonImage.ImageTransparency = 0.22
        buttonImage.ScaleType = Enum.ScaleType.Crop
        buttonImage.ZIndex = 10
        btn.BackgroundTransparency = 0.55
        buttonImage.Active = false
        Instance.new("UICorner", buttonImage).CornerRadius = UDim.new(0, 18)

        local stroke = Instance.new("UIStroke", btn)
        stroke.Color = Color3.fromRGB(70, 90, 130)
        stroke.Thickness = 1.5
        stroke.Transparency = 0.12
        stroke.Name = "NormalStroke"

        local label = Instance.new("TextLabel", btn)
        label.Name = "TextLabel"
        label.Size = UDim2.new(1, -6, 1, -6)
        label.Position = UDim2.fromOffset(3, 3)
        label.BackgroundTransparency = 1
        label.Text = text
        label.TextColor3 = Color3.fromRGB(255, 255, 255)
        label.Font = Enum.Font.GothamBlack
        label.TextSize = 11
        label.TextScaled = true
        label.TextWrapped = true
        label.TextStrokeTransparency = 0.45
        label.TextStrokeColor3 = Color3.fromRGB(32, 24, 56)
        label.ZIndex = 11
        local textLimit = Instance.new("UITextSizeConstraint", label)
        textLimit.MinTextSize = 8
        textLimit.MaxTextSize = 12

        local uiScale = Instance.new("UIScale", btn)
        uiScale.Scale = floatingButtonScale
        table.insert(_floatingUIScales, uiScale)

        local active = false
        local function setActive(state)
            active = state
            btn:SetAttribute("MobActive", state and true or false)
            paintFloatingBtn(btn, state)
        end
        setActive(false)

        -- Match the reference script's per-button drag behavior:
        -- use the original touch input, a movement threshold, and keep at least
        -- half of each button visible at the screen edges.
        local dragging, dragInput, dragStart, startPos, startAbs, hasMoved = false, nil, nil, nil, nil, false
        local movedDistance = 0

        local function isPress(input)
            return input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch
        end

        btn.InputBegan:Connect(function(input)
            if not isPress(input) then return end
            -- fire right away on the very first touch, anywhere on the button
            if callback then
                task.spawn(function()
                    if isToggle then callback(setActive) else callback(setActive, active) end
                end)
            end
            if uiLocked then return end

            dragging = true
            dragInput = input
            dragStart = input.Position
            startPos = btn.Position
            startAbs = btn.AbsolutePosition
            hasMoved = false
            movedDistance = 0
            _isDraggingButton = false
        end)

        UIS.InputChanged:Connect(function(input)
            if not dragging then return end
            if uiLocked then
                dragging = false
                dragInput = nil
                _isDraggingButton = false
                return
            end

            local sameInput
            if dragInput and dragInput.UserInputType == Enum.UserInputType.Touch then
                sameInput = input == dragInput
            else
                sameInput = input.UserInputType == Enum.UserInputType.MouseMovement
            end
            if not sameInput then return end

            local delta = input.Position - dragStart
            movedDistance = delta.Magnitude
            if not hasMoved and movedDistance > 14 then
                hasMoved = true
                _isDraggingButton = true
            end

            if hasMoved then
                local camera = workspace.CurrentCamera
                local viewport = camera and camera.ViewportSize or Vector2.new(1920, 1080)
                local size = btn.AbsoluteSize
                local nx = math.clamp(startAbs.X + delta.X, -size.X / 2, viewport.X - size.X / 2)
                local ny = math.clamp(startAbs.Y + delta.Y, -size.Y / 2, viewport.Y - size.Y / 2)

                local scaleObj = btn:FindFirstChildOfClass("UIScale")
                local scale = scaleObj and math.max(scaleObj.Scale, 0.01) or 1
                btn.Position = UDim2.fromOffset(
                    startPos.X.Offset + (nx - startAbs.X) / scale,
                    startPos.Y.Offset + (ny - startAbs.Y) / scale
                )
            end
        end)

        local function finishMobileDrag(input)
            if not dragging then return end
            local released = input == dragInput
                or (dragInput and dragInput.UserInputType == Enum.UserInputType.MouseButton1
                    and input.UserInputType == Enum.UserInputType.MouseButton1)
            if not released then return end

            dragging = false
            dragInput = nil

            if hasMoved then
                savedButtonPositions[name] = {
                    X = btn.Position.X.Offset,
                    Y = btn.Position.Y.Offset
                }
            end

            hasMoved = false
            movedDistance = 0
            _isDraggingButton = false
        end

        btn.InputEnded:Connect(finishMobileDrag)
        UIS.InputEnded:Connect(finishMobileDrag)

        buttons[name] = {btn = btn, setActive = setActive, label = label}
        return setActive
    end

    for i, name in ipairs(buttonNames) do
        local text = buttonTexts[i]
        local callback
        if name == "DropBR" then
            callback = function(setActive)
                if autoBatEnabled then return end
                setActive(true)
                executeDropWithToggle(function(v)
                    if dropBrainrotSetVisual then dropBrainrotSetVisual(v) end
                end)
                task.delay(0.3, function() setActive(false) end)
            end
        elseif name == "AutoLeft" then
            callback = function(setActive)
                if _autoToggleDebounced() then return end
                autoLeftEnabled = not autoLeftEnabled
                if autoLeftEnabled then startAutoLeft() else stopAutoLeft() end
                setActive((autoLeftEnabled or moonPendingCarryResume == "AutoLeft"))
                if autoLeftSetVisual then autoLeftSetVisual((autoLeftEnabled or moonPendingCarryResume == "AutoLeft")) end
            end
        elseif name == "AutoBat" then
            callback = function(setActive)
                if not autoBatEnabled then enableAutoBat() else disableAutoBat() end
                setActive(autoBatEnabled or moonPendingCarryResume == "AutoBat")
            end
        elseif name == "AutoRight" then
            callback = function(setActive)
                if _autoToggleDebounced() then return end
                autoRightEnabled = not autoRightEnabled
                if autoRightEnabled then startAutoRight() else stopAutoRight() end
                setActive((autoRightEnabled or moonPendingCarryResume == "AutoRight"))
                if autoRightSetVisual then autoRightSetVisual((autoRightEnabled or moonPendingCarryResume == "AutoRight")) end
            end
        elseif name == "TpDown" then
            callback = function(setActive)
                doTpDown()
                setActive(true)
                task.delay(0.2, function() setActive(false) end)
            end
        elseif name == "Carry" then
            callback = function(setActive)
                setSpeedMode(getCurrentSpeedModeName() == "Carry" and "Normal" or "Carry")
            end
        elseif name == "Lagger1" then
            callback = function(setActive)
                setSpeedMode(getCurrentSpeedModeName() == "Lagger Carry" and "Normal" or "Lagger Carry")
            end
        elseif name == "Lagger2" then
            callback = function(setActive)
                setSpeedMode(getCurrentSpeedModeName() == "Lagger" and "Normal" or "Lagger")
            end
        elseif name == "BatV2" then
            callback = function(setActive)
                if not _G.__RivalHubIsBatV2() then
                    _G.__RivalHubStartBatV2()
                    setActive(true)
                else
                    _G.__RivalHubStopBatV2()
                    setActive(false)
                end
            end
        elseif name == "Aimbot" then
            callback = function(setActive)
                local S = _G.RivalSmartAimbot
                if S then
                    S.toggle()
                    if S.refreshButtons then S.refreshButtons()
                    else setActive(S.enabled == true) end
                end
            end
        elseif name == "AimbotBypass" then
            callback = function(setActive)
                local S = _G.RivalSmartAimbot
                if not (S and S.split and S.toggleBypass) then setActive(false); return end
                S.toggleBypass()
                if S.refreshButtons then S.refreshButtons() end
            end
        elseif name == "InstantReset" then
            callback = function(setActive)
                -- one-shot: flash ON, run the reset, back to the idle look
                setActive(true)
                if type(_G.AmbitiousInstantReset) == "function" then
                    task.spawn(_G.AmbitiousInstantReset)
                end
                task.delay(0.3, function() setActive(false) end)
            end
        end
        local setActive = createButton(name, text, i-1, true, callback)
        if name == "AutoBat" then mobSetAutoBat = setActive end
        if name == "AutoLeft" then mobSetAutoLeft = setActive end
        if name == "AutoRight" then mobSetAutoRight = setActive end
        if name == "DropBR" then mobSetDropBR = setActive end
        if name == "TpDown" then mobSetTpDown = setActive end
        if name == "Carry" then mobSetCarry = setActive end
        if name == "Lagger1" then mobSetLagger1 = setActive end
        if name == "Lagger2" then mobSetLagger2 = setActive end
        if name == "BatV2" then mobSetBatV2 = setActive end
        if name == "Aimbot" then mobSetAimbot = setActive end
        if name == "AimbotBypass" then mobSetAimbotBypass = setActive end
        if name == "InstantReset" then mobSetInstantReset = setActive end
    end
    -- Aimbot Bypass button only exists on screen while "Split Aimbot" is ON
    if type(_G.MoonRefreshAimbotBypassUI) == "function" then
        _G.RivalHubMobilePanel = _G.RivalHubMobilePanel or panel
        pcall(_G.MoonRefreshAimbotBypassUI)
    end

    if buttons.AutoBat and buttons.AutoBat.setActive then buttons.AutoBat.setActive(autoBatEnabled) end
    if buttons.AutoLeft and buttons.AutoLeft.setActive then buttons.AutoLeft.setActive(autoLeftEnabled) end
    if buttons.AutoRight and buttons.AutoRight.setActive then buttons.AutoRight.setActive(autoRightEnabled) end
    if buttons.Carry and buttons.Carry.setActive then buttons.Carry.setActive(speedMode) end
    if buttons.Lagger1 and buttons.Lagger1.setActive then buttons.Lagger1.setActive(laggerCarryToggled) end
    if buttons.Lagger2 and buttons.Lagger2.setActive then buttons.Lagger2.setActive(laggerToggled) end
    if buttons.BatV2 and buttons.BatV2.setActive then
        buttons.BatV2.setActive(_G.__RivalHubIsBatV2 and _G.__RivalHubIsBatV2() or false)
    end
    if buttons.Aimbot and buttons.Aimbot.setActive then
        buttons.Aimbot.setActive(_G.RivalSmartAimbot and _G.RivalSmartAimbot.enabled == true or false)
    end

    return panel
end


local _bootErrors = {}

local function _bootSection(name, fn)
    local startedAt = os.clock()
    print("[Moon Hub Boot] Iniciando:", name)
    local ok, err = pcall(fn)
    local elapsed = os.clock() - startedAt
    if not ok then
        print("[Moon Hub Boot] FALLÓ:", name, tostring(err), string.format("(%.2fs)", elapsed))
        table.insert(_bootErrors, {name = name, err = tostring(err)})
        warn("[Moon Hub Boot] Error en '" .. name .. "': " .. tostring(err))
    else
        print("[Moon Hub Boot] OK:", name, string.format("(%.2fs)", elapsed))
    end
    return ok
end

