if LP and LP.CharacterAdded then
    pcall(function()
        local _respawnQueue = 0
        LP.CharacterAdded:Connect(function(char)
            pcall(function()
                _respawnQueue = _respawnQueue + 1
                local myId = _respawnQueue

                if stealConnection then stealConnection:Disconnect(); stealConnection = nil end
                isStealing = false
                -- flags follow the visuals (stopAutoLeft/Right paint OFF), so a
                -- respawn / Instant Reset never leaves a "ghost ON" state behind
                autoLeftEnabled = false
                autoRightEnabled = false
                if stopAutoLeft then stopAutoLeft() end
                if stopAutoRight then stopAutoRight() end
                if stopBatCounter then stopBatCounter() end
                        if stopMedusaCounter then stopMedusaCounter() end
                if stopDropBrainrot then stopDropBrainrot() end
                if autoBatEnabled and disableAutoBat then disableAutoBat() end
                if bodyLockEnabled and stopBodyLock then stopBodyLock() end

                local deadline = _tick() + 5
                while (not char.Parent) or (not char:FindFirstChild("HumanoidRootPart")) or (not char:FindFirstChildOfClass("Humanoid")) do
                    if _tick() > deadline then return end
                    if myId ~= _respawnQueue then return end
                    task.wait(0.05)
                end

                _hookedVelParts = {}
                local _hrpRespawn = _setupVelChecked(char)
                _hookVelHRP(_hrpRespawn)

                if not _originalAppearance then task.defer(function() captureOriginalAppearance(char) end) end
                if setupMovementAndIndicators then setupMovementAndIndicators(char) end
                if antiRagdollMode == "v1" then
                    AntiRagdollV1.start()
                elseif antiRagdollMode == "v2" then
                    startAntiRagdollV2()
                end
                if antiBatEnabled then startAntiBat() end
                if antiFlingEnabled then startAntiFling() end
                if AntiDieModule.enabled then task.defer(function() activateOnCharacter(char) end) end
                if CONFIG.AUTO_STEAL_ENABLED then pcall(startAutoSteal) end
                if bodyLockEnabled and _blSuppressCount == 0 then startBodyLock() end

                if medusaCounterEnabled then
                    setupMedusaCounter(char)
                    if setMedusaVisual then setMedusaVisual(true) end
                else
                    stopMedusaCounter()
                    if setMedusaVisual then setMedusaVisual(false) end
                end

                if batCounterEnabled then startBatCounter() end
                if currentAnimPack ~= "Off" then task.wait(0.3); startAnimPack(currentAnimPack) end

                updateProgressBarVisibility()
                refreshSpeedModeLabel()

                -- after a respawn / Instant Reset: every mobile button + menu row
                -- shows the real state, hidden buttons stay hidden
                pcall(function() if type(resetMovementState) == "function" then resetMovementState() end end)
                pcall(function()
                    if mobSetAimbot then mobSetAimbot(_G.RivalSmartAimbot and _G.RivalSmartAimbot.enabled == true or false) end
                    if mobSetAutoBat then mobSetAutoBat(autoBatEnabled == true) end
                    if mobSetInstantReset then mobSetInstantReset(false) end
                    if mobSetDropBR then mobSetDropBR(false) end
                    if mobSetTpDown then mobSetTpDown(false) end
                end)
                pcall(function() if type(applyHideButtons) == "function" then applyHideButtons(hideButtonsEnabled == true) end end)
                pcall(function() if type(applyMobileButtonShape) == "function" then applyMobileButtonShape() end end)
                if AntiDieModule.enabled and not _G._AmbitiousInstantResetBusy then
                    pcall(_antiDieRefresh)
                end

                pcall(function() applyOutfitByIndex(currentOutfitIndex) end)
                if outfitSelectorLabel and OUTFITS[currentOutfitIndex] then
                    outfitSelectorLabel.Text = OUTFITS[currentOutfitIndex].label
                end
            end)
        end)
    end)
end

local lastLaggerToggle = 0
local LAGGER_COOLDOWN = 0.12

if _G._RivalMainInputConn then pcall(function() _G._RivalMainInputConn:Disconnect() end) end
_G._RivalMainInputConn = UIS.InputBegan:Connect(function(input, gpe)
    if input == _G.RivalHubBindConsumedInput then return end
    if UIS:GetFocusedTextBox() then return end

    local isMB3 = input.UserInputType == Enum.UserInputType.MouseButton3
    local isKb = input.UserInputType == Enum.UserInputType.Keyboard
    local isGp = isGamepadInput and isGamepadInput(input)
    if not isMB3 and not isKb and not isGp then return end
    if isKb and input.KeyCode == Enum.KeyCode.Unknown then return end

    local kc = input.KeyCode
    -- Never shadow global KB with a broken reference
    do
        local live = _G.RivalHubKB
        if type(live) == "table" then
            for id, entry in pairs(live) do
                if type(KB) == "table" then KB[id] = entry end
            end
        end
    end

    -- Keybind rebind handled ONLY by Ambitious listener at file end
    if _G.RivalHubKeySysListenId or (KeySys and KeySys.listenId) or _anyKeyListening then
        return -- don't fire features while binding
    end


    -- Toggle UI first (works even if gpe, like Moon Hub LeftControl)
    if KB and KB.GuiHide and kbMatch(KB.GuiHide, kc) then
        if _G.RivalHubGuiOpen then
            if type(hideGui) == "function" then hideGui() end
        else
            if type(showGui) == "function" then showGui() end
        end
        return
    end

    -- gpe ignored on purpose: the game/GUI often marks keys as processed and the bind silently dies.
    -- Typing in a TextBox / chat is already blocked at the top of this handler.
    if not isBindableInput(input) then return end

    -- Sync KB entries from RivalBindMap so matches always see latest bind
    if type(_G.RivalBindMap) == "table" and type(KB) == "table" then
        for id, bound in pairs(_G.RivalBindMap) do
            if type(KB[id]) ~= "table" then KB[id] = { kb = nil, gp = nil } end
            if bound == "MB3" then
                KB[id].kb = "MB3"; KB[id].gp = nil
            elseif typeof(bound) == "EnumItem" then
                local isPad = tostring(bound):find("Button") or tostring(bound):find("DPad")
                if isPad then KB[id].gp = bound; KB[id].kb = nil
                else KB[id].kb = bound; KB[id].gp = nil end
            end
        end
    end

    if kbMatch(KB.InstantReset, kc) or kbMatch("InstantReset", kc) then
        if type(_G.AmbitiousInstantReset) == "function" then
            task.spawn(_G.AmbitiousInstantReset)
        end
        if mobSetInstantReset then
            pcall(mobSetInstantReset, true)
            task.delay(0.3, function() if mobSetInstantReset then pcall(mobSetInstantReset, false) end end)
        end
        return
    end
    if kbMatch(KB.LaggerMode, kc) or kbMatch("LaggerMode", kc) then
        if _tick() - lastLaggerToggle >= LAGGER_COOLDOWN then
            lastLaggerToggle = _tick()
            setSpeedMode(getCurrentSpeedModeName() == "Lagger Carry" and "Lagger" or "Lagger Carry")
        end
        return
    end
    if kbMatch(KB.CarryToggle, kc) or kbMatch("CarryToggle", kc) then
        setSpeedMode(getCurrentSpeedModeName() == "Carry" and "Normal" or "Carry"); return
    end
    if kbMatch(KB.DropBrainrot, kc) or kbMatch("DropBrainrot", kc) then
        if autoBatEnabled then return end
        if mobSetDropBR then pcall(mobSetDropBR, true) end
        executeDropWithToggle(function(v)
            if dropBrainrotSetVisual then dropBrainrotSetVisual(v) end
        end)
        task.delay(0.3, function() if mobSetDropBR then pcall(mobSetDropBR, false) end end)
        return
    end
    if kbMatch(KB.TPFloor, kc) or kbMatch("TPFloor", kc) then
        doTpDown()
        if mobSetTpDown then pcall(mobSetTpDown, true) end
        task.delay(0.2, function() if mobSetTpDown then pcall(mobSetTpDown, false) end end)
        return
    end
    if kbMatch(KB.AutoLeft, kc) or kbMatch("AutoLeft", kc) then
        if _autoToggleDebounced() then return end
        autoLeftEnabled = not autoLeftEnabled
        if autoLeftEnabled then startAutoLeft() else stopAutoLeft() end
        if autoLeftSetVisual then autoLeftSetVisual((autoLeftEnabled or moonPendingCarryResume == "AutoLeft")) end
        if mobSetAutoLeft then mobSetAutoLeft((autoLeftEnabled or moonPendingCarryResume == "AutoLeft")) end
        return
    end
    if kbMatch(KB.AutoRight, kc) or kbMatch("AutoRight", kc) then
        if _autoToggleDebounced() then return end
        autoRightEnabled = not autoRightEnabled
        if autoRightEnabled then startAutoRight() else stopAutoRight() end
        if autoRightSetVisual then autoRightSetVisual((autoRightEnabled or moonPendingCarryResume == "AutoRight")) end
        if mobSetAutoRight then mobSetAutoRight((autoRightEnabled or moonPendingCarryResume == "AutoRight")) end
        return
    end
    if kbMatch(KB.Aimbot, kc) or kbMatch("Aimbot", kc) then
        if _G.RivalSmartAimbot then
            _G.RivalSmartAimbot.toggle()
            if _G.RivalSmartAimbot.refreshButtons then _G.RivalSmartAimbot.refreshButtons()
            elseif mobSetAimbot then mobSetAimbot(_G.RivalSmartAimbot.enabled == true) end
        end
        return
    end
    if _G.MoonAimbotSplit == true and (kbMatch(KB.AimbotBypass, kc) or kbMatch("AimbotBypass", kc)) then
        local S = _G.RivalSmartAimbot
        if S and S.split and S.toggleBypass then
            S.toggleBypass()
            if S.refreshButtons then S.refreshButtons() end
        end
        return
    end
end)

-- Removed the old always-on bat/Medusa cosmetic overrides.
-- Clean residual replicas left by an earlier execution of this script.
do
    local Players = game:GetService("Players")
    local player = Players.LocalPlayer
    local function cleanTool(tool)
        if not tool or not tool:IsA("Tool") then return end
        local handle = tool:FindFirstChild("Handle")
        local swordReplica = handle and handle:FindFirstChild("ShelSwordReplica")
        if swordReplica then
            pcall(function() swordReplica:Destroy() end)
            -- The previous cosmetic hid the original bat handle.
            pcall(function() handle.Transparency = 0 end)
        end

        local skinFolder = tool:FindFirstChild("ShelMedusaBombSkin")
        local hadMedusaSkin = tool:GetAttribute("ShelMedusaBombSkin") == true or skinFolder ~= nil
        local hadCustomSound = false
        for _, obj in ipairs(tool:GetDescendants()) do
            if obj:IsA("Sound") and (obj.Name == "ShelBombSound" or obj.Name == "ShelCustomToolSound") then
                hadCustomSound = true
                break
            end
        end
        if hadMedusaSkin or hadCustomSound then
            for _, obj in ipairs(tool:GetDescendants()) do
                if hadMedusaSkin and obj:IsA("BasePart") and not (skinFolder and obj:IsDescendantOf(skinFolder)) then
                    pcall(function() obj.LocalTransparencyModifier = 0 end)
                elseif obj:IsA("Sound") and obj.Name ~= "ShelBombSound" and obj.Name ~= "ShelCustomToolSound" then
                    pcall(function() if obj.Volume == 0 then obj.Volume = 1 end end)
                end
            end
        end
        if skinFolder then pcall(function() skinFolder:Destroy() end) end
        pcall(function() tool:SetAttribute("ShelMedusaBombSkin", nil) end)

        for _, obj in ipairs(tool:GetDescendants()) do
            if obj:IsA("Sound") and (obj.Name == "ShelBombSound" or obj.Name == "ShelCustomToolSound") then
                pcall(function() obj:Destroy() end)
            end
        end
    end
    local function cleanContainer(container)
        if not container then return end
        for _, child in ipairs(container:GetChildren()) do cleanTool(child) end
    end
    if player then
        cleanContainer(player.Character)
        cleanContainer(player:FindFirstChildOfClass("Backpack"))
    end
    _G.ShelSwordVisual = nil
    _G.ShelSwordSound = nil
    _G.ShelBombSound = nil
    _G.ShelMedusaSkin = nil
    _G.ShelSwordRainbowParts = {}
    _G.ShelSwordRainbowSpeed = nil
end


-- ============================================================
-- SINGLE KEYBIND LISTENER (Ambitious-style) — one system only
-- ============================================================
do
    local UIS = game:GetService("UserInputService")

    -- Ensure map exists
    _G.RivalBindMap = _G.RivalBindMap or {}
    local defaults = {
        DropBrainrot = Enum.KeyCode.X,
        AutoLeft = Enum.KeyCode.Z,
        AutoRight = Enum.KeyCode.C,
        TPFloor = Enum.KeyCode.F,
        GuiHide = Enum.KeyCode.LeftControl,
        CarryToggle = Enum.KeyCode.Q,
        LaggerMode = Enum.KeyCode.R,
        Aimbot = Enum.KeyCode.E,
        InstantReset = Enum.KeyCode.G,
        AimbotBypass = Enum.KeyCode.V,
    }
    for id, k in pairs(defaults) do
        if _G.RivalBindMap[id] == nil then _G.RivalBindMap[id] = k end
    end

    local function keyName(key)
        if key == nil then return "None" end
        if key == "MB3" then return "MB3" end
        return tostring(key):gsub("Enum.KeyCode.", ""):gsub("Button", "BTN "):gsub("DPad", "DPad ")
    end

    local function syncKB(id, bound)
        if type(KB) ~= "table" then return end
        if type(KB[id]) ~= "table" then KB[id] = { kb = nil, gp = nil } end
        if bound == nil then
            KB[id].kb = nil; KB[id].gp = nil
        elseif bound == "MB3" then
            KB[id].kb = "MB3"; KB[id].gp = nil
        else
            KB[id].kb = bound; KB[id].gp = nil
        end
    end

    local function refreshAll()
        if type(KeySys) ~= "table" or type(KeySys.buttons) ~= "table" then return end
        local listenId = _G.RivalHubKeySysListenId
        for id, btn in pairs(KeySys.buttons) do
            if typeof(btn) == "Instance" then
                if listenId == id then
                    btn.Text = "Press..."
                    pcall(function() btn.TextColor3 = Color3.fromRGB(255, 255, 255) end)
                else
                    btn.Text = keyName(_G.RivalBindMap[id])
                    pcall(function() btn.TextColor3 = Color3.fromRGB(255, 255, 255) end)
                end
            end
        end
    end

    -- Push map into KB now
    for id, bound in pairs(_G.RivalBindMap) do
        syncKB(id, bound)
    end

    if _G._RivalSingleKeyConn then pcall(function() _G._RivalSingleKeyConn:Disconnect() end) end
    _G._RivalSingleKeyConn = UIS.InputBegan:Connect(function(input, gameProcessed)
        local targetKey = _G.RivalHubKeySysListenId
        if not targetKey then return end

        local isMB3 = input.UserInputType == Enum.UserInputType.MouseButton3
        local isKb = input.UserInputType == Enum.UserInputType.Keyboard
        local isGp = tostring(input.UserInputType):find("Gamepad") ~= nil

        -- While listening: ignore gameProcessed (Ambitious)
        if UIS:GetFocusedTextBox() then return end
        if not isMB3 and not isKb and not isGp then return end
        if isKb and input.KeyCode == Enum.KeyCode.Unknown then return end

        local started = _G.RivalHubListenStarted or 0
        if tick() - started < 0.02 then return end

        -- same InputObject reaches the main handler too: tell it to ignore this press
        _G.RivalHubBindConsumedInput = input
        task.defer(function()
            if _G.RivalHubBindConsumedInput == input then _G.RivalHubBindConsumedInput = nil end
        end)

        if isKb and input.KeyCode == Enum.KeyCode.Escape then
            _G.RivalHubKeySysListenId = nil
            _anyKeyListening = false
            if KeySys then KeySys.listenId = nil end
            refreshAll()
            return
        end

        if isKb and (input.KeyCode == Enum.KeyCode.Backspace or input.KeyCode == Enum.KeyCode.Delete) then
            _G.RivalBindMap[targetKey] = nil
            syncKB(targetKey, nil)
            _G.RivalHubKeySysListenId = nil
            _anyKeyListening = false
            if KeySys then KeySys.listenId = nil end
            refreshAll()
            return
        end

        local pressed = isMB3 and "MB3" or input.KeyCode

        -- clear duplicates
        for id, bound in pairs(_G.RivalBindMap) do
            if id ~= targetKey and bound == pressed then
                _G.RivalBindMap[id] = nil
                syncKB(id, nil)
            end
        end

        _G.RivalBindMap[targetKey] = pressed
        syncKB(targetKey, pressed)
        _G.RivalLastBind = { id = targetKey, key = pressed, name = keyName(pressed) }
        _G.RivalHubKeySysListenId = nil
        _anyKeyListening = false
        if KeySys then KeySys.listenId = nil end
        refreshAll()
    end)

    -- Refresh button labels after GUI ready
    task.spawn(function()
        for _ = 1, 100 do
            if type(KeySys) == "table" and type(KeySys.buttons) == "table" then
                local n = 0
                for _ in pairs(KeySys.buttons) do n += 1 end
                if n > 0 then
                    refreshAll()
                    break
                end
            end
            task.wait(0.1)
        end
    end)

    _G.RivalRefreshKeybinds = refreshAll
end

-- ##############################################################################
-- # ANTI BAT DETECTOR — enemy head tag "ANTI BAT" (ported 1:1 from MoonHub_v2)
-- # + SMART AIMBOT. Wrapped in its own function: own 200-locals budget.
-- ##############################################################################
;(function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local localPlayer = Players.LocalPlayer

local ANTI_BAT_TAG_NAME = "YassinAntiBatHeadTag"
local ANTI_BAT_ATTR = "YassinAntiBat"

function _YassinInternal_destroyAntiBatTagOnChar(char)
    if not char then return end
    local head = char:FindFirstChild("Head")
    if head then
        local old = head:FindFirstChild(ANTI_BAT_TAG_NAME)
        if old then pcall(function() old:Destroy() end) end
    end
    local old2 = char:FindFirstChild(ANTI_BAT_TAG_NAME)
    if old2 then pcall(function() old2:Destroy() end) end
end

function _YassinInternal_createEnemyAntiBatTag(char)
    if not char then return end
    local head = char:FindFirstChild("Head")
    if not head then return end
    local existing = head:FindFirstChild(ANTI_BAT_TAG_NAME)
    if existing and existing:IsA("BillboardGui") then return existing end
    _YassinInternal_destroyAntiBatTagOnChar(char)
    local bb = Instance.new("BillboardGui")
    bb.Name = ANTI_BAT_TAG_NAME
    bb.Adornee = head
    bb.Size = UDim2.new(0, 120, 0, 36)
    bb.StudsOffset = Vector3.new(0, 3.15, 0)
    bb.AlwaysOnTop = true
    bb.MaxDistance = math.huge
    bb.AlwaysOnTop = true
    bb.Parent = head

    local box = Instance.new("Frame")
    box.Name = "Box"
    box.Size = UDim2.new(1, 0, 1, 0)
    box.BackgroundColor3 = Color3.fromRGB(20, 8, 28)
    box.BackgroundTransparency = 0.15
    box.BorderSizePixel = 0
    box.Parent = bb
    Instance.new("UICorner", box).CornerRadius = UDim.new(0, 8)
    local stroke = Instance.new("UIStroke", box)
    stroke.Color = Color3.fromRGB(255, 255, 255)
    stroke.Thickness = 2
    stroke.Transparency = 0.1

    local lbl = Instance.new("TextLabel")
    lbl.Name = "Label"
    lbl.Size = UDim2.new(1, -6, 1, -4)
    lbl.Position = UDim2.new(0, 3, 0, 2)
    lbl.BackgroundTransparency = 1
    lbl.Text = "ANTI BAT"
    lbl.TextColor3 = Color3.fromRGB(255, 255, 255)
    lbl.Font = Enum.Font.GothamBlack
    lbl.TextSize = 18
    lbl.TextStrokeTransparency = 0.3
    lbl.TextStrokeColor3 = Color3.fromRGB(32, 24, 56)
    lbl.Parent = box
    return bb
end

-- NEVER put the tag on local player (visual only). Attribute still broadcasts to others.
function _YassinInternal_clearLocalAntiBatTag()
    local char = localPlayer.Character
    if char then _YassinInternal_destroyAntiBatTagOnChar(char) end
end

-- Publish a local Anti Bat marker attribute; Roblox does not guarantee client-set attributes replicate to other clients.
function _YassinInternal_publishAntiBatAttr(on)
    local char = localPlayer.Character
    if not char then return end
    pcall(function()
        if on then
            char:SetAttribute(ANTI_BAT_ATTR, true)
            char:SetAttribute("AmbitiousAntiBat", true)
            char:SetAttribute("AntiBatEnabled", true)
        else
            char:SetAttribute(ANTI_BAT_ATTR, nil)
            char:SetAttribute("AmbitiousAntiBat", nil)
            char:SetAttribute("AntiBatEnabled", nil)
            char:SetAttribute("AntiBat", nil)
        end
    end)
end

-- Evidence tracker per other player (velocity spoof pattern)
-- Vx7 / similar anti-bat: brief huge random XZ velocity spikes then restore.
local _abEvidence = {} -- [userId] = { score, lastSpike, lastSeen, samples }
local _abTagByUser = {} -- [userId] = BillboardGui
_G._MoonHubAntiBatEvidence = _abEvidence
_G._MoonHubAntiBatTags = _abTagByUser
local ANTI_BAT_TAG_STICKY_SECONDS = 5.0 -- stable tag; clears after real OFF (v8.1.3 exact)

function _YassinInternal_clearEnemy(uid, char)
    local bb = _abTagByUser[uid]
    if bb then pcall(function() bb:Destroy() end) end
    _abTagByUser[uid] = nil
    if char then _YassinInternal_destroyAntiBatTagOnChar(char) end
end

function _YassinInternal_readHorizSpeed(root)
    local ok, v = pcall(function() return root.AssemblyLinearVelocity end)
    if not ok or not v then
        ok, v = pcall(function() return root.Velocity end)
    end
    if not ok or not v then return 0 end
    return math.sqrt(v.X * v.X + v.Z * v.Z)
end

function _YassinInternal_enemyHasAttrFlag(char)
    local on = false
    pcall(function()
        if char:GetAttribute(ANTI_BAT_ATTR) == true then on = true end
        if char:GetAttribute("AmbitiousAntiBat") == true then on = true end
        if char:GetAttribute("AntiBat") == true then on = true end
        if char:GetAttribute("AntiBatEnabled") == true then on = true end
    end)
    return on
end

function _YassinInternal_sampleEnemy(plr)
    if not plr or plr == localPlayer then return end
    local uid = plr.UserId
    local char = plr.Character
    if not char or not char.Parent then
        _YassinInternal_clearEnemy(uid, nil)
        _abEvidence[uid] = nil
        return
    end
    local hum = char:FindFirstChildOfClass("Humanoid")
    local root = char:FindFirstChild("HumanoidRootPart")
    if not hum or not root or hum.Health <= 0 then
        _YassinInternal_clearEnemy(uid, char)
        return
    end

    local ev = _abEvidence[uid]
    -- Reset evidence only when this player gets a new character; keep a confirmed
    -- head tag stable through distance changes and ordinary movement states.
    if ev and ev.char ~= char then
        _YassinInternal_clearEnemy(uid, nil)
        ev = nil
    end
    if not ev then
        ev = {
            char = char,
            confirmed = false,
            score = 0,
            lastSpike = 0,
            lastPos = root.Position,
            lastT = os.clock(),
            lastHSpeed = 0,
            hardSpikes = 0,
            pulsePairs = 0, -- spike then drop = classic anti-bat
            windowStart = os.clock(),
        }
        _abEvidence[uid] = ev
    end

    local now = os.clock()
    local dt = math.clamp(now - (ev.lastT or now), 0.02, 0.35)
    ev.lastT = now

    if (now - (ev.windowStart or now)) > 6 then
        ev.windowStart = now
        if not ev.confirmed then
            ev.hardSpikes = math.max((ev.hardSpikes or 0) - 2, 0)
            ev.pulsePairs = math.max((ev.pulsePairs or 0) - 1, 0)
            ev.score = math.max((ev.score or 0) * 0.5, 0)
        else
            ev.hardSpikes = math.max((ev.hardSpikes or 0) - 1, 0)
            ev.score = math.max((ev.score or 0) * 0.7, 0)
        end
    end

    -- Skip unreliable states (knockback / ragdoll / freefall look like "spikes")
    local stOk, st = pcall(function() return hum:GetState() end)
    local state = stOk and st or nil
    local ignoreState = state == Enum.HumanoidStateType.Ragdoll
        or state == Enum.HumanoidStateType.FallingDown
        or state == Enum.HumanoidStateType.Physics
        or state == Enum.HumanoidStateType.Jumping
        or state == Enum.HumanoidStateType.Freefall
        or state == Enum.HumanoidStateType.GettingUp
    if hum.PlatformStand or ignoreState then
        ev.lastPos = root.Position
        ev.lastHSpeed = _YassinInternal_readHorizSpeed(root)
        if ev.confirmed or (ev.fromAttr and _YassinInternal_enemyHasAttrFlag(char)) then
            local last = ev.lastConfirmTime or ev.lastSpike or 0
            if (now - last) < ANTI_BAT_TAG_STICKY_SECONDS or ev.fromAttr then
                local bb = _YassinInternal_createEnemyAntiBatTag(char)
                _abTagByUser[uid] = bb
            end
        end
        return
    end

    local attrOn = _YassinInternal_enemyHasAttrFlag(char)
    local hSpeed = _YassinInternal_readHorizSpeed(root)
    local walk = tonumber(hum.WalkSpeed) or 16
    -- Legitimate combat/speed scripts often sit 30–70. Anti-bat pulse is extreme + brief.
    local pos = root.Position
    local dist = (Vector3.new(pos.X, 0, pos.Z) - Vector3.new(ev.lastPos.X, 0, ev.lastPos.Z)).Magnitude
    local instSpeed = dist / dt
    ev.lastPos = pos

    local prev = tonumber(ev.lastHSpeed) or 0
    ev.lastHSpeed = hSpeed

    -- Max confidence Anti-Bat velocity thresholds (Moon Hub v8.1.3 exact)
    local hardVel = hSpeed >= 350
    local hardInst = instSpeed >= 320
    local megaVel = hSpeed >= 600

    local pulsePair = false
    if prev >= 300 and hSpeed <= math.max(walk * 2.2, 55) and (prev - hSpeed) >= 200 then
        pulsePair = true
    end
    if prev >= 300 and instSpeed <= math.max(walk * 2.5, 60) and hSpeed <= math.max(walk * 2.2, 55) then
        pulsePair = true
    end

    if attrOn then
        ev.score = math.min(ev.score + 4, 18)
        ev.lastSpike = now
        ev.hardSpikes = (ev.hardSpikes or 0) + 1
        ev.pulsePairs = (ev.pulsePairs or 0) + 1
    elseif megaVel then
        ev.score = math.min(ev.score + 4, 18)
        ev.lastSpike = now
        ev.hardSpikes = (ev.hardSpikes or 0) + 1
    elseif hardVel or hardInst then
        ev.score = math.min(ev.score + 1.8, 18)
        ev.lastSpike = now
        ev.hardSpikes = (ev.hardSpikes or 0) + 1
    elseif pulsePair then
        ev.score = math.min(ev.score + 3, 18)
        ev.lastSpike = now
        ev.pulsePairs = (ev.pulsePairs or 0) + 1
    else
        if ev.confirmed then
            ev.score = math.max(ev.score - 0.6, 0)
        else
            ev.score = math.max(ev.score - 2.0, 0)
        end
    end

    local recent = (now - (ev.lastSpike or 0)) < 2.0

    local active = false
    if attrOn then
        active = true
        ev.confirmed = true
        ev.lastConfirmTime = now
        ev.fromAttr = true
    elseif ev.fromAttr then
        active = false
        ev.confirmed = false
        ev.fromAttr = false
    elseif recent and (ev.hardSpikes or 0) >= 5 and (ev.pulsePairs or 0) >= 2 and (ev.score or 0) >= 10 then
        active = true
        ev.fromAttr = false
        ev.lastConfirmTime = now
    elseif recent and (ev.hardSpikes or 0) >= 8 and (ev.score or 0) >= 12 then
        active = true
        ev.fromAttr = false
        ev.lastConfirmTime = now
    elseif ev.confirmed and not ev.fromAttr then
        local last = ev.lastConfirmTime or ev.lastSpike or 0
        active = (now - last) < ANTI_BAT_TAG_STICKY_SECONDS
    end

    if active then
        ev.confirmed = true
        local bb = _YassinInternal_createEnemyAntiBatTag(char)
        if bb then
            pcall(function()
                bb.MaxDistance = math.huge
                bb.AlwaysOnTop = true
            end)
        end
        _abTagByUser[uid] = bb
    else
        ev.confirmed = false
        ev.fromAttr = false
        _YassinInternal_clearEnemy(uid, char)
    end
end


-- Anti Bat detector-- Anti Bat detector: sample every other player (any distance / walls).
_G.__YASSIN_ANTIBAT_DETECTOR_GEN = (_G.__YASSIN_ANTIBAT_DETECTOR_GEN or 0) + 1
local _antiBatDetectorGen = _G.__YASSIN_ANTIBAT_DETECTOR_GEN
task.spawn(function()
    while _antiBatDetectorGen == _G.__YASSIN_ANTIBAT_DETECTOR_GEN do
        local alive = {}
        for _, enemy in ipairs(Players:GetPlayers()) do
            if enemy ~= localPlayer then
                alive[enemy.UserId] = true
                pcall(_YassinInternal_sampleEnemy, enemy)
            end
        end
        for uid, evidence in pairs(_abEvidence) do
            if not alive[uid] then
                local oldPlayer = Players:GetPlayerByUserId(uid)
                _YassinInternal_clearEnemy(uid, oldPlayer and oldPlayer.Character or (evidence and evidence.char))
                _abEvidence[uid] = nil
            end
        end
        task.wait(0.05) -- v8.1.3 detector tick
    end
end)

Players.PlayerRemoving:Connect(function(plr)
    if plr then
        _YassinInternal_clearEnemy(plr.UserId, plr.Character)
        _abEvidence[plr.UserId] = nil
    end
end)


-- ---- Hook into this script's own Anti Bat toggle -------------------------------
do
    local origStart, origStop = startAntiBat, stopAntiBat
    if type(origStop) == "function" then
        stopAntiBat = function(...)
            local r = origStop(...)
            pcall(_YassinInternal_publishAntiBatAttr, false)
            return r
        end
    end
    if type(origStart) == "function" then
        startAntiBat = function(...)
            local r = origStart(...)
            pcall(_YassinInternal_publishAntiBatAttr, true)
            return r
        end
    end
    localPlayer.CharacterAdded:Connect(function()
        task.wait(0.4)
        if antiBatEnabled then pcall(_YassinInternal_publishAntiBatAttr, true) end
    end)
end

do
    local V3 = {
        enabled = false,
        equipped = false,
        targetPlayer = nil,
        conn = nil,
        lastActivationTime = 0,
        speed = 58
    }
    local V3_ATT = "VynxAimbotV2Attachment"
    local V3_MOVER = "VynxAimbotV2Velocity"
    local v3Pred = {}

    local function clearV3Mover(root)
        if not root then return end
        pcall(function()
            local m = root:FindFirstChild(V3_MOVER); if m then m:Destroy() end
            local a = root:FindFirstChild(V3_ATT); if a then a:Destroy() end
        end)
    end

    local function ensureV3Mover(root, speed)
        local att = root:FindFirstChild(V3_ATT)
        if not att then
            att = Instance.new("Attachment")
            att.Name = V3_ATT
            att.Parent = root
        end
        local lv = root:FindFirstChild(V3_MOVER)
        if not lv then
            lv = Instance.new("LinearVelocity")
            lv.Name = V3_MOVER
            lv.Attachment0 = att
            lv.RelativeTo = Enum.ActuatorRelativeTo.World
            lv.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
            lv.ForceLimitsEnabled = true
            lv.ForceLimitMode = Enum.ForceLimitMode.PerAxis
            lv.VectorVelocity = Vector3.zero
            lv.Parent = root
        end
        local f = math.clamp(root.AssemblyMass * math.max(speed * 220, 6000), 1000000, 50000000)
        lv.MaxAxesForce = Vector3.new(f, f, f)
        lv.Enabled = true
        return lv
    end

    local function pickTargetPlayer(currentRoot)
        local bestPlayer, bestDist = nil, math.huge
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p.Character then
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                if hrp and hum and hum.Health > 0 then
                    local d = (hrp.Position - currentRoot.Position).Magnitude
                    if d < bestDist then
                        bestDist = d
                        bestPlayer = p
                    end
                end
            end
        end
        return bestPlayer
    end

    local function getBatTool(char)
        local eq = char and char:FindFirstChildOfClass("Tool")
        if eq then
            local n = eq.Name:lower()
            if n:find("bat") or n:find("slap") then return eq end
        end
        local bp = LP:FindFirstChildOfClass("Backpack")
        if bp then
            for _, t in ipairs(bp:GetChildren()) do
                if t:IsA("Tool") then
                    local n = t.Name:lower()
                    if n:find("bat") or n:find("slap") then return t end
                end
            end
        end
        return nil
    end

    local function stopBatV3()
        V3.enabled = false
        V3.equipped = false
        V3.targetPlayer = nil
        if V3.conn then V3.conn:Disconnect(); V3.conn = nil end
        local c = LP.Character
        local hum = c and c:FindFirstChildOfClass("Humanoid")
        local root = c and c:FindFirstChild("HumanoidRootPart")
        if hum then hum.AutoRotate = true end
        if root then
            root.AssemblyAngularVelocity = Vector3.zero
            clearV3Mover(root)
            pcall(function() root.Velocity = root.Velocity * 0.3 end)
        end
    end

    local function startBatV3()
        stopBatV3()
        if _G.__RivalHubStopBatV2 then pcall(_G.__RivalHubStopBatV2); if mobSetBatV2 then mobSetBatV2(false) end end
        if _G.__RivalHubStopBatV4 then pcall(_G.__RivalHubStopBatV4) end
        V3.enabled = true
        V3.equipped = false
        V3.targetPlayer = nil
        V3.lastActivationTime = 0
        V3.speed = tonumber(State and State.bypassBatSpeed) or 58

        V3.conn = RunService.RenderStepped:Connect(function(deltaTime)
            if not V3.enabled then return end
            local currentCharacter = LP.Character
            local currentRoot = currentCharacter and currentCharacter:FindFirstChild("HumanoidRootPart")
            local currentHumanoid = currentCharacter and currentCharacter:FindFirstChildOfClass("Humanoid")
            if not currentRoot or not currentHumanoid or currentHumanoid.Health <= 0 then return end
            if _G.MoonHubHardHit and _G.MoonHubHardHit() then
                pcall(clearV3Mover, currentRoot)
                return
            end

            if not V3.equipped then
                V3.equipped = true
                if not currentCharacter:FindFirstChildOfClass("Tool") then
                    local tool = getBatTool(currentCharacter)
                    if tool then pcall(function() currentHumanoid:EquipTool(tool) end) end
                end
            end

            local targetPlayer = pickTargetPlayer(currentRoot)
            local tChar = targetPlayer and targetPlayer.Character
            local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
            if not tRoot then
                currentHumanoid.AutoRotate = true
                currentRoot.AssemblyAngularVelocity = Vector3.zero
                clearV3Mover(currentRoot)
                return
            end

            V3.targetPlayer = targetPlayer
            local speed = math.clamp(tonumber(State and State.bypassBatSpeed) or tonumber(V3.speed) or 58, 1, 500)
            currentHumanoid.AutoRotate = false
            local now = tick()
            local tPos = tRoot.Position

            local rec = v3Pred[tRoot]
            local vel
            if not rec then
                v3Pred[tRoot] = { pos = tPos, time = now, vel = Vector3.zero }
                vel = Vector3.zero
            else
                local dt = math.clamp(now - rec.time, 1 / 120, 0.25)
                local raw = (tPos - rec.pos) / dt
                rec.vel = rec.vel:Lerp(raw.Magnitude > 80 and raw.Unit * 80 or raw, 0.25)
                rec.pos, rec.time = tPos, now
                vel = rec.vel
            end

            local aim = tPos + vel * math.clamp(vel.Magnitude / 130, 0.05, 0.12) + Vector3.new(0, 1, 0)
            local d = aim - currentRoot.Position
            local dirUnit = d.Magnitude > 0.01 and d.Unit or Vector3.zero
            local flat = Vector3.new(d.X, 0, d.Z)
            if d.Magnitude > 0.01 and flat.Magnitude > 0.01 then
                local yawErr = (math.deg(math.atan2(-flat.X, -flat.Z)) - currentRoot.Orientation.Y + 180) % 360 - 180
                local pitchErr = (math.deg(math.atan2(d.Y, flat.Magnitude)) - currentRoot.Orientation.X + 180) % 360 - 180
                local yawRate = math.clamp(math.rad(yawErr) * 285, -28, 28)
                local pitchRate = math.clamp(math.rad(pitchErr) * 285, -28, 28)
                local yawRad = math.rad(currentRoot.Orientation.Y)
                local axis = Vector3.new(math.cos(yawRad), 0, -math.sin(yawRad))
                currentRoot.AssemblyAngularVelocity = Vector3.new(0, yawRate, 0) + axis * pitchRate
            else
                currentRoot.AssemblyAngularVelocity = Vector3.zero
            end

            local off = aim + dirUnit * 2.8 + Vector3.new(0, 4.75, 0) - currentRoot.Position
            local hOff = Vector3.new(off.X, 0, off.Z)
            local hVel = hOff.Magnitude > 0.1 and hOff.Unit * speed or Vector3.zero
            local vVel = math.abs(off.Y) > 0.1 and Vector3.new(0, math.sign(off.Y) * 52, 0) or Vector3.new(0, -2, 0)
            local lv = ensureV3Mover(currentRoot, speed)
            local k = 1 - math.exp(-math.max(deltaTime or 1 / 60, 0) * 26)
            lv.VectorVelocity = lv.VectorVelocity:Lerp(hVel + vVel, k)
            if hOff.Magnitude > 0.5 then currentHumanoid:Move(hOff.Unit, false) end

            local tool = currentCharacter:FindFirstChildOfClass("Tool")
            if tool and (tool.Name:lower():find("bat") or tool.Name:lower():find("slap")) then
                if now - (V3.lastActivationTime or 0) >= 0.08 then
                    V3.lastActivationTime = now
                    pcall(tool.Activate, tool)
                    local re = tool:FindFirstChildWhichIsA("RemoteEvent")
                    if re then re:FireServer() end
                end
            end
        end)
    end

    _G.__RivalHubStartBatV3 = startBatV3
    _G.__RivalHubStopBatV3  = stopBatV3
    _G.__RivalHubIsBatV3    = function() return V3.enabled == true end

--------------------------------------------------------------------
-- ============================================================
-- Bypass Aimbot v4 — full Vision Bat Aimbot (angles / prediction / hybrid)
-- Ported 1:1 from Vision startBatAimbot + BUBBLE_BAT_AIM system
-- ============================================================
do
    local V4 = {
        enabled = false,
        conn = nil,
        previousAutoRotate = nil,
        lastWarn = 0,
        autoBatTarget = nil,
        autoBatLastScan = 0,
        equippedThisRun = false,
    }
    _G.__RivalHubBatV4 = V4

    local bubbleBatAim = {
        targetPlayer = nil,
        lastTargetPos = nil,
        targetVelocity = Vector3.zero,
        smoothedVelocity = Vector3.zero,
        velocityHistory = {},
        accelerationHistory = {},
        aerialVelocityHistory = {},
        previousDirection = nil,
        lastDirectionChangeTime = 0,
        airborneTime = 0,
        lastActivationTime = 0,
        currentPing = 0.1,
        realPingMs = 0,
        lastPingCheck = 0,
    }

    local BUBBLE_BAT_AIM = {
        ACTIVATE_DISTANCE = 13,
        MIN_FOLLOW_DISTANCE = 1,
        PREDICTION_TIME = 0.22,
        PREDICT_AHEAD = 3,
        MAX_VELOCITY_CHANGE = 150,
        VELOCITY_SMOOTHING = 0.2,
        MAX_HORIZONTAL_VELOCITY = 80,
        SERVER_TICKRATE = 1 / 60,
        MIN_PING_COMPENSATION = 0.03,
        MAX_PING_COMPENSATION = 0.25,
        ACCELERATION_PREDICTION_WEIGHT = 0.3,
        DIRECTION_CHANGE_DETECTION_TIME = 0.12,
        QUICK_DIRECTION_CHANGE_MULTIPLIER = 1.5,
        GRAVITY = 196.2,
        AIR_CONTROL_FACTOR = 0.8,
        MIN_AIRBORNE_TIME = 0.08,
    }

    local AUTO_BAT_SPEED = 58

    local function bubbleAverage(list)
        if #list == 0 then return Vector3.zero end
        local sum = Vector3.zero
        for _, value in ipairs(list) do sum = sum + value end
        return sum / #list
    end

    local function bubblePush(list, value, maxCount)
        table.insert(list, value)
        if #list > maxCount then table.remove(list, 1) end
    end

    local function bubbleResetAimState()
        bubbleBatAim.targetPlayer = nil
        bubbleBatAim.lastTargetPos = nil
        bubbleBatAim.targetVelocity = Vector3.zero
        bubbleBatAim.smoothedVelocity = Vector3.zero
        bubbleBatAim.velocityHistory = {}
        bubbleBatAim.accelerationHistory = {}
        bubbleBatAim.aerialVelocityHistory = {}
        bubbleBatAim.previousDirection = nil
        bubbleBatAim.airborneTime = 0
        bubbleBatAim.lastActivationTime = 0
    end

    local function findAimbotBat(character)
        if not character then return nil end
        local backpack = LP:FindFirstChildOfClass("Backpack") or LP:FindFirstChild("Backpack")
        local function isBatTool(item)
            if not item or not item:IsA("Tool") then return false end
            local name = string.lower(item.Name)
            return name:find("bat", 1, true) ~= nil or name:find("slap", 1, true) ~= nil
        end
        for _, item in ipairs(character:GetChildren()) do
            if isBatTool(item) then return item end
        end
        if backpack then
            for _, item in ipairs(backpack:GetChildren()) do
                if isBatTool(item) then return item end
            end
        end
        return nil
    end

    local function getAutoBatTarget()
        local root = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
        if not root then return nil end
        local now = tick()
        if now - V4.autoBatLastScan <= 0.1 and V4.autoBatTarget and V4.autoBatTarget.Parent then
            local hum = V4.autoBatTarget.Parent:FindFirstChildOfClass("Humanoid")
            if hum and hum.Health > 0 then return V4.autoBatTarget end
        end
        V4.autoBatLastScan = now
        V4.autoBatTarget = nil
        local closest, minDist = nil, math.huge
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LP and player.Character then
                local targetRoot = player.Character:FindFirstChild("HumanoidRootPart")
                local targetHumanoid = player.Character:FindFirstChildOfClass("Humanoid")
                if targetRoot and targetHumanoid and targetHumanoid.Health > 0 then
                    local distance = (targetRoot.Position - root.Position).Magnitude
                    if distance < minDist then
                        minDist = distance
                        closest = targetRoot
                    end
                end
            end
        end
        V4.autoBatTarget = closest
        return closest
    end

    local function resetAutoBatMotion()
        local character = LP.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if root then
            root.AssemblyAngularVelocity = Vector3.zero
            local velocity = root.AssemblyLinearVelocity
            root.AssemblyLinearVelocity = Vector3.new(velocity.X * 0.3, velocity.Y, velocity.Z * 0.3)
        end
        if humanoid then
            if type(_G.MoonHubRestoreAutoRotate) == "function" then
                pcall(_G.MoonHubRestoreAutoRotate, humanoid, V4.previousAutoRotate)
            else
                humanoid.AutoRotate = (V4.previousAutoRotate == nil) and true or V4.previousAutoRotate
            end
        end
        V4.previousAutoRotate = nil
    end

    local function stopBatV4()
        if V4.conn then
            pcall(function() V4.conn:Disconnect() end)
            V4.conn = nil
        end
        V4.enabled = false
        V4.autoBatTarget = nil
        V4.equippedThisRun = false
        bubbleResetAimState()
        resetAutoBatMotion()
    end

    local function startBatV4()
        stopBatV4()
        -- stop other bypass engines so only one runs
        pcall(function() if _G.__RivalHubStopBatV2 then _G.__RivalHubStopBatV2() end end)
        pcall(function() if _G.__RivalHubStopBatV3 then _G.__RivalHubStopBatV3() end end)
        pcall(function() if type(stopAimbotAdapt) == "function" then stopAimbotAdapt() end end)

        V4.enabled = true
        V4.equippedThisRun = false
        V4.speed = tonumber(State and State.bypassBatSpeed)
            or tonumber(_G.MoonAimbotSpeed)
            or tonumber(BYPASS_AIMBOT_SPEED)
            or 58
        bubbleResetAimState()

        V4.conn = RunService.RenderStepped:Connect(function(deltaTime)
            if not V4.enabled then return end
            local character = LP.Character
            local root = character and character:FindFirstChild("HumanoidRootPart")
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            if not root or not humanoid or humanoid.Health <= 0 then return end
            if _G.MoonHubHardHit and _G.MoonHubHardHit() then return end

            local ok, err = pcall(function()
                if V4.previousAutoRotate == nil then
                    V4.previousAutoRotate = humanoid.AutoRotate
                end
                humanoid.AutoRotate = false

                local bat = findAimbotBat(character)
                if bat and bat.Parent ~= character then
                    pcall(function() humanoid:EquipTool(bat) end)
                    V4.equippedThisRun = true
                end

                if tick() - (bubbleBatAim.lastPingCheck or 0) >= 0.5 then
                    bubbleBatAim.lastPingCheck = tick()
                    local ping = 100
                    pcall(function()
                        local stats = game:GetService("Stats")
                        local item = stats and stats.Network and stats.Network.ServerStatsItem
                        local pingItem = item and item["Data Ping"]
                        if pingItem and pingItem.GetValue then
                            ping = tonumber(pingItem:GetValue()) or ping
                        end
                    end)
                    bubbleBatAim.realPingMs = math.floor(ping)
                    bubbleBatAim.currentPing = math.clamp(
                        bubbleBatAim.realPingMs / 1000,
                        BUBBLE_BAT_AIM.MIN_PING_COMPENSATION,
                        BUBBLE_BAT_AIM.MAX_PING_COMPENSATION
                    )
                end

                local targetRoot = getAutoBatTarget()
                if not targetRoot then
                    bubbleResetAimState()
                    return
                end
                local targetPlayer = Players:GetPlayerFromCharacter(targetRoot.Parent)
                local targetHumanoid = targetRoot.Parent and targetRoot.Parent:FindFirstChildOfClass("Humanoid")
                if not targetHumanoid or targetHumanoid.Health <= 0 then
                    bubbleResetAimState()
                    return
                end

                if bubbleBatAim.targetPlayer ~= targetPlayer then
                    bubbleResetAimState()
                    bubbleBatAim.targetPlayer = targetPlayer
                    bubbleBatAim.lastTargetPos = targetRoot.Position
                    bubbleBatAim.targetVelocity = targetRoot.AssemblyLinearVelocity
                    bubbleBatAim.smoothedVelocity = targetRoot.AssemblyLinearVelocity
                end

                local dt = math.clamp(deltaTime or 0.016, 0.001, 0.05)
                local targetPosition = targetRoot.Position

                if bubbleBatAim.lastTargetPos then
                    local velocity = (targetPosition - bubbleBatAim.lastTargetPos) / dt
                    local change = velocity - bubbleBatAim.targetVelocity
                    if change.Magnitude > BUBBLE_BAT_AIM.MAX_VELOCITY_CHANGE then
                        velocity = bubbleBatAim.targetVelocity + change.Unit * BUBBLE_BAT_AIM.MAX_VELOCITY_CHANGE
                    end
                    local horizontal = Vector3.new(velocity.X, 0, velocity.Z)
                    if horizontal.Magnitude > BUBBLE_BAT_AIM.MAX_HORIZONTAL_VELOCITY then
                        horizontal = horizontal.Unit * BUBBLE_BAT_AIM.MAX_HORIZONTAL_VELOCITY
                        velocity = Vector3.new(horizontal.X, velocity.Y, horizontal.Z)
                    end
                    bubblePush(bubbleBatAim.accelerationHistory, (velocity - bubbleBatAim.targetVelocity) / dt, 4)
                    bubblePush(bubbleBatAim.velocityHistory, velocity, 8)
                    bubbleBatAim.targetVelocity = velocity
                end
                bubbleBatAim.lastTargetPos = targetPosition

                local avgVel = bubbleAverage(bubbleBatAim.velocityHistory)
                bubbleBatAim.smoothedVelocity = bubbleBatAim.smoothedVelocity:Lerp(
                    avgVel.Magnitude > 0.01 and avgVel or bubbleBatAim.targetVelocity,
                    BUBBLE_BAT_AIM.VELOCITY_SMOOTHING
                )

                local isAirborne = targetHumanoid.FloorMaterial == Enum.Material.Air
                if isAirborne then
                    bubbleBatAim.airborneTime = bubbleBatAim.airborneTime + dt
                    bubblePush(bubbleBatAim.aerialVelocityHistory, bubbleBatAim.smoothedVelocity, 6)
                else
                    bubbleBatAim.airborneTime = 0
                    bubbleBatAim.aerialVelocityHistory = {}
                end

                local lead = bubbleBatAim.currentPing + BUBBLE_BAT_AIM.SERVER_TICKRATE * BUBBLE_BAT_AIM.PREDICT_AHEAD
                local acceleration = bubbleAverage(bubbleBatAim.accelerationHistory)
                local predicted = targetPosition
                    + bubbleBatAim.smoothedVelocity * lead
                    + acceleration * BUBBLE_BAT_AIM.ACCELERATION_PREDICTION_WEIGHT * (lead * lead * 0.5)

                if isAirborne and bubbleBatAim.airborneTime >= BUBBLE_BAT_AIM.MIN_AIRBORNE_TIME then
                    local aerial = bubbleAverage(bubbleBatAim.aerialVelocityHistory)
                    if aerial.Magnitude > 0.01 then
                        predicted = predicted + aerial * lead * BUBBLE_BAT_AIM.AIR_CONTROL_FACTOR * 0.35
                    end
                    predicted = predicted + Vector3.new(0, -0.5 * BUBBLE_BAT_AIM.GRAVITY * lead * lead * 0.15, 0)
                end

                local predictionTime = BUBBLE_BAT_AIM.PREDICTION_TIME * 1.1
                local bubbleGoal = predicted - root.Position
                local legacyTarget = targetPosition + bubbleBatAim.smoothedVelocity * predictionTime
                local legacyDirection = legacyTarget - root.Position
                local legacyFlat = Vector3.new(legacyDirection.X, 0, legacyDirection.Z)
                local legacyFlatUnit = legacyFlat.Magnitude > 0.1 and legacyFlat.Unit or root.CFrame.LookVector
                local heightDiff = (legacyTarget.Y + 0.35) - root.Position.Y
                local legacyYVelocity = heightDiff * 12
                if heightDiff > 2 then legacyYVelocity = legacyYVelocity + 18 end
                if heightDiff < -2 then legacyYVelocity = legacyYVelocity - 10 end
                legacyYVelocity = math.clamp(legacyYVelocity, -70, 110)

                -- Same shared Aimbot Speed as Bypass v1/v2/v3/v4 and Normal (live)
                local speed = math.clamp(
                    tonumber(State and State.bypassBatSpeed)
                        or tonumber(_G.MoonAimbotSpeed)
                        or tonumber(BYPASS_AIMBOT_SPEED)
                        or tonumber(BAT_AIMBOT_SPEED)
                        or AUTO_BAT_SPEED
                        or 58,
                    1, 500
                )
                local legacyVelocity = Vector3.new(legacyFlatUnit.X * speed, legacyYVelocity, legacyFlatUnit.Z * speed)
                local bubbleVelocity = bubbleGoal.Magnitude > BUBBLE_BAT_AIM.MIN_FOLLOW_DISTANCE
                    and bubbleGoal.Unit * speed or Vector3.zero

                -- Vision angle system (cross product + lookAt orientation clamp)
                if bubbleGoal.Magnitude > 0.01 then
                    local cross = root.CFrame.LookVector:Cross(bubbleGoal.Unit)
                    local angle = math.asin(math.clamp(cross.Magnitude, -1, 1))
                    root.AssemblyAngularVelocity = cross.Magnitude > 0.01 and cross.Unit * angle * 80 or Vector3.zero
                end
                if legacyDirection.Magnitude > 0.1 then
                    local legacyGoalCF = CFrame.lookAt(root.Position, legacyTarget)
                    local legacyDiffCF = root.CFrame:ToObjectSpace(legacyGoalCF)
                    local rx, ry, rz = legacyDiffCF:ToOrientation()
                    rx = math.clamp(rx, -2.5, 2.5)
                    ry = math.clamp(ry, -2.5, 2.5)
                    rz = math.clamp(rz, -2.5, 2.5)
                    local legacyAngular = root.CFrame:VectorToWorldSpace(Vector3.new(rx * 42, ry * 42, rz * 42))
                    root.AssemblyAngularVelocity = root.AssemblyAngularVelocity:Lerp(legacyAngular, 0.45)
                end

                if (targetPosition - root.Position).Magnitude <= BUBBLE_BAT_AIM.ACTIVATE_DISTANCE
                    and tick() - bubbleBatAim.lastActivationTime >= 0.3 then
                    if bat then pcall(function() bat:Activate() end) end
                    bubbleBatAim.lastActivationTime = tick()
                end
                if bubbleGoal.Magnitude > BUBBLE_BAT_AIM.MIN_FOLLOW_DISTANCE then
                    local hybridVelocity = bubbleVelocity:Lerp(legacyVelocity, 0.45)
                    root.AssemblyLinearVelocity = root.AssemblyLinearVelocity:Lerp(hybridVelocity, 0.8)
                else
                    root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y * 0.5, 0)
                end
            end)
            if not ok and tick() - V4.lastWarn >= 3 then
                V4.lastWarn = tick()
                warn("[Moon Hub] Bypass Aimbot v4 frame error: " .. tostring(err))
            end
        end)
    end

    _G.__RivalHubStartBatV4 = startBatV4
    _G.__RivalHubStopBatV4 = stopBatV4
    _G.__RivalHubIsBatV4 = function() return V4.enabled == true end
end


    LP.CharacterAdded:Connect(function()
        task.wait(0.5)
        if V3.enabled then
            V3.equipped = false
            V3.targetPlayer = nil
            local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
            if hrp then clearV3Mover(hrp) end
        end
    end)
end


-- [MOON HUB signature 2/3]
do
    local env = (type(getgenv) == "function" and getgenv()) or _G
    local sig, name = {77,79,79,78,32,72,85,66}, ""
    for _, b in ipairs(sig) do name = name .. string.char(b) end
    env.MOON_HUB_SIGNATURE = name
    env.MoonHubWhoAmI = env.MoonHubWhoAmI or function() return name .. " (Moon_v230)" end
end

-- ############################################################################
-- # SMART AIMBOT  (one button "AIMBOT" + one key)
-- #   enemy has NO Anti Bat  -> Adapt Volt normal aimbot only (angles + prediction)
-- #   enemy HAS Anti Bat     -> Bypass aimbot: version 1 = Bypass Bat, 2 = Bat V2
-- #   Version is chosen in the Custom tab (last item): "Bypass Aimbot Version"
-- ############################################################################
do
    local bv = tonumber(_G.RivalAimbotBypassVersion) or 1
    if bv < 1 or bv > 4 then bv = 1 end
    _G.RivalAimbotBypassVersion = bv
end

local Smart = { enabled = false, mode = nil, applying = false, split = (_G.MoonAimbotSplit == true), forced = nil, fixed = (_G.MoonAimbotFixed == true) }
_G.RivalSmartAimbot = Smart

-- front-hit tuning
local FRONT_DIST   = 4.5   -- studs in front of the target to aim at first
local SIDE_DIST    = 5     -- sidestep so the path goes AROUND the target, not through it
local CHARGE_ON    = 1.0   -- once this far in front (along its look direction) -> charge in
local CHARGE_OFF   = -1.5  -- if it turns and you end up this far behind -> reposition again
local SWING_GRACE  = 1.2   -- seconds: if stuck behind, swing anyway so you never get stuck

local normalConn, normalPrevAR, normalSuppressed = nil, nil, false
local charging, behindSince = false, nil

local function aimSpeed()
    -- Shared speed for Normal V1, Normal V2 (Clean), Bypass V1, Bypass V2
    local s = tonumber(State and State.bypassBatSpeed)
        or tonumber(BYPASS_AIMBOT_SPEED)
        or tonumber(BAT_AIMBOT_SPEED)
        or tonumber(_G.RivalSmartAimbot and _G.RivalSmartAimbot.aimSpd)
        or 58
    if s ~= s or s <= 0 or s == math.huge then s = 58 end
    return s
end

local function stopNormal(soft)
    if normalConn then pcall(function() normalConn:Disconnect() end); normalConn = nil end
    if normalSuppressed then
        normalSuppressed = false
        if type(_unsuppressBodyLock) == "function" then pcall(_unsuppressBodyLock, true) end
    end
    charging, behindSince = false, nil
    if soft then return end
    local char = localPlayer.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        hum.AutoRotate = true
        hum.PlatformStand = false
        pcall(function() hum:ChangeState(Enum.HumanoidStateType.Running) end)
    end
    if root then
        root.AssemblyLinearVelocity = Vector3.new(0, -0.1, 0)
        root.AssemblyAngularVelocity = Vector3.zero
    end
    normalPrevAR = nil
end

local function startNormal()
    -- V1 = current Moon/Adapt | V2 = Clean Hub normal (full angles + prediction)
    if normalConn then return end
    if _G.AmbitiousAntiDieArmNow then pcall(_G.AmbitiousAntiDieArmNow) end
    if not normalSuppressed then
        normalSuppressed = true
        if type(_suppressBodyLock) == "function" then pcall(_suppressBodyLock) end
    end
    local hum0 = localPlayer.Character and localPlayer.Character:FindFirstChildOfClass("Humanoid")
    if hum0 then
        if normalPrevAR == nil then normalPrevAR = hum0.AutoRotate end
        hum0.AutoRotate = false
    end
    charging, behindSince = false, nil
    local swingCooldown = false

    normalConn = RunService.RenderStepped:Connect(function()
        if not Smart.enabled or Smart.mode ~= "normal" then return end
        local char = localPlayer.Character
        if not char then return end
        local root = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not root or not hum or hum.Health <= 0 then return end
        if _G.MoonHubHardHit and _G.MoonHubHardHit() then return end
        if hum.AutoRotate then hum.AutoRotate = false end

        local tool = char:FindFirstChildOfClass("Tool")
        if not tool then
            local bat = (type(findBat) == "function" and findBat())
                or (type(getRivalHubAimbotBat) == "function" and getRivalHubAimbotBat(char))
            if bat then
                pcall(function() hum:EquipTool(bat) end)
                tool = bat
            end
        end

        local target = (type(getClosestTarget) == "function" and getClosestTarget()) or nil
        if not target then return end
        local tHum = target.Parent and target.Parent:FindFirstChildOfClass("Humanoid")
        if tHum and tHum.Health <= 0 then return end

        local spd = aimSpeed() -- shared across Normal V1/V2 and Bypass V1/V2
        local myPos = root.Position
        local tPos = target.Position
        local tVel = target.AssemblyLinearVelocity or Vector3.zero
        local useClean = (tonumber(_G.RivalAimbotNormalVersion) == 2)

        if useClean then
            -- Clean Hub normal aimbot (exact angles + prediction + swing)
            local predictPos = tPos + tVel * 0.14 + _G.MoonSafeFacingOffset(target, 0.3)
            local direction = predictPos - myPos
            local flatDir = Vector3.new(direction.X, 0, direction.Z)
            if flatDir.Magnitude > 0 then flatDir = flatDir.Unit else flatDir = Vector3.zero end
            local desiredHeight = tPos.Y + 3.7
            local yVel = (desiredHeight - myPos.Y) * 19.5 + tVel.Y * 0.8
            if hum.FloorMaterial ~= Enum.Material.Air then yVel = math.max(yVel, 13) end
            yVel = math.clamp(yVel, -70, 110)
            local desiredVel = Vector3.new(flatDir.X * spd, yVel, flatDir.Z * spd)
            root.AssemblyLinearVelocity = root.AssemblyLinearVelocity:Lerp(desiredVel, 0.8)

            local speed3 = tVel.Magnitude
            local predictTime = math.clamp(speed3 / 150, 0.05, 0.2)
            local predictedPos = tPos + tVel * predictTime
            local toPredict = predictedPos - myPos
            if toPredict.Magnitude > 0.1 then
                local goalCF = CFrame.lookAt(myPos, predictedPos)
                local diffCF = root.CFrame:Inverse() * goalCF
                local rx, ry, rz = diffCF:ToEulerAnglesXYZ()
                rx = math.clamp(rx, -2.5, 2.5)
                ry = math.clamp(ry, -2.5, 2.5)
                rz = math.clamp(rz, -2.5, 2.5)
                root.AssemblyAngularVelocity = root.CFrame:VectorToWorldSpace(Vector3.new(rx * 42, ry * 42, rz * 42))
            end

            if (root.Position - tPos).Magnitude <= 8 then
                if tool and tool.Parent == char and not swingCooldown then
                    local n = string.lower(tool.Name or "")
                    if n:find("bat") or n:find("slap") then
                        swingCooldown = true
                        pcall(function() tool:Activate() end)
                        task.delay(0.12, function() swingCooldown = false end)
                    end
                end
            end
            return
        end

        -- V1: current Moon / Adapt normal
        local aimOffset = tPos + tVel * 0.14 + _G.MoonSafeFacingOffset(target, 0.3) - myPos
        local horiz = Vector3.new(aimOffset.X, 0, aimOffset.Z)
        local unit = (horiz.Magnitude > 0.01) and horiz.Unit or Vector3.zero
        local vert = (tPos.Y + 3.7 - myPos.Y) * 19.5 + tVel.Y * 0.8
        if hum.FloorMaterial ~= Enum.Material.Air then
            vert = math.max(vert, 13)
        end
        vert = math.clamp(vert, -70, 110)
        local desired = Vector3.new(unit.X * spd, vert, unit.Z * spd)
        root.AssemblyLinearVelocity = root.AssemblyLinearVelocity:Lerp(desired, 0.8)

        local pred = tPos + tVel * math.clamp(tVel.Magnitude / 140, 0.05, 0.2)
        if (pred - myPos).Magnitude > 0.4 then
            local goalCF = CFrame.lookAt(myPos, pred)
            local rx, ry, rz = (root.CFrame:Inverse() * goalCF):ToEulerAnglesXYZ()
            root.AssemblyAngularVelocity = root.CFrame:VectorToWorldSpace(Vector3.new(
                math.clamp(rx, -1.6, 1.6) * 42,
                math.clamp(ry, -1.6, 2.5) * 42,
                math.clamp(rz, -1.6, 1.6) * 42
            ))
        end

        if (root.Position - tPos).Magnitude <= 8 then
            if tool and tool.Parent == char and not swingCooldown then
                local n = string.lower(tool.Name or "")
                if n:find("bat") or n:find("slap") then
                    swingCooldown = true
                    pcall(function() tool:Activate() end)
                    task.delay(0.12, function() swingCooldown = false end)
                end
            end
        end
    end)
end

-- ---- anti-bat check on the nearest enemy (same logic as Moon Hub) -----------
local function getNearestLivingEnemy()
    if type(getClosestTarget) == "function" then
        local ok, tRoot = pcall(getClosestTarget)
        if ok and tRoot then
            local plr = Players:GetPlayerFromCharacter(tRoot.Parent)
            if plr then return plr end
        end
    end
    if type(_YassinInternal_getNearestEnemy) == "function" then
        local ok, plr = pcall(_YassinInternal_getNearestEnemy)
        if ok and plr then return plr end
    end
    return nil
end

local function enemyHasAntiBat(plr)
    if not plr then return false end
    local uid = plr.UserId
    local now = os.clock()
    -- v8.1.3 timing: confirmed sticky window (ANTI_BAT_TAG_STICKY_SECONDS)
    local ev = nil
    pcall(function()
        if type(_abEvidence) == "table" then ev = _abEvidence[uid] end
    end)
    if not ev and type(_G._MoonHubAntiBatEvidence) == "table" then
        ev = _G._MoonHubAntiBatEvidence[uid]
    end
    if type(ev) == "table" then
        if ev.fromAttr == true then return true end
        if ev.confirmed == true then
            local last = tonumber(ev.lastConfirmTime) or tonumber(ev.lastSpike) or 0
            if (now - last) <= (ANTI_BAT_TAG_STICKY_SECONDS or 5.0) then
                return true
            end
        end
    end
    if type(_abTagByUser) == "table" and _abTagByUser[uid] and _abTagByUser[uid].Parent then
        return true
    end
    if type(_G._MoonHubAntiBatTags) == "table" then
        local bb = _G._MoonHubAntiBatTags[uid]
        if bb and bb.Parent then return true end
    end
    local char = plr.Character
    if char and type(_YassinInternal_enemyHasAttrFlag) == "function" then
        local ok, on = pcall(_YassinInternal_enemyHasAttrFlag, char)
        if ok and on then return true end
    end
    return false
end

local function bypassModeName()
    local bv = tonumber(_G.RivalAimbotBypassVersion) or 1
    if bv == 4 then return "v4" elseif bv == 3 then return "v3" elseif bv == 2 then return "v2" else return "v1" end
end

local function desiredMode()
    -- Split Aimbot ON: no automatic Anti-Bat switching. AUTO BAT = normal, AIMBOT BYPASS = bypass.
    if Smart.split then
        if Smart.forced == "bypass" then return bypassModeName() end
        return "normal"
    end
    -- Fixed Aimbot ON: no automatic Anti-Bat switching, AUTO BAT always runs the chosen side
    if Smart.fixed then
        if _G.MoonAimbotFixedMode == "bypass" then return bypassModeName() end
        return "normal"
    end
    local enemy = getNearestLivingEnemy()
    if enemy and enemyHasAntiBat(enemy) then
        local bv = tonumber(_G.RivalAimbotBypassVersion) or 1
        if bv == 4 then return "v4" elseif bv == 3 then return "v3" elseif bv == 2 then return "v2" else return "v1" end
    end
    return "normal"
end

-- ---- originals (captured before we wrap them) --------------------------------
local origStartAim      = startAimbotAdapt      -- Bypass Bat engine (Circle Combat)
local origStopAim       = stopAimbotAdapt
local origEnableAutoBat = enableAutoBat
local origStartV2       = _G.__RivalHubStartBatV2
local origStopV2        = _G.__RivalHubStopBatV2

local function refreshButtons()
    local on = Smart.enabled == true
    local byp = on and Smart.split == true and Smart.forced == "bypass"
    if mobSetAimbot then pcall(mobSetAimbot, on and not byp) end
    if mobSetAimbotBypass then pcall(mobSetAimbotBypass, byp == true) end
end
Smart.refreshButtons = refreshButtons

local function setBtn(_on)
    refreshButtons()
end

local function stopCurrent(soft)
    local m = Smart.mode
    if m == "normal" then
        stopNormal(soft)
    elseif m == "v1" then
        if origStopAim then pcall(origStopAim) end
    elseif m == "v2" then
        if origStopV2 then pcall(origStopV2) end
    elseif m == "v3" then
        if _G.__RivalHubStopBatV3 then pcall(_G.__RivalHubStopBatV3) end
            if _G.__RivalHubStopBatV4 then pcall(_G.__RivalHubStopBatV4) end
    elseif m == "v4" then
        if _G.__RivalHubStopBatV4 then pcall(_G.__RivalHubStopBatV4) end
    end
    Smart.mode = nil
end

local function applyMode(mode)
    if Smart.mode == mode then return end
    local prev = Smart.mode
    -- normal -> bypass: only detach the normal loop (no velocity reset => no visible "reset" on switch)
    stopCurrent(prev == "normal" and mode ~= "normal")
    Smart.mode = mode
    Smart.applying = true
    if mode == "normal" then
        autoBatEnabled = true
        startNormal()
    elseif mode == "v1" then
        autoBatEnabled = true
        if origStartAim then pcall(origStartAim) end
    elseif mode == "v2" then
        autoBatEnabled = false
        if origStartV2 then pcall(origStartV2) end
    elseif mode == "v3" then
        autoBatEnabled = false
        if _G.__RivalHubStartBatV3 then pcall(_G.__RivalHubStartBatV3) end
    elseif mode == "v4" then
        autoBatEnabled = false
        if _G.__RivalHubStartBatV4 then pcall(_G.__RivalHubStartBatV4) end
    end
    Smart.applying = false
end

function Smart.start(forcedMode)
    if Smart.enabled then return end
    -- same hand-over as Auto Bat: stop auto-path + any manual aimbot first
    if autoLeftEnabled then
        autoLeftEnabled = false
        if autoLeftSetVisual then autoLeftSetVisual(false) end
        if mobSetAutoLeft then mobSetAutoLeft(false) end
        if stopAutoLeft then pcall(stopAutoLeft) end
    end
    if autoRightEnabled then
        autoRightEnabled = false
        if autoRightSetVisual then autoRightSetVisual(false) end
        if mobSetAutoRight then mobSetAutoRight(false) end
        if stopAutoRight then pcall(stopAutoRight) end
    end
    if autoBatEnabled then
        autoBatEnabled = false
        if autoBatSetVisual then autoBatSetVisual(false) end
        if mobSetAutoBat then mobSetAutoBat(false) end
        if origStopAim then pcall(origStopAim) end
    end
    if origStopV2 and _G.__RivalHubIsBatV2 and _G.__RivalHubIsBatV2() then
        pcall(origStopV2)
        if mobSetBatV2 then mobSetBatV2(false) end
    end
    if _G.__RivalHubIsBatV3 and _G.__RivalHubIsBatV3() and _G.__RivalHubStopBatV3 then
        pcall(_G.__RivalHubStopBatV3)
    end
    if _G.__RivalHubIsBatV4 and _G.__RivalHubIsBatV4() and _G.__RivalHubStopBatV4 then
        pcall(_G.__RivalHubStopBatV4)
    end
    Smart.enabled = true
    Smart.mode = nil
    Smart.forced = Smart.split and (forcedMode or "normal") or nil
    applyMode(desiredMode())
    setBtn(true)
end

function Smart.stop()
    if moonPendingCarryResume == "SmartNormal" or moonPendingCarryResume == "SmartBypass" then
        moonPendingCarryResume = nil
    end
    if not Smart.enabled then return end
    Smart.enabled = false
    Smart.forced = nil
    stopCurrent(false)
    autoBatEnabled = false
    setBtn(false)
end

function Smart.toggle()
    if not Smart.enabled and _G.MoonIsHoldingBrainrot() then
        moonTogglePending("SmartNormal")
        return false
    end
    if Smart.split then
        -- AUTO BAT button in Split mode = normal aimbot only
        if Smart.enabled and Smart.forced ~= "bypass" then
            Smart.stop()
        elseif Smart.enabled then
            Smart.forced = "normal"
            pcall(applyMode, desiredMode())
            refreshButtons()
        else
            Smart.start("normal")
        end
        return Smart.enabled
    end
    if Smart.enabled then Smart.stop() else Smart.start() end
    return Smart.enabled
end

-- AIMBOT BYPASS button / key (only works while Split Aimbot is ON): bypass aimbot only (v1/v2/v3)
function Smart.toggleBypass()
    if not Smart.split then return false end
    if not Smart.enabled and _G.MoonIsHoldingBrainrot() then
        moonTogglePending("SmartBypass")
        return false
    end
    if Smart.enabled and Smart.forced == "bypass" then
        Smart.stop()
    elseif Smart.enabled then
        Smart.forced = "bypass"
        pcall(applyMode, desiredMode())
        refreshButtons()
    else
        Smart.start("bypass")
    end
    return Smart.enabled
end

-- Resume the last requested carry-blocked feature immediately when the game
-- clears Stealing. Attribute signals are event-driven: no Heartbeat polling,
-- task.wait, debounce, or artificial delay is added.
local function moonResumeAfterCarry()
    if _G.MoonIsHoldingBrainrot() then return end
    local pending = moonPendingCarryResume
    if not pending then return end
    moonPendingCarryResume = nil
    if pending == "AutoLeft" then
        if type(startAutoLeft) == "function" then autoLeftEnabled = true; startAutoLeft() end
    elseif pending == "AutoRight" then
        if type(startAutoRight) == "function" then autoRightEnabled = true; startAutoRight() end
    elseif pending == "AutoBat" then
        if type(enableAutoBat) == "function" then enableAutoBat() end
    elseif pending == "SmartNormal" then
        if not Smart.enabled then Smart.start("normal") end
    elseif pending == "SmartBypass" then
        if not Smart.enabled then Smart.start("bypass") end
    end
end

local moonCarryCharConnection
local function moonBindCarryCharacter(character)
    if moonCarryCharConnection then
        pcall(function() moonCarryCharConnection:Disconnect() end)
        moonCarryCharConnection = nil
    end
    if character then
        moonCarryCharConnection = character:GetAttributeChangedSignal("Stealing"):Connect(moonResumeAfterCarry)
    end
end

LP:GetAttributeChangedSignal("Stealing"):Connect(moonResumeAfterCarry)
LP.CharacterAdded:Connect(function(character)
    moonBindCarryCharacter(character)
    moonResumeAfterCarry()
end)
moonBindCarryCharacter(LP.Character)

-- Fixed Aimbot ON/OFF. OFF = back to the automatic Anti-Bat switch.
function Smart.setFixed(on)
    on = on == true
    _G.MoonAimbotFixed = on
    Smart.fixed = on
    if on and Smart.split then
        -- exclusive with Split Aimbot: Smart.setSplit(false) applies the mode once (fixed already set)
        Smart.setSplit(false)
        if _G.MoonAimbotSplitSetVisual then pcall(_G.MoonAimbotSplitSetVisual, false) end
    elseif Smart.enabled then
        pcall(applyMode, desiredMode())
    end
    refreshButtons()
end

-- Normal / Bypass side of Fixed Aimbot (applies live if the aimbot is already running)
function Smart.setFixedMode(m)
    _G.MoonAimbotFixedMode = (m == "bypass") and "bypass" or "normal"
    if Smart.enabled and Smart.fixed then pcall(applyMode, desiredMode()) end
    refreshButtons()
end

-- Split Aimbot ON/OFF. OFF = back to the automatic Anti-Bat switch.
function Smart.setSplit(on)
    on = on == true
    _G.MoonAimbotSplit = on
    if on and Smart.fixed then
        Smart.fixed = false
        _G.MoonAimbotFixed = false
        if _G.MoonAimbotFixedSetVisual then pcall(_G.MoonAimbotFixedSetVisual, false) end
    end
    if Smart.split ~= on then
        Smart.split = on
        if on then
            Smart.forced = (Smart.enabled and Smart.mode and Smart.mode ~= "normal") and "bypass" or "normal"
        else
            Smart.forced = nil
        end
        if Smart.enabled then pcall(applyMode, desiredMode()) end
    end
    refreshButtons()
    if type(_G.MoonRefreshAimbotBypassUI) == "function" then pcall(_G.MoonRefreshAimbotBypassUI) end
end

function Smart.setVersion(v)
    local n = tonumber(v) or 1
    if n < 1 or n > 4 then n = 1 end
    _G.RivalAimbotBypassVersion = n
    if Smart.enabled then
        pcall(function() applyMode(desiredMode()) end)
    end
    if type(scheduleRivalHubSave) == "function" then pcall(scheduleRivalHubSave)
    elseif _G.MoonSave and _G.MoonSave.markDirty then pcall(_G.MoonSave.markDirty) end
end

-- auto-switch loop (same tick as the detector: 0.05s)
_G.__RIVAL_SMART_AIMBOT_GEN = (_G.__RIVAL_SMART_AIMBOT_GEN or 0) + 1
local _smartGen = _G.__RIVAL_SMART_AIMBOT_GEN
task.spawn(function()
    while _smartGen == _G.__RIVAL_SMART_AIMBOT_GEN do
        task.wait(0.05)
        if Smart.enabled then
            -- something else (drop, reset, manual Auto Bat, ...) stopped our aimbot -> follow it
            local m = Smart.mode
            local dead = false
            if m == "v2" then
                dead = not (_G.__RivalHubIsBatV2 and _G.__RivalHubIsBatV2())
            elseif m == "v3" then
                dead = not (_G.__RivalHubIsBatV3 and _G.__RivalHubIsBatV3())
            elseif m == "v4" then
                dead = not (_G.__RivalHubIsBatV4 and _G.__RivalHubIsBatV4())
            elseif m == "normal" or m == "v1" then
                dead = not autoBatEnabled
            end
            if dead then
                Smart.enabled = false
                Smart.forced = nil
                stopCurrent(false)
                setBtn(false)
            else
                pcall(function() applyMode(desiredMode()) end)
            end
        end
    end
end)

-- manual Auto Bat / Bat V2 buttons take over: Smart steps aside
enableAutoBat = function(...)
    if Smart.enabled then Smart.stop() end
    return origEnableAutoBat(...)
end
if origStartV2 then
    _G.__RivalHubStartBatV2 = function(...)
        if Smart.enabled and not Smart.applying then Smart.stop() end
        return origStartV2(...)
    end
end

_G.MoonHubEnemyHasAntiBat = function(plr) return enemyHasAntiBat(plr) end
end)()


-- ============================================================
-- Shift Lock auto-restore (v224)
-- After ANY feature ends (Auto Bat / Left / Right / Aimbot / TP Bat / Body Lock /
-- Look / Instant Reset) the character goes back to 100% normal so Shift Lock
-- works exactly like before. AutoRotate is always forced back to true (what
-- Shift Lock needs); no more "remembered" false values.
-- ============================================================
;(function()
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local LP = Players.LocalPlayer
    if not LP then return end

    local wasActive = false
    local idleSince = tick()
    local nextEnforce = 0

    local function getHum()
        local char = LP.Character
        return char and char:FindFirstChildOfClass("Humanoid"), char
    end

    local function lookBusy()
        local t = workspace:FindFirstChild("Terrain")
        if t and (t:FindFirstChild("MoonLookAnchor") or t:FindFirstChild("MoonLookOrientation")) then return true end
        if workspace:FindFirstChild("MoonLookAnchor") or workspace:FindFirstChild("MoonLookOrientation") then return true end
        return false
    end

    local function isActive()
        local ok, r = pcall(function()
            return autoBatEnabled == true
                or autoLeftEnabled == true
                or autoRightEnabled == true
                or bodyLockEnabled == true
                or (State ~= nil and State.bypassBatEnabled == true)
                or (TPBatState ~= nil and TPBatState.enabled == true)
                or (_G.RivalSmartAimbot and _G.RivalSmartAimbot.enabled == true)
                or (_G.AmbitiousTPRagdollBusy == true)
                or (_G.AmbitiousNormalAimbotOn == true)
                or (_G.AmbitiousBatAimbotV2On == true)
                or (_G._AmbitiousInstantResetBusy == true)
                or (type(_G.MoonLookAtEnemyOn) == "boolean" and _G.MoonLookAtEnemyOn == true)
                or (_G.MoonSpin and _G.MoonSpin.enabled == true)
                or lookBusy()
        end)
        return ok and r == true
    end

    local function gameControlsRotation(hum)
        -- ragdoll / stun etc: let the game own AutoRotate, do not fight it
        if hum.PlatformStand then return true end
        local st
        pcall(function() st = hum:GetState() end)
        return st == Enum.HumanoidStateType.Physics
            or st == Enum.HumanoidStateType.Ragdoll
            or st == Enum.HumanoidStateType.FallingDown
            or st == Enum.HumanoidStateType.Dead
    end

    local function fullRestore()
        local hum, char = getHum()
        if not hum or hum.Health <= 0 then return end
        pcall(_G.MoonHubRestoreAutoRotate, hum)
        local root = char:FindFirstChild("HumanoidRootPart")
        if root then
            -- leftovers of Aimbot / Bat V2 rotation helpers
            local a = root:FindFirstChild("_RivalHub_AngV"); if a then pcall(function() a:Destroy() end) end
            local at = root:FindFirstChild("_RivalHub_Att"); if at then pcall(function() at:Destroy() end) end
            if root.AssemblyAngularVelocity.Magnitude > 0.5 then
                root.AssemblyAngularVelocity = Vector3.zero
            end
        end
    end

    local _slAcc = 0
    RunService.Heartbeat:Connect(function(_slDt)
        _slAcc = _slAcc + (_slDt or 0)
        if _slAcc < 0.05 then return end
        _slAcc = 0
        local now = tick()
        if isActive() then
            wasActive = true
            idleSince = now
            return
        end
        if wasActive then
            wasActive = false
            idleSince = now
            pcall(fullRestore)
            task.delay(0.1, function() pcall(fullRestore) end)
            task.delay(0.3, function() pcall(fullRestore) end)
            return
        end
        -- idle: keep AutoRotate true (Shift Lock needs it) unless the game itself took over
        if now - idleSince > 0.25 and now >= nextEnforce then
            nextEnforce = now + 0.1
            local hum = getHum()
            if hum and hum.Health > 0 and hum.AutoRotate == false and not gameControlsRotation(hum) then
                pcall(_G.MoonHubRestoreAutoRotate, hum)
            end
        end
    end)

    LP.CharacterAdded:Connect(function()
        task.delay(0.6, function() pcall(fullRestore) end)
    end)
end)()


-- ============================================================
-- Anti Bat HARD OFF on Medusa OR bat — visual OFF, full wipe
-- When ragdoll/Medusa danger is FULLY over → auto ON again (fast)
-- ============================================================
;(function()
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local LP = Players.LocalPlayer
    if not LP then return end

    local wasDanger = false
    local wantBackOn = false
    local resumeToken = 0
    local lastOffAt = 0

    local function isDanger(hum)
        if not hum then return false end
        local st
        pcall(function() st = hum:GetState() end)
        if hum.PlatformStand == true
            or st == Enum.HumanoidStateType.Physics
            or st == Enum.HumanoidStateType.Ragdoll
            or st == Enum.HumanoidStateType.FallingDown
            or st == Enum.HumanoidStateType.GettingUp then
            return true
        end
        local et = LP:GetAttribute("RagdollEndTime")
        if et ~= nil then
            local ok, now = pcall(function() return workspace:GetServerTimeNow() end)
            if ok and tonumber(et) and tonumber(et) > now then return true end
        end
        local medT = tonumber(_G._AmbitiousMedusaHitTime) or 0
        if medT > 0 and (tick() - medT) < 0.45 then return true end
        return false
    end

    -- Resume check: the hit itself only (GettingUp no longer blocks resume)
    local function isHitActive(hum)
        local st
        pcall(function() st = hum:GetState() end)
        if hum.PlatformStand == true
            or st == Enum.HumanoidStateType.Physics
            or st == Enum.HumanoidStateType.Ragdoll
            or st == Enum.HumanoidStateType.FallingDown then
            return true
        end
        local et = LP:GetAttribute("RagdollEndTime")
        if et ~= nil then
            local ok, now = pcall(function() return workspace:GetServerTimeNow() end)
            if ok and tonumber(et) and tonumber(et) > now then return true end
        end
        local medT = tonumber(_G._AmbitiousMedusaHitTime) or 0
        if medT > 0 and (tick() - medT) < 0.35 then return true end
        return false
    end

    local function wipeAntiBatCompletely(fromUserWantedOn)
        -- FASTEST OFF: kill the pulse loop before doing anything else
        if type(AntiBat) == "table" and AntiBat.Connection then
            local c0 = AntiBat.Connection
            AntiBat.Connection = nil
            pcall(function() c0:Disconnect() end)
        end
        _G.MoonHubAntiBatPulsing = false
        -- INSTANT OFF: if a pulse is mid-flight (random +-4000 velocity already written),
        -- put the real velocity back right now instead of waiting for the next frame.
        if type(AntiBat) == "table" then
            if AntiBat.PulseActive == true then
                pcall(function()
                    local c = LP.Character
                    local h = c and c:FindFirstChild("HumanoidRootPart")
                    if h then
                        local o = AntiBat.origXZ or Vector3.zero
                        local cur = h.Velocity
                        h.Velocity = Vector3.new(o.X, cur.Y, o.Z)
                    end
                end)
            end
            AntiBat.gen = (AntiBat.gen or 0) + 1
        end
        if fromUserWantedOn == true or antiBatEnabled == true then
            wantBackOn = true
            _G._RivalAntiBatWantOn = true
        end
        antiBatEnabled = false
        if type(AntiBat) == "table" then
            local c = AntiBat.Connection
            AntiBat.Connection = nil
            AntiBat.PulseActive = false
            if c then pcall(function() c:Disconnect() end) end
        end
        _G.MoonHubAntiBatPulsing = false
        _G._AmbitiousAntiBatSpiking = false
        _G._AmbitiousAntiBatDesiredXZ = nil
        if _G.VX7MotionCompat then
            _G.VX7MotionCompat.antiBatPulseActive = false
            _G.VX7MotionCompat.antiBatPulseEndedAt = os.clock()
        end
        pcall(stopAntiBat)
        pcall(function()
            if type(AntiBat) == "table" then
                if AntiBat.Connection then
                    AntiBat.Connection:Disconnect()
                    AntiBat.Connection = nil
                end
                AntiBat.PulseActive = false
            end
        end)
        -- Hand the hit over to Anti Ragdoll immediately (Anti Bat is fully OFF here)
        if type(_G.MoonHubAntiRagdollNow) == "function" then pcall(_G.MoonHubAntiRagdollNow) end
        -- UI stays as user left it (no visible toggle flicker)
        lastOffAt = tick()
        resumeToken = resumeToken + 1
        local myToken = resumeToken

        -- Auto-ON the very first instant the hit is over (no fixed waits): checked on
        -- Stepped, Heartbeat AND RenderStepped, whichever fires first.
        do
            local conns = {}
            local function dropAll()
                for i = 1, #conns do pcall(function() conns[i]:Disconnect() end) end
                conns = {}
            end
            local function check()
                if myToken ~= resumeToken or not wantBackOn then dropAll(); return end
                local char = LP.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                -- Anti Bat returns exactly 2 seconds after the stick / Medusa hit
                if hum and hum.Health > 0 and (tick() - lastOffAt) >= 2 then
                    dropAll()
                    wantBackOn = false
                    _G._RivalAntiBatWantOn = false
                    pcall(startAntiBat)
                end
            end
            conns[1] = RunService.Heartbeat:Connect(check)
        end
    end

    function _G.RivalAntiBatPanicOff(reason)
        local wasOn = antiBatEnabled == true
            or (type(AntiBat) == "table" and AntiBat.Connection ~= nil)
            or _G.MoonHubAntiBatPulsing == true
            or (type(AntiBat) == "table" and AntiBat.PulseActive == true)
        if not wasOn and not wantBackOn then
            return
        end
        wipeAntiBatCompletely(true)
    end

    local function panicStep()
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then
            wasDanger = false
            return
        end
        local danger = isHitActive(hum)
        local medT = tonumber(_G._AmbitiousMedusaHitTime) or 0
        local medusaRecent = medT > 0 and (tick() - medT) < 0.35

        if antiBatEnabled == true or _G.MoonHubAntiBatPulsing == true
            or (type(AntiBat) == "table" and (AntiBat.Connection or AntiBat.PulseActive)) then
            if (danger and not wasDanger) or medusaRecent or (danger and antiBatEnabled == true) then
                wipeAntiBatCompletely(true)
            end
        end
        wasDanger = danger
    end

    -- One early render bind + Heartbeat only (avoids GUI hitch from 4x panicStep/frame)
    local stepName = "RivalAntiBatPanic_" .. tostring(math.random(1, 1e9))
    pcall(function()
        RunService:BindToRenderStep(stepName, Enum.RenderPriority.First.Value - 100000, panicStep)
    end)
    RunService.Heartbeat:Connect(panicStep)
    pcall(function() RunService.Stepped:Connect(panicStep) end)

    -- Event driven triggers: they fire the moment the hit is replicated, before the next
    -- frame step even runs, so Anti Bat is OFF as early as the engine allows.
    do
        local function instantWipe()
            if antiBatEnabled == true or _G.MoonHubAntiBatPulsing == true
                or (type(AntiBat) == "table" and (AntiBat.Connection or AntiBat.PulseActive)) then
                wipeAntiBatCompletely(true)
            end
        end
        local function hookHitEvents(char)
            if not char then return end
            task.spawn(function()
                local hum = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 5)
                if not hum then return end
                hum.StateChanged:Connect(function(_, new)
                    if new == Enum.HumanoidStateType.Physics
                        or new == Enum.HumanoidStateType.Ragdoll
                        or new == Enum.HumanoidStateType.FallingDown then
                        instantWipe()
                    end
                end)
                hum:GetPropertyChangedSignal("PlatformStand"):Connect(function()
                    if hum.PlatformStand == true then instantWipe() end
